buttonsRow.onClick:
/**
 * ปุ่ม "เรียก" — onClick ของ buttonsRow · ฟอร์ม EMR 6a4f64e7f8cdfc54cec16488 → list-ui `visit_unit` (แท็บ Unit Queue) ปุ่มที่ 1
 *
 * ไม่เลือกห้อง = หน้าห้องตรวจ (จุดคัดกรองคิวกลางของหน่วยแม่ MP · ไม่ใช่ห้องใน master)
 *   → queue-call-front เรียกใบนี้มาหน้าห้องตรวจ → คิวย้ายไปแท็บ My Room → ซักประวัติ → "ย้ายห้อง" เข้าห้องตรวจ
 * เลือกห้อง = list โชว์เฉพาะคิวที่ถูกจัดเข้าห้องนี้ (พี่เคาะ 2026-10-08)
 *   → call-next-queue pick_id เรียกใบนี้เข้าห้องตัวเอง (ข้ามคิวได้ตาม custom_queue)
 * ส่ง unit ที่เลือกอยู่ → process นับลำดับ custom_queue ในรายการเดียวกับ list นี้ (ปุ่มโชว์แต่ list ค้าง = ถูกปฏิเสธ แล้ว refresh)
 * 🔴 ห้ามใช้ await — buttonsRow onClick เป็น sync handler
 */
const CALL_FRONT = '6ab0bb0afc8b9ef3e717b010'; // process queue-call-front
const CALL_NEXT = '6a4b942bac48023662b1b42a';  // process call-next-queue

const listField = this;
const api = this.getFormRef().userState;
const u = api.user || {};
const unitCode = (u.unit && u.unit.code) || undefined;
const atRoom = !!(u.room && u.room.code);
const refresh = () => {
	const ed = listField.getFieldEditor();
	if (ed) ed.handleRefresh();
};

const proc = atRoom ? CALL_NEXT : CALL_FRONT;
const args = atRoom
	? { unit_to: unitCode, room: { value: u.room.code, label: u.room.name, qtype: u.room.qtype || null }, pick_id: String(dataRow._id) }
	: { tran_id: String(dataRow._id), unit: unitCode };

api.runProcess(proc, args, (res) => {
	const d = (res && res.data) || {};
	if (!d.success) {
		listField.alert(d.message || 'เรียกคิวไม่สำเร็จ', 'warning');
		if (d.code === 'OVER_LIMIT') refresh(); // ลำดับบนจอเก่ากว่า DB — โหลดใหม่ให้ปุ่มตรง
		return;
	}
	const where = (d.room_to && d.room_to.label) || (atRoom ? u.room.name : 'หน้าห้องตรวจ');
	listField.alert((d.recalled ? 'เรียกซ้ำ ' : 'เรียก ') + d.queue_label + ' ที่' + where, 'success');
	// คิวที่เรียกย้ายไปอยู่แท็บ My Room — refresh ทั้งสอง list
	['visit_unit', 'visit_room'].forEach((n) => {
		const f = listField.getFormRef().getFieldRef(n);
		if (f && f.getFieldEditor()) f.getFieldEditor().handleRefresh();
	});
}, (err) => listField.alert('เรียกคิวไม่สำเร็จ: ' + ((err && err.message) || err), 'error'));

buttonsRow.showFunc:
// showFunc ปุ่ม "เรียก" — ฟอร์ม EMR 6a4f64e7f8cdfc54cec16488 → list-ui `visit_unit` → buttonsRow[0]
// โชว์เฉพาะ N แถวแรก ตาม custom_queue ที่ onCreated โหลดมา · 🔴 ห้าม await (predicate ต้อง sync)
const limit = this.rowState.callLimit;
if (limit === undefined) return false; // ยังโหลดไม่เสร็จ
return limit === null || dataIndex < limit;

buttonsRow.onClick:
/**
 * ปุ่ม "ซักประวัติ" — onClick ของ buttonsRow
 * วางที่: ฟอร์ม EMR 6a4f64e7f8cdfc54cec16488 → list-ui `visit_room` (แท็บ My Room) เป็นปุ่มที่ 1
 *                                           → list-ui `visit_unit` (แท็บ Unit Queue) เป็นปุ่มที่ 1 — โค้ดเดียวกัน
 *         หน้าห้องตรวจ (เลือก MP) ซักประวัติคิวที่ยังไม่มีห้องได้เลย ก่อนจัดเข้าห้อง
 *
 * เปิดจอซักประวัติของคิวนั้น — ฟอร์มโหลดค่าเดิมเองผ่าน onFormMounted
 * 🔴 ห้ามใช้ await — buttonsRow onClick เป็น sync handler
 */

const HISTORY_FORM = '6a950188422c1ca959829d72'; // ฟอร์ม "ซักประวัติ"

const host = this.getFormRef();
const listField = this;

const ctx = {
	tran_id: String(dataRow._id),
	visit_id: (dataRow.vid && dataRow.vid.value) ? String(dataRow.vid.value) : '',
	queue_label: dataRow.queue_label || '',
};

host.openForm(HISTORY_FORM, '', '', ctx, {
	params: ctx,
	cancelCallback: () => {
		host.subFormClose();
		const ed = listField.getFieldEditor();
		if (ed) ed.handleRefresh(); // cc ที่เพิ่งบันทึกไหลไป tran แล้ว (screening sync) → แถวต้องอัปเดต
	},
});

/**
 * ปุ่ม "ย้ายห้อง" — onClick ของ buttonsRow
 * วางที่: ฟอร์ม EMR 6a4f64e7f8cdfc54cec16488 → list-ui `visit_room` (แท็บ My Room) เป็นปุ่มที่ 4
 *                                           → list-ui `visit_unit` (แท็บ Unit Queue) เป็นปุ่มที่ 1 — โค้ดเดียวกัน
 *         หน้าห้องตรวจเลือกหน่วยแม่ (MP) = เห็นคิวทุกคลินิกลูก → จัดคิวเข้าห้องได้ (ดรอปดาวน์คัดห้องตามคลินิกของคิวเอง)
 *
 * ย้ายคิวไปห้องอื่น "ในแผนกเดียวกัน" → คิวกลับไปสถานะรอเรียกที่ห้องใหม่ (ตกท้ายแถวของห้องนั้น)
 * ข้ามแผนกใช้ปุ่ม "ส่งต่อ" ตัวเดิม — คนละ process กัน
 *
 * 🔴 ห้ามใช้ await — buttonsRow onClick เป็น sync handler (ใช้ callback ของ openForm/runProcess แทน)
 */

const MOVE_ROOM_FORM = '6a9524df422c1ca959829d9e'; // ฟอร์ม "ย้ายห้อง"

const host = this.getFormRef();
const listField = this;

const st = dataRow.vtran_status;
if (!['waiting', 'called', 'in_progress', 'skipped'].includes(st)) {
	this.alert('ย้ายห้องได้เฉพาะคิวที่ยังอยู่ในแผนก', 'warning');
	return;
}

// unit_prefix = ตัวกรองห้องในฟอร์ม (where: `unit_id.label` LIKE :unit_prefix)
// ห้องเก็บแผนกเป็น label "A103 คลินิกทันตกรรม" ที่ขึ้นต้นด้วย unit_code → prefix ของคิวนี้จึงคัดเหลือห้องในแผนกเดียวกัน
const unitCode = (dataRow.unit_to && dataRow.unit_to.value) || '';
const curRoomCode = (dataRow.room_to && dataRow.room_to.value) || '';
const ctx = {
	tran_id: String(dataRow._id),
	unit_prefix: unitCode ? unitCode + '%' : '%',
	// ห้องที่คิวอยู่ตอนนี้ — ฟอร์มตัดออกจากตัวเลือก · ไม่มีห้อง = ส่ง '~' ที่ไม่ตรงกับ code ไหน (ไม่ตัดอะไร)
	cur_room: curRoomCode || '~',
	cur_room_label: (dataRow.room_to && dataRow.room_to.label) || '',
	queue_label: dataRow.queue_label || '',
};

host.openForm(MOVE_ROOM_FORM, '', '', ctx, {
	params: ctx,
	cancelCallback: () => {
		host.subFormClose();
		const ed = listField.getFieldEditor();
		if (ed) ed.handleRefresh();
		// คิวหลุดจากห้องนี้ไปห้องอื่น — จอคิวกลางของแผนกก็ต้อง refresh ตาม
		const other = listField.getFieldRef('visit_unit');
		if (other && other.getFieldEditor()) other.getFieldEditor().handleRefresh();
	},
});

/**
 * ปุ่ม "ส่งต่อ" ในหน้า EMR — onClick ของ buttonsRow
 * วางที่: ฟอร์ม EMR 6a4f64e7f8cdfc54cec16488 → list-ui **`visit_unit`** (ปุ่มที่ 1)
 *                                           → list-ui **`visit_room`** (ปุ่มที่ 3 "ส่งต่อ")
 *         โค้ดก้อนนี้ใช้ได้ทั้งสองที่ วางเหมือนกันทุกตัวอักษร
 *
 * 🆕 E132 A6 (7 ต.ค. 2569) — เติมปลายทางจาก `visit_route` (his-finance-bill-v2) แทน `cpoe-order-dest`
 *   · มีแล็บ/เอกซเรย์ที่รอเงิน ⇒ เติม **การเงิน** (step_clinic ของห้อง) · มียาที่ห้องยายังไม่จัด ด้วย ⇒ เปิด switch
 *     "เปิดคิวห้องยาคู่" ใน Move Unit (สองขา) · มีแต่ยา ⇒ เติม **ห้องยา** (เส้นเดิม)
 *   · เดิม `cpoe-order-dest` นับทุกใบไม่แยกชนิด + ใบแล็บ/เอกซเรย์ชี้ m01.p ⇒ เติมห้องยาเสมอ (demo 6 ต.ค.)
 *   ลำดับความสำคัญ: consult (เดิม) > visit_route > ไม่ prefill
 *   🔴 consult มาก่อนเสมอ — เป็นคำสั่งที่หมอเจาะจงปลายทางไว้ ส่วนเส้นทางเป็นการคำนวณจากงานที่ค้าง
 *   🔴 ห้ามใช้ await — ปุ่มนี้เป็น sync handler ⇒ ใช้ callback ของ runProcess แทน
 *   🔴 หา dest ไม่ได้/ล้ม = เปิดฟอร์มตามปกติ ห้ามบล็อกพยาบาล (ตัวช่วยกรอก ไม่ใช่ด่าน)
 */

const host = this.getFormRef();
const listField = this;
const ci = dataRow.consult_info || null;
const curUnit = (dataRow.unit_to && dataRow.unit_to.value) || '';
const ROUTE_PROC = '6a8c4732f851000f28e5022a'; // his-finance-bill-v2 · action visit_route (อ่านอย่างเดียว)
const ctx = {
	tran_id: String(dataRow._id),
	cur_unit: curUnit,
	visit_priority: dataRow.visit_priority || '10',
	tran_note: '',
	consult_id: '',
	open_drug_leg: false,
};

const openMove = () => {
	host.openForm('6a4f828d22f95f21b606d9a2', '', '', ctx, {
		params: ctx,
		cancelCallback: () => {
			host.subFormClose();
			const ed = listField.getFieldEditor();
			if (ed) ed.handleRefresh();
			const other = listField.getFieldRef(listField.field.options.name === 'visit_unit' ? 'visit_room' : 'visit_unit');
			if (other && other.getFieldEditor()) other.getFieldEditor().handleRefresh();
		},
	});
};

if (ci && ci.clinic && String(ci.clinic) !== String(curUnit)) {
	// ต้นทาง → ส่งไปคลินิก consult + stamp accept
	ctx.unit_to = { value: ci.clinic, label: ci.to_label || ci.clinic };
	ctx.tran_note = ci.reason || '';
	ctx.visit_priority = ci.priority || ctx.visit_priority;
	ctx.consult_id = ci.consult_id || '';
	openMove();
} else if (ci && ci.reply && String(ci.clinic) === String(curUnit) && dataRow.unit_from && dataRow.unit_from.value) {
	// ปลายทาง + ขอส่งกลับ → prefill คลินิกต้นทาง (tran.unit_from — ไม่ใช่ consult_info)
	ctx.unit_to = { value: dataRow.unit_from.value, label: dataRow.unit_from.label || dataRow.unit_from.value };
	openMove();
} else {
	// ไม่มี consult → ถามเส้นทางจากงานที่ค้าง (E132 สองขา)
	host.userState.runProcess(
		ROUTE_PROC,
		{ action: 'visit_route', tran_id: ctx.tran_id },
		(res) => {
			const d = (res && res.data) || {};
			if (d.ok) {
				const u = d.patient_leg === 'finance' ? d.finance_unit : d.patient_leg === 'pharmacy' ? d.pharmacy_unit : null;
				if (u && u.value) ctx.unit_to = { value: u.value, label: u.label || u.value };
				const notes = [];
				if (d.reason) notes.push(d.reason);
				(d.warnings || []).forEach((w) => { if (w && w.message) notes.push('⚠️ ' + w.message); });
				ctx.route_note = notes.join(' · ');
				if (d.drug_leg && d.pharmacy_unit && d.pharmacy_unit.value) {
					ctx.open_drug_leg = true;
					ctx.visit_id = d.visit_id || '';
					ctx.drug_leg_unit = d.pharmacy_unit.value;
					ctx.drug_leg_label = d.pharmacy_unit.label || d.pharmacy_unit.value;
				}
			}
			openMove();
		},
		() => openMove(),
	);
}

options.onCreated:
/**
 * onCreated — ฟอร์ม EMR 6a4f64e7f8cdfc54cec16488 → แท็บ Unit Queue → list-ui `visit_unit`
 *
 * โหลด "เรียกคิวข้ามได้กี่แถว" (Organization.custom_queue · หน่วยแม่ก่อนแล้วค่อยคลินิก) ใส่ this.rowState.callLimit
 * ให้ showFunc ของปุ่ม "เรียก" ซ่อนแถวที่เกิน — rowState เป็น reactive ค่ามาถึงเมื่อไหร่ปุ่มก็วาดใหม่เอง
 *   callLimit: undefined = ยังโหลดไม่เสร็จ (ซ่อนไว้ก่อน กันปุ่มโผล่แล้วหาย) · null = ไม่จำกัด · N = แถว 1..N
 * โหลดไม่สำเร็จ → null (โชว์ทุกแถว) — process queue-call-front ปฏิเสธแถวที่เกินเองอยู่แล้ว
 */
const CALL_FRONT = '6ab0bb0afc8b9ef3e717b010'; // process queue-call-front

const listField = this;
/* emr2-builder-guard */
const form = this.getFormRef();
// บิลเดอร์ไม่มีฟอร์มให้ — ไม่ต้องโหลดคิว (เดิมพังขึ้น warning "reading 'userState'" ทุกครั้งที่เปิดบิลเดอร์)
if (!form || !form.userState) return;
const api = form.userState;
const u = api.user || {};

if (!u.unit || !u.unit.code) {
	listField.rowState.callLimit = null;
} else {
	api.runProcess(CALL_FRONT, { unit: u.unit.code, limit_only: true }, (res) => {
		const d = (res && res.data) || {};
		listField.rowState.callLimit = d.success && typeof d.call_limit === 'number' ? d.call_limit : null;
	}, () => {
		listField.rowState.callLimit = null;
	});
}

buttons.onClick:
// ปุ่ม "เรียกคิวถัดไป" — btn_unit (Unit Queue) + btn_room (My Room) · ฟอร์ม EMR 6a4f64e7f8cdfc54cec16488 — โค้ดเดียวกันทั้งสองปุ่ม
// เลือกห้อง = เรียกเข้าห้องตัวเอง (call-next-queue เดิม)
// ไม่เลือกห้อง = ทำหน้าที่ "หน้าห้องตรวจ" (คัดกรองคิวกลาง) → queue-call-front ดึงคิวถัดไปของหน่วย + คลินิกลูก มาหน้าห้องตรวจ
//   หน่วยที่ไม่ได้ตั้ง Organization.front_desk → process ตอบ NO_FRONT พร้อมข้อความ "เลือกห้องตรวจก่อน" (พฤติกรรมเดิม)
const CALL_NEXT = '6a4b942bac48023662b1b42a';  // call-next-queue
const CALL_FRONT = '6ab0bb0afc8b9ef3e717b010'; // queue-call-front
const api = this.getFormRef().userState;
const u = api.user || {};
if (!u.unit || !u.unit.code) { this.alert('ยังไม่ได้เลือกแผนก', 'warning'); return; }
const atFront = !u.room || !u.room.code;
const proc = atFront ? CALL_FRONT : CALL_NEXT;
const args = atFront
  ? { unit: u.unit.code }
  : { unit_to: u.unit.code, room: { value: u.room.code, label: u.room.name, qtype: u.room.qtype || null } };
  // doctor: {value,label} — ส่งเมื่อเป็น "จอหมอ" (ดึงเฉพาะคิวกลาง+คิวเจาะจงหมอคนนี้); ไม่ส่ง = override ได้ทุกคิว
api.runProcess(proc, args, (res) => {
  const d = res.data || {};
  if (d.empty) { this.alert('ไม่มีคิวรอ', 'info'); return; }
  if (!d.success) { this.alert(d.message || 'เรียกคิวไม่สำเร็จ', 'warning'); return; }
  this.alert('เรียกคิว ' + d.queue_label + (atFront && d.room_to ? ' ที่' + d.room_to.label : ''), 'success');
  ['visit_unit', 'visit_room'].forEach((n) => {
    const f = this.getFieldRef(n);
    if (f && f.getFieldEditor()) f.getFieldEditor().handleRefresh();
  });
}, (err) => this.alert('เรียกคิวไม่สำเร็จ: ' + ((err && err.message) || err), 'error'));

/**
 * ปุ่ม "Check-in" — แท็บ My Room หน้า EMR (ฟอร์ม EMR 6a4f64e7f8cdfc54cec16488 · button-ui `button_ui52909`)
 *
 * เปิด popup ฟอร์ม "Check-in": ใส่ VN → เห็นคิวล่าสุดของคนไข้ → ยืนยันดึงคิวมาแผนก/ห้องของคนกด
 * งานทั้งหมดอยู่ในการ์ดของ popup (checkin-card.*) + process queue-checkin-here — ปุ่มนี้แค่เปิดและ refresh คิวตอนปิด
 *
 * 🔴 ห้ามใช้ await — onClick เป็น sync handler
 */

const CHECKIN_FORM = '6ac9f156481c196fbb330cab'; // ฟอร์ม "Check-in" (form_ui) — gen-checkin-model.mjs เขียน id ให้ตอน build

// 🔴 ห้ามชื่อ btn/index — button-ui compile onClick ด้วยพารามิเตอร์ (btn, index) ประกาศซ้ำ = SyntaxError ทั้งปุ่ม
const form = this.getFormRef();
const u = form.userState.user || {};
if (!u.unit || !u.unit.code) {
	this.alert('ยังไม่ได้เลือกแผนก', 'warning');
	return;
}

const refreshQueues = () => {
	['visit_unit', 'visit_room'].forEach((n) => {
		const f = form.getFieldRef(n);
		if (f && f.getFieldEditor && f.getFieldEditor()) f.getFieldEditor().handleRefresh();
	});
};
// ปิดทางไหนก็ refresh — การ์ดสั่ง closePopup() หลัง Check-in สำเร็จ ซึ่งวิ่งเข้า cancelCallback ชุดนี้
const closeAndRefresh = () => {
	form.subFormClose();
	refreshQueues();
};

form.openForm(CHECKIN_FORM, '', '', {}, {
	params: {},
	cancelCallback: closeAndRefresh,
	// form_ui ไม่มีปุ่มบันทึก — ใส่ไว้กัน popup ค้างถ้าวันหนึ่งฟอร์มถูกเปลี่ยนชนิด (autosave ระหว่างกรอกห้ามปิด)
	afterSaveCallback: (saved, autoSave) => {
		if (autoSave) return;
		closeAndRefresh();
	},
});

buttonsRow.onClick:
/**
 * ปุ่ม "ซักประวัติ" — onClick ของ buttonsRow
 * วางที่: ฟอร์ม EMR 6a4f64e7f8cdfc54cec16488 → list-ui `visit_room` (แท็บ My Room) เป็นปุ่มที่ 5
 *         (วางที่ list-ui `visit_unit` ด้วยก็ได้ ถ้าอยากซักประวัติจากคิวกลางของแผนก — โค้ดชุดเดียวกัน)
 *
 * เปิดจอซักประวัติของคิวนั้น — ฟอร์มโหลดค่าเดิมเองผ่าน onFormMounted
 * 🔴 ห้ามใช้ await — buttonsRow onClick เป็น sync handler
 */

const HISTORY_FORM = '6a950188422c1ca959829d72'; // ฟอร์ม "ซักประวัติ"

const host = this.getFormRef();
const listField = this;

const ctx = {
	tran_id: String(dataRow._id),
	visit_id: (dataRow.vid && dataRow.vid.value) ? String(dataRow.vid.value) : '',
	queue_label: dataRow.queue_label || '',
};

host.openForm(HISTORY_FORM, '', '', ctx, {
	params: ctx,
	cancelCallback: () => {
		host.subFormClose();
		const ed = listField.getFieldEditor();
		if (ed) ed.handleRefresh(); // cc ที่เพิ่งบันทึกไหลไป tran แล้ว (screening sync) → แถวต้องอัปเดต
	},
});

const form = this.getFormRef();
const goEmr = (row) => {
  form.$examTran = row;                                  // opd_card อ่านตอน mount แรก (lazy tab)
  const card = form.getFieldRef('opd_card');
  if (card && card.vueState && card.vueState.setTran) card.vueState.setTran(row);

  const tab = form.getFieldRef('main_app');
  if (tab) tab.activeTabName = 'tab_pane_41691';
};
const st = dataRow.vtran_status;
if (st === 'in_progress') { goEmr(dataRow); return; }
if (st !== 'called') { this.alert('เริ่มตรวจได้เฉพาะคิวที่เรียกแล้ว', 'warning'); return; }
const api = form.userState;
api.runProcess('6a4f852422f95f21b606d9a3', { tran_id: String(dataRow._id), action: 'start' }, (res) => {
  const d = res.data || {};
  if (!d.success) { this.alert(d.message || 'เริ่มตรวจไม่สำเร็จ', 'warning'); return; }
  this.alert('เริ่มตรวจคิว ' + d.queue_label, 'success');
  this.getFieldEditor().handleRefresh();
    // process เพิ่ง stamp start_at ใน DB — dataRow เป็น snapshot เก่า ต้อง patch ก่อนส่งเข้าการ์ด ไม่งั้น timer ขึ้น --:--
  goEmr({ ...dataRow, vtran_status: 'in_progress', start_at: this.dayjs().format('YYYY-MM-DD HH:mm:ss') });

}, (err) => this.alert(String((err && err.message) || err), 'error'));

const st = dataRow.vtran_status;
const action = st === 'called' ? 'skip' : (st === 'skipped' ? 'recall' : null);
if (!action) { this.alert('ข้าม/เรียกกลับได้เฉพาะคิวสถานะ "เรียกแล้ว" หรือ "ข้าม"', 'warning'); return; }
const api = this.getFormRef().userState;
api.runProcess('6a4b9451ac48023662b1b42b', { tran_id: String(dataRow._id), action: action }, (res) => {
  const d = res.data || {};
  if (!d.success) { this.alert(d.message || 'ทำรายการไม่สำเร็จ', 'warning'); return; }
  this.alert((action === 'skip' ? 'ข้ามคิว ' : 'เรียกกลับเข้าแถว ') + d.queue_label, 'success');
  this.getFieldEditor().handleRefresh();
}, (err) => this.alert(String((err && err.message) || err), 'error'));

/**
 * ปุ่ม "ย้ายห้อง" — onClick ของ buttonsRow
 * วางที่: ฟอร์ม EMR 6a4f64e7f8cdfc54cec16488 → list-ui `visit_room` (แท็บ My Room) เป็นปุ่มที่ 4
 *
 * ย้ายคิวไปห้องอื่น "ในแผนกเดียวกัน" → คิวกลับไปสถานะรอเรียกที่ห้องใหม่ (ตกท้ายแถวของห้องนั้น)
 * ข้ามแผนกใช้ปุ่ม "ส่งต่อ" ตัวเดิม — คนละ process กัน
 *
 * 🔴 ห้ามใช้ await — buttonsRow onClick เป็น sync handler (ใช้ callback ของ openForm/runProcess แทน)
 */

const MOVE_ROOM_FORM = '6a9524df422c1ca959829d9e'; // ฟอร์ม "ย้ายห้อง"

const host = this.getFormRef();
const listField = this;

const st = dataRow.vtran_status;
if (!['waiting', 'called', 'in_progress', 'skipped'].includes(st)) {
	this.alert('ย้ายห้องได้เฉพาะคิวที่ยังอยู่ในแผนก', 'warning');
	return;
}

// unit_prefix = ตัวกรองห้องในฟอร์ม (where: `unit_id.label` LIKE :unit_prefix)
// ห้องเก็บแผนกเป็น label "A103 คลินิกทันตกรรม" ที่ขึ้นต้นด้วย unit_code → prefix ของคิวนี้จึงคัดเหลือห้องในแผนกเดียวกัน
const unitCode = (dataRow.unit_to && dataRow.unit_to.value) || '';
const curRoomCode = (dataRow.room_to && dataRow.room_to.value) || '';
const ctx = {
	tran_id: String(dataRow._id),
	unit_prefix: unitCode ? unitCode + '%' : '%',
	// ห้องที่คิวอยู่ตอนนี้ — ฟอร์มตัดออกจากตัวเลือก · ไม่มีห้อง = ส่ง '~' ที่ไม่ตรงกับ code ไหน (ไม่ตัดอะไร)
	cur_room: curRoomCode || '~',
	cur_room_label: (dataRow.room_to && dataRow.room_to.label) || '',
	queue_label: dataRow.queue_label || '',
};

host.openForm(MOVE_ROOM_FORM, '', '', ctx, {
	params: ctx,
	cancelCallback: () => {
		host.subFormClose();
		const ed = listField.getFieldEditor();
		if (ed) ed.handleRefresh();
		// คิวหลุดจากห้องนี้ไปห้องอื่น — จอคิวกลางของแผนกก็ต้อง refresh ตาม
		const other = listField.getFieldRef('visit_unit');
		if (other && other.getFieldEditor()) other.getFieldEditor().handleRefresh();
	},
});

/**
 * ปุ่ม "ส่งต่อ" ในหน้า EMR — onClick ของ buttonsRow
 * วางที่: ฟอร์ม EMR 6a4f64e7f8cdfc54cec16488 → list-ui **`visit_unit`** (ปุ่มที่ 1)
 *                                           → list-ui **`visit_room`** (ปุ่มที่ 3 "ส่งต่อ")
 *         โค้ดก้อนนี้ใช้ได้ทั้งสองที่ วางเหมือนกันทุกตัวอักษร
 *
 * 🆕 E132 A6 (7 ต.ค. 2569) — เติมปลายทางจาก `visit_route` (his-finance-bill-v2) แทน `cpoe-order-dest`
 *   · มีแล็บ/เอกซเรย์ที่รอเงิน ⇒ เติม **การเงิน** (step_clinic ของห้อง) · มียาที่ห้องยายังไม่จัด ด้วย ⇒ เปิด switch
 *     "เปิดคิวห้องยาคู่" ใน Move Unit (สองขา) · มีแต่ยา ⇒ เติม **ห้องยา** (เส้นเดิม)
 *   · เดิม `cpoe-order-dest` นับทุกใบไม่แยกชนิด + ใบแล็บ/เอกซเรย์ชี้ m01.p ⇒ เติมห้องยาเสมอ (demo 6 ต.ค.)
 *   ลำดับความสำคัญ: consult (เดิม) > visit_route > ไม่ prefill
 *   🔴 consult มาก่อนเสมอ — เป็นคำสั่งที่หมอเจาะจงปลายทางไว้ ส่วนเส้นทางเป็นการคำนวณจากงานที่ค้าง
 *   🔴 ห้ามใช้ await — ปุ่มนี้เป็น sync handler ⇒ ใช้ callback ของ runProcess แทน
 *   🔴 หา dest ไม่ได้/ล้ม = เปิดฟอร์มตามปกติ ห้ามบล็อกพยาบาล (ตัวช่วยกรอก ไม่ใช่ด่าน)
 */

const host = this.getFormRef();
const listField = this;
const ci = dataRow.consult_info || null;
const curUnit = (dataRow.unit_to && dataRow.unit_to.value) || '';
const ROUTE_PROC = '6a8c4732f851000f28e5022a'; // his-finance-bill-v2 · action visit_route (อ่านอย่างเดียว)
const ctx = {
	tran_id: String(dataRow._id),
	cur_unit: curUnit,
	visit_priority: dataRow.visit_priority || '10',
	tran_note: '',
	consult_id: '',
	open_drug_leg: false,
};

const openMove = () => {
	host.openForm('6a4f828d22f95f21b606d9a2', '', '', ctx, {
		params: ctx,
		cancelCallback: () => {
			host.subFormClose();
			const ed = listField.getFieldEditor();
			if (ed) ed.handleRefresh();
			const other = listField.getFieldRef(listField.field.options.name === 'visit_unit' ? 'visit_room' : 'visit_unit');
			if (other && other.getFieldEditor()) other.getFieldEditor().handleRefresh();
		},
	});
};

if (ci && ci.clinic && String(ci.clinic) !== String(curUnit)) {
	// ต้นทาง → ส่งไปคลินิก consult + stamp accept
	ctx.unit_to = { value: ci.clinic, label: ci.to_label || ci.clinic };
	ctx.tran_note = ci.reason || '';
	ctx.visit_priority = ci.priority || ctx.visit_priority;
	ctx.consult_id = ci.consult_id || '';
	openMove();
} else if (ci && ci.reply && String(ci.clinic) === String(curUnit) && dataRow.unit_from && dataRow.unit_from.value) {
	// ปลายทาง + ขอส่งกลับ → prefill คลินิกต้นทาง (tran.unit_from — ไม่ใช่ consult_info)
	ctx.unit_to = { value: dataRow.unit_from.value, label: dataRow.unit_from.label || dataRow.unit_from.value };
	openMove();
} else {
	// ไม่มี consult → ถามเส้นทางจากงานที่ค้าง (E132 สองขา)
	host.userState.runProcess(
		ROUTE_PROC,
		{ action: 'visit_route', tran_id: ctx.tran_id },
		(res) => {
			const d = (res && res.data) || {};
			if (d.ok) {
				const u = d.patient_leg === 'finance' ? d.finance_unit : d.patient_leg === 'pharmacy' ? d.pharmacy_unit : null;
				if (u && u.value) ctx.unit_to = { value: u.value, label: u.label || u.value };
				const notes = [];
				if (d.reason) notes.push(d.reason);
				(d.warnings || []).forEach((w) => { if (w && w.message) notes.push('⚠️ ' + w.message); });
				ctx.route_note = notes.join(' · ');
				if (d.drug_leg && d.pharmacy_unit && d.pharmacy_unit.value) {
					ctx.open_drug_leg = true;
					ctx.visit_id = d.visit_id || '';
					ctx.drug_leg_unit = d.pharmacy_unit.value;
					ctx.drug_leg_label = d.pharmacy_unit.label || d.pharmacy_unit.value;
				}
			}
			openMove();
		},
		() => openMove(),
	);
}

/**
 * ปุ่ม "💉 ฉีดวัคซีน" — onClick ของ buttonsRow · ฟอร์ม EMR 6a4f64e7f8cdfc54cec16488 → list-ui `visit_room` (C24)
 * เปิด drawer สมุดวัคซีน (ฟอร์ม Vaccine Book) ที่แท็บ "บันทึกการฉีด" — ติ๊กรายการ + ข้อยืนยันของหมอไว้ให้
 * แบบเดียวกับ openVxBook ของ opd_card (C21): drawer ขวา · readonly · ไม่ส่ง backdrop (ใช้ค่าตั้งของฟอร์ม Vaccine Book)
 * 🔴 ไม่ส่ง cancelCallback — กลายเป็น before-close (sdform/patient-history/README.md)
 */
const VX_BOOK_FORM = '6ad60671481c196fbb33a0b4'; // Vaccine Book (form_ui)

const form = this.getFormRef();
const vid = (dataRow && dataRow.vid) || {};
const visitId = vid.value ? String(vid.value) : '';
const pid = vid.xtbxlv1_xfx_id ? String(vid.xtbxlv1_xfx_id) : '';
if (!visitId || !pid) {
	this.alert('ไม่พบข้อมูล visit ของแถวนี้', 'warning');
	return;
}
// 🔴 spread formParams ของแม่ ไม่งั้น drawer ไม่เหลือ xsitex/xunitx
const ctx = Object.assign({}, form.formParams, { pid, visit_id: visitId, mode: 'record' });
form.openForm(VX_BOOK_FORM, '', '', ctx, { popupType: 'drawer', drawerDirection: 'rtl', readonly: true, params: ctx });
// บันทึกแล้วปุ่มหายเองในรอบโหลด 20 วิ ของ onCreated

buttonsRow.showFunc:
// showFunc ปุ่ม "💉 ฉีดวัคซีน" — ฟอร์ม EMR 6a4f64e7f8cdfc54cec16488 → list-ui `visit_room` → buttonsRow (C24)
// โชว์เฉพาะแถวที่หมอส่งฉีดแล้วยังไม่บันทึก (rowState.vx มาจาก onCreated) · 🔴 ห้าม await (predicate ต้อง sync)
const m = this.rowState.vx;
if (!m) return false; // ยังโหลดไม่เสร็จ
const vid = dataRow && dataRow.vid && dataRow.vid.value;
const x = vid ? m[String(vid)] : null;
return !!x && x.status === 'ordered';

options.onCreated:
/**
 * onCreated — ฟอร์ม EMR 6a4f64e7f8cdfc54cec16488 → แท็บ My Room → list-ui `visit_room` (C24 · topic vaccine)
 *
 * โหลด "visit วันนี้ที่หมอส่งฉีด/ฉีดแล้ว" (process vx-order action today) ใส่ this.rowState.vx = { <visit id>: { status, n, watch_until } }
 * ให้ showFunc ของปุ่ม 💉 โชว์เฉพาะแถวที่หมอส่งแล้วยังไม่ฉีด — rowState เป็น reactive ค่ามาถึงเมื่อไหร่ปุ่มก็วาดใหม่เอง
 *   rowState.vx: undefined = ยังโหลดไม่เสร็จ (ซ่อนปุ่มไว้ก่อน) · {} = ไม่มีใครส่ง
 * แถวคิวเป็น Visit Tran (ไม่มีช่องวัคซีน · พี่เคาะให้ Visit Tran เป็นคิวล้วน) จึงต้องโหลดแยกแบบนี้ (พี่เลือกข้อ 1A 2026-10-19)
 * โหลดซ้ำทุก 20 วิ — หมอกดส่งแล้วปุ่มขึ้นในแถวช้าสุดราว 20 วิ · หยุดตอน unmount (onUnmount)
 * โหลดไม่สำเร็จ = คงค่าเดิม (ไม่ล้างปุ่มที่ขึ้นอยู่) — process vx-give ปฏิเสธ visit ที่ไม่ได้ส่งเองอยู่แล้ว
 */
const VX_ORDER = '6ad63a8ef2880767e1b78170'; // process vx-order
const REFRESH_MS = 20000;

const listField = this;
/* emr2-builder-guard */
const form = this.getFormRef();
// บิลเดอร์ไม่มีฟอร์มให้ — ไม่ต้องโหลดคิว (เดิมพังขึ้น warning "reading 'userState'" ทุกครั้งที่เปิดบิลเดอร์)
if (!form || !form.userState) return;
const api = form.userState;

const loadVx = () => api.runProcess(VX_ORDER, { action: 'today' }, (res) => {
	const d = (res && res.data) || {};
	if (d.success) listField.rowState.vx = d.map || {};
}, () => {});

loadVx();
if (listField.rowState.vxTimer) clearInterval(listField.rowState.vxTimer);
listField.rowState.vxTimer = setInterval(loadVx, REFRESH_MS);

options.onUnmount:
// onUnmount — ฟอร์ม EMR 6a4f64e7f8cdfc54cec16488 → list-ui `visit_room` (C24) · หยุดโหลดรายการส่งฉีดซ้ำ
if (this.rowState && this.rowState.vxTimer) {
	clearInterval(this.rowState.vxTimer);
	this.rowState.vxTimer = null;
}

options.onCreated:
const s = this.vueState
const field = this
s.tran = null   // visit tran ที่เลือกจากคิว — เซ็ตโดยปุ่ม EMR / onMounted

s.pt = () => (s.tran && s.tran.vid && s.tran.vid.pid) || {}
s.ptName = () => {
  const p = s.pt()
  return ((p.prename && p.prename.label) || '') + (p.p_fname || '') + ' ' + (p.p_lname || '')
}
s.picUrl = () => {
  const p = s.pt()
  return (Array.isArray(p.p_pic) && p.p_pic[0] && p.p_pic[0].url) || ''
}
s.initial = () => { const p = s.pt(); return p.p_fname ? p.p_fname.charAt(0) : '?' }
s.genderLabel = () => ({ '1': 'ชาย', '2': 'หญิง' })[s.pt().p_gender] || '-'
s.aboLabel = () => {
  const m = { '1': 'A', '2': 'B', '3': 'AB', '4': 'O', '5': 'ไม่ทราบ', '9': 'ไม่ทราบ' }
  const p = s.pt()
  return m[p.p_abogroup] || p.p_abogroup || '-'
}
// ประเภทบริการ (visit_type บน Visit form) — ค่าจาก builder: 1=ตรวจสุขภาพ, 2=ตรวจตามนัด, 3=รับส่งต่อ, 4=ตรวจรักษา, 5=อื่นๆ
s.visitTypeMap = { '1': 'ตรวจสุขภาพ', '2': 'ตรวจตามนัด', '3': 'รับส่งต่อ', '4': 'ตรวจรักษา', '5': 'อื่นๆ' }
s.serviceTypeLabel = () => {
  const v = s.tran && s.tran.vid && s.tran.vid.visit_type
  return v ? (s.visitTypeMap[v] || v) : ''
}
s.visitTime = () => {
  const t = s.tran && s.tran.checkin_at
  if (!t) return '-'
  const d = field.dayjs(t)
  return d.format('DD/MM/') + (d.year() + 543) + d.format(' HH:mm')   // ค.ศ. → พ.ศ. (+543)
}

// เปิดฟอร์มผู้ป่วย (PERSON) — id ผู้ป่วยอยู่ที่ vid.xtbxlv1_xfx_id (= pid.value ของ visit)
s.openPatient = () => {
  const pidId = s.tran && s.tran.vid && s.tran.vid.xtbxlv1_xfx_id
  if (!pidId) { field.alert('ไม่พบ id ผู้ป่วยใน visit นี้', 'warning'); return }
  const form = field.getFormRef()
  form.openForm('6a37d3bd4cfbfdbe257fc912', String(pidId), '', null, {
    afterSaveCallback: (saved) => {
      form.subFormClose()
      if (!saved) return
      const p = s.tran.vid.pid
      if (p) {
        ['hn', 'prename', 'p_fname', 'p_lname', 'p_gender', 'age', 'p_abogroup', 'birth_date', 'p_pic']
          .forEach((k) => { if (k in saved) p[k] = saved[k] })
      }
      // sync allergy_tags ลง visit_tran จริง → ws เด้งจอคิว + เอา tags กลับมาอัปเดตการ์ด
      form.userState.runProcess('6a50cc20e97c6d6bbf111ce0', { person_id: String(s.tran.vid.xtbxlv1_xfx_id), sync_allergy: true }, (res) => {
        const d = res.data || {}
        if (d.success && 'allergy_tags' in d) s.tran.allergy_tags = d.allergy_tags || []
      }, (err) => field.alert('sync การแพ้ไม่สำเร็จ: ' + ((err && err.message) || err), 'error'))
    }

  })
}

s.bmiRec = null   // record BMI ล่าสุดของ visit นี้

s.loadBmi = () => {
  s.bmiRec = null
  const visitId = s.tran && s.tran.vid && s.tran.vid.value
  if (!visitId) return
  field.getFormRef().userState.crudGetAll({
    sdProvider: {
      providerId: '6a4689ef39179670f85ba2a2',   // ฟอร์ม BMI
      providerType: 'FORM',
      params: { vid: String(visitId) },
      options: {
        where: "`vid.value` = CONVERT(:vid, 'objectId')",
        orderBy: [{ column: 'created_at', sort: 'DESC' }],
        limit: 1,
        page: 1
      }

    },
    totalEnable: false
  }, (res) => { s.bmiRec = (res.data && res.data[0]) || null })
}

// เซ็ตคนไข้ + โหลด BMI — ให้ปุ่ม EMR / onMounted เรียกตัวนี้แทนเซ็ต tran ตรง
s.setTran = (row) => {
  s.tran = row; s.loadBmi(); s.loadVs(); s.tickExam(); s.vxLoad(row)
  // ยังไม่เลือกผู้ป่วย → ซ่อนโซน SOAP ทั้งแถบ (container hide แค่ซ่อน ไม่ล้างค่า field)
  const box = field.getFieldRef('emr_box')
  if (box) { row ? box.show() : box.hide() }
  // action bar ล่างจอ (ตรวจเสร็จ/ย้ายห้อง/ส่งต่อ) ใช้ได้เฉพาะตอนมีคนไข้ — ตั้ง hidden ไว้ใน builder แล้วเปิดที่นี่ (2026-10-08)
  const bar = field.getFieldRef('action_bar_affix')
  if (bar) { row ? bar.show() : bar.hide() }
  // เซ็ต visit id ลง field vid + refresh consult — หน่วง 1 tick กันเคส mount แรกที่ field ยังไม่ register
    // เซ็ต visit id ลง field vid + refresh consult + registry — หน่วง 1 tick กันเคส mount แรกที่ field ยังไม่ register
  setTimeout(() => {
    const vidVal = (row && row.vid && row.vid.value) ? String(row.vid.value) : ''
