// เกณฑ์ปกติ (ผู้ใหญ่) — นอกช่วง min-max = เตือนเหลือง (is-warning), แตะ dMin/dMax = แดง (is-danger)
// ปรับตัวเลขได้ที่นี่จุดเดียว
s.vsRules = {
  bp_h:  { min: 90, max: 140, dMin: 80, dMax: 180 },
  bp_l:  { min: 60, max: 90,  dMax: 110 },
  pulse: { min: 60, max: 100, dMin: 40, dMax: 130 },
  temp:  { min: 36, max: 37.4, dMin: 35, dMax: 38.5 },
  rr:    { min: 12, max: 20,  dMin: 8,  dMax: 30 }
}
s.vsClassForRec = (rec, name) => {
  const r = s.vsRules[name]
  const v = rec ? rec[name] : null
  if (!r || v == null || v === '') return ''
  if ((r.dMin != null && v <= r.dMin) || (r.dMax != null && v >= r.dMax)) return 'is-danger'
  if (v < r.min || v > r.max) return 'is-warning'
  return ''
}
s.vsClass = (name) => s.vsClassForRec(s.vsRec, name)
// BP ใช้ระดับที่แย่กว่าระหว่างตัวบน/ตัวล่าง
s.bpClassForRec = (rec) => {
  const c = [s.vsClassForRec(rec, 'bp_h'), s.vsClassForRec(rec, 'bp_l')]
  return c.indexOf('is-danger') >= 0 ? 'is-danger' : (c.indexOf('is-warning') >= 0 ? 'is-warning' : '')
}
s.bpClass = () => s.bpClassForRec(s.vsRec)
// สีเซลล์ตาราง VS ตาม threshold เดียวกับการ์ดสรุป — inline style (ไม่พึ่ง CSS class ที่ไม่มีนิยามใน cssCode)
s.vsCellStyle = (rec, name) => {
  const cls = name === 'bp' ? s.bpClassForRec(rec) : s.vsClassForRec(rec, name)
  if (cls === 'is-danger') return 'color:var(--el-color-danger);font-weight:600;'
  if (cls === 'is-warning') return 'color:var(--el-color-warning);font-weight:600;'
  return ''
}

