// ตัวเลขมาจาก process vx-engine ตัวเดียวกับสมุด (C12) — จอนี้ไม่คิดกฎเอง · แบบ: design/vaccine/vaccine-mockup.html emrHeader/vxCounts
const VX_ENGINE = '6ad5f14921fe5a1471b50fce'   // vx-engine
const VX_BOOK_FORM = '6ad60671481c196fbb33a0b4' // Vaccine Book (form_ui · C20)
s.vxData = null      // ผล engine ของคนไข้ปัจจุบัน · null = ยังไม่โหลด/โหลดไม่ได้ (แถบไม่ขึ้น)
s.vxFor = ''         // person id ที่ผลนี้เป็นของ — กันผลเก่ามาทับเมื่อสลับคนไข้เร็ว ๆ

s.vxLoad = (row) => {
