  s.vxData = null
  s.vxFor = personId
  if (!personId) return
  const form = field.getFormRef && field.getFormRef()
  if (!form || !form.userState) return
  e2Req(form, VX_ENGINE, { pid: personId }, (res) => {
    const r = res && res.data
    if (s.vxFor !== personId) return   // สลับคนไข้ไปแล้ว
    // engine ล้ม (เช่นไม่มีวันเกิด) = ไม่ขึ้นแถบ · ไม่เด้ง error ทับจอหมอ — เปิดสมุดแล้วจะเห็นเหตุผลเอง
    s.vxData = r && r.success ? r.data : null
  }, () => { if (s.vxFor === personId) s.vxData = null })
}

// นับเหมือน vxCounts ของ mockup: เลยกำหนด/ถึงกำหนด = วัคซีนจำเป็น + ทางเลือกที่เริ่มแล้ว (engine นับให้ใน counts)
// หมอต้องยืนยัน / แนะนำเพิ่ม = ทุก antigen
s.vxCounts = () => {
  const d = s.vxData
  if (!d) return { over: 0, due: 0, cau: 0, rec: 0 }
  const all = (d.grid || []).reduce((a, g) => a.concat(g.doses || []), [])
  return {
    over: (d.counts && d.counts.overdue) || 0,
    due: (d.counts && d.counts.due) || 0,
    cau: all.filter((x) => x.st === 'caution').length,
    rec: all.filter((x) => x.st === 'opt' && x.rec && x.can_give).length,
  }
}
// แถบไหนขึ้น (พี่เลือกข้อ 1 · 2026-10-19):
//   ''      = ไม่ขึ้น — ผู้ใหญ่ ≥ 18 ปี (ตาราง PIDST ครอบคลุมแค่เด็ก-วัยรุ่น · engine ตัดสินผู้ใหญ่ว่า BCG เลยกำหนด)
//             หรือมีประวัติแล้วแต่ไม่มีเรื่องต้องทำ (ครบแล้ว = ไม่รกหัวจอ · เปิดสมุดได้จากปุ่ม 💉 เสมอ)
//   'none'  = แถบเทา "ยังไม่มีประวัติในระบบ" — ยังไม่เคยลงประวัติฉีดสักเข็ม engine จะนับว่าเลยกำหนดทุกเข็ม
//             ⇒ ถ้าขึ้นตัวเลขเหลือง/แดงตอนนี้ หมอจะเห็นเตือนแทบทุกคนจนเลิกอ่าน (his ยังไม่มีประวัติฉีดสักแถว 10-19)
//   'alert' = แถบเหลืองตาม mockup emrHeader
const VX_ADULT_DAYS = Math.round(18 * 365.25)
s.vxStrip = () => {
  const d = s.vxData
  if (!d || !d.person || d.person.age_days >= VX_ADULT_DAYS) return ''
  if (!(d.shots || []).length) return 'none'
  const c = s.vxCounts()
  return c.over || c.due || c.cau || c.rec ? 'alert' : ''
}

