// สูตร LMS มาตรฐาน (WHO) — X_p จาก z-score, และย้อนกลับ z-score จาก X ที่วัดได้จริง
s.lmsToValue = (L, M, S, z) => (Math.abs(L) < 1e-8 ? M * Math.exp(S * z) : M * Math.pow(1 + L * S * z, 1 / L))
s.lmsToZ = (L, M, S, x) => (Math.abs(L) < 1e-8 ? Math.log(x / M) / S : (Math.pow(x / M, L) - 1) / (L * S))
s.BMI_SD_LINES = [-3, -2, -1.5, -1, 0, 1, 1.5, 2, 3]   // เส้น SD/Z-score ตาม BMI Chart for Thai Children by TSPE (thaipedendo.org)

// LMS ที่อายุใดๆ (เดือน) — interpolate เชิงเส้นระหว่างจุดที่มีจริง (ตารางไม่ได้ละเอียดทุกเดือนช่วง 2 ปีขึ้นไป)
s.lmsAt = (table, ageMo) => {
  if (ageMo <= table[0][0]) return table[0]
  const last = table[table.length - 1]
  if (ageMo >= last[0]) return last
  for (let i = 0; i < table.length - 1; i++) {
    const a = table[i], b = table[i + 1]
    if (ageMo >= a[0] && ageMo <= b[0]) {
      const t = (b[0] === a[0]) ? 0 : (ageMo - a[0]) / (b[0] - a[0])
      return [ageMo, a[1] + (b[1] - a[1]) * t, a[2] + (b[2] - a[2]) * t, a[3] + (b[3] - a[3]) * t]
    }
  }
  return last
}

s.ageMonthsBetween = (fromDate, toDate) => {
  if (!fromDate || !toDate) return null
  const a = field.dayjs(fromDate), b = field.dayjs(toDate)
  if (!a.isValid() || !b.isValid()) return null
  return b.diff(a, 'month', true)
}
s.currentAgeMonths = () => s.ageMonthsBetween(s.pt().birth_date, new Date())
s.isPediatricBmi = () => { const m = s.currentAgeMonths(); return m != null && m <= 228 }   // <= 19 ปี
s.bmiSexKey = () => (s.pt().p_gender === '2' ? 'girls' : 'boys')   // '2' = หญิง (genderLabel เดียวกับที่ใช้ทั้งไฟล์)

// ช่วงอายุของ "โปสเตอร์" ที่จะโชว์ — ยึดจุดตัดข้อมูลจริงที่ 60 เดือน (WHO สลับ curve fit ตรงนี้พอดี)
// เด็ก <5y เห็นกราฟ 0-5y, เด็ก >=5y เห็นกราฟ 5-19y (แบบเดียวกับโปสเตอร์จริงที่ TSPE ใช้แยกช่วงอายุ)
s.bmiChartAgeRange = () => {
  const k = (s.growthTab === 'bmi' && s.growthRangeKey) || null   // 🆕 9 ต.ค. ปุ่มสลับช่วงในแท็บ BMI
  if (k === '5-19') return [60, 228]
  if (k === '0-5') return [0, 60]
  const m = s.currentAgeMonths(); return (m != null && m >= 60) ? [60, 228] : [0, 60]
}

// เกณฑ์ overweight/obesity ของจริงจาก BMI Chart for Thai Children by TSPE (คนละเกณฑ์ระหว่างช่วงอายุ) —
// แสดงเป็นข้อมูลอ้างอิงในกราฟเท่านั้น ไม่เอาไปตัดสิน/ติดป้ายผลของคนไข้อัตโนมัติ (เหตุผลเดิม: อ่าน log 2026-08-03)
s.bmiDefinitionLines = () => {
  const [lo] = s.bmiChartAgeRange()
  return lo === 0
    ? ['Overweight: BMI SDS > +2 to +3', 'Obesity: BMI SDS > +3']
    : ['Overweight: BMI SDS > +1 to +2 or BMI ≥ 23-24.9 kg/m²', 'Obesity: BMI SDS > +2 or BMI ≥ 25 kg/m²']
}
// ความโปร่งใสเรื่อง data source: 0-5y ใช้ WHO ตรงกับที่ TSPE ใช้ แต่ 5-19y ต้นฉบับ TSPE ใช้ข้อมูลไทย
// (National Growth Reference 2020) คนละชุดกับ WHO Growth Reference ที่กราฟนี้ใช้ — บอกตรงๆ ในกราฟเลย
s.bmiSourceNote = () => {
  const [lo] = s.bmiChartAgeRange()
  return lo === 0
    ? 'BMI-for-age อ้างอิง: WHO Child Growth Standards (2006) — แหล่งเดียวกับที่ TSPE ใช้ในช่วงอายุนี้ · รูปแบบ/สีออกแบบให้ล้อตาม BMI Chart for Thai Children โดย TSPE'
    : 'BMI-for-age อ้างอิง: WHO Growth Reference (2007) — คำเตือน: กราฟต้นฉบับของ TSPE ช่วงอายุนี้ใช้ข้อมูล National Growth Reference 2020 (สำนักโภชนาการ) คนละชุดกับที่นี่ ตัวเลขอาจต่างเล็กน้อย'
}
s.bmiGrowthCurves = () => {
  const [lo, hi] = s.bmiChartAgeRange()
  return s.WHO_BMI_LMS[s.bmiSexKey()].filter((r) => r[0] >= lo && r[0] <= hi)
}

// จุด BMI จริงของเด็ก (อายุ ณ วันที่บันทึกแต่ละครั้ง, ไม่ใช่ index) — เฉพาะจุดที่อยู่ในช่วงโปสเตอร์ที่เลือก
s.bmiPatientPoints = () => {
  const [lo, hi] = s.bmiChartAgeRange()
  const bd = s.pt().birth_date
  return (s.bmiHistory || [])
    .map((r) => {
      const age = s.ageMonthsBetween(bd, r.created_at)
      return (age == null || r.bmi == null) ? null : { age, bmi: Number(r.bmi) }
    })
    .filter((p) => p && p.age >= lo && p.age <= hi)
    .sort((a, b) => a.age - b.age)
}

// วาดกราฟ BMI-for-age เอง — เส้นอ้างอิง P3/P15/P50/P85/P97 (จาก LMS จริงข้างบน) + เส้น BMI จริงของเด็กทับ
s.bmiApexOptions = () => {
  const curves = s.bmiGrowthCurves()
  const [lo, hi] = s.bmiChartAgeRange()
  const isGirl = s.bmiSexKey() === 'girls'
  const bg = isGirl ? '#fbe4ee' : '#e1f0f8'
  const gridColor = isGirl ? '#f2c2d9' : '#bfe0ef'

  const sdLines = s.BMI_SD_LINES
  const sdSeries = sdLines.map((z) => ({
    name: (z > 0 ? '+' + z : String(z)) + ' SD',
    data: curves.map((r) => ({ x: r[0], y: Math.round(s.lmsToValue(r[1], r[2], r[3], z) * 100) / 100 }))
  }))
  const ptPoints = s.bmiPatientPoints()
  const patientSeries = {
    name: 'BMI คนไข้',
    data: ptPoints.map((p) => ({ x: p.age, y: p.bmi }))
  }
  const series = sdSeries.concat([patientSeries])

  return {
    chart: {
      type: 'line',
      height: '100%',
      background: bg,
      toolbar: { show: true, tools: { download: false } },
      zoom: { enabled: true, type: 'x', autoScaleYaxis: true },
      animations: { enabled: false }
    },
    colors: sdLines.map(() => '#222222').concat(['#626aef']),
    stroke: {
      width: sdLines.map((z) => (z === 0 ? 3 : 1.3)).concat([3]),
      curve: 'straight'
    },
    markers: { size: sdLines.map(() => 0).concat([4]) },
    dataLabels: { enabled: false },
    grid: { borderColor: gridColor },
    legend: { show: true, position: 'right', fontSize: '11px', offsetY: 10 },
    tooltip: {
      shared: false,
      custom: function (opt) {
        const ser = opt.w.config.series[opt.seriesIndex]
        const pt = ser.data[opt.dataPointIndex]
        const ageYears = (pt.x / 12).toFixed(1)
        const color = (opt.w.config.colors && opt.w.config.colors[opt.seriesIndex]) || '#222222'
        return '<div style="background:#ffffff;color:#222222;padding:6px 10px;border-radius:4px;font-size:12px;border:1px solid #cccccc;box-shadow:0 2px 6px rgba(0,0,0,0.25);white-space:nowrap;">' +
          '<div style="font-weight:600;margin-bottom:2px;">' + ageYears + ' ปี</div>' +
          '<div><span style="display:inline-block;width:8px;height:8px;border-radius:50%;background:' + color + ';margin-right:4px;"></span>' + ser.name + ': ' + pt.y + '</div>' +
          '</div>'
      }
    },
    xaxis: {
      type: 'numeric',
      min: lo,
      max: hi,
      title: { text: 'อายุ (ปี)' },
      labels: { formatter: (v) => (v / 12).toFixed(0) },
      tooltip: { enabled: false }
    },
    yaxis: {
      title: { text: 'BMI (kg/m²)' },
      decimalsInFloat: 1
    },
    series: series
  }
}

s.bmiApexLoadTries = 0
s.mountBmiChart = () => {
  if (!s.bmiChartVisible || !s.bmiHistory || !s.bmiHistory.length) return   // 🆕 v3 ผู้ใหญ่/ไม่มีวันเกิดก็วาด (เดิมเฉพาะ ≤ 19 ปี)
  const el = s.bmiChartElNode
  const hasLib = (typeof ApexCharts !== 'undefined')
  if (s.bmiApexLoadTries === 0) {
    console.log('[BMI chart] mount attempt: container=' + (el ? 'found' : 'MISSING') + ' ApexCharts=' + (hasLib ? 'ready' : 'MISSING'))
  }
  if (!el || !hasLib) {
    s.bmiApexLoadTries++
    if (s.bmiApexLoadTries > 120) {
      const reason = !el ? 'ไม่พบ container element' : 'ApexCharts library ไม่พร้อมใช้งาน'
      console.error('[BMI chart] gave up after ' + s.bmiApexLoadTries + ' tries — container=' + (el ? 'found' : 'MISSING') + ' ApexCharts=' + (hasLib ? 'ready' : 'MISSING'))
      if (el) el.innerHTML = '<div style="padding:16px;color:#c0392b;font-size:12px;">โหลดกราฟไม่สำเร็จ: ' + reason + '</div>'
      return
    }
    setTimeout(s.mountBmiChart, 150)
    return
  }
  s.bmiApexLoadTries = 0
  if (s.bmiApexInstance) { s.bmiApexInstance.destroy(); s.bmiApexInstance = null }
  try {
    s.bmiApexInstance = new ApexCharts(el, s.growthBmiClassic() ? s.bmiApexOptions() : s.growthApexOptions())
    s.bmiApexInstance.render()
    console.log('[BMI chart] rendered ok')
  } catch (e) {
    el.innerHTML = '<div style="padding:16px;color:#c0392b;font-size:12px;">วาดกราฟผิดพลาด: ' + (e && e.message ? e.message : String(e)) + '</div>'
    console.error('[BMI chart] render error', e)
  }
}

s.bmiLatestZ = () => {
  const list = s.bmiHistory || []
  const rec = list.length ? list[list.length - 1] : null   // loadBmiHistory เรียง created_at ASC
  if (!rec || rec.bmi == null) return null
  const age = s.ageMonthsBetween(s.pt().birth_date, rec.created_at)
  if (age == null || age > 228) return null   // 🆕 v3 ผู้ใหญ่เกินตาราง BMI (เดิมผู้ใหญ่ไม่เคยมาถึงตรงนี้)
  const [, L, M, S] = s.lmsAt(s.WHO_BMI_LMS[s.bmiSexKey()], age)
  return { z: s.lmsToZ(L, M, S, Number(rec.bmi)), age, bmi: Number(rec.bmi) }
}

s.bmiHistoryLabels = () => (s.bmiHistory || []).map((r) => field.dayjs(r.created_at).format('DD/MM'))
s.bmiHistoryChartBmi = () => s.svgLineChart([
  { name: 'BMI', color: '#626aef', values: (s.bmiHistory || []).map((r) => (r.bmi == null ? null : Number(r.bmi))) }
], s.bmiHistoryLabels(), '')
s.bmiHistoryChartWeight = () => s.svgLineChart([
  { name: 'น้ำหนัก', color: '#e6a23c', values: (s.bmiHistory || []).map((r) => (r.weight == null ? null : Number(r.weight))) }
], s.bmiHistoryLabels(), ' กก.')
