s.growthIsAdult = () => { const m = s.currentAgeMonths(); return m != null && m > s.GROWTH_ADULT_MO }
// ช่วง "> 19 ปี" — มีเฉพาะผู้ใหญ่ · ไม่มีในแท็บรอบศีรษะ · แกนตามช่วงที่วัดจริง ±6 ด. (อย่างน้อย 12 ด.) ไม่งั้นจุดไปกองที่ขอบ
s.growthAdultRangeOf = (tab) => {
  if (!s.growthIsAdult() || tab === 'hc') return null
  const A = s.GROWTH_ADULT_MO
  const xs = s.growthPointsOf(tab).map((p) => p.x).filter((x) => x > A)
  const now = s.currentAgeMonths()
  const lo = Math.max(A, Math.floor((xs.length ? Math.min.apply(null, xs) : now) - 6))
  const hi = Math.max(lo + 12, Math.ceil((xs.length ? Math.max.apply(null, xs) : now) + 6))
  return { k: '19+', t: '> 19 ปี', lo: lo, hi: hi, adult: true }
}
s.growthRanges = () => {
  if (!s.growthAgeKnown()) return []   // ไม่มีวันเกิด = แกนวันที่ ไม่มีช่วงอายุให้เลือก
  const base = ({
    bmi: [{ k: '0-5', t: '0–5 ปี', lo: 0, hi: 60 }, { k: '5-19', t: '5–19 ปี', lo: 60, hi: 228 }],
    wt: [{ k: '0-2', t: '0–2 ปี', lo: 0, hi: 24 }, { k: '2-19', t: '2–19 ปี', lo: 24, hi: 228 }],
    ht: [{ k: '0-2', t: '0–2 ปี (ความยาว)', lo: 0, hi: 24 }, { k: '2-19', t: '2–19 ปี (ส่วนสูง)', lo: 24, hi: 228 }],
    hc: [{ k: '0-5', t: '0–5 ปี', lo: 0, hi: 60 }]
  })[s.growthTab] || []
  const ad = s.growthAdultRangeOf(s.growthTab)
  return ad ? base.concat([ad]) : base
}
// ช่วงตั้งต้นตามอายุปัจจุบัน — หลักเดียวกับ bmiChartAgeRange เดิม (แบ่งตามแผ่นโปสเตอร์ของ TSPE) · ผู้ใหญ่ = "> 19 ปี"
s.growthDefaultRange = (tab) => {
  const m = s.currentAgeMonths()
  if (m != null && m > s.GROWTH_ADULT_MO && tab !== 'hc') return '19+'
  if (tab === 'bmi') return (m != null && m >= 60) ? '5-19' : '0-5'
  if (tab === 'hc') return '0-5'
  return (m != null && m >= 24) ? '2-19' : '0-2'
}
s.growthRangeNow = () => s.growthRangeKey || s.growthDefaultRange(s.growthTab)
s.growthRange = () => {
  const list = s.growthRanges()
  const k = s.growthRangeNow()
  return list.find((r) => r.k === k) || list[0] || null
}
// แท็บ BMI ช่วง 0–5/5–19 ของคนที่มีวันเกิด = กราฟ BMI เดิมของพี่ (เส้น SD · Definition · z-score) · นอกนั้นใช้ growthApexOptions
s.growthBmiClassic = () => {
  if (s.growthTab !== 'bmi' || !s.growthAgeKnown()) return false
  const rg = s.growthRange()
  return !(rg && rg.adult)
}
// สีพื้นกล่องกราฟ (เดิมเขียนในเทมเพลต) — ไม่มีวันเกิด = เทา บอกว่าเป็นกราฟคนละแบบ
s.growthBoxBg = () => (!s.growthAgeKnown() ? '#f4f4f5' : s.bmiSexKey() === 'girls' ? '#fbe4ee' : '#e1f0f8')
s.remountGrowthChart = () => { s.bmiApexLoadTries = 0; s.mountBmiChart() }
s.setGrowthTab = (k) => {
  if (s.growthTab === k) return
  s.growthTab = k
  s.growthRangeKey = null
  s.remountGrowthChart()
}
s.setGrowthRange = (k) => {
  if (s.growthRangeNow() === k) return
  s.growthRangeKey = k
  s.remountGrowthChart()
}

// ตารางอ้างอิงที่อายุหนึ่ง ๆ (เดือน) ของแท็บนั้น — null = ช่วงนี้ยังไม่มีข้อมูลอ้างอิง
s.growthRefTable = (tab, ageMo) => {
  const sex = s.bmiSexKey()
  const W = s.WHO_GROWTH_LMS
  const T = s.TH_GROWTH_LMS
  if (tab === 'hc') return ageMo <= 60 ? W.hcfa[sex] : null
  if (tab === 'wt') return ageMo <= 60 ? W.wfa[sex] : (T.wfa ? T.wfa[sex] : null)
  if (tab === 'ht') return ageMo < 24 ? W.lfa[sex] : ageMo <= 60 ? W.hfa[sex] : (T.hfa ? T.hfa[sex] : null)
  return null
}
// แถว LMS ของเส้นอ้างอิงในช่วงที่เลือก — WHO ถึง 60 ด. แล้วต่อข้อมูลไทย (ถ้ามี) หลัง 60 ด.
s.growthCurveRows = () => {
  const tab = s.growthTab
  const rg = s.growthRange()
  if (!rg || rg.adult) return []
  const sex = s.bmiSexKey()
  const W = s.WHO_GROWTH_LMS
  const T = s.TH_GROWTH_LMS
  const thai = (t) => (t && t[sex] ? t[sex].filter((r) => r[0] > 60) : [])
  let rows = []
  if (tab === 'wt') rows = W.wfa[sex].concat(thai(T.wfa))
  else if (tab === 'ht') rows = rg.k === '0-2' ? W.lfa[sex] : W.hfa[sex].concat(thai(T.hfa))
  else if (tab === 'hc') rows = W.hcfa[sex]
  return rows.filter((r) => r[0] >= rg.lo && r[0] <= rg.hi)
}
s.growthVal = (r, f) => {
  const v = (r[f] == null || r[f] === '') ? null : Number(r[f])
  return (v == null || !isFinite(v) || v <= 0) ? null : v
}
// จุดวัดจริงตามอายุ — อายุ ณ วันที่บันทึก (created_at) · ค่าว่าง/0/ติดลบไม่นับ
s.growthPointsOf = (tab) => {
  const f = s.GROWTH_FIELD[tab]
  const bd = s.pt().birth_date
  if (!f) return []
  return (s.bmiHistory || [])
    .map((r) => {
      const v = s.growthVal(r, f)
      const age = s.ageMonthsBetween(bd, r.created_at)
      return (v == null || age == null || age < 0) ? null : { x: Math.round(age * 100) / 100, y: v }
    })
    .filter((p) => p)
    .sort((a, b) => a.x - b.x)
}
s.growthPoints = () => s.growthPointsOf(s.growthTab)
// จุดวัดจริงตามวันที่ — ใช้เมื่อไม่มีวันเกิด (x = เวลา ms)
s.growthDatePoints = () => {
  const f = s.GROWTH_FIELD[s.growthTab]
  if (!f) return []
  return (s.bmiHistory || [])
    .map((r) => {
      const v = s.growthVal(r, f)
      const d = r.created_at ? field.dayjs(r.created_at) : null
      return (v == null || !d || !d.isValid()) ? null : { x: d.valueOf(), y: v }
    })
    .filter((p) => p)
    .sort((a, b) => a.x - b.x)
}
s.growthAgeText = (m) => {
  const y = Math.floor(m / 12)
  const mo = Math.floor(m - y * 12)
  return (y ? y + ' ปี ' : '') + mo + ' ด.'
}
// z → เปอร์เซ็นไทล์ (normal CDF · Abramowitz-Stegun 7.1.26 · คลาดไม่เกิน 1.5e-7)
s.zToPercentile = (z) => {
  const x = Math.abs(z) / Math.SQRT2
  const t = 1 / (1 + 0.3275911 * x)
  const erf = 1 - (((((1.061405429 * t - 1.453152027) * t) + 1.421413741) * t - 0.284496736) * t + 0.254829592) * t * Math.exp(-x * x)
  return 50 * (1 + (z < 0 ? -erf : erf))
}
s.growthPctOf = (tab, ageMo, v) => {
  const tbl = s.growthRefTable(tab, ageMo)
  if (!tbl) return null
  const r = s.lmsAt(tbl, ageMo)
  const z = s.lmsToZ(r[1], r[2], r[3], v)
  return { z, p: s.zToPercentile(z) }
}
s.growthCaption = () => {
  const tab = s.growthTab
  if (!s.growthAgeKnown()) return 'ไม่มีวันเกิดของคนไข้ในระบบ — วาดตามอายุไม่ได้ จึงแสดงค่าที่วัดตามวันที่ (ไม่มีเส้นอ้างอิง)'
  const adult = s.growthIsAdult()
  const sex = s.bmiSexKey() === 'girls' ? (adult ? 'หญิง' : 'เด็กหญิง') : (adult ? 'ชาย' : 'เด็กชาย')
  const rg = s.growthRange()
  const zoom = ' · ลากในกราฟหรือใช้ปุ่มมุมขวาบนเพื่อซูม)'
  if (rg && rg.adult) return s.GROWTH_NAME[tab] + 'ตามอายุ (' + sex + ' · อายุเกิน 19 ปี — ไม่มีเส้นอ้างอิง แสดงค่าที่วัดตามอายุ' + zoom
  const tail = ' · เส้นเปอร์เซ็นไทล์ P3–P97 ล้อตาม Thai Growth Chart โดย TSPE' + zoom
  if (tab === 'wt') return 'Weight-for-age (' + sex + tail
  if (tab === 'ht') return (rg && rg.k === '0-2' ? 'Length-for-age · นอนวัด (' : 'Height-for-age · ยืนวัด (') + sex + tail
  if (tab === 'hc') return 'Head circumference-for-age (' + sex + tail
  return ''
}
s.growthSourceNote = () => {
  if (!s.growthAgeKnown()) return 'แก้วันเกิดในทะเบียนผู้ป่วยแล้ว กราฟจะกลับมาวาดตามอายุพร้อมเส้นอ้างอิง'
  const rg = s.growthRange()
  if (rg && rg.adult) return 'เกณฑ์อ้างอิงการเจริญเติบโต (WHO / TSPE) ครอบถึงอายุ 19 ปี — อายุเกินนี้ไม่มีเส้นอ้างอิง'
  const T = s.TH_GROWTH_LMS
  const who = 'WHO Child Growth Standards (2006) — แหล่งเดียวกับที่ TSPE ใช้ในช่วงอายุนี้'
  if (s.growthTab === 'hc') return 'อ้างอิง: ' + who + ' · รอบศีรษะมีเส้นอ้างอิงถึง 5 ปี'
  if (!rg || rg.k === '0-2') return 'อ้างอิง: ' + who
  const th = s.growthTab === 'wt' ? T.wfa : T.hfa
  return 'อ้างอิง 2–5 ปี: ' + who + ' · 5–19 ปี: ' +
    (th ? 'National Growth References 2020 (สำนักโภชนาการ กรมอนามัย)' : 'รอตารางข้อมูลเด็กไทย (National Growth References 2020 · สำนักโภชนาการ) — ช่วงนี้ยังไม่มีเส้นอ้างอิง')
}
s.growthLatestText = () => {
  const tab = s.growthTab
  const name = s.GROWTH_NAME[tab]
  const unit = s.GROWTH_UNIT[tab]
  if (!s.growthAgeKnown()) {
    const dp = s.growthDatePoints()
    if (!dp.length) return 'ยังไม่มีค่า' + name + 'ที่บันทึกไว้'
    const l = dp[dp.length - 1]
    return 'ค่าล่าสุด: ' + name + ' ' + l.y + ' ' + unit + ' เมื่อ ' + field.dayjs(l.x).format('DD/MM/YYYY')
  }
  const pts = s.growthPoints()
  if (!pts.length) {
    return (tab === 'hc' && (s.currentAgeMonths() || 0) > 60)
      ? 'อายุเกิน 5 ปี — รอบศีรษะมีเส้นอ้างอิงถึง 5 ปี (WHO / TSPE)'
      : 'ยังไม่มีค่า' + name + 'ที่บันทึกไว้'
  }
  const last = pts[pts.length - 1]
  const head = 'ค่าล่าสุด: ' + name + ' ' + last.y + ' ' + unit + ' ที่อายุ ' + s.growthAgeText(last.x)
  if (last.x > s.GROWTH_ADULT_MO) return head + ' · อายุเกิน 19 ปี ไม่มีเส้นอ้างอิง'
  const pc = s.growthPctOf(tab, last.x, last.y)
  if (!pc) return head + (tab === 'hc' ? ' · เกิน 5 ปี ไม่มีเส้นอ้างอิงรอบศีรษะ' : ' · ยังบอกเปอร์เซ็นไทล์ไม่ได้ (รอตารางข้อมูลเด็กไทย 5–19 ปี)')
  return head + ' · ≈ P' + Math.round(pc.p) + ' (z ' + (pc.z >= 0 ? '+' : '') + pc.z.toFixed(2) + ')'
}

// วาดกราฟทุกแบบที่ไม่ใช่ BMI เดิม — ทรงเดียวกับ bmiApexOptions (สีพื้นตามเพศ · zoom · tooltip)
//   เด็ก: เส้นเปอร์เซ็นไทล์ · ผู้ใหญ่ ("> 19 ปี"): ค่าที่วัดตามอายุ ไม่มีเส้น · ไม่มีวันเกิด: ค่าที่วัดตามวันที่ ไม่มีเส้น (พื้นเทา)
s.growthApexOptions = () => {
  const tab = s.growthTab
  const noAge = !s.growthAgeKnown()
  const rg = noAge ? null : s.growthRange()
  const plain = noAge || !rg || !!rg.adult   // ไม่มีเส้นอ้างอิง
  const isGirl = s.bmiSexKey() === 'girls'
  const bg = noAge ? '#f4f4f5' : isGirl ? '#fbe4ee' : '#e1f0f8'
  const gridColor = noAge ? '#e4e7ed' : isGirl ? '#f2c2d9' : '#bfe0ef'
  const P = plain ? [] : s.GROWTH_PCT
  const solid = (n) => n === 'P3' || n === 'P50' || n === 'P97'
  const rows = plain ? [] : s.growthCurveRows()
  const series = P.map((p) => ({
    name: p[0],
    data: rows.map((r) => ({ x: r[0], y: Math.round(s.lmsToValue(r[1], r[2], r[3], p[1]) * 100) / 100 }))
  }))
  const pts = noAge ? s.growthDatePoints() : s.growthPoints().filter((q) => q.x >= rg.lo && q.x <= rg.hi)
  series.push({ name: s.GROWTH_NAME[tab] + ' คนไข้', data: pts })
  // ช่วงที่ยังไม่มีเส้นอ้างอิง (5–19 ปี ระหว่างรอตารางไทย) — แถบเทาบอกตรง ๆ ไม่ปล่อยให้ดูเหมือนข้อมูลหาย
  const lastRef = rows.length ? rows[rows.length - 1][0] : (rg ? rg.lo : 0)
  const gap = !plain && tab !== 'hc' && rg.hi > lastRef
  const nRef = P.length
  // ไม่มีเส้นอ้างอิง ⇒ แกนตั้งเผื่อ ±10% (ไม่งั้นค่าต่างกันนิดเดียวดูขึ้นลงแรง)
  const ys = pts.map((q) => q.y)
  const yPad = plain && ys.length ? { min: Math.floor(Math.min.apply(null, ys) * 0.9), max: Math.ceil(Math.max.apply(null, ys) * 1.1) } : {}
  const xaxis = noAge
    ? { type: 'datetime', title: { text: 'วันที่วัด' }, labels: { datetimeUTC: false, format: 'dd/MM' }, tooltip: { enabled: false } }
    : rg.adult
      ? { type: 'numeric', min: rg.lo, max: rg.hi, tickAmount: Math.round((rg.hi - rg.lo) / 3), title: { text: 'อายุ (ปี)' },
        labels: { formatter: (v) => (v / 12).toFixed(1) }, tooltip: { enabled: false } }
      : { type: 'numeric', min: rg.lo, max: rg.hi,
        tickAmount: rg.hi - rg.lo <= 24 ? (rg.hi - rg.lo) / 2 : Math.min(17, (rg.hi - rg.lo) / 12),
        title: { text: rg.hi <= 24 ? 'อายุ (เดือน)' : 'อายุ (ปี)' },
        labels: { formatter: (v) => (rg.hi <= 24 ? String(Math.round(v)) : (v / 12).toFixed(0)) }, tooltip: { enabled: false } }
  return {
    chart: {
      type: 'line',
      height: '100%',
      background: bg,
      toolbar: { show: true, tools: { download: false } },
      zoom: { enabled: true, type: 'x', autoScaleYaxis: true },
      animations: { enabled: false }
    },
    colors: P.map((p) => (p[0] === 'P50' ? '#222222' : '#555555')).concat(['#626aef']),
    stroke: {
      width: P.map((p) => (p[0] === 'P50' ? 2.6 : solid(p[0]) ? 1.6 : 1.1)).concat([3]),
      dashArray: P.map((p) => (solid(p[0]) ? 0 : 5)).concat([0]),
      curve: 'straight'
    },
    markers: { size: P.map(() => 0).concat([5]) },
    dataLabels: { enabled: false },
    grid: { borderColor: gridColor },
    legend: { show: true, position: 'right', fontSize: '11px', offsetY: 10, showForSingleSeries: true },
    annotations: gap ? {
      xaxis: [{
        x: lastRef, x2: rg.hi, fillColor: '#909399', opacity: 0.12, borderColor: '#909399',
        label: { text: 'ยังไม่มีเส้นอ้างอิง: รอตารางข้อมูลเด็กไทย 2020', orientation: 'horizontal', position: 'top',
          style: { background: '#ffffff', color: '#606266', fontSize: '11px' } }
      }]
    } : {},
    tooltip: {
      shared: false,
      custom: function (opt) {
        const ser = opt.w.config.series[opt.seriesIndex]
        const pt = ser.data[opt.dataPointIndex]
        const color = (opt.w.config.colors && opt.w.config.colors[opt.seriesIndex]) || '#222222'
        const pc = (!plain && opt.seriesIndex === nRef) ? s.growthPctOf(tab, pt.x, pt.y) : null
        const when = noAge ? field.dayjs(pt.x).format('DD/MM/YYYY') : s.growthAgeText(pt.x)
        return '<div style="background:#ffffff;color:#222222;padding:6px 10px;border-radius:4px;font-size:12px;border:1px solid #cccccc;box-shadow:0 2px 6px rgba(0,0,0,0.25);white-space:nowrap;">' +
          '<div style="font-weight:600;margin-bottom:2px;">' + when + '</div>' +
          '<div><span style="display:inline-block;width:8px;height:8px;border-radius:50%;background:' + color + ';margin-right:4px;"></span>' +
          ser.name + ': ' + pt.y + ' ' + s.GROWTH_UNIT[tab] + (pc ? ' · ≈ P' + Math.round(pc.p) : '') + '</div>' +
          '</div>'
      }
    },
    xaxis: xaxis,
    yaxis: Object.assign({ title: { text: s.GROWTH_YTITLE[tab] }, decimalsInFloat: 1 }, yPad),
    series: series
  }
}

// ---- กราฟ Vital Sign (BP/Pulse/Temp/RR) — เปิดจากไอคอน TrendCharts ข้างดินสอ Vital Sign ----
s.vsChartVisible = false
s.openVsChart = () => { s.vsChartVisible = true; s.loadVsHistory() }
s.closeVsChart = () => { s.vsChartVisible = false }
s.vsTableRows = () => {
  let list = (s.vsHistory || []).slice()
  if (s.vsFilterMode.type === 'count') {
    list = list.slice(-s.vsFilterMode.value)
  } else {
    list = list.filter((r) => field.dayjs().diff(field.dayjs(r.created_at), 'month', true) <= s.vsFilterMode.value)
  }
  return list.reverse().map((r) => {
    const d = field.dayjs(r.created_at)
    return {
      rec: r,
      dateLabel: d.format('DD/MM/') + (d.year() + 543) + d.format(' HH:mm'),
      vn: (r.vid && r.vid.vn) || '-'
    }
  })
}

// ---- timer เวลาตรวจ — นับจาก start_at (stamp ตอนกดเริ่มตรวจ) เท่านั้น ----
// ยังไม่เริ่มตรวจ = '--:--' (ไม่ fallback checkin_at — นั่นคือเวลารอ ไม่ใช่เวลาตรวจ)
s.examClock = '--:--'
s.tickExam = () => {
  const t = s.tran && s.tran.start_at
  if (!t) { s.examClock = '--:--'; return }
  const sec = Math.max(0, Math.floor((new Date() - new Date(String(t).replace(' ', 'T'))) / 1000))
  const h = Math.floor(sec / 3600)
  const mm = String(Math.floor((sec % 3600) / 60)).padStart(2, '0')
  const ss = String(sec % 60).padStart(2, '0')
  s.examClock = h > 0 ? h + ':' + mm + ':' + ss : mm + ':' + ss
}

/* ── allergy-tag.snippet · ป้ายแพ้ยา emoji → ไอคอน SVG ของระบบ (2026-10-01) ──────────────
   ต้นฉบับ: sdform/cpoe/allergy-tag.snippet.js — แก้ที่นี่แล้ววางทับทุกจอที่ใช้
     (pt_header ของ Drug Order + Item Order · opd_card ของ EMR · emr_view · patient_history)
   ป้ายใน DB ยังเป็นข้อความ "💊 paracetamol 🔴" (api-checkin · api-tran-update · cpoe-allergy-sync)
   🔴 emoji เป็นแค่รหัสในข้อมูล — จอแปลงเป็นไอคอน + ป้ายระดับ ผู้ใช้ไม่เห็น emoji (พี่เคาะแบบ A 2026-10-01)
      วิสิทเก่าทุกวันเก็บรูปเดียวกัน ⇒ แสดงแบบใหม่ได้ทันทีโดยไม่ต้องย้ายข้อมูล
   🔴 อ่านรหัสไม่ออก = แสดงข้อความตามที่เก็บ ห้ามตัดทิ้ง — ป้ายแพ้ยาหายจากจอ อันตรายกว่าหน้าตาไม่สวย */
const ALG_TYPE = [
	{ mark: '💊', icon: 'addon-capsule-pill', label: 'แพ้ยา' },
	{ mark: '🍤', icon: 'el-food', label: 'แพ้อาหาร' },
	// ⚠️ มี 2 รูปในข้อมูลจริงได้ (มี/ไม่มี variation selector U+FE0F) — ตัวยาวต้องเช็คก่อน
	{ mark: '⚠️', icon: 'el-warning', label: 'อื่น ๆ / ภาวะของผู้ป่วย' },
	{ mark: '⚠', icon: 'el-warning', label: 'อื่น ๆ / ภาวะของผู้ป่วย' },
];
// key = class ของ .pcard-sev ใน initcraft/src/styles/index.scss (ไม่มี class = สีแดง) · tag = type ของ el-tag
const ALG_LVL = [
	{ mark: '🔴', key: 'severe', label: 'รุนแรง', tag: 'danger' },
	{ mark: '🟠', key: 'moderate', label: 'ปานกลาง', tag: 'warning' },
	{ mark: '🟡', key: 'mild', label: 'เล็กน้อย', tag: 'info' },
];
s.algOf = (raw) => {
	let text = String(raw == null ? '' : raw).trim();
	const type = ALG_TYPE.find((t) => text === t.mark || text.startsWith(t.mark + ' '));
	if (type) text = text.slice(type.mark.length).trim();
	const lvl = ALG_LVL.find((l) => text.endsWith(' ' + l.mark));
	if (lvl) text = text.slice(0, -lvl.mark.length).trim();
	return {
		name: text,
		icon: type ? type.icon : 'el-warning',
		title: (type ? type.label : 'แพ้') + (lvl ? ' · ระดับ' + lvl.label : ''),
		sev: lvl ? lvl.key : '',
		sevLabel: lvl ? lvl.label : '',
		tagType: lvl ? lvl.tag : 'danger',
	};
};
s.algList = (tags) => (Array.isArray(tags) ? tags : tags ? [tags] : []).map(s.algOf).filter((a) => a.name);
/* ── end allergy-tag.snippet ── */

/* emr2-full — ปุ่มขยาย/ย่อของ EMR v2 (gen-emr-v2-model.cjs แทรกให้ · อย่าแก้ในบิลเดอร์) */
// สถานะเต็มจออยู่ที่ emr2_soap (vueState reactive ⇒ ไอคอนเปลี่ยนเอง) · หา widget ไม่เจอ = ปุ่มกดแล้วเงียบ
const emr2W = () => {
  const w = field.getFieldRef('emr2_soap');
  return w && w.vueState ? w.vueState : null;
};
s.emr2IsFull = () => { const v = emr2W(); return !!(v && v.e2Full); };
s.emr2ToggleFull = () => { const v = emr2W(); if (v && v.e2ToggleFull) v.e2ToggleFull(); };
/* /emr2-full */

/* emr2-head — หัวคนไข้ EMR v2 (gen-emr-v2-model.cjs ต่อท้าย onCreated ของ opd_card ให้ · อย่าแก้ในบิลเดอร์) */
// ป้ายสิทธิ: โชว์แค่ "( OFC ) O1" · ชื่อเต็มขึ้นเป็น tooltip (พี่สั่ง 2026-10-23)
// รูปแบบใน zdata_visit_tran.pttype: "( OFC ) O1 สิทธิเบิกกรมบัญชีกลาง(ข้าราชการ)" · ข้อมูลเก่าบางแถวมีแค่ "OFC"
// ⇒ แยกได้ = code · แยกไม่ได้ = ทั้งข้อความ (tooltip ปิดเอง เพราะไม่มีอะไรเพิ่ม)
const EMR2_INS_RE = /^(\(\s*[^)]*\)\s*\S+)\s+\S/;
s.emr2InsCode = (t) => {
  const text = String(t == null ? '' : t).trim();
  const m = text.match(EMR2_INS_RE);
  return m ? m[1] : text;
};
s.emr2InsFull = (t) => String(t == null ? '' : t).trim() !== s.emr2InsCode(t);

// กดป้ายวัคซีน → สลับช่องขวาไปแท็บวัคซีน + กระพริบที่หัวแท็บ "วัคซีน" ให้เห็นว่ากดแล้ว (พี่สั่ง 2026-10-23 · เดิมเปิดสมุดวัคซีน)
// สมุดเต็มยังเปิดได้จากปุ่ม "สมุดเต็ม" ในแท็บ · ไม่เจอแท็บ (ฟอร์มอื่นที่ยืมหัวนี้) = เปิดสมุดแบบเดิม
// 🔴 document ถูก shadow ในโค้ด event → globalThis.document (CLAUDE.md กับดักข้อ 4)
const EMR2_ORDER_TABS = 'emr2_order_tabs';
const EMR2_VX_PANE = 'emr2_tab_vx';
s.emr2OpenVxTab = () => {
  const form = field.getFormRef();
  const tabs = form && form.getFieldRef ? form.getFieldRef(EMR2_ORDER_TABS) : null;
  if (!tabs) { s.openVxBook(); return; }
  tabs.activeTabName = EMR2_VX_PANE;
  // หัวแท็บของ el-tabs มี id = "tab-<ชื่อ pane>" (พี่ชี้ให้กระพริบตรงนี้ ไม่ใช่ทั้งกรอบ)
  const box = globalThis.document.getElementById('tab-' + EMR2_VX_PANE);
  if (!box) return;
  // ถอดคลาสก่อน + บังคับ reflow ⇒ กดซ้ำระหว่างแอนิเมชันยังกระพริบใหม่ได้
  box.classList.remove('emr2-flash');
  void box.offsetWidth;
  box.classList.add('emr2-flash');
  setTimeout(() => box.classList.remove('emr2-flash'), 2800); // 3 รอบ × 0.9 วิ (emr2-orders.css) + เผื่อ
  if (box.scrollIntoView) box.scrollIntoView({ block: 'nearest', behavior: 'smooth' });
};
/* /emr2-head */

/* emr2-req-addon — EMR v2 (gen-emr-v2-model.cjs ต่อท้ายให้ · อย่าแก้ในบิลเดอร์) */
/* emr2-req — รวม request ที่ซ้ำกันระหว่าง widget (B2 · 2026-10-24)
   วัดจอจริง: เปิดคนไข้ยิง process เดียวกัน params เดียวกันพร้อมกันหลายตัว (vx-engine · emr-lab-board-get · cpoe-order-list)
   ⇒ request ที่ยังรอคำตอบอยู่ (หรือเพิ่งตอบไม่เกิน E2_REQ_REUSE_MS) ใช้คำตอบเดียวกัน · นอกนั้นยิงใหม่ตามปกติ
   🔴 ไม่ cache ยาว — หลังบันทึกใบแล้วโหลดใหม่ต้องได้ข้อมูลสด · ค่า 300ms กันแค่ตัวที่ยิงห่างกันนิดเดียวในรอบเปิดคนไข้
   ทุกตัวได้ res.data คนละชุด (copy) — widget แก้ข้อมูลของตัวเองได้โดยไม่กระทบตัวอื่น
   สมุดเก็บที่ form.$e2Req (ฟอร์มเดียวกัน = เห็นกัน) · gen-emr-v2-model.cjs ฝังไฟล์นี้ในแต่ละ widget ที่ใช้ — แก้ที่นี่แล้ว gen ใหม่ */
const E2_REQ_REUSE_MS = 300;
const e2Req = (form, procId, params, ok, err) => {
	if (!form || !form.userState) return;
	const key = `${procId} ${JSON.stringify(params || {})}`;
	const book = form.$e2Req || (form.$e2Req = {});
	const copy = (res) => (res && typeof res === 'object' && res.data !== undefined ? { ...res, data: JSON.parse(JSON.stringify(res.data)) } : res);
	// callback ของ widget หนึ่งพัง ต้องไม่ทำให้ตัวอื่นไม่ได้ข้อมูล
	const call = (fn, value) => {
		if (typeof fn !== 'function') return;
		try {
			fn(value);
		} catch (e) {
			globalThis.console.error('[e2Req]', procId, e);
		}
	};
	const hit = book[key];
	if (hit && hit.pending) {
		hit.waiters.push([ok, err]);
		return;
	}
	if (hit && Date.now() - hit.at < E2_REQ_REUSE_MS) {
		setTimeout(() => (hit.ok ? call(ok, copy(hit.res)) : call(err, hit.res)), 0);
		return;
	}
	const entry = { pending: true, waiters: [[ok, err]], at: Date.now(), ok: false, res: null };
	book[key] = entry;
	const settle = (isOk, res) => {
		entry.pending = false;
		entry.ok = isOk;
		entry.res = res;
		entry.at = Date.now();
		entry.waiters.forEach(([o, x], i) => (isOk ? call(o, i === 0 ? res : copy(res)) : call(x, res)));
	};
	form.userState.runProcess(procId, params, (res) => settle(true, res), (e) => settle(false, e));
};
/* /emr2-req-addon */

options.onMounted:
const form = this.getFormRef()
if (form && form.$examTran) {
  this.vueState.setTran(form.$examTran)
} else {
  // เปิดแท็บ EMR ตรงๆ โดยยังไม่กด EMR จากคิว → ซ่อนโซน SOAP
  const box = this.getFieldRef('emr_box')
  if (box) box.hide()
}

// เริ่มเดินนาฬิกา — กัน interval ซ้อนกรณี re-mount
const s = this.vueState
if (s.examTimerId) clearInterval(s.examTimerId)
s.tickExam()
s.examTimerId = setInterval(s.tickExam, 1000)

options.onCreated:
/**
 * m_history · onCreated — การ์ด "ประวัติการเจ็บป่วย" ในหน้า EMR (ฟอร์ม EMR 6a4f64e7f8cdfc54cec16488)
 *
 * วางที่: vue-ui `m_history` ในการ์ด `box_mhistory`
 * หน้าที่: ① เห็นโรคประจำตัว + การผ่าตัดของคนไข้ที่เปิดอยู่ ② กด "แก้ไข" เปิดจอแก้ (popup)
 *   ข้อมูลจริงอยู่ที่ฟอร์ม PERSON (zdata_person) — การ์ดนี้ **อ่านอย่างเดียว** ไม่เขียน DB เอง
 *
 * 🔴 การ์ดนี้ query เอง ไม่หยิบจาก tran.vid.pid ที่ opd_card ถืออยู่ —
 *    pid ใน visit เป็น snapshot ตอนรับบริการ (มีแค่ ชื่อ/เพศ/วันเกิด) ไม่มี ailment_main/or_main
 *    person _id ที่ใช้ query อยู่ที่ tran.vid.xtbxlv1_xfx_id (parent ของ visit = person)
 * 🔴 ทุก key ที่เทมเพลตอ้างต้องมีค่าตั้งแต่ตรงนี้ — ขาดตัวเดียว = error box ทั้ง widget
 */

const s = this.vueState;
const field = this;

const HISTORY_FORM_ID = '6a940562422c1ca959829d51'; // จอ "ประวัติการเจ็บป่วย" (form_ui)
const GET_PROC = '6a94062170aba128180fbce9'; // person-history-get

/* ══ state ════════════════════════════════════════════════════════════════ */
s.mhPid = null; // person _id ปัจจุบัน
s.mhName = ''; // ชื่อคนไข้ — ไม่ได้โชว์บนการ์ด (opd_card โชว์อยู่แล้ว) เก็บไว้ส่งต่อให้จอแก้ไข
s.mhStamp = ''; // ข้อความ "อัปเดต …" บนหัวการ์ด (บรรทัดบน)
s.mhBy = ''; // ชื่อคนที่แก้ล่าสุด (บรรทัดล่าง — ตัดอีเมลออกแล้ว)
s.mhStampTip = ''; // ข้อความเต็มไว้ hover (ชื่อ+อีเมล และบอกว่าเป็นเวลาของอะไร)
s.mhAilment = [];
s.mhOr = [];
s.mhLoading = false;
s.mhErr = '';
s.mhDirty = false; // จอแก้แตะข้อมูลใน DB แล้วหรือยัง — ตัวตัดสินว่าตอนปิด popup ต้องโหลดใหม่ไหม

s.mhYear = (n) => (n === null || n === undefined || n === '' ? '' : Number(n) + ' ปี');

// "2026-08-30 17:34:53" → "30/08/2569 17:34" (แสดงเป็น พ.ศ. ตาม convention ของระบบ)
s.mhWhen = (v) => {
	const t = String(v || '');
	if (t.length < 16) return '';
	return t.slice(8, 10) + '/' + t.slice(5, 7) + '/' + (Number(t.slice(0, 4)) + 543) + ' ' + t.slice(11, 16);
};

/* ประกอบข้อความเวลาอัปเดต
   🔴 ต้องแยกให้ออกว่าเป็นเวลาของ "ประวัติ" หรือของ "ทั้งระเบียน"
      record เก่าที่ไม่เคยแก้ผ่านจอนี้ไม่มี history_updated_at ⇒ ตกไปใช้เวลาแก้ทั้งระเบียน
      ซึ่งขยับตอนเวชระเบียนแก้ที่อยู่/สิทธิด้วย — ถ้าไม่บอกกำกับ คนอ่านจะเข้าใจผิดว่าประวัติเพิ่งถูกแก้ */
/* ชื่อผู้แก้มาได้ 2 รูป: { value, label } (select-data-input ของฟอร์ม PERSON)
   หรือ { id, name } (updated_by ที่ระบบเขียนให้ทุก record) ⇒ รับทั้งคู่
   ตัด "(อีเมล)" ท้ายชื่อออก — คอลัมน์การ์ดแคบ ชื่อเต็มพร้อมอีเมลกินที่จนอ่านไม่ออก (ดูเต็มได้ที่ hover) */
const nameOf = (by) => {
	const raw = String((by && (by.label || by.name || by.username)) || '').trim();
	return raw.replace(/\s*\([^)]*@[^)]*\)\s*$/, '').trim();
};
s.mhSetStamp = (d) => {
	const hist = s.mhWhen(d.history_updated_at);
	if (hist) {
		s.mhStamp = 'อัปเดต ' + hist;
		s.mhBy = nameOf(d.history_updated_by);
		s.mhStampTip = 'แก้ประวัติล่าสุดโดย ' + (String((d.history_updated_by && (d.history_updated_by.label || d.history_updated_by.name)) || 'ไม่ทราบ'));
		return;
	}
	const rec = s.mhWhen(d.record_updated_at);
	if (rec) {
		// ยังไม่เคยแก้ผ่านจอนี้ → เวลานี้เป็นของทั้งระเบียน ต้องกำกับไว้ ไม่งั้นอ่านเป็น "ประวัติเพิ่งถูกแก้"
		s.mhStamp = 'อัปเดต ' + rec + ' (ทั้งระเบียน)';
		s.mhBy = nameOf(d.record_updated_by);
		s.mhStampTip = 'ยังไม่เคยแก้ประวัติผ่านจอนี้ — นี่คือเวลาแก้ระเบียนผู้ป่วยล่าสุด โดย ' + (String((d.record_updated_by && (d.record_updated_by.label || d.record_updated_by.name)) || 'ไม่ทราบ'));
		return;
	}
	s.mhStamp = '';
	s.mhBy = '';
	s.mhStampTip = '';
};

/* ══ โหลดประวัติของคนไข้ ══════════════════════════════════════════════════
   เรียกจาก opd_card.setTran (เปลี่ยนคนไข้) · onMounted (เข้าแท็บ EMR ทีหลัง) · หลังปิด popup */
s.mhLoad = (personId, ptName) => {
	s.mhPid = personId ? String(personId) : null;
	if (ptName !== undefined) s.mhName = ptName || '';
	s.mhAilment = [];
	s.mhOr = [];
	s.mhErr = '';
	s.mhStamp = '';
	s.mhBy = '';
	s.mhStampTip = '';
	if (!s.mhPid) return;

	const form = field.getFormRef();
	if (!form) return;

	s.mhLoading = true;
	form.userState.runProcess(
		GET_PROC,
		{ person_id: s.mhPid },
		(res) => {
			s.mhLoading = false;
			const d = (res && res.data) || {};
			// process ที่ตีกลับด้วย success:false ก็มาทาง callback นี้ ไม่ใช่ errCb — ต้องเช็คเอง
			if (!d.success) {
				s.mhErr = d.message || 'อ่านประวัติการเจ็บป่วยไม่สำเร็จ';
				return;
			}
			s.mhAilment = Array.isArray(d.ailment_main) ? d.ailment_main : [];
			s.mhOr = Array.isArray(d.or_main) ? d.or_main : [];
			s.mhSetStamp(d);
		},
		(err) => {
			s.mhLoading = false;
			s.mhErr = 'อ่านประวัติการเจ็บป่วยไม่สำเร็จ: ' + ((err && err.message) || err);
		}
	);
};

// ดึง context คนไข้จาก tran ที่ opd_card เซ็ตไว้ที่ form.$examTran (แหล่งเดียวกับการ์ดใบสั่งยา)
s.mhLoadFromTran = (tran) => {
	const visit = (tran && tran.vid) || null;
	const pt = (visit && visit.pid) || {};
	const personId = visit && visit.xtbxlv1_xfx_id ? String(visit.xtbxlv1_xfx_id) : null;
	const name = [(pt.prename && pt.prename.label) || '', pt.p_fname || '', pt.p_lname || ''].join(' ').trim();
	s.mhLoad(personId, name);
};

s.mhReload = () => s.mhLoad(s.mhPid, undefined);

/* ══ เปิดจอแก้ไข ══════════════════════════════════════════════════════════
   🔴 refresh เฉพาะตอนที่ "ข้อมูลเปลี่ยนจริง" — cancelCallback เป็นทางออกทางเดียวของ popup
      ทั้งกดปิดเฉยๆ และบันทึกแล้วปิด ⇒ ให้จอเป็นคนบอกผ่าน callback ที่ฝากไปกับ params */
s.mhEdit = () => {
	if (!s.mhPid) return;
	const form = field.getFormRef();
	if (!form) return;
	s.mhDirty = false;
	form.openForm(HISTORY_FORM_ID, '', '', null, {
		// 🔴 ต้อง spread formParams ของแม่ ไม่งั้น popup ไม่เหลือ _id/xsitex/xunitx (ระบบใช้ตัดสิน site/unit)
		params: Object.assign({}, form.formParams, {
			person_id: s.mhPid,
			pt_name: s.mhName,
			on_history_saved: () => {
				s.mhDirty = true;
			},
		}),
		// 🔴 ใส่ cancelCallback เอง = ทับ default ⇒ ต้อง subFormClose() เองด้วย
		cancelCallback: () => {
			form.subFormClose();
			if (!s.mhDirty) return; // ปิดเฉยๆ — ที่แสดงอยู่ยังตรงกับ DB
			s.mhDirty = false;
			s.mhReload();
		},
	});
};

/* emr2-hist-addon — EMR v2 (gen-emr-v2-model.cjs ต่อท้ายให้ · อย่าแก้ในบิลเดอร์) */
/* ══ emr2-pmh addon — EMR v2 การ์ด PMH (m_history) · generator ต่อท้าย onCreated ของ m_history ใน v2 เท่านั้น ══════
   ใช้ `s` ของ m_history — ห้ามประกาศซ้ำ
   "เป็นมา / ผ่ามา" คิดจากวันที่ (ailment_date / or_date · พี่เพิ่มในฟอร์ม PERSON 2026-10-23) เป็น "2y 3m 10d"
   รูปแบบเดียวกับอายุในฟอร์ม PERSON (onFormMounted ช่อง age) · ไม่มีวันที่ = ใช้จำนวนปีที่กรอกไว้ (mhYear เดิม) · พี่สั่ง 2026-10-23 */

// 'YYYY-MM-DD' → "2y 3m 10d" นับถึงวันนี้ · แยกเลขเอง ไม่ผ่าน new Date(string) กัน timezone เลื่อนวัน
// วันที่ในอนาคต / อ่านไม่ออก = '' (ให้ตกไปใช้จำนวนปี)
s.e2hSince = (v) => {
	const p = String(v || '').slice(0, 10).split('-').map(Number);
	if (p.length !== 3 || p.some((n) => !Number.isFinite(n) || n <= 0)) return '';
	const now = new Date();
	let y = now.getFullYear() - p[0];
	let m = now.getMonth() + 1 - p[1];
	let d = now.getDate() - p[2];
	if (d < 0) {
		m -= 1;
		d += new Date(now.getFullYear(), now.getMonth(), 0).getDate(); // ยืมวันจากเดือนก่อนหน้า (จำนวนวันจริงของเดือนนั้น)
	}
	if (m < 0) {
		m += 12;
		y -= 1;
	}
	return y < 0 ? '' : y + 'y ' + m + 'm ' + d + 'd';
};

// แถวโรค/ผ่าตัด → ข้อความหลัง "เป็นมา / ผ่ามา" · dateKey = ailment_date | or_date · yearKey = ailment_y | or_y
s.e2hDur = (row, dateKey, yearKey) => (row && s.e2hSince(row[dateKey])) || s.mhYear(row && row[yearKey]);

/* ตัวนับบนหัวการ์ด (พี่เลือกข้อ A 2026-10-24) — โรคประจำตัว + ผ่าตัด รวมกัน · 0 = ไม่แสดง
   หัวการ์ดวาดโดย card-render ของแพลตฟอร์ม (มีแค่ label/subLabel) ⇒ เขียน data-e2h-n ลง .wcard-title แล้ว CSS วาดเม็ด (::after)
   ท่าเดียวกับ orders/tab-count.js · คลาส e2h-pmh-card generator ใส่ให้การ์ด box_mhistory
   🔴 document ถูก shadow ในโค้ด event (CLAUDE.md กับดักข้อ 4) → globalThis.document */
const e2hPmhPaint = (n) => {
	const doc = globalThis.document;
	const el = doc && doc.querySelector('.el-card.e2h-pmh-card .wcard-title');
	if (!el) return;
	if (n > 0) el.setAttribute('data-e2h-n', String(n));
	else el.removeAttribute('data-e2h-n');
};
if (typeof field.$watch === 'function') {
	// watch ของ component หยุดเองตอน unmount · flush post = หัวการ์ดวาดเสร็จก่อนค่อยเขียน
	field.$watch(() => (s.mhPid ? (s.mhAilment || []).length + (s.mhOr || []).length : 0), e2hPmhPaint, { immediate: true, flush: 'post' });
}
/* /emr2-hist-addon */

/* emr2-once-addon — EMR v2 (gen-emr-v2-model.cjs ต่อท้ายให้ · อย่าแก้ในบิลเดอร์) */
{
/* emr2-once — กันโหลดซ้ำตอนเปิดคนไข้ครั้งแรก (B1 · วัดจอจริง 2026-10-24: เปิดครั้งแรก 30 request · เปิดซ้ำ 15)
   ต้นเหตุ: ตอน mount ครั้งแรก widget ถูกสั่งโหลด 2 ทางพร้อมกัน
     ① opd_card.onMounted → setTran($examTran) → ไล่สั่งทุกการ์ด (ทาง "feed" · opd_card ติดธง form.$e2Feed ระหว่างไล่)
     ② onMounted ของ widget เอง อ่าน $examTran แล้วโหลดเอง
   ⇒ ห่อฟังก์ชันโหลด: อีกทางเพิ่งโหลด visit เดียวกันไม่เกิน E2_ONCE_MS = ข้าม
      ทางเดียวกันเรียกซ้ำ (กดโหลดใหม่ · หลังบันทึก · WS) ไม่ข้าม · เปลี่ยนคนไข้ (visit ต่าง) ไม่ข้าม
   gen-emr-v2-model.cjs ฝังไฟล์นี้ต่อท้าย onCreated ของแต่ละ widget (ในบล็อก { } ชื่อไม่ชนโค้ดเดิม) — แก้ที่ไฟล์นี้แล้ว gen ใหม่ */
const E2_ONCE_MS = 2000;
const e2OnceWrap = (widget, name, fnName, vidOf) => {
	const st = widget.vueState;
	const orig = st[fnName];
	if (typeof orig !== 'function' || orig.e2Once) return;
	const key = `${name}.${fnName}`;
	const wrapped = (...args) => {
		const form = widget.getFormRef && widget.getFormRef();
		const raw = vidOf(...args);
		const vid = raw ? String(raw) : '';
		if (form && vid) {
			const fromFeed = form.$e2Feed === true;
			const seen = form.$e2Loaded || (form.$e2Loaded = {});
			const last = seen[key];
			const now = Date.now();
			if (last && last.vid === vid && last.fromFeed !== fromFeed && now - last.at < E2_ONCE_MS) return undefined;
			seen[key] = { vid, fromFeed, at: now };
		}
		return orig(...args);
	};
	wrapped.e2Once = true;
	st[fnName] = wrapped;
};
e2OnceWrap(this, 'm_history', 'mhLoadFromTran', (tran) => tran && tran.vid && tran.vid.value);
}
/* /emr2-once-addon */

options.onMounted:
const field = this;
const s = this.vueState;
// เคสแท็บ EMR mount หลังกดเลือกคนไข้จากคิวไปแล้ว → opd_card.setTran ยิงไปก่อนที่การ์ดนี้จะเกิด
// ⇒ ดึง tran จาก form เองรอบแรก (pattern เดียวกับ order_card / item_card)
setTimeout(() => {
	const form = field.getFormRef();
	s.mhLoadFromTran((form && form.$examTran) || null);
}, 0);

options.onCreated:
/**
 * treat_summary · onCreated — การ์ด "สรุปการรักษา" ในหน้า EMR (ฟอร์ม EMR 6a4f64e7f8cdfc54cec16488)
 *
 * วางที่: vue-ui `treat_summary` ในการ์ด `card62530`
 * หน้าที่: เห็นว่า "ครั้งก่อนรักษาอะไรไป" — CC / วินิจฉัย / ยา + sig / แผนการรักษา
 *          และผล Lab · X-ray ล่าสุดของคนไข้ (2 อย่างหลังไม่ผูก visit — ผูกด้วย HN)
 *
 * 🔴 ข้อมูลมาจาก snapshot ฟอร์ม Visit History ไม่ได้ query ตารางต้นทางเอง (ดู skill add-visit-history)
 *    visit เก่าที่ยังไม่เคยมี snapshot → process จะ build ให้เองครั้งแรกที่เปิด (คืน built:true)
 * 🔴 ทุก key ที่เทมเพลตอ้างต้องมีค่าตั้งแต่ตรงนี้ — ขาดตัวเดียว = error box ทั้ง widget
 * 🔴 `tsUi` ต้องเป็น object เพราะเทมเพลตใช้ v-model="tsUi.tab" (scope proxy ไม่มี set trap ให้ตัวแปรเดี่ยว)
 */

const s = this.vueState;
const field = this;

const SUMMARY_PROC = '6a9574cc1812c7078a067299'; // emr-summary-get
const TS_XRAY_HISTORY_PROC = '6ad58d76481c196fbb339ae8'; // X-ray only; ไม่เปลี่ยน emr-lab-board-get
const TS_XRAY_RESULT_PDF_REPORT_ID = '6ab2d3e4f5061728394a5b6c'; // Xray result

/* ══ state ════════════════════════════════════════════════════════════════ */
s.tsPid = null; // person _id ของคนไข้ที่เปิดอยู่
s.tsHn = null;
s.tsCurVisit = null; // visit ที่กำลังตรวจ — ตัดออกจากผลลัพธ์ (การ์ดนี้เล่า "ครั้งก่อน")
s.tsVisit = null; // { visit_id, vn, visit_date, clinic, doctor, history_id }
s.tsVisitTip = '';
s.tsHasHistory = false;
s.tsCc = '';
s.tsHpi = '';
s.tsPe = null; // ตรวจร่างกายครั้งล่าสุดที่มีบันทึก
s.tsDx = [];
s.tsMeds = [];
s.tsOther = [];
s.tsPlan = null;
s.tsHasPlan = false; // มีเนื้อ 'แผนการรักษา' จริงไหม (คำแนะนำผู้ป่วยแยกหัวข้อ ไม่นับ)
s.tsLab = [];
s.tsXray = [];
s.tsLoading = false;
s.tsErr = '';
s.tsUi = { tab: 'med' };
s.tsXrayBoardOn = false;
s.tsXrayBoardLoading = false;
s.tsXrayBoardError = '';
s.tsXrayOrders = [];
s.tsXrayOrderOpen = {};
s.tsXrayReport = { visible: false, item: null, order: null, room: null };
s.tsXrayHistory = { visible: false, item: null, order: null, limit: 5 };
s.tsXrayPdfReportList = [{ reportId: TS_XRAY_RESULT_PDF_REPORT_ID, label: 'PDF', type: 'pdf' }];

// ทุกหัวข้อมาจาก visit ใบเดียวกัน (พี่เคาะ: เอาแค่ใบล่าสุด) ⇒ ที่มาโชว์ที่หัวการ์ดที่เดียวพอ
s.tsFrom = null;

// form id ไว้กดเปิด record ต้นทาง — process ส่งกลับมาด้วย เผื่อฟอร์มถูกย้าย/เปลี่ยน
s.tsDxFormId = '6a47a9cc8ca8083d715e3486';
s.tsLabFormId = '6a8bc91df851000f28e501fb';
s.tsXrayFormId = '6a860980f851000f28e44ab0';

// "2026-08-10 09:15:00" / "2026-08-10" → "10/08/2569" (+ เวลา ถ้ามี) — พ.ศ. ตาม convention ของระบบ
s.tsWhen = (v) => {
	const t = String(v || '');
	if (t.length < 10) return t;
	const d = t.slice(8, 10) + '/' + t.slice(5, 7) + '/' + (Number(t.slice(0, 4)) + 543);
	return t.length >= 16 ? d + ' ' + t.slice(11, 16) : d;
};

// "มาจากครั้งไหน" — โชว์สั้น ๆ ท้ายหัวข้อ (วันที่ + VN ถ้ามี)
s.tsFromText = (f) => {
	if (!f) return '';
	const d = s.tsWhen(f.visit_date);
	return f.vn ? d + ' · VN ' + f.vn : d;
};

// initCraft อาจสร้าง vue-ui ก่อน parent Form พร้อม: เลือก connector แบบ fail-safe
s.tsApi = () => {
	const form = field.getFormRef && field.getFormRef();
	const api = (form && form.userState) || field.globalUserState || null;
	return api && typeof api.runProcess === 'function' ? api : null;
};

/* ══ โหลดสรุป ═════════════════════════════════════════════════════════════
   เรียกจาก opd_card.setTran (เปลี่ยนคนไข้) · onMounted (เข้าแท็บ EMR ทีหลัง) */
s.tsLoad = (personId, hn, curVisitId) => {
	s.tsPid = personId ? String(personId) : null;
	s.tsHn = hn || null;
	s.tsCurVisit = curVisitId ? String(curVisitId) : null;
	s.tsVisit = null;
	s.tsVisitTip = '';
	s.tsHasHistory = false;
	s.tsCc = '';
	s.tsHpi = '';
	s.tsPe = null;
	s.tsDx = [];
	s.tsMeds = [];
	s.tsOther = [];
	s.tsPlan = null;
	s.tsHasPlan = false;
	s.tsLab = [];
	s.tsXray = [];
	s.tsXrayBoardOn = false;
	s.tsXrayBoardLoading = false;
	s.tsXrayBoardError = '';
	s.tsXrayOrders = [];
	s.tsXrayOrderOpen = {};
	s.tsXrayReport = { visible: false, item: null, order: null, room: null };
	s.tsXrayHistory = { visible: false, item: null, order: null, limit: 5 };
	s.tsErr = '';
	if (!s.tsPid && !s.tsHn) return;

	const api = s.tsApi();
	if (!api) {
		s.tsErr = 'ไม่พบ API Process connector';
		return;
	}

	s.tsLoading = true;
	if (s.tsXrayBoardLoad && s.tsCurVisit) s.tsXrayBoardLoad(s.tsCurVisit);
	api.runProcess(
		SUMMARY_PROC,
		{ person_id: s.tsPid, hn: s.tsHn, visit_id: s.tsCurVisit },
		(res) => {
			s.tsLoading = false;
			const d = (res && res.data) || {};
			// process ที่ตีกลับด้วย success:false มาทาง callback นี้เหมือนกัน ไม่ใช่ errCb
			if (!d.success) {
				s.tsErr = d.message || 'อ่านสรุปการรักษาไม่สำเร็จ';
				return;
			}
			s.tsHasHistory = !!d.has_history;
			s.tsVisit = d.visit || null;
			s.tsVisitTip = s.tsVisit
				? 'สรุปจากการรักษาวันที่ ' + s.tsWhen(s.tsVisit.visit_date) + ' (VN ' + (s.tsVisit.vn || '-') + ')' + (d.built ? ' · สร้างสรุปให้ตอนเปิดครั้งแรก' : '')
				: '';
			s.tsCc = d.cc || '';
			s.tsHpi = d.hpi || '';
			s.tsPe = d.pe || null;
			s.tsFrom = d.from || null;
			s.tsDx = Array.isArray(d.dx) ? d.dx : [];
			s.tsMeds = Array.isArray(d.meds) ? d.meds : [];
			s.tsOther = Array.isArray(d.other) ? d.other : [];
			s.tsPlan = d.plan || null;
			// หัวข้อ "แผนการรักษา" โผล่เฉพาะตอนมีเนื้อจริง — คำแนะนำผู้ป่วย (education) แยกหัวข้อของตัวเอง
			s.tsHasPlan = !!(s.tsPlan && (s.tsPlan.disposition || s.tsPlan.sick_leave_days || s.tsPlan.safety_net));
			s.tsLab = Array.isArray(d.lab) ? d.lab : [];
			s.tsXray = Array.isArray(d.xray) ? d.xray : [];
			s.tsAbsorb(d); // แท็บ Lab/X-Ray แบบจัดกลุ่ม — ดูบล็อกท้ายไฟล์
			if (d.lab_form_id) s.tsLabFormId = d.lab_form_id;
			if (d.xray_form_id) s.tsXrayFormId = d.xray_form_id;
			// ผู้ใช้ยืนยัน 19/10/2569: เปิดแท็บยาเป็นค่าเริ่มต้นเสมอ ไม่สลับตามข้อมูลที่มี
			s.tsUi.tab = 'med';
		},
		(err) => {
			s.tsLoading = false;
			s.tsErr = 'อ่านสรุปการรักษาไม่สำเร็จ: ' + ((err && err.message) || err);
		}
	);
};

// ดึง context คนไข้จาก tran ที่ opd_card เซ็ตไว้ที่ form.$examTran (แหล่งเดียวกับการ์ดอื่นในหน้านี้)
s.tsLoadFromTran = (tran) => {
	const visit = (tran && tran.vid) || null;
	const pt = (visit && visit.pid) || {};
	// person id อยู่ที่ chain ของ joiner (parent ของ visit = person) — pid ใน visit เป็น snapshot ไม่มี _id
	const personId = visit && visit.xtbxlv1_xfx_id ? String(visit.xtbxlv1_xfx_id) : null;
	s.tsLoad(personId, pt.hn || null, visit && visit.value ? String(visit.value) : null);
};

s.tsReload = () => s.tsLoad(s.tsPid, s.tsHn, s.tsCurVisit);

/* ══ เปิด record ต้นทาง ═══════════════════════════════════════════════════
   ทุกก้อนใน snapshot พก form_id + data_id มาด้วย ⇒ กดดูใบจริงได้จากทุกบรรทัด */
s.tsOpen = (formId, dataId) => {
	if (!formId || !dataId) return;
	const form = field.getFormRef();
	if (!form) return;
	form.openForm(String(formId), String(dataId), '', null, {
		// 🔴 ต้อง spread formParams ของแม่ ไม่งั้น popup ไม่เหลือ _id/xsitex/xunitx (ระบบใช้ตัดสิน site/unit)
		params: Object.assign({}, form.formParams),
		cancelCallback: () => form.subFormClose(),
	});
};

// เปิดจอ EMR History ของ visit ครั้งก่อนทั้งใบ (ก้อนที่การ์ดนี้ไม่ได้แสดง เช่น vital sign / ใบสั่งทุกใบ / การเงิน)
// 🔴 form_ui ไม่มี record ของตัวเอง ⇒ เปิดด้วย dataId ว่าง แล้วส่ง visit_id ไปทาง params
//    (จอนั้นหา snapshot เอง — ยังไม่มีก็ build ให้ ⇒ ไม่ต้องพึ่ง history_id ที่อาจยังไม่เกิด)
s.tsOpenVisit = () => {
	const EMR_HISTORY_FORM = '6a96557e422c1ca959829eae'; // จอ EMR History (form_ui อ่านอย่างเดียว)
	const visitId = s.tsVisit && s.tsVisit.visit_id;
	if (!visitId) return;
	const form = field.getFormRef();
	if (!form) return;
	const ctx = Object.assign({}, form.formParams, { visit_id: String(visitId), history_id: (s.tsVisit && s.tsVisit.history_id) || '' });
	form.openForm(EMR_HISTORY_FORM, '', '', ctx, {
		params: ctx,
		cancelCallback: () => form.subFormClose(),
	});
};


/**
 * treat_summary · แท็บ Lab / X-Ray แบบจัดกลุ่มตามใบสั่ง
 * ฟอร์ม EMR `6a4f64e7f8cdfc54cec16488` · widget vue-ui `treat_summary` (การ์ด `card62530`)
 *
 * ⬆️ ทุกอย่างเหนือบรรทัดนี้คือ onCreated เดิม **ไม่ถูกแก้เลยสักตัวอักษร**
 *    ยกเว้นบรรทัดเดียวใน callback ของ `tsLoad` ที่เติม `s.tsAbsorb(d);` เข้าไป
 * ⬇️ ตั้งแต่บรรทัดนี้ลงไปคือของใหม่ทั้งหมด — เพิ่มอย่างเดียว ไม่เขียนทับคีย์เดิมสักตัว
 *    (ยกเว้น `s.tsLoad` ที่ถูก "ห่อ" ไว้ท้ายไฟล์ ตัวเดิมยังถูกเรียกครบทุกครั้ง)
 *
 * 🔴 ต้องใช้คู่กับ Template ที่มีแท็บ Lab / X-Ray เวอร์ชันใหม่ — ถ้ายังเป็น Template เดิม
 *    ไฟล์นี้จะไม่ทำให้อะไรพัง แต่ก็ไม่เห็นผลอะไร (ของใหม่ไม่มีใครเรียกใช้)
 * 🔴 ถ้า process ยังไม่ส่ง `lab_orders` / `xray_results` มา → `tsLgOn` / `tsXgOn` เป็น false
 *    Template จะตกไปแสดง "ลิสต์แบนแบบเดิม" เหมือนทุกวันนี้เป๊ะ ๆ
 *
 * ── สัญญาข้อมูลที่ `emr-summary-get` (6a9574cc1812c7078a067299) ต้องส่งเพิ่ม ──────
 *    เพิ่ม **คีย์ใหม่** เท่านั้น ห้ามแก้/ตัด `lab[]` `xray[]` เดิม
 *    (ตรรกะเลือกแท็บเริ่มต้นด้านบนยังอ่านจาก `tsLab.length` / `tsXray.length`)
 *
 *  d.current_vn   : "6900305"                       // VN ที่เปิดอยู่ (ไว้ขึ้นหัวข้อ)
 *  d.lab_orders   : [{
 *      order_id, order_no, section, lab_no,
 *      section_code,      // 'BC'|'HM'|'HH'|'ML'|'MB' — จอใช้เลือก Report ผล (MB = micro)
 *      status,            // sent|accepted|collected|in_process|resulted|completed|cancelled|rejected
 *      scope,             // "visit" = ใบของ VN นี้ · "today" = สั่งครั้งก่อนแต่ผลออกวันนี้
 *      ordered_at,        // "YYYY-MM-DD HH:mm:ss"  เวลาสั่ง
 *      resulted_at,       // "" ถ้ายังไม่ออกผล      เวลาที่ผลเข้าระบบ HIS
 *      received_at, collected_at, in_process_at,    // ออปชัน — ใช้วาด stepper
 *      cancel_reason,
 *      result_report_ids, // id ของ Result Report ที่พบในใบนี้ — ปุ่ม PDF ขึ้นเฉพาะตอนมีชุดเดียว
 *      view_form_id, view_data_id,                  // ออปชัน — ปุ่ม "ดูผลทั้งใบ"
 *      items: [{ name, code, value, unit, ref, flag, critical, text, form_id, data_id }]
 *                         // text:true = ผลเป็นรายงานความเรียง (MB/MLab) ไม่ใช่ค่าเดี่ยว
 *    }]
 *  d.xray_results : [{ key, exam_name, accession_no, scope, ordered_at, resulted_at,
 *                      severity, result_text, form_id, data_id }]
 *  d.lab_trends   : [{ name, unit, ref, flag, series:[{ when, value }] }]   // ออปชัน
 *
 * 🔴 ขอบเขตที่ผู้ใช้เคาะ 2026-09-22: การ์ดแสดงแค่ 2 กลุ่ม — ใบของ VN ที่เปิดอยู่ กับใบที่
 *    "ผลออกวันนี้" นับจาก **เวลาที่ผลเข้าระบบ HIS** · การกรองเป็นหน้าที่ของ process (`scope`)
 * 🔴 การ์ดโชว์ค่าล่าสุดค่าเดียว — ค่าก่อนหน้าอยู่ในจอ "ดูผลทั้งใบ" ที่เดียว
 */

