// "16.p โรคสมอง" → "โรคสมอง" (mockup ไม่มีรหัสคลินิก — ท่าเดียวกับ e2oClinicName ของช่องขวา)
s.e2hClinic = (label) => String(label || '').replace(/^\S+\.\S*\s+/, '') || String(label || '');

// วันที่สั้นท้ายหัวข้อ "21/10" — ทุกหัวข้อมาจาก visit ใบเดียวกัน (tsVisit)
s.e2hDay = () => {
	const t = String((s.tsVisit && s.tsVisit.visit_date) || '');
	return t.length >= 10 ? t.slice(8, 10) + '/' + t.slice(5, 7) : '';
};

const E2H_KEY = 'emr2:rail'; // '0' = พับอยู่
const E2H_FOLD_SVG = '<svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" aria-hidden="true"><path d="M15 6l-6 6 6 6"></path></svg>';
const E2H_OPEN_SVG = '<svg viewBox="0 0 24 24" width="18" height="18" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" aria-hidden="true"><path d="M9 6l6 6-6 6"></path></svg>';

const e2hClosed = () => {
	try {
		return localStorage.getItem(E2H_KEY) === '0';
	} catch (e) {
		return false;
	}
};

// แถวตัวงานของการ์ดนี้ — จาก element ของ widget เอง (ไม่หาทั้งหน้า กันไปโดนฟอร์มอื่นที่เปิดซ้อน)
// $el ของ component อาจเป็น text/comment node (root หลายตัว) ⇒ ใช้ parentElement · หาไม่เจอจริง ๆ ค่อยหาทั้งหน้า
const e2hRow = () => {
	const el = field.$el;
	const node = el && el.nodeType === 1 ? el : el && el.parentElement;
	const row = node && node.closest ? node.closest('.emr2-row') : null;
	if (row) return row;
	const doc = globalThis.document;
	const tabs = doc && doc.querySelector('.el-tabs.emr2-hist-tabs');
	return tabs ? tabs.closest('.emr2-row') : null;
};

// คืน true เมื่อแปะครบแล้ว (ใช้ตอนรอให้จอ mount เสร็จ)
const e2hApply = () => {
	const doc = globalThis.document;
	const row = e2hRow();
	if (!doc || !row) return false;
	row.classList.toggle('e2h-closed', e2hClosed());

	const head = row.querySelector('.el-tabs.emr2-hist-tabs > .el-tabs__header');
	if (head && !head.querySelector('.e2h-fold')) {
		const btn = doc.createElement('button');
		btn.type = 'button';
		btn.className = 'e2h-fold';
		btn.title = 'พับช่องประวัติ';
		btn.setAttribute('aria-label', 'พับช่องประวัติ');
		btn.innerHTML = E2H_FOLD_SVG;
		btn.addEventListener('click', () => e2hSet(true));
		head.appendChild(btn);
	}

	const col = row.querySelector('.emr2-col-left');
	if (col && !col.querySelector('.e2h-rail')) {
		const rail = doc.createElement('div');
		rail.className = 'e2h-rail';
		rail.innerHTML = '<button type="button" aria-label="เปิดช่องประวัติ" title="เปิดช่องประวัติ">' + E2H_OPEN_SVG + '</button><span>ประวัติการรักษา</span><i class="e2h-rail-ico" aria-hidden="true">H</i>'; // H ใต้ข้อความ (พี่สั่ง 2026-10-23)
		rail.addEventListener('click', () => e2hSet(false));
		col.appendChild(rail);
	}
	return !!(head && col);
};

const e2hSet = (closed) => {
	try {
		localStorage.setItem(E2H_KEY, closed ? '0' : '1');
	} catch (e) {
		// เครื่องที่ปิด localStorage — พับได้แต่จำไม่ได้
	}
	e2hApply();
};

// รอจอ mount (form-render อาจโหลด component แบบ async) — ลองทุก 200ms สูงสุด ~5 วิ
const e2hBoot = (n) => {
	if (!e2hApply() && n > 0) setTimeout(() => e2hBoot(n - 1), 200);
};
setTimeout(() => e2hBoot(25), 0);

// เปลี่ยนคนไข้ (opd_card.setTran / onMounted → tsLoad) — เช็คซ้ำเผื่อหัวแท็บถูกวาดใหม่
const e2hTsLoad = s.tsLoad;
s.tsLoad = (...args) => {
	setTimeout(e2hApply, 0);
	return e2hTsLoad(...args);
};

/* ③ แท็บ Lab / X-Ray = ของ visit ครั้งก่อน (พี่เลือกข้อ B 2026-10-23 · ผลของวันนี้อยู่ปุ่ม "ผลตรวจวันนี้" แถบล่างแล้ว)
   ขอ emr-summary-get แบบ lab_visit:'prev' (process ส่งคีย์ lab board ของ visit ก่อนหน้ามาแทน · v1 ไม่ส่ง = เหมือนเดิม)
   หัวการ์ด "ประวัติครั้งก่อน" บอก VN/วันที่อยู่แล้ว ⇒ กลุ่มหลักไม่มีหัวข้อซ้ำ · ข้อความว่างบอกว่า "ครั้งก่อน" (ผลเก่าที่ไม่บอก หมอจะนึกว่าเป็นของวันนี้)
   X-ray board เดิมโหลดด้วย visit ที่เปิดอยู่ตั้งแต่ต้น tsLoad ⇒ ข้ามรอบนั้น แล้วโหลดด้วย visit ครั้งก่อนเมื่อ summary ตอบ */
const E2H_SUMMARY_PROC = '6a9574cc1812c7078a067299'; // emr-summary-get
s.e2hPrevVisit = null;

const e2hApiBase = s.tsApi;
s.tsApi = () => {
	const api = e2hApiBase();
	if (!api) return api;
	// ครอบเฉพาะ runProcess ของ summary · เมธอดอื่นของ userState ใช้ตัวเดิมผ่าน prototype
	const wrapped = Object.create(api);
	wrapped.runProcess = (id, p, ok, err) =>
		api.runProcess(id, id === E2H_SUMMARY_PROC ? Object.assign({}, p, { lab_visit: 'prev' }) : p, ok, err);
	return wrapped;
};

const e2hTsLoadPrev = s.tsLoad;
s.tsLoad = (...args) => {
	s.e2hPrevVisit = null; // คนไข้ใหม่ — ห้ามใช้ visit ก่อนหน้าของคนก่อน
	s.e2hSheets = []; // ปุ่มสลับคลินิก (④) ของคนก่อนต้องหายระหว่างโหลด
	s.e2hSheetSel = '';
	return e2hTsLoadPrev(...args);
};

const e2hXrayBase = s.tsXrayBoardLoad;
if (typeof e2hXrayBase === 'function') {
	s.tsXrayBoardLoad = (visitId) => {
		const isCurrent = !!visitId && String(visitId) === String(s.tsCurVisit || '');
		const target = isCurrent ? s.e2hPrevVisit : visitId;
		if (target) e2hXrayBase(target);
	};
}

/* ④ ครั้งก่อนตรวจหลายคลินิก → ปุ่มสลับคลินิก (C12 · พี่เลือกข้อ ค 2026-10-23)
   emr-summary-get คืน sheets[] (1 ก้อนต่อคลินิก ตามลำดับคิว) + sheet_default (คลินิกของคนเปิดจอ ถ้ามีใบ · ไม่มี = คลินิกแรก)
   กดปุ่ม = เอาก้อนของคลินิกนั้นใส่ tsCc/tsHpi/tsPe/tsDx ⇒ หัวข้อใน history/ts-head.html ใช้ตัวแปรเดิมของ treat_summary
   visit คลินิกเดียว / process รุ่นเก่า (ไม่มี sheets) = ไม่มีปุ่ม ค่าเดิมของ tsAbsorb ตามเดิม
   template เรียกฟังก์ชันนี้แทนการกำหนดค่าตรง (scope proxy ไม่มี set trap · handoff emr-multiclinic §🧠 ข้อ 29) */
s.e2hSheets = [];
s.e2hSheetSel = '';
s.e2hPickSheet = (code) => {
	const sh = s.e2hSheets.find((x) => x.code === code);
	if (!sh) return;
	s.e2hSheetSel = code;
	s.tsCc = sh.cc || '';
	s.tsHpi = sh.hpi || '';
	s.tsPe = sh.pe || null;
	s.tsDx = Array.isArray(sh.dx) ? sh.dx : [];
};

const e2hAbsorbBase = s.tsAbsorb;
s.tsAbsorb = (d) => {
	e2hAbsorbBase(d);
	const src = d || {};
	s.e2hSheets = Array.isArray(src.sheets) ? src.sheets : [];
	s.e2hSheetSel = '';
	if (s.e2hSheets.length > 1) s.e2hPickSheet(src.sheet_default || s.e2hSheets[0].code);
	if (src.lab_visit !== 'prev') return; // process ยังเป็นรุ่นเก่า = คงหัวข้อเดิม
	const from = src.from || {};
	s.e2hPrevVisit = from.visit_id ? String(from.visit_id) : null;
	if (!s.e2hPrevVisit) {
		s.tsLgSections = [{ key: 'ordered_today', title: 'Lab ครั้งก่อน', empty: '— ยังไม่มี visit ครั้งก่อน —', list: [] }];
		s.tsXgSections = [{ key: 'visit', title: 'X-ray ครั้งก่อน', empty: '— ยังไม่มี visit ครั้งก่อน —', list: [] }];
		return;
	}
	// กลุ่มหลักไม่มีหัวข้อ — หัวการ์ด "ประวัติครั้งก่อน" บอก VN/วันที่แล้ว (พี่ชี้ 2026-10-23 "มีแล้วไม่ต้องแสดงอีก") · generator ไม่วาดแถวหัวข้อที่ title ว่าง
	s.tsLgSections = [{ key: 'ordered_today', title: '', empty: '— ครั้งก่อนไม่ได้สั่ง Lab —', list: s.tsLgVisit }];
	if (s.tsLgToday.length) s.tsLgSections.push({ key: 'resulted_today', title: 'ผลที่ออกวันนั้น · จากใบสั่งก่อนหน้า', empty: '', list: s.tsLgToday });
	s.tsXgSections = [{ key: 'visit', title: '', empty: '— ครั้งก่อนไม่ได้สั่ง X-ray —', list: s.tsXgVisit }];
	if (s.tsXgToday.length) s.tsXgSections.push({ key: 'today', title: 'ผลที่ออกวันนั้น · จากใบสั่งก่อนหน้า', empty: '', list: s.tsXgToday });
	if (typeof e2hXrayBase === 'function') e2hXrayBase(s.e2hPrevVisit);
};
/* /emr2-hist-addon */

/* emr2-once-addon — EMR v2 (gen-emr-v2-model.cjs ต่อท้ายให้ · อย่าแก้ในบิลเดอร์) */
{
/* emr2-once — กันโหลดซ้ำตอนเปิดคนไข้ครั้งแรก (B1 · วัดจอจริง 2026-10-24: เปิดครั้งแรก 30 request · เปิดซ้ำ 15)
   ต้นเหตุ: ตอน mount ครั้งแรก widget ถูกสั่งโหลด 2 ทางพร้อมกัน
     ① opd_card.onMounted → setTran($examTran) → ไล่สั่งทุกการ์ด (ทาง "feed" · opd_card ติดธง form.$e2Feed ระหว่างไล่)
     ② onMounted ของ widget เอง อ่าน $examTran แล้วโหลดเอง
   ⇒ ห่อฟังก์ชันโหลด: อีกทางเพิ่งโหลด visit เดียวกันไม่เกิน E2_ONCE_MS = ข้าม
      ทางเดียวกันเรียกซ้ำ (กดโหลดใหม่ · หลังบันทึก · WS) ไม่ข้าม · เปลี่ยนคนไข้ (visit ต่าง) ไม่ข้าม
   gen-emr-v2-model.cjs ฝังไฟล์นี้ต่อท้าย onCreated ของแต่ละ widget (ในบล็อก { } ชื่อไม่ชนโค้ดเดิม) — แก้ที่ไฟล์นี้แล้ว gen ใหม่ */
const E2_ONCE_MS = 2000;
const e2OnceWrap = (widget, name, fnName, vidOf) => {
	const st = widget.vueState;
	const orig = st[fnName];
	if (typeof orig !== 'function' || orig.e2Once) return;
	const key = `${name}.${fnName}`;
	const wrapped = (...args) => {
		const form = widget.getFormRef && widget.getFormRef();
		const raw = vidOf(...args);
		const vid = raw ? String(raw) : '';
		if (form && vid) {
			const fromFeed = form.$e2Feed === true;
			const seen = form.$e2Loaded || (form.$e2Loaded = {});
			const last = seen[key];
			const now = Date.now();
			if (last && last.vid === vid && last.fromFeed !== fromFeed && now - last.at < E2_ONCE_MS) return undefined;
			seen[key] = { vid, fromFeed, at: now };
		}
		return orig(...args);
	};
	wrapped.e2Once = true;
	st[fnName] = wrapped;
};
e2OnceWrap(this, 'treat_summary', 'tsLoadFromTran', (tran) => tran && tran.vid && tran.vid.value);
}
/* /emr2-once-addon */

options.onMounted:
const field = this;
const s = this.vueState;
// เคสแท็บ EMR mount หลังกดเลือกคนไข้จากคิวไปแล้ว → opd_card.setTran ยิงไปก่อนที่การ์ดนี้จะเกิด
// ⇒ ดึง tran จาก form เองรอบแรก (pattern เดียวกับ m_history / order_card / item_card)
setTimeout(() => {
	const form = field.getFormRef();
	s.tsLoadFromTran((form && form.$examTran) || null);
}, 0);

options.onCreated:
const s = this.vueState
const field = this

// ★ แทนด้วย _id ของ process disease_registry_list ใน API Factory
const REG_PROCESS = '6a51a09c6e185ae01ab5bb4d'

s.regList = []
s.regLoading = false
s.regPid = null      // person _id ปัจจุบัน — เซ็ตผ่าน s.load จาก opd_card
s.regPidRef = null   // ref ผู้ป่วยจาก visit (hn, ชื่อ) — ใช้ประกอบ joiner ตอน Add

// form id อ้างอิงในระบบ — ใช้เลือกว่า parentId ควรเป็น visit หรือ person
const VISIT_FORM = '6a40fdec4b6dfdf45acbfbce'
const PERSON_FORM = '6a37d3bd4cfbfdbe257fc912'

s.regVid = null   // visit _id ปัจจุบัน — มาจาก opd_card

// เรียกจาก opd_card.setTran — pattern เดียวกับ consult_box.load
s.load = (personId, pidRef, visitId) => {
  s.regPid = personId || null
  s.regPidRef = pidRef || null
  s.regVid = visitId || null
  s.regList = []
  if (!s.regPid) return
  const form = field.getFormRef()
  if (!form) return
  s.regLoading = true
  form.userState.runProcess(REG_PROCESS, { person_id: s.regPid, visit_id: s.regVid }, (res) => {
    const d = res.data || {}
    s.regList = d.items || []
    s.regLoading = false
  }, (err) => {
    s.regLoading = false
    field.alert('โหลดทะเบียนโรคไม่สำเร็จ: ' + ((err && err.message) || err), 'error')
  })
}

// badge ของแถว: match สถานะกับ status_options — ไม่เจอ → เทา + ค่า raw
s.regStatusOf = (item) => {
  if (!item.has_record) return null
  const raw = item.latest ? item.latest.status : null
  const hit = (item.status_options || []).find((o) => String(o.op_value) === String(raw))
  if (hit) return { label: hit.op_label, color: hit.op_color || 'info' }
  return { label: (raw === null || raw === undefined) ? '-' : String(raw), color: 'info' }
}


// parentId ที่ต้องส่งให้ฟอร์มเป้าหมาย ตาม parent ที่ฟอร์มนั้นผูก
s.regParentOf = (item) => {
  if (item.parent_form === VISIT_FORM) return s.regVid ? String(s.regVid) : null
  if (item.parent_form === PERSON_FORM) return s.regPid ? String(s.regPid) : null
  return null
}

// เปิด record ล่าสุด
s.openReg = (item) => {
  const form = field.getFormRef()
  if (!form) return
  const dataId = item.latest ? String(item.latest.data_id) : null
  form.openForm(item.target_form, dataId, s.regParentOf(item), null, {
    afterSaveCallback: () => { form.subFormClose(); s.load(s.regPid, s.regPidRef, s.regVid) }
  })
}

// เพิ่ม record ใหม่ — joiner โหลดจาก parentId เอง ไม่ต้องประกอบ initData
s.addReg = (item) => {
  const form = field.getFormRef()
  if (!form || !s.regPid) return
  const parentId = s.regParentOf(item)
  if (item.parent_form && !parentId) { field.alert('ไม่พบ visit ปัจจุบัน', 'warning'); return }
  form.openForm(item.target_form, null, parentId, null, {
    afterSaveCallback: () => { form.subFormClose(); s.load(s.regPid, s.regPidRef, s.regVid) }
  })
}

/* emr2-hist-addon — EMR v2 (gen-emr-v2-model.cjs ต่อท้ายให้ · อย่าแก้ในบิลเดอร์) */
/* ══ ตัวเลขบนหัวแท็บ "ทะเบียนโรค" (board 4) — EMR v2 · ต่อท้าย onCreated ของ registry_card ══════
   ตัวเลข = โรคที่ลงทะเบียนแล้ว (has_record) · ไม่มี = ไม่มีป้าย
   หัวแท็บวาดโดย tab-render ของแพลตฟอร์ม (มีแค่ label) ⇒ เขียน data-e2h-n ลงปุ่มแท็บ แล้ว CSS วาดเป็นป้าย (::after)
   ปุ่มแท็บของ el-tabs มี id = "tab-<ชื่อ tab-pane>" ที่ generator ตั้งไว้ (ท่าเดียวกับ orders/tab-count.js)
   🔴 document ถูก shadow ในโค้ด event (CLAUDE.md กับดักข้อ 4) → globalThis.document */
const E2H_REG_TAB = 'tab-emr2_tab_reg'
const e2hRegCount = () => (s.regList || []).filter((i) => i.has_record).length
const e2hRegPaint = (n) => {
  const doc = globalThis.document
  const el = doc && doc.getElementById(E2H_REG_TAB)
  if (!el) return
  if (n > 0) el.setAttribute('data-e2h-n', String(n))
  else el.removeAttribute('data-e2h-n')
}
// watch ของ component หยุดเองตอน unmount · flush post = วาดหลัง DOM อัปเดต
if (typeof field.$watch === 'function') field.$watch(e2hRegCount, e2hRegPaint, { immediate: true, flush: 'post' })

/* ══ บรรทัดเสริมของแถวทะเบียนโรค (ข้อ B · พี่เลือก 2026-10-23) ══════
   ข้อมูลจาก disease_registry_list: latest.{updated_at, updated_by, is_current_visit} · first_at · history[{status, at}] (เก่า→ใหม่ ≤ 5) */
// "2026-07-11 11:56:35" → "11/07/2569"
const e2hRegFull = (at) => {
  const t = String(at || '')
  return t.length >= 10 ? t.slice(8, 10) + '/' + t.slice(5, 7) + '/' + (Number(t.slice(0, 4)) + 543) : ''
}
// เส้นสถานะ: ปีนี้ = "11/07" · ปีอื่น = "11/07/68" (แถวแคบ ปีเต็มไม่พอที่)
s.e2hRegDay = (at) => {
  const t = String(at || '')
  if (t.length < 10) return ''
  const dm = t.slice(8, 10) + '/' + t.slice(5, 7)
  return Number(t.slice(0, 4)) === new Date().getFullYear() ? dm : dm + '/' + String(Number(t.slice(0, 4)) + 543).slice(2)
}
// สถานะดิบ → ป้าย (กติกาเดียวกับ regStatusOf ของไฟล์หลัก · ไม่เจอ = เทา + ค่าดิบ)
s.e2hRegSt = (item, raw) => {
  const hit = ((item && item.status_options) || []).find((o) => String(o.op_value) === String(raw))
  if (hit) return { label: hit.op_label, color: hit.op_color || 'info' }
  return { label: raw === null || raw === undefined ? '-' : String(raw), color: 'info' }
}
// "QSNICH Admin (iencoded@gmail.com)" → "QSNICH Admin"
const e2hRegWho = (v) => String(v || '').replace(/\s*\([^)]*@[^)]*\)\s*$/, '')
// ประวัติตัดไว้ที่ 5 ครั้ง ⇒ ใบแรกเก่ากว่าเส้นสถานะ ต้องบอกว่าเริ่มเมื่อไหร่ (ต้นเส้นสถานะ)
const e2hRegSince = (item) =>
  item.first_at && (item.record_count || 0) > (item.history || []).length ? 'ตั้งแต่ ' + e2hRegFull(item.first_at) + ' · ' : ''
s.e2hRegSinceText = (item) => e2hRegSince(item || {})
// ขวาบรรทัดบน (ช่องแคบ ~350px): ใบล่าสุดเป็นของ visit นี้ = "visit นี้" แทนวันที่ (วันเดียวกันอยู่แล้ว) · ไม่ใช่ = วันที่
s.e2hRegSub = (item) => {
  const l = (item && item.latest) || null
  if (!l || !l.updated_at) return ''
  const who = e2hRegWho(l.updated_by)
  return (l.is_current_visit ? 'visit นี้' : e2hRegFull(l.updated_at)) + (who ? ' · ' + who : '')
}
s.e2hRegOffSub = (item) => {
  const h = (item && item.history) || []
  if (!h.length) return ''
  return (item.by_form === 'vid' ? 'visit นี้ยังไม่บันทึก · ' : '') + 'ครั้งก่อน ' + e2hRegFull(h[h.length - 1].at)
}
/* /emr2-hist-addon */

/* emr2-once-addon — EMR v2 (gen-emr-v2-model.cjs ต่อท้ายให้ · อย่าแก้ในบิลเดอร์) */
{
/* emr2-once — กันโหลดซ้ำตอนเปิดคนไข้ครั้งแรก (B1 · วัดจอจริง 2026-10-24: เปิดครั้งแรก 30 request · เปิดซ้ำ 15)
   ต้นเหตุ: ตอน mount ครั้งแรก widget ถูกสั่งโหลด 2 ทางพร้อมกัน
     ① opd_card.onMounted → setTran($examTran) → ไล่สั่งทุกการ์ด (ทาง "feed" · opd_card ติดธง form.$e2Feed ระหว่างไล่)
     ② onMounted ของ widget เอง อ่าน $examTran แล้วโหลดเอง
   ⇒ ห่อฟังก์ชันโหลด: อีกทางเพิ่งโหลด visit เดียวกันไม่เกิน E2_ONCE_MS = ข้าม
      ทางเดียวกันเรียกซ้ำ (กดโหลดใหม่ · หลังบันทึก · WS) ไม่ข้าม · เปลี่ยนคนไข้ (visit ต่าง) ไม่ข้าม
   gen-emr-v2-model.cjs ฝังไฟล์นี้ต่อท้าย onCreated ของแต่ละ widget (ในบล็อก { } ชื่อไม่ชนโค้ดเดิม) — แก้ที่ไฟล์นี้แล้ว gen ใหม่ */
const E2_ONCE_MS = 2000;
const e2OnceWrap = (widget, name, fnName, vidOf) => {
	const st = widget.vueState;
	const orig = st[fnName];
	if (typeof orig !== 'function' || orig.e2Once) return;
	const key = `${name}.${fnName}`;
	const wrapped = (...args) => {
		const form = widget.getFormRef && widget.getFormRef();
		const raw = vidOf(...args);
		const vid = raw ? String(raw) : '';
		if (form && vid) {
			const fromFeed = form.$e2Feed === true;
			const seen = form.$e2Loaded || (form.$e2Loaded = {});
			const last = seen[key];
			const now = Date.now();
			if (last && last.vid === vid && last.fromFeed !== fromFeed && now - last.at < E2_ONCE_MS) return undefined;
			seen[key] = { vid, fromFeed, at: now };
		}
		return orig(...args);
	};
	wrapped.e2Once = true;
	st[fnName] = wrapped;
};
e2OnceWrap(this, 'registry_card', 'load', (personId, pidRef, visitId) => visitId);
}
/* /emr2-once-addon */

options.onMounted:
