options.onCreated:
/**
 * emr2_soap · onCreated — ช่องกลางของ EMR v2 (board 4): S · O · A · C · P ใบละคลินิก + consult
 *
 * วางที่: ฟอร์ม EMR v2 6ada06229291822e416c21cb → grid_col82059 (ช่องกลาง) → vue-ui `emr2_soap`
 *   generator ใส่ให้เอง (sdform/emr/v2/gen-emr-v2-model.cjs) — แก้ไฟล์นี้แล้ว gen ใหม่ ไม่ต้องวางในบิลเดอร์
 *
 * ข้อมูล: process emr2-soap-get (อ่านอย่างเดียว · ครั้งเดียวได้ครบ) — กติกาเจ้าของใบอยู่ฝั่ง process
 * ปลุก: opd_card.setTran → e2Load(visitId, tran) (hook ที่ generator แทรกให้ใน opd_card ของ v2)
 *       + onMounted อ่าน form.$examTran (แท็บ EMR เปิดทีหลัง)
 * แก้ไข: เปิดฟอร์มเดิม (Screening / PE / Plan / Diagnosis / Consult) — ไม่มีที่เขียนข้อมูลใหม่ในตัว widget
 * ลอก logic มาจาก (คลังของ EMR เก่า): consult_banner · consult_box · examinationformbtn
 *
 * 🔴 ทุก key ที่เทมเพลตอ้างต้องมีค่าตั้งแต่ตรงนี้ — ขาดตัวเดียว = error box ทั้ง widget
 * ⚠️ รอบ 1 ยังไม่ส่ง WS ออก — จออื่นที่เปิด v1 อยู่จะไม่รีเฟรชเองตอนแก้จากที่นี่ (ฟังอย่างเดียว)
 */

const s = this.vueState;
const field = this;

const SOAP_PROC = '6ada1ba0abcbb06488ffb615'; // emr2-soap-get
const NOTE_FORM = '6a957607422c1ca959829e59'; // Clinical Note (form_ui) — ปุ่ม "บันทึกการตรวจรักษา"
const TRAN_FORM = '6a461235e521219e514d1c4b'; // Visit Tran — โหลด tran ใหม่หลังตอบ consult
const FORMS = {
	S: '6a473513d54977f38061dddd', // Screening
	O: '6a473a1dd54977f38061dddf', // Physical Examination
	P: '6a47dcac8ca8083d715e3492', // Plan
	A: '6a47a9cc8ca8083d715e3486', // Diagnosis
	C: '6a482ea68ca8083d715e3498', // Consult
};
const SECTION_META = {
	S: { title: 'ประวัติอาการ', sub: 'SUBJECTIVE', badge: 'is-s' },
	O: { title: 'ตรวจร่างกาย', sub: 'OBJECTIVE', badge: 'is-o' },
	P: { title: 'แผนการรักษา', sub: 'PLAN', badge: 'is-p' },
};
const MODE_KEY = 'emr2:otherMode'; // ย่อ/เต็ม/ซ่อน จำต่อเครื่อง (localStorage เปิดให้ใช้แล้ว)

/* ══ state ════════════════════════════════════════════════════════════════ */
s.e2Vid = null;
s.e2Tran = null;
s.e2Data = null;
s.e2Loading = false;
s.e2Err = '';
s.e2Pop = false; // popover คลินิกใน visit
s.e2SetPop = (v) => {
	s.e2Pop = !!v;
};
s.e2OpenConsult = ''; // แถว consult ที่กางอยู่
// คลินิกอื่น: ค่าเริ่มต้น "เต็ม" (มติ 2026-10-22 · ใช้ทุกจอที่มีปุ่มนี้)
s.e2Mode = (() => {
	try {
		const v = localStorage.getItem(MODE_KEY);
		return ['full', 'compact', 'hidden'].includes(v) ? v : 'full';
	} catch (e) {
		return 'full';
	}
})();

s.e2Modes = [
	{ key: 'compact', label: 'ย่อ' },
	{ key: 'full', label: 'เต็ม' },
	{ key: 'hidden', label: 'ซ่อน' },
];
s.e2SetMode = (key) => {
	s.e2Mode = key;
	try {
		localStorage.setItem(MODE_KEY, key);
	} catch (e) {
		/* เก็บไม่ได้ก็ใช้ค่าในจอไปก่อน */
	}
};

/* ══ โหลด ═════════════════════════════════════════════════════════════════ */
let reqSeq = 0; // เปลี่ยนคนไข้ระหว่างรอ = ทิ้งผลของคนเก่า

s.e2Load = (visitId, tran) => {
	s.e2Vid = visitId ? String(visitId) : null;
	if (tran !== undefined) s.e2Tran = tran || null;
	s.e2Data = null;
	s.e2Err = '';
	s.e2OpenConsult = '';
	wsWatch(s.e2Vid);
	s.e2Reload();
	// คลินิกเฉพาะทางใน O (sp-addon.js) — tran ของ opd_card มีข้อมูลคนไข้ครบ · ไม่มี tran = ส่งแค่เลข visit ให้ process อ่านเอง
	if (s.scLoad) s.scLoad(s.e2Vid ? s.e2Tran || { vid: { value: s.e2Vid } } : null);
	s.e2Fit(); // เปลี่ยนคนไข้ = หัวจอเปลี่ยนสูงได้ (แถบวัคซีน/แพ้ยา)
};

s.e2Reload = () => {
	if (!s.e2Vid) return;
	const form = field.getFormRef();
	if (!form) return;
	const seq = ++reqSeq;
	const vid = s.e2Vid;
	s.e2Loading = true;
	form.userState.runProcess(
		SOAP_PROC,
		{ visit_id: vid },
		(res) => {
			if (seq !== reqSeq) return;
			s.e2Loading = false;
			const d = (res && res.data) || {};
			// process ที่ตีกลับด้วย success:false ก็มาทาง callback นี้ ไม่ใช่ errCb — ต้องเช็คเอง
			if (!d.success) {
				s.e2Err = d.message || 'อ่านบันทึกการตรวจไม่สำเร็จ';
				return;
			}
			s.e2Data = d;
		},
		(err) => {
			if (seq !== reqSeq) return;
			s.e2Loading = false;
			s.e2Err = 'อ่านบันทึกการตรวจไม่สำเร็จ: ' + ((err && err.message) || err);
		}
	);
};

/* ══ WS: มีคนบันทึก S/O/P/Dx/Consult ของ visit นี้ที่จออื่น → โหลดใหม่ (ช่องเดียวกับ record-ui) ══
   ข้อความ WS มาจาก client ที่บันทึก (record-ui ส่งเองหลัง save) — กรองเฉพาะ record ของ visit เรา */
let wsConns = [];
let wsVid = '';
let wsTimer = null;
const isOurRecord = (row) => {
	if (!row || !s.e2Vid) return false;
	const v = row.vid && (row.vid.value || row.vid._id);
	return String(row.xparentx || '') === s.e2Vid || String(v || '') === s.e2Vid;
};
const wsWatch = (visitId) => {
	const vid = visitId ? String(visitId) : '';
	if (vid === wsVid) return;
	wsConns.forEach((c) => c && c.wsDisconnect && c.wsDisconnect());
	wsConns = [];
	wsVid = vid;
	if (!vid) return;
	const form = field.getFormRef();
	if (!form || !form.userState || !form.userState.connectWebSocket) return;
	const widgetId = 'emr2-soap-' + Math.random().toString(36).slice(2);
	wsConns = Object.values(FORMS).map((formId) =>
		form.userState.connectWebSocket('gridform', formId, widgetId, (payload) => {
			if (!payload || payload.from === 'server' || !isOurRecord(payload.data)) return;
			if (wsTimer) clearTimeout(wsTimer);
			wsTimer = setTimeout(() => {
				wsTimer = null;
				if (s.e2Vid === vid) s.e2Reload();
			}, 400);
		})
	);
};
/* ══ ความสูง 3 ช่อง + โหมดเต็มจอ ══════════════════════════════════════════════════════
   โหมดปกติ: ช่อง = จอ − แถบปุ่มล่าง − ตำแหน่งแถวตอนยังไม่เลื่อน ⇒ จบเหนือแถบปุ่มพอดี (หน้าแบบที่พี่ OK 2026-10-22)
   โหมดเต็มจอ: แท็บ EMR ขึ้นเต็มจอด้วย CSS (.emr2-full) — หัวคนไข้บน · 3 ช่องยืดเต็ม · แถบปุ่มล่างสุด
     เปิด/ปิดด้วยปุ่มในกล่องนาฬิกาของหัวคนไข้ (opd_card) หรือ Esc · ไม่จำต่อเครื่องแล้ว — เปิดจอ/กดเมนู EMR = ย่อเสมอ (พี่สั่ง 2026-10-23)
   ประวัติ: ค่าคงที่ 96px (ช่องยาวเลยแถบล่าง · มัว) → ยืดตามการเลื่อน (พี่ให้เลิก: "ไม่ต้องสกอมัวละ ทำปุ่มขยาย")
   🔴 document/window ถูก shadow ในโค้ด event (compileFn restricted) → ใช้ globalThis.* (CLAUDE.md กับดักข้อ 4) */
const GAP = 12;
const MIN_H = 500; // ตัวงานสูงไม่ต่ำกว่านี้ (พี่สั่ง 2026-10-22) — จอเตี้ยกว่า = เลื่อนทั้งหน้าแทนการบีบช่อง
const FULL_KEY = 'emr2:full';
let fitTimer = null;
let fitObserver = null;
let keyBound = false;

// ตัวเลื่อนจริง — กล่อง overflow auto/scroll ชั้นแรกเหนือแถว (QSNICH = el-scrollbar__wrap) ไม่เจอ = ทั้งเอกสาร
const scrollerOf = (doc, row) => {
	for (let el = row.parentElement; el && el !== doc.body; el = el.parentElement) {
		const oy = globalThis.getComputedStyle(el).overflowY;
		if (oy === 'auto' || oy === 'scroll') return el;
	}
	return doc.scrollingElement || doc.documentElement;
};
const rowOf = (doc) => doc.querySelector('.el-row.emr2-row');
const paneOf = (row) => (row ? row.closest('.el-tab-pane') : null);

const doFit = () => {
	const doc = globalThis.document;
	if (!doc) return;
	const row = rowOf(doc);
	if (!row || !row.offsetParent) return;
	if (globalThis.innerWidth < 1200) {
		row.style.removeProperty('--emr2-h');
		return;
	}
	// โหมดเต็มจอ: แท็บเองคือกรอบ (fixed เต็มจอ) · โหมดปกติ: ตัวเลื่อนของแอป
	const pane = paneOf(row);
	const full = !!(pane && pane.classList.contains('emr2-full'));
	const sc = full ? pane : scrollerOf(doc, row);
	const isDoc = sc === doc.documentElement || sc === doc.scrollingElement;
	const scrolled = isDoc ? globalThis.scrollY || 0 : sc.scrollTop || 0;
	// ขอบล่างที่มองเห็นจริง — el-scrollbar ของแอปสูง "จอ − 60" แต่แถบเมนูสูงกว่านั้น ⇒ ยึดขอบจอ ไม่ยึดขอบตัวเลื่อน
	const scBottom = isDoc ? globalThis.innerHeight : sc.getBoundingClientRect().bottom;
	const target = Math.min(globalThis.innerHeight, scBottom) - GAP;
	const bar = doc.querySelector('.emr2-bar');
	const col = row.querySelector('.emr2-col');
	if (!bar || !bar.offsetParent || !col) return;
	// วัดขอบล่างแถบปุ่มจริง แล้วชดเชยให้ชิดขอบล่างจอ (ตอนยังไม่เลื่อน) — ไม่ต้องรู้ว่าใต้/รอบตัวงานมี margin อะไรบ้าง
	// เดิมหัก "ส่วนที่ยังเลื่อนได้" ทั้งก้อน แล้วหักเกิน เหลือที่ว่างใต้แถบ ~110px (พี่เห็น 2026-10-22) · ทำ 2 รอบให้นิ่ง
	for (let i = 0; i < 2; i += 1) {
		const now = col.getBoundingClientRect().height;
		const delta = target - (bar.getBoundingClientRect().bottom + scrolled);
		if (Math.abs(delta) < 1) break;
		const h = Math.max(MIN_H, Math.floor(now + delta));
		row.style.setProperty('--emr2-h', h + 'px');
		if (h === MIN_H) break; // ชนขั้นต่ำแล้ว แถบปุ่มจะเลยขอบจอ — เลื่อนหน้าดูได้
	}
};

// หน่วงกันวัดถี่ตอนการ์ดหลายใบโหลดพร้อมกัน (resize / หัวจอเปลี่ยนสูง / เปลี่ยนคนไข้)
s.e2Fit = () => {
	if (fitTimer) clearTimeout(fitTimer);
	fitTimer = setTimeout(() => {
		fitTimer = null;
		doFit();
	}, 120);
};

/* ── โหมดเต็มจอ ──
   เริ่มที่ย่อเสมอ (พี่เลือกข้อ A 2026-10-23: "กดเมนู EMR แล้วออกจากโหมดเต็มจอทุกครั้ง")
   เดิมจำ emr2:full ต่อเครื่อง ⇒ ออกจาก EMR ตอนเต็มจอ (ย้ายห้อง/ตรวจเสร็จ พาไป My Room) แล้วกดเมนู EMR กลับมาก็ยังเต็มจอ
   ล้างค่าเก่าที่เคยจำไว้ทิ้งด้วย ไม่ให้ค้างในเครื่อง */
s.e2Full = false;
try {
	localStorage.removeItem(FULL_KEY);
} catch (e) {
	/* ไม่มีที่เก็บก็ไม่มีค่าเก่าให้ล้าง */
}
const applyFull = () => {
	const doc = globalThis.document;
	if (!doc) return;
	const row = rowOf(doc);
	const pane = paneOf(row);
	if (!pane) return;
	// เข้าเต็มจอ: เลื่อนตัวเลื่อนของแอปกลับบนสุดก่อน — กลับมาโหมดปกติแล้วไม่ค้างกลางหน้า
	if (s.e2Full) {
		const sc = scrollerOf(doc, row);
		if (sc) sc.scrollTop = 0;
	}
	pane.classList.toggle('emr2-full', !!s.e2Full);
	doFit();
};
s.e2SetFull = (on) => {
	s.e2Full = !!on;
	applyFull();
};
s.e2ToggleFull = () => s.e2SetFull(!s.e2Full);
s.e2ApplyFull = applyFull;

// Esc = ย่อกลับ · 🔴 ถ้ามี popup (ฟอร์ม/dialog) เปิดอยู่ ปล่อยให้ Esc ปิด popup ก่อน ไม่ย่อจอ
const popupOpen = (doc) =>
	Array.from(doc.querySelectorAll('.el-overlay')).some((el) => globalThis.getComputedStyle(el).display !== 'none');
const onKey = (ev) => {
	if (ev.key !== 'Escape' || !s.e2Full) return;
	const doc = globalThis.document;
	if (doc && popupOpen(doc)) return;
	s.e2SetFull(false);
};
// กดหัวแท็บ EMR ของเมนู (main_app) = ย่อ — แท็บที่เต็มจอค้างอยู่ตอนถูกพาไปแท็บอื่นจะกลับมาแบบย่อ
// หัวแท็บของ el-tabs มี id "tab-<ชื่อ pane>" ส่วนตัว pane มี id "pane-<ชื่อ pane>"
const onTabClick = (ev) => {
	if (!s.e2Full || !ev.target || !ev.target.closest) return;
	const pane = paneOf(rowOf(globalThis.document));
	if (!pane || !pane.id) return;
	if (ev.target.closest('#' + pane.id.replace(/^pane-/, 'tab-'))) s.e2SetFull(false);
};

const watchFit = () => {
	const doc = globalThis.document;
	if (!doc) return;
	if (globalThis.addEventListener) {
		globalThis.addEventListener('resize', s.e2Fit);
		if (!keyBound) {
			globalThis.addEventListener('keydown', onKey);
			globalThis.addEventListener('click', onTabClick, true);
			keyBound = true;
		}
	}
	if (typeof globalThis.ResizeObserver !== 'function' || fitObserver) return;
	fitObserver = new globalThis.ResizeObserver(s.e2Fit);
	const pane = paneOf(rowOf(doc));
	if (pane) Array.from(pane.children).forEach((el) => fitObserver.observe(el));
};
s.e2WatchFit = watchFit;

// เรียกจาก onUnmount — ไม่ปิด = socket / listener ค้างทุกครั้งที่สลับแท็บ/ปิดจอ
s.e2Cleanup = () => {
	if (wsTimer) clearTimeout(wsTimer);
	wsTimer = null;
	wsWatch(null);
	if (fitTimer) clearTimeout(fitTimer);
	if (globalThis.removeEventListener) {
		globalThis.removeEventListener('resize', s.e2Fit);
		globalThis.removeEventListener('keydown', onKey);
		globalThis.removeEventListener('click', onTabClick, true);
	}
	keyBound = false;
	if (fitObserver) fitObserver.disconnect();
	fitObserver = null;
	// ออกจากฟอร์มขณะเต็มจอ — ถอดคลาสออก ไม่ให้แท็บค้างเป็น fixed
	const doc = globalThis.document;
	const pane = doc ? paneOf(rowOf(doc)) : null;
	if (pane) pane.classList.remove('emr2-full');
};

/* ══ ข้อมูลที่เทมเพลตใช้ ══════════════════════════════════════════════════ */
s.e2Me = () => (s.e2Data && s.e2Data.me) || {};
s.e2Journey = () => (s.e2Data && s.e2Data.journey) || [];
// คลินิกที่โชว์บนจอ — ตัดคิวที่แค่ผ่านโดยไม่ได้บันทึก (show จาก emr2-soap-get ข้อ 4b · พี่เลือกข้อ A 2026-10-24)
// process รุ่นก่อนไม่มี show = โชว์ทุกคลินิกแบบเดิม · 🔴 สีป้ายยังใช้ e2Journey (ลำดับเต็ม) สีจะได้ไม่เลื่อน
s.e2JourneyShown = () => s.e2Journey().filter((j) => j.show !== false);
s.e2JourneyText = () => {
	const n = s.e2JourneyShown().length;
	return n ? 'visit วันนี้ ' + n + ' คลินิก' : 'visit วันนี้';
};
// สีป้ายคลินิก is-c0…c4 (class .e2-tag ใน emr2-orders.css) — 🔴 กติกาเดียวกับ e2oClinicTone ใน orders/orders-addon.js
//   (ลำดับใน journey · ไม่อยู่ใน journey = สีจากรหัส) ⇒ คลินิกเดียวกันสีเดียวกันทั้งจอ · แก้ที่หนึ่งต้องแก้อีกที่
s.e2Tone = (code) => {
	const c = String(code || '');
	const i = s.e2Journey().findIndex((j) => String(j.unit) === c);
	if (i >= 0) return 'is-c' + (i % 5);
	let h = 0;
	for (let k = 0; k < c.length; k += 1) h = (h + c.charCodeAt(k)) % 5;
	return 'is-c' + h;
};

// ส่วน S/O/P — ใบละคลินิก (C11): ใบของฉัน = mine · ของคลินิกอื่น = others (🔒) · ยังไม่มีใบของฉัน = canAdd
// เจ้าของใบ/สิทธิ์เพิ่มตัดสินที่ process (emr2-soap-get · sheets) — widget แค่วาด
s.e2Secs = (keys) =>
	keys.map((key) => {
		const sh = s.e2Data && s.e2Data.sheets ? s.e2Data.sheets[key] : null;
		const ss = sh || { mine: null, others: [], canAdd: false };
		return Object.assign({ key, mine: ss.mine, others: ss.others || [], canAdd: !!ss.canAdd }, SECTION_META[key]);
	});

// คลินิกอื่นโหมด "ย่อ" = บรรทัดเดียวจากข้อความบรรทัดแรก
s.e2Summary = (rec) => {
	const ln = (rec && rec.lines && rec.lines[0]) || null;
	return ln ? ln.l + ' ' + ln.t : 'ยังไม่มีข้อความ';
};

s.e2Dx = () => (s.e2Data && s.e2Data.dx) || null;
s.e2DxGroups = (mine) => {
	const dx = s.e2Dx();
	return dx ? dx.groups.filter((g) => !!g.mine === mine) : [];
};
s.e2DxSummary = (g) => g.rows.map((r) => r.code).join(' · ');
// Principal Diagnosis เป็นของคลินิกเจ้าของโรคหลัก ⇒ วางในบล็อกคลินิกนั้น (พี่สั่ง 2026-10-23 "เป็นคลินิกเดียวกัน")
// ไม่มีบล็อกไหนมีโรคหลัก (ลง Principal แต่ยังไม่ลง ICD10 หลัก) = ยังแสดงแยกใต้บล็อกเหมือนเดิม
s.e2DxHasPrimary = (g) => !!g && (g.rows || []).some((r) => r.primary);
// ใบละคลินิก (g.sheet) มี Principal ของใบตัวเอง · ใบเดิม 1 ใบ/visit ใช้ Principal ของทั้งใบ
s.e2DxPrincipalOf = (g) => {
	if (!s.e2DxHasPrimary(g)) return '';
	const dx = s.e2Dx();
	return g.sheet ? g.principal || '' : (dx && dx.principal) || '';
};
s.e2DxPrincipalLoose = () => {
	const dx = s.e2Dx();
	return !!dx && !!dx.principal && !dx.groups.some(s.e2DxHasPrimary);
};

s.e2Consults = () => (s.e2Data && s.e2Data.consults) || [];
s.e2ConsultHeader = () => {
	const list = s.e2Consults();
	const wait = list.filter((c) => c.status === 'send').length;
	return list.length ? list.length + ' รายการ' + (wait ? ' · รอ ' + wait : '') : 'ยังไม่มีรายการปรึกษา';
};
s.e2ToggleConsult = (c) => {
	s.e2OpenConsult = s.e2OpenConsult === c.id ? '' : c.id;
};

/* ══ แบนเนอร์ consult (ลอกจาก consult_banner) — เฉพาะเมื่อคิวนี้คือปลายทางของ consult ══ */
s.bnCi = () => {
	const t = s.e2Tran;
	if (!t || !t.consult_info) return null;
	const c = t.consult_info;
	const dest = c.clinic && t.unit_to && String(c.clinic) === String(t.unit_to.value);
	return dest ? c : null;
};
s.bnFrom = () => {
	const lb = (s.e2Tran && s.e2Tran.unit_from && s.e2Tran.unit_from.label) || '-';
	return lb.replace(/^\S+\s+/, ''); // "19.p คลินิกวัคซีน" → "คลินิกวัคซีน"
};
s.bnPriority = () => {
	const c = s.bnCi();
	return c ? { '20': 'เร่งด่วน', '30': 'STAT' }[String(c.priority)] || '' : '';
};
s.bnTime = () => {
	const c = s.bnCi();
	const m = String((c && c.at) || '').match(/\b(\d{2}:\d{2})/);
	return m ? m[1] : '';
};
// ตอบ/แก้คำตอบ consult — หลังบันทึก consult-sync-tran อัปเดต tran.consult_info แล้ว
// ⇒ โหลด tran ตัวเดิมใหม่แล้วป้อนผ่าน opd_card.setTran (กระจายให้การ์ดทุกตัวรวม widget นี้)
s.bnAnswer = () => {
	const c = s.bnCi();
	if (!c) return;
	const form = field.getFormRef();
	const tranId = s.e2Tran && s.e2Tran._id ? String(s.e2Tran._id) : '';
	form.openForm(FORMS.C, String(c.consult_id), s.e2Vid, null, {
		afterSaveCallback: () => {
			form.subFormClose();
			if (!tranId) return s.e2Reload();
			form.userState.crudGetAll(
				{
					sdProvider: {
						providerId: TRAN_FORM,
						providerType: 'FORM',
						params: { tid: tranId },
						options: { where: "`_id` = CONVERT(:tid, 'objectId')", limit: 1, page: 1 },
					},
					totalEnable: false,
				},
				(res) => {
					const fresh = (res.data && res.data[0]) || null;
					const opd = field.getFieldRef('opd_card');
					if (fresh && opd && opd.vueState && opd.vueState.setTran) opd.vueState.setTran(fresh);
					else s.e2Reload();
				}
			);
		},
	});
};

/* ══ เปิดฟอร์มเดิม ═════════════════════════════════════════════════════════ */
// การ์ดเก่าที่ยังวางเทียบอยู่ใต้ widget (รอบ 1) — สั่งโหลดใหม่ด้วย ไม่งั้นสองที่โชว์ไม่ตรงกัน
const refreshOldCards = () => {
	['record_cc', 'record_pe', 'record_dx', 'record_plan'].forEach((n) => {
		const f = field.getFieldRef(n);
		const editor = f && f.getFieldEditor && f.getFieldEditor();
		if (editor && typeof editor.changeParentId === 'function') {
			try {
				editor.changeParentId(s.e2Vid);
			} catch (e) {
				/* การ์ดเก่ารีเฟรชไม่ได้ไม่กระทบ widget นี้ */
			}
		}
	});
};
const afterChange = () => {
	s.e2Reload();
	refreshOldCards();
};

// ปุ่ม "บันทึกการตรวจรักษา" — ลอกจาก examinationformbtn
// 🔴 ส่ง visitId ทาง options.params (form_ui ทิ้ง initData) · ฟอร์มนี้ไม่มี save ของแพลตฟอร์ม → ใช้ cancelCallback
s.e2OpenNote = () => {
	if (!s.e2Vid) return field.alert('ยังไม่ได้เลือกผู้ป่วย/visit', 'warning');
	const form = field.getFormRef();
	form.openForm(NOTE_FORM, null, null, undefined, {
		params: { visitId: s.e2Vid },
		cancelCallback: () => {
			form.subFormClose();
			afterChange();
		},
	});
};

// S / O / P / A — ดู (อ่านอย่างเดียว) · แก้ไข · เพิ่ม (ยังไม่มีใบ)
// เพิ่มใบ S/O/P = ใบของคลินิกที่บันทึก → ติด so_clinic ตั้งแต่สร้าง (ด่าน unique ต่อคลินิกเช็คค่านี้ตอน save · stamp ไม่ทับใบที่มีเจ้าของแล้ว)
s.e2Open = (key, id, readonly) => {
	if (!s.e2Vid) return;
	const form = field.getFormRef();
	const me = s.e2Me();
	// วินิจฉัยก็ใบละคลินิกแล้ว (C41) — ใบใหม่ติด so_clinic เหมือน S/O/P (ฟอร์ม Diagnosis เติมเองด้วยถ้าเปิดจากที่อื่น)
	const initData = !id && me.soClinic ? { so_clinic: me.soClinic } : null;
	form.openForm(FORMS[key], id ? String(id) : null, s.e2Vid, initData, {
		readonly: !!readonly,
		afterSaveCallback: () => {
			form.subFormClose();
			afterChange();
		},
	});
};

// consult — ลอกจาก consult_box: send = แก้ได้ · accept/complete = ดูอย่างเดียว
s.e2OpenConsultForm = (c) => {
	const form = field.getFormRef();
	form.openForm(FORMS.C, c ? String(c.id) : null, s.e2Vid, null, {
		readonly: !!c && c.status !== 'send',
		afterSaveCallback: () => {
			form.subFormClose();
			s.e2Reload();
		},
	});
};

/* ── emr2 sp-addon (soap/sp-addon.js · gen-emr-v2-model.cjs ต่อท้าย onCreated ของ emr2_soap) ──
   คลินิกเฉพาะทางใน O · ตรวจร่างกาย (mockup board 4 · มติ M1 "คลินิกเฉพาะทางอยู่ใน O")
   🔴 ต้นฉบับ = onCreated ของ vue-ui `spclinic_card` ใน **EMR v1 `6a4f64e7…` บน DB** (decode 2026-10-23 · บรรทัด 19–372)
      ไฟล์ sdform/specialty-clinic/spclinic-card.oncreated.js ในรีโปเก่ากว่า (ไม่มีภาพใบพิมพ์) — ห้ามใช้เป็นฐาน
   ต่างจากต้นฉบับ 3 จุด: ① hideField/showField ไม่ทำอะไร ② ตัวพิมพ์ซ่อนอยู่ที่ #e2s-sp-print-host
      ③ ไม่มี onMounted/watch ของตัวเอง — emr2_soap.e2Load เรียก s.scLoad(tran) ทุกครั้งที่เปลี่ยนคนไข้
   ครอบด้วย { } — ชื่อ const ในนี้ (form · run · PROC …) ไม่ชนกับของ emr2_soap · state ทั้งหมดขึ้นต้น sc* */
{

const PROC = {
  card: '6ac774898ee3675369ac67b6',   // spclinic-card
  copy: '6ac775bb455b901042f7dd14',   // spclinic-copy
  // spclinic-others 6ac775bb…dd15 เลิกใช้แล้ว (2026-10-10) — แท็บคลินิกอื่นมาจาก spclinic-card scope others
}

// ---- state (ค่าเริ่มต้นต้องพร้อมก่อน render แรก)
s.scLoading = false
s.scData = null        // ผลจาก spclinic-card (คลินิกของหน่วยงานที่ login)
s.scOthersData = null  // ผลจาก spclinic-card scope others (คลินิกอื่นใน visit นี้)
s.scTab = ''           // unit_code ของแท็บที่เปิดอยู่
s.scTabPicked = false  // ผู้ใช้กดเลือกแท็บเองแล้ว → ผลที่มาทีหลังห้ามสลับแท็บให้
s.scPending = 0        // call ที่ยังไม่ตอบ (ตัดสินซ่อนการ์ดได้เมื่อครบทั้งสอง)
s.scError = ''
s.scCtx = null         // { visitId, personId, birthDate, visitDate }
s.scOpen = {}          // แถวแบบประเมินที่กางอยู่ (binding_id → true)
s.scMenu = false       // รายการ + Assess
s.scPrintJob = null    // รายงานที่กำลังจะพิมพ์ → <sd-report> ที่ซ่อนอยู่ใน content

const form = () => field.getFormRef()

// ซ่อน/แสดงทั้ง field (ไม่ให้กินที่ตอนไม่มีการ์ด) — แต่ห้ามทำใน builder:
// hide() เขียน options.hidden = true ลงตัวฟอร์ม → ใครกด Save ใน builder การ์ดจะติด hidden ไปทั้งระบบ (เจอจริง 2026-10-08 18:06)
// 🔴 v2: การ์ดอยู่ในช่องกลาง emr2_soap — hide()/show() ของ v1 จะซ่อนทั้งช่องกลาง ⇒ ไม่ทำอะไร (เทมเพลตซ่อนส่วนนี้เองเมื่อไม่มีคลินิก)
const hideField = () => {}
const showField = () => {}
s.scHideField = hideField

// ---- โหลด
s.scLoad = (row) => {
  const vid = row && row.vid
  const ctx = vid && vid.value ? {
    visitId: String(vid.value),
    personId: vid.xtbxlv1_xfx_id ? String(vid.xtbxlv1_xfx_id) : '',
    birthDate: (vid.pid && vid.pid.birth_date) || '',
    visitDate: vid.visit_date || '',
  } : null
  s.scCtx = ctx
  s.scData = null
  s.scOthersData = null
  s.scTab = ''
  s.scTabPicked = false
  s.scError = ''
  s.scOpen = {}
  s.scMenu = false
  s.scPrintJob = null
  if (!ctx) { s.scPending = 0; hideField(); return }
  const f = form()
  if (!f) return
  s.scLoading = true
  s.scPending = 2
  const p = { visit_id: ctx.visitId, person_id: ctx.personId, birth_date: ctx.birthDate, visit_date: ctx.visitDate }
  // คนไข้เปลี่ยนระหว่างรอ → ทิ้งผลเก่า
  const stale = () => !s.scCtx || s.scCtx.visitId !== ctx.visitId
  f.userState.runProcess(PROC.card, p, (res) => {
    if (stale()) return
    const d = (res && res.data) || {}
    s.scLoading = false
    s.scData = d
    if (d.success === false) s.scError = d.message || 'Load failed'
    if (d.success && !d.hidden) refreshImages(d.items)
    s.scPending--
    settle()
  }, () => {
    if (stale()) return
    s.scLoading = false
    s.scError = 'Load failed'
    s.scPending--
    settle()
  })
  f.userState.runProcess(PROC.card, { ...p, scope: 'others' }, (res) => {
    if (stale()) return
    s.scOthersData = (res && res.data) || null
    for (const c of (s.scOthersData && s.scOthersData.clinics) || []) refreshImages(c.items)
    s.scPending--
    settle()
  }, () => {
    if (stale()) return
    s.scPending--
    settle()
  })
}
// หลังแต่ละ call ตอบ: เลือกแท็บเริ่มต้น + ซ่อน/แสดง field
// ไม่มีคลินิกให้โชว์เลย (ทั้งของตัวเองและคลินิกอื่น) → ซ่อนทั้ง field ไม่ให้กินที่บนจอ — แต่รอให้ครบทั้งสอง call ก่อน
const settle = () => {
  const tabs = s.scTabs()
  if (!s.scTabPicked && tabs.length) {
    const own = tabs.find((t) => t.own)
    s.scTab = own ? own.key : tabs[0].key
  }
  if (tabs.length) showField()
  else if (s.scPending <= 0 && !s.scError) hideField()
}
s.scReload = () => { if (s.scCtx) s.scLoad({ vid: { value: s.scCtx.visitId, xtbxlv1_xfx_id: s.scCtx.personId, visit_date: s.scCtx.visitDate, pid: { birth_date: s.scCtx.birthDate } } }) }

// ---- แท็บ: คลินิกตัวเอง + คลินิกอื่นที่บันทึกใน visit นี้
s.scTabs = () => {
  const out = []
  const d = s.scData
  if (d && d.success && !d.hidden) out.push({ key: d.clinic.unit_code || '_own', clinic: d.clinic, items: d.items || [], first_at: d.first_at || '', own: true })
  for (const c of (s.scOthersData && s.scOthersData.clinics) || []) {
    if (out.some((t) => t.key === c.clinic.unit_code)) continue
    out.push({ key: c.clinic.unit_code, clinic: c.clinic, items: c.items || [], first_at: c.first_at || '', own: false })
  }
  // ตามลำดับที่คนไข้ไป (บันทึกครั้งแรก) · ยังไม่บันทึก ('') ไปท้าย
  const at = (t) => t.first_at || '\uffff'
  return out.sort((a, b) => (at(a) < at(b) ? -1 : at(a) > at(b) ? 1 : 0))
}
s.scCur = () => {
  const tabs = s.scTabs()
  return tabs.find((t) => t.key === s.scTab) || tabs[0] || null
}
s.scPickTab = (t) => { s.scTabPicked = true; s.scTab = t.key; s.scMenu = false }
s.scTabCount = (t) => t.items.reduce((n, i) => n + i.entries.length, 0)

// ---- กลุ่มรายการ (ของแท็บที่เปิดอยู่)
s.scItems = () => ((s.scCur() && s.scCur().items) || []).filter((i) => i.display !== 'assessment')
s.scAssess = () => ((s.scCur() && s.scCur().items) || []).filter((i) => i.display === 'assessment')
s.scAssessDone = () => s.scAssess().filter((i) => i.entries.length)
// ยังไม่ประเมิน + แก้ได้ → อยู่ในเมนู · ถึงกำหนดขึ้นก่อน (Overdue > Due > อื่น)
s.scAssessTodo = () => {
  const rank = (i) => (!i.due ? 2 : i.due.level === 'danger' ? 0 : 1)
  return s.scAssess().filter((i) => !i.entries.length && i.can_add).sort((a, b) => rank(a) - rank(b))
}
s.scDueCount = () => s.scAssessTodo().filter((i) => i.due).length

// ---- ข้อความ/สี
const COLOR = { primary: 'primary', success: 'success', warning: 'warning', danger: 'danger', info: 'info' }
s.scTagType = (c) => COLOR[c] || 'info'
s.scColor = (c) => 'var(--el-color-' + (COLOR[c] || 'info') + ')'
// class เน้นคำจาก server → inline style (CSS ของฟอร์ม EMR เป็น global จึงไม่เพิ่ม class ใหม่)
const HL = {
  'hl-b': 'font-weight:600;color:var(--el-text-color-primary)',
  'hl-danger': 'font-weight:600;color:var(--el-color-danger)',
  'hl-warning': 'font-weight:600;color:var(--el-color-warning)',
  'hl-success': 'font-weight:600;color:var(--el-color-success)',
  'hl-primary': 'font-weight:600;color:var(--el-color-primary)',
}
s.scHl = (cls) => HL[cls] || ''
s.scAge = () => {
  const a = s.scData && s.scData.age
  if (!a || a.months === null || a.months === undefined) return ''
  const t = (m) => (m >= 12 ? Math.floor(m / 12) + ' y ' : '') + (m % 12) + ' m'
  return t(a.months) + (a.corrected_months !== null && a.corrected_months !== undefined ? ' · corrected ' + t(a.corrected_months) : '')
}
s.scWhen = (r) => (r.date && s.scCtx && r.date !== s.scCtx.visitDate ? r.date + ' ' : '') + (r.time || '')
s.scBarStyle = (b) => 'flex:1;height:8px;background:' + s.scColor(b.color) + ';opacity:' + (b.hit ? 1 : 0.25)
s.scDrawSize = (item) => ({ S: 56, M: 96, L: 140 }[item.drawing_size] || 96)

// ---- เปิดฟอร์ม (popup ต้องปิดเองหลังบันทึก · autosave ห้ามปิด)
const openPopup = (formId, dataId, initData, readonly) => {
  const f = form()
  if (!f || !s.scCtx) return
  f.openForm(formId, dataId, s.scCtx.visitId, initData, {
    readonly: !!readonly,
    afterSaveCallback: (saved, autoSave) => {
      if (autoSave) return
      f.subFormClose()
      s.scReload()
      if (!readonly) makeImage(formId, savedId(saved, dataId)) // ฟอร์มที่พิมพ์เป็นภาพ: ทำภาพใหม่ทันที
    },
    cancelCallback: () => f.subFormClose(),
  })
}
// แถวที่มีข้อมูล → เปิดดู/แก้ (ไม่มีสิทธิ์แก้ = อ่านอย่างเดียว)
s.scOpenEntry = (item, entry) => openPopup(item.form_id, entry.data_id, null, !item.can_edit)
s.scAdd = (item) => { s.scMenu = false; openPopup(item.form_id, null, null, false) }
s.scToggleMenu = () => { s.scMenu = !s.scMenu }
s.scToggle = (item) => { s.scOpen = { ...s.scOpen, [item.binding_id]: !s.scOpen[item.binding_id] } }

// A2 — เปิดฟอร์มใหม่พร้อมค่าจากครั้งก่อน (ผู้ใช้ยังต้องกดบันทึกเอง)
s.scCopy = (item) => {
  const f = form()
  if (!f || !item.prev || !s.scCtx) return
  f.userState.runProcess(PROC.copy, { binding_id: item.binding_id, data_id: item.prev.data_id, person_id: s.scCtx.personId }, (res) => {
    const d = (res && res.data) || {}
    if (!d.success) { field.alert(d.message || 'Copy failed', 'warning'); return }
    openPopup(item.form_id, null, d.values || {}, false)
  }, () => {})
}


// ปุ่มพิมพ์ต่อรายการ — รายงานที่ตั้งไว้ในฟอร์มลูก (print_report) · ส่ง record_id + visit_id
// createReport() เป็น method ภายใน SdReport เรียกจาก event ไม่ได้ ⇒ mount <sd-report> ตัวใหม่ด้วยค่าของรายการนี้
// (:key เปลี่ยนทุกครั้ง) แล้วกดปุ่มของมันแทน — แบบเดียวกับปุ่มพิมพ์ OPD Card (opd-card.oncreated.js printOpdCard)
s.scPrint = (item, entry) => {
  if (!item.report || !s.scCtx) return
  s.scPrintJob = {
    key: entry.data_id + ':' + Date.now(),
    id: item.report.id,
    type: item.report.type || 'pdf',
    params: { record_id: entry.data_id, visit_id: s.scCtx.visitId },
  }
  setTimeout(() => {
    const doc = globalThis.document // document ตรงๆ ถูก sandbox ปิด
    const btn = doc && doc.querySelector('#e2s-sp-print-host button')
    if (!btn) { field.alert('Print is not available', 'warning'); return }
    btn.click()
  }, 80)
}

// id ของ record ที่เพิ่งบันทึก (shape ของ saved ไม่ตายตัว → ลองหลายแบบ · แก้ record เดิมใช้ dataId ที่เปิดไป)
const savedId = (saved, dataId) => {
  const v = saved && (saved._id || saved.dataid || saved.id)
  const id = v && typeof v === 'object' ? (v.$oid || String(v)) : v
  return id ? String(id) : (dataId ? String(dataId) : '')
}

// ---- ภาพใบพิมพ์ (เพิ่ม 2026-10-10) — ปุ่ม Print = รายงาน Report Factory · ใบที่มีรูปวาดตามข้อมูลใช้ "ภาพ" ของใบ HTML
// ฟอร์มใน PRINT_HTML: หลังบันทึก / ตอนเปิดการ์ดแล้วภาพยังไม่ล่าสุด → ขอ HTML จาก process ของฟอร์ม → วาดลง canvas เป็น JPEG
//   JPEG ไม่ใช่ PNG: PNG จาก canvas มีช่อง alpha → pdfmake แตกเป็น RGB 14 MB + SMask → ตัวแสดง PDF ของ Chrome ที่ฝังใน Report Preview วาดค้างครึ่งใบ (เจอจริง 2026-10-10) · JPEG ฝังตรง (DCT) วาดครบและเร็ว
//   → process spclinic-print-image เก็บ (ส่งเป็นชิ้น ชิ้นละ 512 KB) → SQL provider spclinic_print_image ต่อชิ้นให้รายงาน
// เร็ว: ฟอนต์จาก Google ฝังเป็น data URL ครั้งเดียวต่อหน้าเว็บ (เก็บที่ globalThis) · เช็คก่อนว่า record ไหนภาพเก่า วาดเฉพาะตัวนั้น
//       วาดทีละใบตามคิว ไม่แย่งจังหวะกับหน้าจอ · ใบหนึ่ง ≈ 0.3 วิ หลังฟอนต์พร้อม
// 🔴 sandbox: `document`/`window` เปล่า = undefined → ใช้ globalThis.* (การ์ด opd_card ใช้ globalThis.document อยู่แล้ว)
const PRINT_HTML = {
  '6ac5095e481c196fbb32cb87': '6aca5830481c196fbb3311b1', // Neurological Examination → process neuro-exam-print-html
}
const PRINT_IMG_PROC = '6aca58dc481c196fbb3311b8'         // process spclinic-print-image
const htmlProc = (formId) => { const p = PRINT_HTML[String(formId || '')]; return p && p.indexOf('__') !== 0 ? p : '' }
const imgReady = () => PRINT_IMG_PROC.indexOf('__') !== 0
const RASTER_PX = 1800      // ความกว้างภาพ (px) ≈ 160 dpi บน A4 · คมพอสำหรับตัวหนังสือ 9 pt
const JPEG_Q = 0.92         // คุณภาพ JPEG · ต่ำกว่านี้ขอบตัวหนังสือ/เส้นประเริ่มมีคราบ
const PAGE_RATIO = 781 / 525 // สัดส่วนกรอบภาพในรายงาน (height 781 / width 525) · ภาพวาดลงกรอบนี้เสมอ รายงานไม่ต้องแก้เมื่อใบสูงเปลี่ยน
const IMG_VER = '4'         // รุ่นของภาพ · เปลี่ยนตัววาด/ฟอนต์/กรอบ → เพิ่มเลข แล้วภาพเก่าจะถูกทำใหม่เองตอนเปิดการ์ด (4 = ใบสี + Sarabun + กรอบคงที่ + กล่องผู้ป่วย + reflex สีเหมือนฟอร์ม 2026-10-11)
const CHUNK = 512 * 1024    // ส่งภาพเป็นชิ้น กันชนเพดานขนาด request

s.scImg = {}                // data_id → 'busy' | 'err' · ไม่มี key = ภาพพร้อม (หรือฟอร์มนี้ไม่ใช้ภาพ)
s.scImgBusy = (e) => !!(e && s.scImg[e.data_id] === 'busy')

const G = globalThis
// ฟอนต์: Google Fonts CSS → @font-face ที่ฝังไฟล์เป็น data URL (เก็บแค่ subset thai/latin) · SVG ที่วาดลง canvas โหลดไฟล์ภายนอกไม่ได้
const fontCssOf = (href) => {
  const cache = G.__scPrintFonts || (G.__scPrintFonts = {})
  if (cache[href]) return cache[href]
  const toData = (blob) => new Promise((ok, bad) => { const fr = new G.FileReader(); fr.onload = () => ok(fr.result); fr.onerror = bad; fr.readAsDataURL(blob) })
  cache[href] = G.fetch(href).then((r) => r.text()).then(async (css) => {
    let out = css.split('/* ').slice(1).map((t) => '/* ' + t).filter((t) => /^\/\* (thai|latin) \*\//.test(t)).join('')
    const urls = [...new Set((out.match(/url\((https:[^)]+)\)/g) || []).map((u) => u.slice(4, -1)))]
    const datas = await Promise.all(urls.map((u) => G.fetch(u).then((r) => r.blob()).then(toData)))
    urls.forEach((u, i) => { out = out.split(u).join(datas[i]) })
    return out
  }).catch((e) => { delete cache[href]; throw e })
  return cache[href]
}
// HTML ทั้งหน้า → JPEG data URL · วาดใน iframe ซ่อน (CSS ของใบไม่รั่วไปหน้า EMR) แล้วถ่ายผ่าน SVG foreignObject
const htmlToPng = async (html) => {
  const d = G.document
  const src = new G.DOMParser().parseFromString(html, 'text/html')
  const hrefs = [...src.querySelectorAll('link[rel="stylesheet"]')].map((l) => l.getAttribute('href')).filter((h) => /^https:\/\/fonts\.googleapis\.com\//.test(h))
  const fontCss = (await Promise.all(hrefs.map(fontCssOf))).join('\n')
  const css = fontCss + '\n' + [...src.querySelectorAll('style')].map((t) => t.textContent).join('\n')
  const fr = d.createElement('iframe')
  fr.setAttribute('style', 'position:fixed;left:-20000px;top:0;width:1400px;height:2000px;border:0;visibility:hidden')
  d.body.appendChild(fr)
  try {
    const fd = fr.contentDocument
    fd.open(); fd.write('<!doctype html><html><head><meta charset="utf-8"><style>' + css + '</style></head><body>' + src.body.innerHTML + '</body></html>'); fd.close()
    if (fd.fonts && fd.fonts.ready) await fd.fonts.ready
    // ขนาดใบ = ขอบเขตรวมของทุกอย่างใน body (ลูกตัวแรกอาจเป็น <svg> เก็บ defs ที่ไม่มีขนาด)
    let w = 0, h = 0
    for (const el of fd.body.children) {
      const box = el.getBoundingClientRect()
      if (box.width && box.height) { w = Math.max(w, Math.ceil(box.right)); h = Math.max(h, Math.ceil(box.bottom)) }
    }
    G.__scPrintLast = { w, h, n: fd.body.children.length } // ดูใน Console ได้เมื่อภาพผิดขนาด
    if (!(w > 100 && h > 100)) throw new Error('วัดขนาดใบไม่ได้ (' + w + '×' + h + ')')
    const wrap = fd.createElement('div')
    wrap.setAttribute('style', 'width:' + w + 'px;height:' + h + 'px;background:#fff;overflow:hidden')
    wrap.innerHTML = '<style>' + css + '</style>' + fd.body.innerHTML
    const svg = '<svg xmlns="http://www.w3.org/2000/svg" width="' + w + '" height="' + h + '"><foreignObject x="0" y="0" width="100%" height="100%">' +
      new G.XMLSerializer().serializeToString(wrap) + '</foreignObject></svg>'
    const img = new G.Image()
    img.src = 'data:image/svg+xml;charset=utf-8,' + encodeURIComponent(svg)
    await img.decode()
    // กรอบคงที่ RASTER_PX × (RASTER_PX × PAGE_RATIO) · ใบเตี้ยกว่า = ขาวเติมล่าง · ใบสูงกว่า = ย่อทั้งใบให้พอดี (ไม่ตัด)
    const cv = d.createElement('canvas')
    cv.width = RASTER_PX; cv.height = Math.round(RASTER_PX * PAGE_RATIO)
    const k = Math.min(cv.width / w, cv.height / h)
    const ctx = cv.getContext('2d')
    ctx.fillStyle = '#fff'; ctx.fillRect(0, 0, cv.width, cv.height)
    ctx.translate(Math.round((cv.width - w * k) / 2), 0)
    ctx.scale(k, k)
    ctx.drawImage(img, 0, 0)
    return cv.toDataURL('image/jpeg', JPEG_Q)
  } finally {
    if (fr.parentNode) fr.parentNode.removeChild(fr)
  }
}
// runProcess แบบรอผล (ผลมาทาง callback เท่านั้น)
const run = (proc, p) => new Promise((ok, bad) => {
  const f = form()
  if (!f) { bad(new Error('ไม่มีฟอร์ม')); return }
  f.userState.runProcess(proc, p, (res) => ok((res && res.data) || {}), (e) => bad(e || new Error('process error')))
})
const uploadImg = async (formId, recordId, png) => {
  const parts = Math.ceil(png.length / CHUNK)
  const uploadId = recordId.slice(-8) + '-' + Date.now().toString(36)
  for (let i = 0; i < parts; i++) {
    const r = await run(PRINT_IMG_PROC, { mode: 'save', form_id: formId, record_id: recordId, upload_id: uploadId, part: i, parts, ver: IMG_VER, chunk: png.slice(i * CHUNK, (i + 1) * CHUNK) })
    if (!r.success) throw new Error(r.message || 'เก็บภาพไม่สำเร็จ')
  }
}
// คิววาดภาพ: ทีละใบ · ใบเดียวกันเข้าคิวซ้ำไม่ได้
let imgQueue = Promise.resolve()
const makeImage = (formId, recordId) => {
  const proc = htmlProc(formId)
  if (!proc || !imgReady() || !recordId || s.scImg[recordId] === 'busy') return
  s.scImg = { ...s.scImg, [recordId]: 'busy' }
  const done = (state) => {
    const n = { ...s.scImg }; if (state) n[recordId] = state; else delete n[recordId]; s.scImg = n
    const want = s.scImgWant
    if (want && want.entry && want.entry.data_id === recordId) { s.scImgWant = null; printNow(want.item, want.entry) }
  }
  imgQueue = imgQueue.then(async () => {
    try {
      const r = await run(proc, { data_id: recordId })
      if (!r.success || !r.html) throw new Error(r.message || 'ไม่มีใบพิมพ์')
      await uploadImg(String(formId), recordId, await htmlToPng(r.html))
      done('')
    } catch (e) {
      console.warn('[spclinic print] ทำภาพใบพิมพ์ไม่สำเร็จ:', e && e.message)
      done('err')
    }
  })
}
// อุ่นฟอนต์ไว้ก่อนตั้งแต่เปิดการ์ดที่มีฟอร์มใช้ภาพ (ครั้งแรกของหน้าเว็บใช้เวลาโหลด · ครั้งต่อไปเร็ว)
const FONT_HREF = 'https://fonts.googleapis.com/css2?family=Sarabun:wght@400;500;600;700&display=swap' // ต้องตรงกับ FONTS ใน process ของใบ (ไม่ตรง = แค่อุ่นผิดตัว ช้าลงครั้งแรก)
const hrefsWarm = () => { fontCssOf(FONT_HREF).catch(() => { /* ลองใหม่ตอนวาดจริง */ }) }
// เปิดการ์ด: ฟอร์มที่ใช้ภาพ → ถาม server ว่า record ไหนภาพเก่า/ยังไม่มี แล้ววาดเฉพาะตัวนั้น (1 call ต่อฟอร์ม)
const refreshImages = (items) => {
  if (!imgReady()) return
  for (const item of items || []) {
    if (!item.report || !htmlProc(item.form_id)) continue
    const ids = (item.entries || []).map((e) => e.data_id).filter(Boolean)
    if (!ids.length) continue
    hrefsWarm()
    run(PRINT_IMG_PROC, { mode: 'status', form_id: item.form_id, record_ids: ids, ver: IMG_VER })
      .then((r) => (r.stale || []).forEach((id) => makeImage(item.form_id, id)))
      .catch(() => { /* เช็คไม่ได้ = ไม่วาด ปุ่ม Print ยังกดได้ */ })
  }
}

// กด Print ระหว่างภาพของรายการนั้นยังทำไม่เสร็จ → รอ แล้วพิมพ์ให้เองเมื่อภาพเสร็จ (ไม่ได้ภาพ = พิมพ์ตามเดิม รายงานบอกเอง)
const printNow = s.scPrint
s.scPrint = (item, entry) => {
  if (entry && s.scImg[entry.data_id] === 'busy') {
    s.scImgWant = { item, entry }
    field.notify('กำลังเตรียมใบพิมพ์ รอสักครู่', 'info')
    return
  }
  printNow(item, entry)
}
s.scImgWant = null

/* ══ หน้าตา v2 (mockup board 4 · ส่วน O) — ข้อมูล/ปุ่มทั้งหมดใช้ของต้นฉบับข้างบน ══════════════
   หลักไม่ให้ตาลาย: 1 บรรทัดต่อฟอร์ม · กางได้ทีละอัน · สถานะเป็นสีตัวอักษร ไม่ใช่ป้ายทึบ
   คลินิกอื่น = สรุปบรรทัดเดียวต่อท้ายใบ 🔒 ของคลินิกนั้น (ไม่มีแท็บแบบ v1) */
s.scFormMenu = false // รายการ "+ เพิ่มฟอร์ม"
s.e2SpToggleFormMenu = () => { s.scFormMenu = !s.scFormMenu; s.scMenu = false }
s.e2SpToggleAssessMenu = () => { s.scMenu = !s.scMenu; s.scFormMenu = false }

// คลินิกของหน่วยงานที่ login — ไม่มี config (hidden) = ไม่มีส่วนนี้ใน O
s.e2SpOwn = () => {
  const d = s.scData
  return d && d.success && !d.hidden ? { clinic: d.clinic || {}, items: d.items || [] } : null
}
const ownItems = () => (s.e2SpOwn() ? s.e2SpOwn().items : [])
s.e2SpAddable = () => ownItems().filter((i) => i.display !== 'assessment' && i.can_add)

// กางทีละอัน (mockup) · ใช้ scOpen ของต้นฉบับเก็บ
s.e2SpOpen = (item) => !!s.scOpen[item.binding_id]
s.e2SpToggle = (item) => { s.scOpen = s.scOpen[item.binding_id] ? {} : { [item.binding_id]: true } }

const tone = (color) => s.scColor(color) // 'danger' → var(--el-color-danger)
const plainOf = (parts) => (parts || []).map((p) => p[0]).join('')
const findingsOf = (exam) =>
  (exam.sections || [])
    .filter((x) => x.ok === false)
    .flatMap((x) => (x.findings && x.findings.length ? x.findings.map((f) => f.label + ' ' + f.value) : [x.label + (x.overall ? ' ' + x.overall : '')]))

// บรรทัดของฟอร์ม (exam / card / list) — สรุปจากรายการล่าสุด · หลายรายการบอกจำนวน
s.e2SpRow = (item) => {
  const e = item.entries[0]
  if (!e) return { has: false, dot: 'var(--e2-muted)', status: 'ยังไม่บันทึก', statusColor: 'var(--e2-muted)', detail: '', action: item.copy && item.prev ? 'Copy ' + item.prev.date : '' }
  const many = item.entries.length > 1 ? item.entries.length + ' รายการ · ' : ''
  if (e.exam) {
    const bad = !!e.exam.abnormal
    const color = tone(bad ? 'danger' : 'success')
    const finds = findingsOf(e.exam)
    return {
      has: true, dot: color, statusColor: color,
      status: bad ? e.exam.abnormal + ' abnormal' : 'All WNL · ' + e.exam.normal + ' WNL',
      detail: many + (finds.length ? finds.join(' · ') : 'ไม่พบความผิดปกติ'),
      action: '',
    }
  }
  const color = e.status ? tone(e.status[1]) : 'var(--e2-accent)'
  return {
    has: true, dot: color, statusColor: color,
    status: e.status ? e.status[0] : '',
    detail: many + [plainOf(e.title), plainOf(e.detail)].filter(Boolean).join(' · '),
    action: '',
  }
}
s.e2SpChips = (e) => ((e.exam && e.exam.sections) || []).filter((x) => x.examined)
// กางแล้ว: 1 บรรทัดต่อส่วนที่ผิดปกติ (แบบการ์ด v1) — ฟอร์มใหญ่อย่าง Neuro มีผิดปกติได้เป็นสิบช่อง
s.e2SpFindings = (e) =>
  ((e.exam && e.exam.sections) || [])
    .filter((x) => x.ok === false)
    .map((x) => ({ label: x.label, text: x.findings && x.findings.length ? x.findings.map((f) => f.label + ' ' + f.value).join(' · ') : x.overall || 'ผิดปกติ' }))

// แบบประเมิน
s.e2SpScore = (it) => {
  const a = it.entries[0] && it.entries[0].assess
  return a && a.score !== null && a.score !== undefined && !a.text ? a.score + '/' + a.max : ''
}
s.e2SpLevel = (it) => {
  const e = it.entries[0]
  return e && e.status ? e.status[0] : (e && e.assess && e.assess.text) || ''
}
s.e2SpLevelColor = (it) => {
  const e = it.entries[0]
  return tone(e && e.status ? e.status[1] : 'info')
}
s.e2SpBar = (it) => {
  const a = it.entries[0] && it.entries[0].assess
  const pct = a && a.max ? Math.max(0, Math.min(100, Math.round((a.score / a.max) * 100))) : 0
  return 'width:' + pct + '%;background:' + s.e2SpLevelColor(it)
}
s.e2SpHasBar = (it) => !!s.e2SpScore(it)
s.e2SpPrev = (it) => {
  const a = it.entries[0] && it.entries[0].assess
  return a && a.prev ? 'ครั้งก่อน ' + a.prev.date + ': ' + a.prev.score + (a.max ? '/' + a.max : '') : ''
}
// ยังไม่ประเมิน + ถึงกำหนด (แสดงเป็นแถวใต้รายการที่ทำแล้ว) · เมนู + Assess แยกกลุ่ม Overdue / Due / อื่น ๆ
s.e2SpDue = () => s.scAssessTodo().filter((i) => i.due)
s.e2SpMenuGroups = () => {
  const todo = s.scAssessTodo()
  const groups = [
    { key: 'danger', title: 'Overdue', color: tone('danger'), items: todo.filter((i) => i.due && i.due.level === 'danger') },
    { key: 'warning', title: 'Due', color: tone('warning'), items: todo.filter((i) => i.due && i.due.level !== 'danger') },
    { key: 'other', title: 'อื่น ๆ', color: 'var(--e2-muted)', items: todo.filter((i) => !i.due) },
  ]
  return groups.filter((g) => g.items.length)
}

// คลินิกอื่นใน visit นี้ — สรุปบรรทัดเดียว (ไม่รวมคลินิกของเราเอง)
const otherClinics = () => {
  const own = s.e2SpOwn()
  const ownCode = own && own.clinic ? own.clinic.unit_code : ''
  return ((s.scOthersData && s.scOthersData.clinics) || []).filter((c) => c.clinic && c.clinic.unit_code !== ownCode)
}
// ฟอร์มที่มีบันทึกของคลินิกนั้น — ข้อความสรุป + ที่อยู่ record (กดเปิดดูแบบอ่านอย่างเดียว · พี่สั่ง 2026-10-23)
const itemsOf = (c) =>
  (c.items || [])
    .filter((i) => i.entries && i.entries.length)
    .map((i) => {
      const e = i.entries[0]
      let text = i.label + (e.status ? ': ' + e.status[0] : '')
      if (e.exam) text = i.label + ': ' + (e.exam.abnormal ? e.exam.abnormal + ' abnormal' : 'All WNL')
      else if (e.assess && e.assess.score !== null && e.assess.score !== undefined && !e.assess.text) text = i.label + ' ' + e.assess.score + '/' + e.assess.max
      return { key: i.binding_id || i.form_id, text, form_id: i.form_id, data_id: e.data_id }
    })
// ต่อท้ายใบ 🔒 ของคลินิกนั้น (unit = so_clinic ของใบ) — คืน [] เมื่อไม่มี (template เช็ค .length)
s.e2SpOtherItems = (unit) => {
  const c = otherClinics().find((x) => x.clinic.unit_code === String(unit || ''))
  return c ? itemsOf(c) : []
}
// ฟอร์มของคลินิกอื่น = ดูได้อย่างเดียวเสมอ (ไม่อิง can_edit — ใบไม่ใช่ของเรา)
s.e2SpOtherOpen = (it) => openPopup(it.form_id, it.data_id, null, true)
// คลินิกที่มีแบบฟอร์มแต่ไม่มีใบ O ให้ต่อท้าย → แถว 🔒 ของตัวเอง
s.e2SpOtherLoose = (owners) => {
  const has = new Set((owners || []).map(String))
  return otherClinics()
    .filter((c) => !has.has(c.clinic.unit_code))
    // ชื่อคลินิกตาม Organization (ชุดเดียวกับป้ายใบ 🔒 อื่น) · ไม่อยู่ในคิว = ชื่อคลินิกเฉพาะทาง
    .map((c) => {
      const j = (s.e2Journey ? s.e2Journey() : []).find((x) => x.unit === c.clinic.unit_code)
      return { unit: c.clinic.unit_code, name: j ? j.name : c.clinic.title, items: itemsOf(c) }
    })
    .filter((c) => c.items.length)
}
}

options.onMounted:
// emr2_soap · onMounted — แท็บ EMR เปิดทีหลังคนไข้ถูกเลือก: อ่าน visit จาก $examTran (ตัวเดียวกับ opd_card)
// ครั้งต่อไป opd_card.setTran ปลุกเอง (hook ใน v2) · หน่วง 1 tick กันเคส field ยังไม่ register
// + เริ่มวัดความสูง 3 ช่อง + ใส่/ถอดคลาสเต็มจอตามสถานะ (เริ่มที่ย่อเสมอ) (e2WatchFit / e2ApplyFull / e2Fit อยู่ใน onCreated)
const field = this;
setTimeout(() => {
	const s = field.vueState;
	const form = field.getFormRef();
	const tran = form && form.$examTran;
	const vid = tran && tran.vid && tran.vid.value;
	if (vid && s.e2Vid !== String(vid)) s.e2Load(String(vid), tran);
	if (s.e2WatchFit) s.e2WatchFit();
	if (s.e2ApplyFull) s.e2ApplyFull();
	else if (s.e2Fit) s.e2Fit();
}, 0);

options.onCreated:
/**
 * order_card · onCreated — การ์ด "ใบสั่งยา" ในหน้า EMR (ฟอร์ม EMR 6a4f64e7f8cdfc54cec16488)
 *
 * หน้าที่: ทางเข้า "สั่งยา" ทั้งหมดของหน้า EMR รวมอยู่ที่การ์ดนี้ที่เดียว
 *   ① ปุ่ม "+ สั่งยา" (ใบใหม่)  ② เห็นใบที่บันทึกไปแล้วของวิสิทนี้  ③ กดกลับเข้าไปแก้ใบร่างเดิม
 *   ไม่มีการ์ดนี้ = ใบร่างหายเข้า DB · กดสั่งยาอีกครั้งได้ใบใหม่เรื่อย ๆ แทนที่จะแก้ใบเดิม
 *
 * วางที่: grid_col56484 — 🔴 แทนที่ button-ui `button_ui85075` เดิม (พี่สั่งย้ายปุ่มเข้าการ์ด 2026-08-04)
 *   ⇒ ประกอบ patient context ที่นี่ที่เดียว ไม่ต้องมีสองชุดให้แก้ให้ตรงกัน
 *   (ไฟล์ปุ่มเดิม emr-drug-order-button.js เก็บไว้อ้างอิงเท่านั้น ไม่ได้ใช้แล้ว)
 * โหลดข้อมูล: process cpoe-order-list (อ่านอย่างเดียว)
 *
 * 🔴 ทุก key ที่เทมเพลตอ้างต้องมีค่าตั้งแต่ตรงนี้ — ขาดตัวเดียว = error box ทั้ง widget
 * 🔴 การ์ดนี้ **ไม่ query ข้อมูลคนไข้เอง** — หยิบจาก opd_card ที่โหลดไว้แล้ว (แหล่งเดียวกับปุ่มสั่งยา)
 *    ระดับ warn/danger ของ vital ตัดสินที่ opd_card ที่เดียว ไม่งั้นสองจอเตือนคนละแบบ
 */

const s = this.vueState;
const field = this;

const DRUG_ORDER_FORM_ID = '6a70b8cd74be9b0d6e2dca74'; // Drug Order (form_ui)
const LIST_PROC = '6a71fe5f29c75d41e9c7e9cb'; // cpoe-order-list
const SEND_PROC = '6a757d1bf7bf7668d7673c63'; // cpoe-order-send (draft → sent)
const CANCEL_PROC = '6a7822e11eb17ebfd41dd4d4'; // cpoe-order-cancel (draft → ลบ · sent → cancelled · action recall: sent → draft)
const VISIT_PROVIDER = '6a40fdec4b6dfdf45acbfbce'; // ฟอร์ม Visit → zdata_visit

/* ══ state ════════════════════════════════════════════════════════════════ */
s.ordList = [];
s.ordLoading = false;
s.ordErr = '';
s.ordVid = null; // visit _id ปัจจุบัน — เซ็ตผ่าน ordLoad จาก opd_card
s.ordTran = null; // Visit Tran ทั้งแถว (ใช้ประกอบ patient context ตอนเปิดจอสั่งยา)
s.ordOpenRow = {};
s.ordItemOpen = {}; // '<order_id>:<index>' → กางรายละเอียดราคาของรายการนั้นอยู่ไหม (ราคาแบบ C)
s.ordDirty = false; // จอสั่งยาแตะใบใน DB แล้วหรือยัง — ตัวตัดสินว่าตอนปิด popup ต้องโหลดใหม่ไหม
s.ordSending = {}; // order_id ที่กำลังส่ง — กันกดรัวระหว่างรอ process
s.ordBlocks = {}; // order_id → คำเตือนระดับห้ามสั่งที่ตีกลับมา (แสดงในการ์ด ไม่ใช่ alert ที่หายไป)
s.ordOvrId = ''; // ใบที่กำลังกรอกเหตุผลยืนยันส่ง — ทีละใบเท่านั้น (กล่องเหตุผลของสองใบพร้อมกัน = กรอกผิดใบ)
s.ordOvrText = ''; // เหตุผลที่หมอกำลังพิมพ์
s.ordOvrErr = ''; // เหตุผลสั้นเกิน/ว่าง — บอกที่จอก่อนยิง ไม่ให้ server เป็นคนตีกลับ
s.ordBusy = {}; // order_id ที่กำลังยกเลิก/ลบ — แยกจาก ordSending เพราะเป็นคนละปุ่มบนใบเดียวกัน (C43)
s.ordCanId = ''; // ใบที่กำลังกรอกเหตุผลยกเลิก — ทีละใบ เหตุผลเดียวกับกล่อง override
s.ordCanText = '';
s.ordCanErr = '';
/* ใบที่ต้องเปิดกล่อง "ยืนยันส่งทั้งที่มีคำเตือน" ให้หลังโหลดเสร็จ — { id, blocks } (ปุ่มตรวจเสร็จใน action bar ส่งมา)
   🔴 ไม่ล้างใน ordLoad ตอนเริ่ม — ต้องรอดผ่านการโหลดใหม่ไปถึง callback ถึงจะเปิดกล่องได้ */
s.ordPendingBlock = null;

/* ══ ป้ายสถานะ — ชุดเดียวกับ pis-dispense D6 ═════════════════════════════
   🔴 ค่าที่ไม่รู้จักต้องโชว์ค่าดิบ ห้ามแปลงเป็น "ร่าง" — ใบที่สถานะเพี้ยน (เช่น "DRAFT" ตัวใหญ่)
      ต้องมองเห็นได้จากจอ ไม่ใช่ถูกกลบให้ดูปกติ */
const STATUS = {
	draft: { label: 'ร่าง', color: 'info' },
	sent: { label: 'ส่งห้องยาแล้ว', color: 'warning' },
	accepted: { label: 'ห้องยารับแล้ว', color: 'warning' },
	prepared: { label: 'จัดยาแล้ว', color: 'warning' },
	ready: { label: 'พร้อมจ่าย', color: 'success' },
	dispensed: { label: 'จ่ายยาแล้ว', color: 'success' },
	returned: { label: 'คืนยา', color: 'danger' },
	cancelled: { label: 'ยกเลิก', color: 'info' },
	reversed: { label: 'กลับรายการ', color: 'danger' },
};
s.ordStatus = (o) => {
	const raw = String((o && o.current_status) || '');
	return STATUS[raw] || { label: raw || '—', color: 'danger' };
};

s.ordMoney = (n) => '฿' + Number(n || 0).toLocaleString('th-TH', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
// created_at เป็น "YYYY-MM-DD HH:mm:ss" — ใบของวิสิทเดียวกันเกิดวันเดียวกันเกือบเสมอ จึงโชว์แค่เวลา
s.ordTime = (v) => {
	const t = String(v || '');
	return t.length >= 16 ? t.slice(11, 16) + ' น.' : t;
};

// ยอดของรายการ — ใช้ net_amount ที่ price-calc คิดไว้ (รวม override ราคา) · ใบเก่าที่ไม่มีค่อยคูณเอง
s.ordLineTotal = (it) => {
	if (!it) return 0;
	if (it.net_amount != null) return Number(it.net_amount) || 0;
	return (Number(it.unit_price) || 0) * (Number(it.quantity) || 0);
};
// ตัวเลขในแถวรายการไม่ใส่ ฿ — แถวแคบ และหัวใบบอกหน่วยเงินไว้แล้ว
s.ordNum = (n) => Number(n || 0).toLocaleString('th-TH', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
s.ordItemToggle = (orderId, i) => {
	const k = String(orderId) + ':' + i;
	const next = Object.assign({}, s.ordItemOpen);
	next[k] = !next[k];
	s.ordItemOpen = next;
};

s.ordToggle = (id) => {
	s.ordOpenRow[id] = !s.ordOpenRow[id];
};

/* ══ โหลดใบของวิสิท ═══════════════════════════════════════════════════════
   เรียกจาก opd_card.setTran (เปลี่ยนคนไข้) · onMounted (เข้าแท็บ EMR ทีหลัง) · หลังปิด popup */
s.ordLoad = (visitId, tran) => {
	s.ordVid = visitId ? String(visitId) : null;
	if (tran !== undefined) s.ordTran = tran || null;
	s.ordList = [];
	s.ordErr = '';
	s.ordOpenRow = {};
	s.ordItemOpen = {};
	s.ordBlocks = {}; // คำเตือนของรอบก่อนต้องหายไปพร้อมรายการเก่า ไม่งั้นค้างทับใบที่แก้แล้ว
	s.ordOvrId = ''; // กล่องเหตุผลที่ค้างเปิดอยู่ต้องปิดตามด้วย — ใบเก่าอาจไม่อยู่ในลิสต์ใหม่แล้ว
	s.ordOvrText = '';
	s.ordOvrErr = '';
	s.ordCanId = ''; // กล่องเหตุผลยกเลิกก็ต้องปิดด้วยเหตุผลเดียวกัน (C43)
	s.ordCanText = '';
	s.ordCanErr = '';
	if (!s.ordVid) return;
	const form = field.getFormRef();
	if (!form) return;
	s.ordLoading = true;
	e2Req(
		form,
		LIST_PROC,
		{ visit_id: s.ordVid, full_items: true }, // ใช้ร่วมกับ item_card (e2Req) · ตัดเหลือ 8 บรรทัดข้างล่าง
		(res) => {
			s.ordLoading = false;
			const d = (res && res.data) || {};
			// process ที่ตีกลับด้วย success:false ก็มาทาง callback นี้ ไม่ใช่ errCb — ต้องเช็คเอง
			if (!d.success) {
				s.ordErr = d.message || 'อ่านใบสั่งยาไม่สำเร็จ';
				return;
			}
			/* 🔴 การ์ดนี้แสดง **เฉพาะใบยา** (พี่เคาะ 2026-08-29) — cpoe-order-list คืนทุกใบของวิสิท
			   ตั้งแต่มีจอสั่งตรวจ ใบ lab/x-ray จะปนเข้ามาถ้าไม่กรอง แล้วหมอกด "ส่งใบสั่งยา" กับใบแลปได้
			   🔴 กรองด้วย `service_type_code` (code ดิบ) ไม่ใช่ `service_type` ซึ่งเป็น label ที่ rename ได้
			   ใบสั่งตรวจอยู่ที่การ์ด item_card ซึ่งกรองกลับด้านกันพอดี */
			// ตัดรายการเหลือ 8 บรรทัด/ใบ = ค่าเริ่มต้นของ cpoe-order-list (ไม่ได้ส่ง full_items) — การ์ดนี้เป็นสรุป
			const all = (Array.isArray(d.orders) ? d.orders : []).map((o) => (Array.isArray(o.items) ? Object.assign({}, o, { items: o.items.slice(0, 8) }) : o));
			s.ordList = all.filter((o) => String(o.service_type_code || '') === 'med');
			// มีใบเดียว ⇒ กางให้เลยทุกสถานะ (พี่สั่ง 2026-10-08 — เดิมกางเฉพาะใบร่าง · ชุดเดียวกับการ์ดใบสั่งตรวจ)
			if (s.ordList.length === 1) s.ordOpenRow[s.ordList[0].order_id] = true;
			// กล่องเหตุผลที่ action bar ขอเปิดไว้ (ติดคำเตือนห้ามสั่งตอนกดตรวจเสร็จ) — กางใบ + แปะคำเตือน + เปิดกล่องรอกรอก
			const pb = s.ordPendingBlock;
			s.ordPendingBlock = null;
			if (pb && s.ordList.some((o) => String(o.order_id) === pb.id && String(o.current_status || '') === 'draft')) {
				s.ordOpenRow[pb.id] = true;
				s.ordBlocks[pb.id] = pb.blocks || [];
				s.ordOvrId = pb.id;
			}
		},
		(err) => {
			s.ordLoading = false;
			s.ordErr = 'อ่านใบสั่งยาไม่สำเร็จ: ' + ((err && err.message) || err);
		},
	);
};

/* การ์ดสรุปค่าใช้จ่ายอยู่ใน item_card (แบบ A·1 · 2026-10-08) — ใบยาเปลี่ยนที่นี่ ต้องให้ยอดฝั่งนั้นโหลดตาม
   ทุกจังหวะที่ใบยาเปลี่ยน (ส่ง/ลบ/ยกเลิก/ดึงกลับ/ปิดจอสั่งยา/กดโหลดใหม่) วิ่งผ่าน ordReload ⇒ sync ที่เดียวพอ
   🔴 ไม่มี costRefresh (item_card รุ่นเก่า) = ข้ามเงียบ */
s.ordReload = () => {
	s.ordLoad(s.ordVid, undefined);
	const ic = field.getFieldRef('item_card');
	const fn = ic && ic.vueState && ic.vueState.costRefresh;
	if (typeof fn === 'function') fn();
};

/* ══ patient context ที่จอสั่งยาต้องได้ครบ ════════════════════════════════
   🔴 จอสั่งยา "ห้าม query ซ้ำ" — ข้อมูลคนไข้/วิสิท/สิทธิ์/vitals ต้องส่งครบจากที่นี่ (D4.4)
      ตารางแปลงค่า (เพศ · หมู่เลือด · ชนิดบริการ · ระดับ warn/danger ของ vital) อยู่ที่ opd_card
      ที่เดียว — หยิบมาใช้ ห้ามทำชุดของตัวเอง ไม่งั้นวันหนึ่งสองจอจะเตือนคนละแบบ
   🔴 ส่งทาง `params` ไม่ใช่ `initData` — form_ui ที่มีแต่ vue-ui ตัด initData ทิ้งใน buildDataModel */
const ptContext = () => {
	const form = field.getFormRef();
	const card = field.getFieldRef('opd_card');
	const cs = (card && card.vueState) || {};
	const tran = s.ordTran || cs.tran || (form && form.$examTran) || null;
	const visit = (tran && tran.vid) || null;
	if (!visit) return null;

	const pt = visit.pid || {};
	const bmi = cs.bmiRec || {};
	const vs = cs.vsRec || {};
	const lvl = (name) => {
		if (typeof cs.vsClass !== 'function') return '';
		const c = cs.vsClass(name);
		return c === 'is-danger' ? 'bad' : c === 'is-warning' ? 'warn' : '';
	};
	const vital = (value, level) => (value === null || value === undefined || value === '' ? null : { value: value, level: level || '' });
	const bpValue = vs.bp_h && vs.bp_l ? String(vs.bp_h) + '/' + String(vs.bp_l) : '';
	const bpLevel = typeof cs.bpClass === 'function' ? (cs.bpClass() === 'is-danger' ? 'bad' : cs.bpClass() === 'is-warning' ? 'warn' : '') : '';

	return {
		person_id: visit.xtbxlv1_xfx_id ? String(visit.xtbxlv1_xfx_id) : '',
		hn: pt.hn || '',
		full_name: typeof cs.ptName === 'function' ? cs.ptName() : [pt.p_fname, pt.p_lname].filter(Boolean).join(' '),
		sex: typeof cs.genderLabel === 'function' ? cs.genderLabel() : '',
		age: pt.age == null ? '' : pt.age,
		blood_group: typeof cs.aboLabel === 'function' ? cs.aboLabel() : '',
		p_pic: pt.p_pic || null,
		allergy_tags: (tran && tran.allergy_tags) || [],
		visit_id: String(visit.value || visit._id || ''),
		vn: visit.vn || '',
		visit_type: typeof cs.serviceTypeLabel === 'function' ? cs.serviceTypeLabel() : '',
		visit_datetime: typeof cs.visitTime === 'function' ? cs.visitTime() : visit.visit_date || '',
		visit_clinic: (visit.visit_clinic || {}).label || '',
		visit_doctor: (visit.visit_doctor || {}).label || '',
		dx_summary: '',
		weight: bmi.weight == null ? '' : bmi.weight,
		height: bmi.stature == null ? '' : bmi.stature, // 🔴 ฟอร์ม BMI ใช้ชื่อ stature ไม่ใช่ height
		bmi: bmi.bmi == null ? '' : bmi.bmi,
		bsa: bmi.bsa == null ? '' : bmi.bsa,
		bp: vital(bpValue, bpLevel),
		pr: vital(vs.pulse, lvl('pulse')),
		temp: vital(vs.temp, lvl('temp')),
		rr: vital(vs.rr, lvl('rr')),
		service_type: 'med',
		inscl_hos: Array.isArray(visit.inscl_hos) ? visit.inscl_hos : [],
	};
};

/* เปิดจอสั่งยา — extra = { order_id } เมื่อเป็นการกลับเข้าไปแก้ใบเดิม

   🔴 refresh เฉพาะตอนที่ "ใบเปลี่ยนจริง" เท่านั้น (พี่แจ้ง 2026-08-04)
      cancelCallback เป็นทางออกทางเดียวของ popup — ทั้ง "กดปิดเฉย ๆ" และ "บันทึกแล้วปิด"
      (จอกด closePopup() ซึ่งวิ่งผ่าน cancelCallback ชุดนี้ · SdFormRender:1060) ⇒ ตัวมันเองแยกไม่ออก
      ⇒ ให้ "จอ" เป็นคนบอกผ่าน callback ที่ฝากไปกับ params — เปิดแล้วปิดเฉย ๆ จึงไม่ยิง process ฟรี
      (function ผ่าน params ได้จริง: formParams/vueParams เป็น shallow spread ทั้งคู่ ไม่ได้ clone ทิ้ง) */
const openScreen = (ctx, extra) => {
	const form = field.getFormRef();
	s.ordDirty = false;
	form.openForm(DRUG_ORDER_FORM_ID, '', String(ctx.visit_id), null, {
		backdrop: false, // ใบยาว — กดพลาดนอกกล่องแล้วปิดทิ้ง = เสียของที่เลือกไว้
		// 🔴 ต้อง spread formParams ของแม่ ไม่งั้น popup ไม่เหลือ _id/xsitex/xunitx (ระบบใช้ตัดสิน site/unit)
		params: Object.assign({}, form.formParams, ctx, extra || {}, {
			// จอเรียกตัวนี้เมื่อ "แตะใบใน DB แล้ว" (บันทึกสำเร็จ หรือหัวใบเกิดแล้วรายการล้มกลางทาง)
			on_order_saved: () => {
				s.ordDirty = true;
			},
		}),
		// 🔴 ใส่ cancelCallback เอง = ทับ default ⇒ ต้อง subFormClose() เองด้วย
		cancelCallback: () => {
			form.subFormClose();
			if (!s.ordDirty) return; // ปิดเฉย ๆ — รายการในการ์ดยังตรงกับ DB อยู่แล้ว
			s.ordDirty = false;
			s.ordReload();
		},
	});
};

// ปุ่ม "+ สั่งยา" ที่หัวการ์ด — เปิดจอเปล่าเพื่อออกใบใหม่
s.ordNew = () => {
	const ctx = ptContext();
	if (!ctx || !ctx.visit_id) {
		field.alert('ยังไม่ได้เลือกผู้ป่วย/visit', 'warning');
		return;
	}
	withInscl(ctx, (full) => openScreen(full, null));
};

// เปิดแก้ใบร่างเดิม — จอจะโหลดรายการกลับเป็นตะกร้าเองจาก order_id (process cpoe-order-get)
s.ordEdit = (o) => {
	if (!o || !o.order_id) return;
	if (!o.can_edit) {
		field.alert('ใบนี้ไม่ใช่ใบร่างแล้ว จึงแก้จากจอสั่งยาไม่ได้', 'warning');
		return;
	}
	const ctx = ptContext();
	if (!ctx || !ctx.visit_id) {
		field.alert('ยังไม่ได้เลือกผู้ป่วย/visit', 'warning');
		return;
	}
	withInscl(ctx, (full) => openScreen(full, { order_id: String(o.order_id) }));
};

/* ส่งใบให้ห้องยา (draft → sent) — process ตัดสินทุกอย่างเอง จอไม่ตัดสินแทน

   🔴 ห้องยาปลายทางไม่ได้เลือกที่นี่ — process หาเองจาก mapping ที่ห้องยาตั้งไว้
      (stock_location.serve_units ประกาศว่าคลังนั้นรับใบจากคลินิกไหน) ⇒ อย่าเพิ่มช่องให้หมอเลือก
   🔴 คำเตือนระดับ block ที่ตีกลับมา ต้องแปะไว้ในการ์ด ไม่ใช่ alert ที่กดปิดแล้วหาย —
      หมอต้องอ่านได้ว่าติดตัวไหน ระหว่างเปิดจอไปแก้
   🔴 ห้าม `await` ในไฟล์นี้ — ปุ่มเป็น sync handler ⇒ ใช้ callback ของ runProcess เท่านั้น

   ── override (C31) ────────────────────────────────────────────────────
   ติด block แล้ว "แก้ไม่ได้จริง" มีอยู่จริงในทางคลินิก (ไม่มียาแทน · ประวัติแพ้ไม่ชัด)
   ระบบที่บล็อกสนิทจะโดนหาทางอ้อม (สั่งด้วยวาจา/กระดาษ) แล้วไม่เหลือร่องรอยในระบบเลย
   ⇒ ให้ทางออกที่ **บันทึกได้**: กรอกเหตุผล ≥ MIN_OVR ตัวอักษร แล้วยิงซ้ำพร้อม override_reason
   🔴 เกณฑ์ความยาวต้องตรงกับ MIN_OVERRIDE_REASON ใน cpoe-order-send (พี่เคาะ 10 · 2026-08-07)
      เช็คที่จอด้วยเพื่อบอกก่อนกด — ไม่ใช่ให้หมอพิมพ์เสร็จแล้วโดน server ตีกลับ */
const MIN_OVR = 10;
s.ordOvrMin = MIN_OVR; // เทมเพลตอ่านค่านี้ ห้าม hardcode เลขซ้ำในจอ (สองที่หลุดกันเมื่อไหร่ = จอบอกเกณฑ์ผิด)

s.ordOvrLen = () => String(s.ordOvrText || '').trim().length;
// setter แยก — เทมเพลตใช้ :value + @input เหมือนช่องอื่นในระบบ ไม่ใช้ v-model / assignment ใน template
s.ordOvrInput = (v) => {
	s.ordOvrText = String(v == null ? '' : v);
	if (s.ordOvrErr) s.ordOvrErr = ''; // พิมพ์ต่อ = ข้อความ error ของรอบก่อนหมดอายุแล้ว
};

// ปิดกล่องเหตุผล — ใช้ทั้งตอนกดยกเลิกและตอนส่งสำเร็จ
s.ordOvrClose = () => {
	s.ordOvrId = '';
	s.ordOvrText = '';
	s.ordOvrErr = '';
};

/* ยิง process จริง — reason ว่าง = ส่งปกติ · มีค่า = ยืนยันส่งทั้งที่ติด block
   🔴 ไม่ส่ง key override_reason เลยเมื่อไม่มีเหตุผล (backend ถือว่า "ไม่ override" ตามพฤติกรรมเดิม) */
const sendOrder = (id, reason) => {
	const form = field.getFormRef();
	if (!form) return;
	s.ordSending[id] = true;
	s.ordBlocks[id] = [];
	const args = { order_id: id };
	if (reason) args.override_reason = reason;
	form.userState.runProcess(
		SEND_PROC,
		args,
		(res) => {
			s.ordSending[id] = false;
			const d = (res && res.data) || {};
			if (!d.success) {
				// รายการที่ติดกฎห้ามสั่ง — แปะไว้ในการ์ดให้อ่านต่อได้ ส่วนเหตุผลอื่นบอกเป็น alert พอ
				if (Array.isArray(d.blocks) && d.blocks.length) s.ordBlocks[id] = d.blocks;
				if (d.code === 'HAS_BLOCK' || d.code === 'OVERRIDE_REASON_TOO_SHORT') {
					// เปิดกล่องเหตุผลค้างไว้ให้กรอกต่อ — ที่พิมพ์ไปแล้วต้องไม่หาย
					s.ordOvrId = id;
					s.ordOvrErr = d.code === 'OVERRIDE_REASON_TOO_SHORT' ? d.message || '' : '';
					// 🔴 ไม่ ordReload() ตรงนี้ — โหลดใหม่ = ลิสต์ถูกสร้างใหม่ กล่องที่เพิ่งเปิดจะกระพริบ
					return;
				}
				field.alert(d.message || 'ส่งใบสั่งยาไม่สำเร็จ', 'warning');
				s.ordReload(); // สถานะอาจเปลี่ยนไปแล้วจากอีกจอ — ให้การ์ดตรงกับ DB เสมอ
				return;
			}
			s.ordOvrClose();
			field.alert(d.message || 'ส่งใบสั่งยาแล้ว', 'success');
			s.ordReload();
		},
		(err) => {
			s.ordSending[id] = false;
			field.alert('ส่งใบสั่งยาไม่สำเร็จ: ' + ((err && err.message) || err), 'warning');
		},
	);
};

// ปุ่ม "ส่งใบสั่งยา" ปกติ (ผ่าน el-popconfirm)
s.ordSend = (o) => {
	if (!o || !o.order_id) return;
	const id = String(o.order_id);
	if (s.ordSending[id]) return;
	if (String(o.current_status || '') !== 'draft') {
		field.alert('ใบนี้ถูกส่งไปแล้ว', 'warning');
		return;
	}
	s.ordOvrClose(); // กดส่งใหม่ = เริ่มรอบใหม่ เหตุผลของรอบก่อนต้องไม่ติดมา
	sendOrder(id, '');
};

// ปุ่ม "ยืนยันส่งพร้อมเหตุผล" ในกล่อง override
s.ordOvrSubmit = (o) => {
	const id = String((o && o.order_id) || s.ordOvrId || '');
	if (!id || s.ordSending[id]) return;
	const reason = String(s.ordOvrText || '').trim();
	if (reason.length < MIN_OVR) {
		s.ordOvrErr = 'ระบุเหตุผลอย่างน้อย ' + MIN_OVR + ' ตัวอักษร (ตอนนี้ ' + reason.length + ')';
		return;
	}
	s.ordOvrErr = '';
	sendOrder(id, reason);
};

/* ══ ยกเลิก / ลบใบ (C43) ══════════════════════════════════════════════════
   พี่เคาะ 2026-08-09: ใบร่าง = **ลบทิ้ง** (ยังไม่มีใครเห็น ไม่ใช่เหตุการณ์ทางคลินิก)
   ใบที่ส่งแล้ว = **ยกเลิก** คงใบไว้ให้ห้องยาเห็นว่าถูกยกเลิก + บังคับเหตุผล ≥ MIN_CAN
   🔴 เกณฑ์ความยาวต้องตรงกับ MIN_REASON ใน cpoe-order-cancel — เช็คที่จอเพื่อบอกก่อนกด
      ไม่ใช่ปล่อยให้พิมพ์เสร็จแล้วโดน server ตีกลับ (หลักเดียวกับกล่อง override)
   🔴 ปุ่มโผล่ตาม can_delete/can_cancel ที่ process เป็นคนตัดสิน — จอไม่คิดกติกาเอง */
const MIN_CAN = 10;
s.ordCanMin = MIN_CAN;

s.ordCanLen = () => String(s.ordCanText || '').trim().length;
s.ordCanInput = (v) => {
	s.ordCanText = String(v == null ? '' : v);
	if (s.ordCanErr) s.ordCanErr = '';
};

s.ordCanOpen = (o) => {
	if (!o || !o.order_id) return;
	s.ordOvrClose(); // กล่อง override กับกล่องยกเลิกเปิดพร้อมกันไม่ได้ — คนละเจตนาบนใบเดียวกัน
	s.ordCanId = String(o.order_id);
	s.ordCanText = '';
	s.ordCanErr = '';
};

s.ordCanClose = () => {
	s.ordCanId = '';
	s.ordCanText = '';
	s.ordCanErr = '';
};

/* ยิง process — reason ว่าง = ลบใบร่าง · มีค่า = ยกเลิกใบที่ส่งแล้ว
   process ตัดสิน mode เองจากสถานะสดใน DB จอแค่ส่งเจตนาไป (จอกับ DB อาจไม่ตรงกันได้เสมอ) */
const cancelOrder = (id, reason) => {
	const form = field.getFormRef();
	if (!form) return;
	s.ordBusy[id] = true;
	const args = { order_id: id };
	if (reason) args.reason = reason;
	form.userState.runProcess(
		CANCEL_PROC,
		args,
		(res) => {
			s.ordBusy[id] = false;
			const d = (res && res.data) || {};
			if (!d.success) {
				if (d.code === 'REASON_REQUIRED') {
					// ใบกลายเป็น sent ระหว่างที่การ์ดยังโชว์ปุ่มลบ — เปิดกล่องเหตุผลให้กรอกต่อ ไม่ใช่แค่เด้ง alert
					s.ordCanId = id;
					s.ordCanErr = d.message || '';
					return;
				}
				field.alert(d.message || 'ยกเลิกใบไม่สำเร็จ', 'warning');
				s.ordCanClose();
				s.ordReload(); // สถานะจริงเปลี่ยนไปแล้ว — การ์ดต้องตรงกับ DB เสมอ
				return;
			}
			s.ordCanClose();
			field.alert(d.message || 'ยกเลิกใบแล้ว', 'success');
			s.ordReload();
		},
		(err) => {
			s.ordBusy[id] = false;
			field.alert('ยกเลิกใบไม่สำเร็จ: ' + ((err && err.message) || err), 'warning');
		},
	);
};

// ปุ่ม "ลบใบนี้" ของใบร่าง (ผ่าน el-popconfirm — ไม่ต้องกรอกเหตุผล)
s.ordDelete = (o) => {
	if (!o || !o.order_id) return;
	const id = String(o.order_id);
	if (s.ordBusy[id]) return;
	cancelOrder(id, '');
};

// ปุ่ม "ยืนยันยกเลิก" ในกล่องเหตุผลของใบที่ส่งแล้ว
s.ordCanSubmit = (o) => {
	const id = String((o && o.order_id) || s.ordCanId || '');
	if (!id || s.ordBusy[id]) return;
	const reason = String(s.ordCanText || '').trim();
	if (reason.length < MIN_CAN) {
		s.ordCanErr = 'ระบุเหตุผลอย่างน้อย ' + MIN_CAN + ' ตัวอักษร (ตอนนี้ ' + reason.length + ')';
		return;
	}
	s.ordCanErr = '';
	cancelOrder(id, reason);
};

/* สิทธิ์ของวิสิท (D9 ข้อ 1) — joiner `vid` ของ Visit Tran ยังไม่ได้ดึง inscl_hos[] มาให้
   ไม่มีสิทธิ์ = จอคิดเป็นชำระเองทั้งใบ ⇒ อ่านจาก joiner ก่อน ไม่มีค่อย query visit ทีเดียว */
function withInscl(ctx, done) {
	if (Array.isArray(ctx.inscl_hos) && ctx.inscl_hos.length) {
		done(ctx);
		return;
	}
	const form = field.getFormRef();
	form.userState.crudGetAll(
		{
			sdProvider: {
				providerId: VISIT_PROVIDER,
				providerType: 'FORM',
				params: { vid: String(ctx.visit_id) },
				options: { where: "_id = CONVERT(:vid, 'objectId')", limit: 1, page: 1 },
			},
			totalEnable: false,
		},
		(res) => {
			const rec = (res && res.data && res.data[0]) || null;
			ctx.inscl_hos = (rec && rec.inscl_hos) || [];
			done(ctx);
		},
		() => {
			field.alert('อ่านสิทธิ์ของวิสิทไม่สำเร็จ — จอสั่งยาจะคิดเป็นชำระเองทั้งใบ', 'warning');
			done(ctx);
		},
	);
}

s.orderContext = (done) => {
	const ctx = ptContext();
	if (!ctx || !ctx.visit_id) {
		done(null);
		return;
	}
	withInscl(ctx, done);
};

/* ══ แก้ใบที่ส่งแล้ว (พี่เคาะ 2026-10-08 ข้อ A) ═══════════════════════════
   ดึงใบกลับเป็นร่างก่อน (cpoe-order-cancel action:'recall') แล้วเปิดจอสั่งยาทันที
   แก้เสร็จหมอต้องกด "ส่งใบสั่งยา" ใหม่ — ตอนส่งผ่านด่านห้ามสั่ง/แพ้ยาของ order-send อีกรอบ
   🔴 process ตัดสินเองว่าดึงได้ไหม (ห้องยารับไปแล้ว = ไม่ได้) จอแค่ส่งเจตนา
   🔴 ห้าม `await` — callback ของ runProcess เท่านั้น (หลักเดียวกับทั้งไฟล์) */
s.ordRecall = (o) => {
	if (!o || !o.order_id) return;
	const id = String(o.order_id);
	if (s.ordBusy[id]) return;
	const form = field.getFormRef();
	if (!form) return;
	s.ordBusy[id] = true;
	form.userState.runProcess(
		CANCEL_PROC,
		{ order_id: id, action: 'recall' },
		(res) => {
			s.ordBusy[id] = false;
			const d = (res && res.data) || {};
			if (!d.success) {
				field.alert(d.message || 'ดึงใบกลับมาแก้ไม่สำเร็จ', 'warning');
				s.ordReload();
				return;
			}
			s.ordReload(); // การ์ดหลัง popup ต้องเห็นใบเป็น "ร่าง" แล้ว — ปิดจอโดยไม่แก้ก็ยังตรงกับ DB
			const ctx = ptContext();
			if (!ctx || !ctx.visit_id) {
				field.alert('ยังไม่ได้เลือกผู้ป่วย/visit', 'warning');
				return;
			}
			withInscl(ctx, (full) => openScreen(full, { order_id: id }));
		},
		(err) => {
			s.ordBusy[id] = false;
			field.alert('ดึงใบกลับมาแก้ไม่สำเร็จ: ' + ((err && err.message) || err), 'warning');
		},
	);
};

/* ══ เปิดกล่องยืนยันส่งให้จากภายนอก (ปุ่ม "ตรวจเสร็จ" ใน action bar · พี่สั่ง 2026-10-08) ══════════
   ตรวจเสร็จส่งใบแล้วติดคำเตือนห้ามสั่ง → แทนที่จะบอกให้หมอมากด "ส่งใบสั่งยา" ซ้ำ ให้กล่องเหตุผลเปิดรอไว้เลย
   โหลดการ์ดใหม่ด้วย (ใบอื่นอาจเพิ่งส่งไป) แล้วเปิดกล่องใน callback ของ ordLoad — เปิดก่อนโหลด กล่องจะโดนล้างทิ้ง
   🔴 เปิดได้ทีละใบ (กล่องสองใบพร้อมกัน = กรอกผิดใบ — หลักเดียวกับ ordOvrId เดิม) */
s.ordShowBlock = (orderId, blocks) => {
	s.ordPendingBlock = { id: String(orderId), blocks: Array.isArray(blocks) ? blocks : [] };
	s.ordReload();
};

/* emr2-orders-addon — EMR v2 (gen-emr-v2-model.cjs ต่อท้ายให้ · อย่าแก้ในบิลเดอร์) */
/* ══ emr2-orders addon — EMR v2 เท่านั้น (generator ต่อท้าย onCreated ของ order_card / item_card ใน v2) ══════════
   ใช้ `s` / `field` ของไฟล์หลัก (sdform/cpoe/widget-order-card · widget-item-card .oncreated.js) — ห้ามประกาศซ้ำ
   หน้าที่: จัดใบเป็นกลุ่มตามคลินิกผู้สั่ง (board 4 · มติ M6) · คลินิกตัวเองขึ้นก่อน · คลินิกอื่น 🔒
   🔴 ใบไหนแก้ได้ ยังตัดสินด้วย can_* / own_clinic ของ cpoe-order-list เหมือนเดิม — addon แค่จัดกลุ่ม ไม่คิดกติกาเอง */

// สีของ el-tag เดิม (success/warning/…) → คลาสใน emr2-orders.css
s.e2oTone = (color) => 'is-' + String(color || 'info');

// สีป้ายสถานะเฉพาะ v2 (พี่สั่ง 2026-10-23 · ข้อ A): ส่งแล้ว → เขียว · ยกเลิก → ส้ม (เดิม info = เขียว accent อ่านไม่ออกว่ายกเลิก)
// ทับแค่ color ของ itmStatus / ordStatus — ไฟล์หลักที่ v1 ใช้ร่วมไม่แตะ · สถานะอื่นคงสีเดิม
const E2O_STATUS_TONE = { sent: 'success', cancelled: 'orange' };
['itmStatus', 'ordStatus'].forEach((key) => {
	const base = s[key];
	if (typeof base !== 'function') return;
	s[key] = (o) => {
		const st = base(o);
		const tone = E2O_STATUS_TONE[String((o && o.current_status) || '')];
		return tone ? Object.assign({}, st, { color: tone }) : st;
	};
});

/* ตัวนับปุ่ม "ผลตรวจวันนี้" (emr2_labs · ออก N · รอ M) ตามการ์ดสั่งตรวจ (พี่แจ้ง 2026-10-23 "เพิ่ม แก้ไข แล้วผลตรวจวันนี้ ไม่อัพเดทตาม")
   ทุกทางที่ใบ Lab/X-ray เปลี่ยน (สร้าง · ส่ง · ยกเลิก · ลบ · WS จากจออื่น) จบที่ s.itmLoad ⇒ ครอบตรงนี้ที่เดียว
   โหลดเฉพาะเมื่อ labs ถือ visit เดียวกันอยู่แล้ว — ตอนเปลี่ยนคนไข้ opd_card.setTran สั่ง e2lLoad เองอยู่แล้ว · มีแค่ item_card ที่มี itmLoad */
if (typeof s.itmLoad === 'function') {
	const itmLoadBase = s.itmLoad;
	s.itmLoad = (visitId, tran) => {
		itmLoadBase(visitId, tran);
		const labs = field.getFieldRef('emr2_labs');
		const ls = labs && labs.vueState;
		if (ls && ls.e2lReload && visitId && ls.e2lVid === String(visitId)) ls.e2lReload();
	};
}

const e2oSoap = () => {
	const soap = field.getFieldRef('emr2_soap');
	return (soap && soap.vueState) || {};
};

// โหมด "ซ่อน" คลินิกอื่นของช่องกลาง (emr2_soap · จำต่อเครื่อง) — ใช้ชุดเดียวกันทั้งจอ (มติ 2026-10-22)
const e2oHideOthers = () => e2oSoap().e2Mode === 'hidden';

// "16.p โรคสมอง" → "โรคสมอง" (mockup ป้ายคลินิกไม่มีรหัส — ท่าเดียวกับ bnFrom ของ emr2_soap)
s.e2oClinicName = (label) => String(label || '').replace(/^\S+\.\S*\s+/, '') || String(label || '');

/* สีป้ายคลินิก is-c0…c4 — ลำดับคลินิกใน visit (journey ของ emr2_soap) ⇒ คลินิกเดียวกันสีเดียวกันทุกการ์ดในจอ
   ไม่อยู่ใน journey (ใบเก่า/คลินิกที่ไม่มีคิว) = สีจากรหัส · cost_summary เรียกตัวนี้ผ่าน order_card */
s.e2oClinicTone = (code) => {
	const c = String(code || '');
	const journey = typeof e2oSoap().e2Journey === 'function' ? e2oSoap().e2Journey() : [];
	const i = journey.findIndex((j) => String(j.unit) === c);
	if (i >= 0) return 'is-c' + (i % 5);
	let h = 0;
	for (let k = 0; k < c.length; k += 1) h = (h + c.charCodeAt(k)) % 5;
	return 'is-c' + h;
};

// ใบที่ยังไม่มี order_clinic (ใบเก่า) process ถือว่าเป็นของคนเปิด (own_clinic true) — รวมไว้กลุ่มของฉัน
const e2oGroupAll = (list) => {
	const groups = [];
	(list || []).forEach((o) => {
		const mine = o.own_clinic !== false;
		const key = mine ? '__mine' : String(o.order_clinic_code || o.order_clinic || '-');
		let g = groups.find((x) => x.key === key);
		if (!g) {
			g = { key, mine, code: o.order_clinic_code || '', label: o.order_clinic ? s.e2oClinicName(o.order_clinic) : mine ? 'คลินิกของฉัน' : 'ไม่ระบุคลินิก', orders: [] };
			groups.push(g);
		}
		// กลุ่มของฉันมีใบที่ไม่มีคลินิกปน — ใช้ชื่อคลินิกจากใบที่มี
		if (mine && !g.code && o.order_clinic) {
			g.code = o.order_clinic_code || '';
			g.label = s.e2oClinicName(o.order_clinic);
		}
		g.orders.push(o);
	});
	// คลินิกตัวเองขึ้นก่อน · คลินิกอื่นเรียงตามที่ process ส่งมา
	return groups.filter((g) => g.mine).concat(groups.filter((g) => !g.mine));
};

s.e2oGroups = (list) => {
	const all = e2oGroupAll(list);
	return e2oHideOthers() ? all.filter((g) => g.mine) : all;
};

s.e2oHiddenCount = (list) => {
	if (!e2oHideOthers()) return 0;
	return (list || []).filter((o) => o.own_clinic === false).length;
};

/* ══ ตัวเลขบนหัวแท็บ ยา · สั่งตรวจ · วัคซีน · นัด (board 4 · พี่ขอ 2026-10-22) — EMR v2 · ต่อท้ายเฉพาะ order_card ══════
   หัวแท็บวาดโดย tab-render ของแพลตฟอร์ม (มีแค่ label ไม่มีช่องใส่ตัวเลข) ⇒ เขียน data-e2o-n ลงปุ่มแท็บ แล้ว CSS วาดเป็นป้าย (::after)
   ปุ่มแท็บของ el-tabs มี id = "tab-<ชื่อ tab-pane>" (emr2_tab_med …) ซึ่ง generator ตั้งไว้
   เจ้าของมีตัวเดียว (order_card) ไม่เขียนแข่งกัน · อ่าน state การ์ดอื่นผ่าน getFieldRef (vueState reactive ⇒ $watch ติดเอง)
   🔴 เริ่ม watch ตอน ordLoad ครั้งแรก (opd_card.setTran / onMounted) — ตอน onCreated การ์ดแท็บอื่นยังไม่ mount
      getFieldRef คืน null แล้ว watch จะไม่รู้จักการ์ดนั้นตลอดไป
   🔴 document ถูก shadow ในโค้ด event (CLAUDE.md กับดักข้อ 4) → globalThis.document */
const E2O_TABS = { med: 'emr2_tab_med', exam: 'emr2_tab_exam', vx: 'emr2_tab_vx', appt: 'emr2_tab_appt' };
const e2oState = (name) => {
	const f = field.getFieldRef(name);
	return (f && f.vueState) || {};
};
// ใบที่ยกเลิกแล้วไม่นับ — ตัวเลขบอก "ใบที่ยังมีผล" ของ visit นี้
const e2oLive = (list) => (list || []).filter((o) => String(o.current_status || '') !== 'cancelled').length;

const e2oTabCounts = () => {
	const it = e2oState('item_card');
	const vx = e2oState('vx_today_card');
	const ap = e2oState('appt_box');
	return {
		med: e2oLive(s.ordList),
		exam: e2oLive(it.itmList),
		// วัคซีน = เข็มที่ถึง/เลยกำหนดที่ยังไม่ได้ส่งฉีด (ป้ายแดง) — ส่งพยาบาลแล้ว/ฉีดแล้ว = ไม่ต้องเตือน
		vx: typeof vx.vtMode === 'function' && vx.vtMode() === 'draft' && typeof vx.vtGroups === 'function' ? vx.vtGroups().must.length : 0,
		// นัด = นัดที่ออกใน visit นี้ ไม่นับที่ยกเลิก/ไม่มา
		appt: (ap.aptList || []).filter((b) => !(typeof ap.aptDead === 'function' && ap.aptDead(b))).length,
	};
};

const e2oPaintTabs = (n) => {
	const doc = globalThis.document;
	if (!doc || !n) return;
	Object.keys(E2O_TABS).forEach((k) => {
		const el = doc.getElementById('tab-' + E2O_TABS[k]);
		if (!el) return;
		if (n[k] > 0) el.setAttribute('data-e2o-n', String(n[k]));
		else el.removeAttribute('data-e2o-n');
	});
};

let e2oTabWatch = false;
const e2oOrdLoad = s.ordLoad;
s.ordLoad = (visitId, tran) => {
	if (!e2oTabWatch && typeof field.$watch === 'function') {
		e2oTabWatch = true;
		// watch ของ component หยุดเองตอน unmount — ไม่ต้องเก็บตัวปิด
		field.$watch(e2oTabCounts, e2oPaintTabs, { immediate: true, deep: true, flush: 'post' });
	}
	return e2oOrdLoad(visitId, tran);
};
/* /emr2-orders-addon */

/* emr2-once-addon — EMR v2 (gen-emr-v2-model.cjs ต่อท้ายให้ · อย่าแก้ในบิลเดอร์) */
{
/* emr2-once — กันโหลดซ้ำตอนเปิดคนไข้ครั้งแรก (B1 · วัดจอจริง 2026-10-24: เปิดครั้งแรก 30 request · เปิดซ้ำ 15)
   ต้นเหตุ: ตอน mount ครั้งแรก widget ถูกสั่งโหลด 2 ทางพร้อมกัน
     ① opd_card.onMounted → setTran($examTran) → ไล่สั่งทุกการ์ด (ทาง "feed" · opd_card ติดธง form.$e2Feed ระหว่างไล่)
     ② onMounted ของ widget เอง อ่าน $examTran แล้วโหลดเอง
   ⇒ ห่อฟังก์ชันโหลด: อีกทางเพิ่งโหลด visit เดียวกันไม่เกิน E2_ONCE_MS = ข้าม
      ทางเดียวกันเรียกซ้ำ (กดโหลดใหม่ · หลังบันทึก · WS) ไม่ข้าม · เปลี่ยนคนไข้ (visit ต่าง) ไม่ข้าม
   gen-emr-v2-model.cjs ฝังไฟล์นี้ต่อท้าย onCreated ของแต่ละ widget (ในบล็อก { } ชื่อไม่ชนโค้ดเดิม) — แก้ที่ไฟล์นี้แล้ว gen ใหม่ */
const E2_ONCE_MS = 2000;
const e2OnceWrap = (widget, name, fnName, vidOf) => {
	const st = widget.vueState;
	const orig = st[fnName];
	if (typeof orig !== 'function' || orig.e2Once) return;
	const key = `${name}.${fnName}`;
	const wrapped = (...args) => {
		const form = widget.getFormRef && widget.getFormRef();
		const raw = vidOf(...args);
		const vid = raw ? String(raw) : '';
		if (form && vid) {
			const fromFeed = form.$e2Feed === true;
			const seen = form.$e2Loaded || (form.$e2Loaded = {});
			const last = seen[key];
			const now = Date.now();
			if (last && last.vid === vid && last.fromFeed !== fromFeed && now - last.at < E2_ONCE_MS) return undefined;
			seen[key] = { vid, fromFeed, at: now };
		}
		return orig(...args);
	};
	wrapped.e2Once = true;
	st[fnName] = wrapped;
};
e2OnceWrap(this, 'order_card', 'ordLoad', (visitId) => visitId);
}
/* /emr2-once-addon */

/* emr2-req-addon — EMR v2 (gen-emr-v2-model.cjs ต่อท้ายให้ · อย่าแก้ในบิลเดอร์) */
/* emr2-req — รวม request ที่ซ้ำกันระหว่าง widget (B2 · 2026-10-24)
   วัดจอจริง: เปิดคนไข้ยิง process เดียวกัน params เดียวกันพร้อมกันหลายตัว (vx-engine · emr-lab-board-get · cpoe-order-list)
   ⇒ request ที่ยังรอคำตอบอยู่ (หรือเพิ่งตอบไม่เกิน E2_REQ_REUSE_MS) ใช้คำตอบเดียวกัน · นอกนั้นยิงใหม่ตามปกติ
   🔴 ไม่ cache ยาว — หลังบันทึกใบแล้วโหลดใหม่ต้องได้ข้อมูลสด · ค่า 300ms กันแค่ตัวที่ยิงห่างกันนิดเดียวในรอบเปิดคนไข้
   ทุกตัวได้ res.data คนละชุด (copy) — widget แก้ข้อมูลของตัวเองได้โดยไม่กระทบตัวอื่น
   สมุดเก็บที่ form.$e2Req (ฟอร์มเดียวกัน = เห็นกัน) · gen-emr-v2-model.cjs ฝังไฟล์นี้ในแต่ละ widget ที่ใช้ — แก้ที่นี่แล้ว gen ใหม่ */
const E2_REQ_REUSE_MS = 300;
const e2Req = (form, procId, params, ok, err) => {
	if (!form || !form.userState) return;
	const key = `${procId} ${JSON.stringify(params || {})}`;
	const book = form.$e2Req || (form.$e2Req = {});
	const copy = (res) => (res && typeof res === 'object' && res.data !== undefined ? { ...res, data: JSON.parse(JSON.stringify(res.data)) } : res);
	// callback ของ widget หนึ่งพัง ต้องไม่ทำให้ตัวอื่นไม่ได้ข้อมูล
	const call = (fn, value) => {
		if (typeof fn !== 'function') return;
		try {
			fn(value);
		} catch (e) {
			globalThis.console.error('[e2Req]', procId, e);
		}
	};
	const hit = book[key];
	if (hit && hit.pending) {
		hit.waiters.push([ok, err]);
		return;
	}
	if (hit && Date.now() - hit.at < E2_REQ_REUSE_MS) {
		setTimeout(() => (hit.ok ? call(ok, copy(hit.res)) : call(err, hit.res)), 0);
		return;
	}
	const entry = { pending: true, waiters: [[ok, err]], at: Date.now(), ok: false, res: null };
	book[key] = entry;
	const settle = (isOk, res) => {
		entry.pending = false;
		entry.ok = isOk;
		entry.res = res;
		entry.at = Date.now();
		entry.waiters.forEach(([o, x], i) => (isOk ? call(o, i === 0 ? res : copy(res)) : call(x, res)));
	};
	form.userState.runProcess(procId, params, (res) => settle(true, res), (e) => settle(false, e));
};
/* /emr2-req-addon */

options.onMounted:
const field = this;
const s = this.vueState;
// เคสแท็บ EMR mount หลังกดเลือกคนไข้จากคิวไปแล้ว → opd_card.setTran ยิงไปก่อนที่การ์ดนี้จะเกิด
// ⇒ ดึง tran จาก form เองรอบแรก (pattern เดียวกับ registry_card)
setTimeout(() => {
	const form = field.getFormRef();
	const tran = form && form.$examTran;
	const visitId = tran && tran.vid && tran.vid.value ? String(tran.vid.value) : null;
	s.ordLoad(visitId, tran || null);
}, 0);

options.onCreated:
/**
 * item_card · onCreated — การ์ด "ใบสั่งตรวจ / บริการ" ในหน้า EMR (ฟอร์ม EMR 6a4f64e7f8cdfc54cec16488)
 *
 * หน้าที่: ทางเข้า "สั่งตรวจ" ทั้งหมดของหน้า EMR รวมอยู่ที่การ์ดนี้ที่เดียว
 *   ① ปุ่ม "+ สั่งตรวจ" (ใบใหม่)  ② เห็นใบที่บันทึกไปแล้วของวิสิทนี้  ③ กดกลับเข้าไปแก้ใบร่างเดิม
 * โครงลอกมาจาก order_card (ใบสั่งยา) — คนละใบ คนละจอ คนละแหล่งข้อมูล แต่ flow เดียวกัน
 *
 * 🔴 **ไม่ประกอบ patient context เอง** — เรียก `order_card.vueState.orderContext()`
 *    จุดประกอบ context ต้องมีที่เดียว ไม่งั้นวันหนึ่งสองการ์ดจะส่งค่าให้จอไม่เท่ากัน
 *    ⇒ ต้องแพตช์ order_card ก่อน (sdform/cpoe/emr-order-card-expose-context.patch.js)
 * 🔴 กรองใบด้วย `service_type_code` ไม่ใช่ `service_type` — ตัวหลังเป็น label ("Medicine"/"Lab Test")
 *    ที่ rename ได้ทุกเมื่อ (cpoe-order-list ส่ง code มาให้แล้ว)
 * 🔴 ทุก key ที่เทมเพลตอ้างต้องมีค่าตั้งแต่ตรงนี้ — ขาดตัวเดียว = error box ทั้ง widget
 */

const s = this.vueState;
const field = this;

const ITEM_APP_FORM_ID = '6a927860422c1ca959829d26'; // CPOE Order App (form_ui)
const LIST_PROC = '6a71fe5f29c75d41e9c7e9cb'; // cpoe-order-list (ใช้ตัวเดียวกับการ์ดใบสั่งยา)
const SEND_PROC = '6a757d1bf7bf7668d7673c63'; // cpoe-order-send   (draft → sent)
const CANCEL_PROC = '6a7822e11eb17ebfd41dd4d4'; // cpoe-order-cancel (draft → ลบ · sent → cancelled · action recall: sent → draft)
const DRUG_TYPE = 'med'; // ใบยาไม่อยู่ในการ์ดนี้ — ยาแยกใบเสมอ (spec §3.4)

/* ══ state ════════════════════════════════════════════════════════════════ */
s.itmList = [];
s.itmLoading = false;
s.itmErr = '';
s.itmVid = null; // visit _id ปัจจุบัน — เซ็ตผ่าน itmLoad จาก opd_card
s.itmTran = null;
s.itmOpenRow = {};
s.itmItemOpen = {}; // '<order_id>:<index>' → กางรายละเอียดราคาของรายการนั้นอยู่ไหม (ราคาแบบ C)
s.itmDirty = false; // จอสั่งตรวจแตะใบใน DB แล้วหรือยัง — ตัวตัดสินว่าตอนปิด popup ต้องโหลดใหม่ไหม
s.itmSending = {}; // order_id ที่กำลังส่ง — กันกดรัวระหว่างรอ process
s.itmBusy = {}; // order_id ที่กำลังลบ/ยกเลิก — แยกจาก itmSending เพราะเป็นคนละปุ่มบนใบเดียวกัน
s.itmBlocks = {}; // order_id → เหตุที่ส่งไม่ได้ ที่ process ตีกลับมา (แปะในการ์ด ไม่ใช่ alert ที่กดปิดแล้วหาย)
s.itmCanId = ''; // ใบที่กำลังกรอกเหตุผลยกเลิก — ทีละใบเท่านั้น (กล่องสองใบพร้อมกัน = กรอกผิดใบ)
s.itmCanText = '';
s.itmCanErr = '';
s.costAll = []; // ใบทุกชนิดของวิสิท (รวมใบยา) — ฐานของการ์ดสรุปค่าใช้จ่าย
s.costLoading = false;

/* ══ ป้ายสถานะ ════════════════════════════════════════════════════════════
   🔴 ค่าที่ไม่รู้จักต้องโชว์ค่าดิบ ห้ามแปลงเป็น "ร่าง" — ใบที่สถานะเพี้ยนต้องมองเห็นได้จากจอ */
const STATUS = {
	draft: { label: 'ร่าง', color: 'info' },
	sent: { label: 'ส่งแล้ว', color: 'warning' },
	accepted: { label: 'ห้องตรวจรับแล้ว', color: 'warning' },
	collected: { label: 'เก็บสิ่งส่งตรวจแล้ว', color: 'warning' },
	in_process: { label: 'กำลังตรวจ', color: 'warning' },
	resulted: { label: 'มีผลแล้ว', color: 'success' },
	completed: { label: 'เสร็จสิ้น', color: 'success' },
	cancelled: { label: 'ยกเลิก', color: 'info' },
};
s.itmStatus = (o) => {
	const raw = String((o && o.current_status) || '');
	return STATUS[raw] || { label: raw || '—', color: 'danger' };
};

/* ══ ป้ายชนิดรายการ ═══════════════════════════════════════════════════════
   1 ใบมีได้หลายชนิดปนกัน (spec §3.4) ⇒ กางใบแล้วต้องแยกออกด้วยตาเปล่าว่าบรรทัดไหนเป็นอะไร
   🔴 คำกับสีต้องตรงกับจอสั่งตรวจ (TYPES ใน widget item_screen) — คนละคำสองจอ = คนละของในสายตาหมอ
   🔴 map จาก **code** ไม่ใช่ label: label ในทะเบียนเป็น "Radio Exam"/"Nursing Service" ซึ่ง rename ได้ทุกเมื่อ */
const ITEM_TYPE = {
	lab: { label: 'Lab', color: 'success' },
	xray: { label: 'X-ray', color: 'warning' },
	nurs: { label: 'หัตถการ', color: 'primary' },
	order: { label: 'บริการอื่นๆ', color: 'info' },
	med: { label: 'ยา', color: 'danger' }, // ปกติใบยาไม่เข้าการ์ดนี้ แต่ใบผสมชนิดมีได้ ⇒ ต้องมีคำไว้
};
// ไม่รู้ชนิด (ใบเก่าที่บันทึกก่อนมีช่องนี้) → คืน null = ไม่โชว์ป้าย ดีกว่าโชว์ป้ายเปล่าหรือเดาชนิดให้
s.itmType = (it) => {
	const code = String((it && it.item_type_code) || '');
	if (ITEM_TYPE[code]) return ITEM_TYPE[code];
	const raw = String((it && it.item_type_label) || '').trim();
	return raw ? { label: raw, color: 'info' } : null;
};

/* สรุปชนิดในใบ → ชิปหัวใบ (Lab 2 · X-ray 1) เรียงตามลำดับที่เจอในใบ
   🔴 นับจาก o.items ⇒ ต้องโหลดรายการครบทุกบรรทัด (full_items ใน itmLoad) ไม่งั้นใบยาวนับขาด */
s.itmTypeSum = (o) => {
	const sum = [];
	((o && o.items) || []).forEach((it) => {
		const t = s.itmType(it);
		if (!t) return;
		const hit = sum.find((x) => x.label === t.label);
		if (hit) hit.count += 1;
		else sum.push({ label: t.label, color: t.color, count: 1 });
	});
	return sum;
};

// ยอดของรายการ — ใช้ net_amount ที่ price-calc คิดไว้ (รวม override ราคา) · ใบเก่าที่ไม่มีค่อยคูณเอง
s.itmLineTotal = (it) => {
	if (!it) return 0;
	if (it.net_amount != null) return Number(it.net_amount) || 0;
	return (Number(it.unit_price) || 0) * (Number(it.quantity) || 0);
};
// ตัวเลขในแถวรายการไม่ใส่ ฿ — แถวแคบ และหัวใบบอกหน่วยเงินไว้แล้ว
s.itmNum = (n) => Number(n || 0).toLocaleString('th-TH', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
s.itmItemToggle = (orderId, i) => {
	const k = String(orderId) + ':' + i;
	const next = Object.assign({}, s.itmItemOpen);
	next[k] = !next[k];
	s.itmItemOpen = next;
};

s.itmMoney = (n) => '฿' + Number(n || 0).toLocaleString('th-TH', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
// created_at เป็น "YYYY-MM-DD HH:mm:ss" — ใบของวิสิทเดียวกันเกิดวันเดียวกันเกือบเสมอ จึงโชว์แค่เวลา
s.itmTime = (v) => {
	const t = String(v || '');
	return t.length >= 16 ? t.slice(11, 16) + ' น.' : t;
};

s.itmToggle = (id) => {
	const k = String(id);
	// เขียนทั้ง object ใหม่ ไม่แก้ key เดิมในที่ — ให้ Vue เห็นการเปลี่ยนแน่นอน
	const next = {};
	Object.keys(s.itmOpenRow).forEach((x) => {
		next[x] = s.itmOpenRow[x];
	});
	next[k] = !next[k];
	s.itmOpenRow = next;
};

/* ══ realtime — ใบที่ process ออกให้เบื้องหลัง (DF อัตโนมัติ) โผล่เองโดยไม่ต้องกดโหลดใหม่ ══
   process ส่ง app.wsSend('app', 'cpoe-visit:<visit_id>', …) หลังออกใบ (dx-df-auto · พี่เลือก ข 2026-10-09)
   ⇒ การ์ดฟังห้องของวิสิทที่เปิดอยู่ · เปลี่ยนคนไข้ = ปิดห้องเก่าแล้วเปิดห้องใหม่ · ปิดตอน unmount (itmCleanup)
   🔴 connection เก็บในตัวแปร closure ไม่ใช่ vueState — reactive proxy ห่อ WebSocket แล้วพังได้
   🔴 message ติดกันหลายตัว (หมอหลายคน = หลายใบ) รวบเป็นโหลดรอบเดียว */
const WS_CHANNEL = 'app';
let wsConn = null;
let wsVid = '';
let wsTimer = null;
const wsWatch = (visitId) => {
	const vid = visitId ? String(visitId) : '';
	if (vid === wsVid) return;
	if (wsConn && wsConn.wsDisconnect) wsConn.wsDisconnect();
	wsConn = null;
	wsVid = vid;
	if (!vid) return;
	const form = field.getFormRef();
	if (!form || !form.userState || !form.userState.connectWebSocket) return;
	wsConn = form.userState.connectWebSocket(WS_CHANNEL, 'cpoe-visit:' + vid, 'item-card-' + Math.random().toString(36).slice(2), () => {
		if (wsTimer) clearTimeout(wsTimer);
		wsTimer = setTimeout(() => {
			wsTimer = null;
			if (s.itmVid === vid) s.itmReload(); // เปลี่ยนคนไข้ไประหว่างรอ = ทิ้ง
		}, 400);
	});
};
// เรียกจาก onUnmount — ไม่ปิด = socket ค้างทุกครั้งที่สลับแท็บ/ปิดจอ
s.itmCleanup = () => {
	if (wsTimer) clearTimeout(wsTimer);
	wsTimer = null;
	wsWatch(null);
};

/* ══ โหลดใบของวิสิท ═══════════════════════════════════════════════════════
   เรียกจาก opd_card.setTran (เปลี่ยนคนไข้) · onMounted (เข้าแท็บ EMR ทีหลัง) · หลังปิด popup */
s.itmLoad = (visitId, tran) => {
	s.itmVid = visitId ? String(visitId) : null;
	wsWatch(s.itmVid);
	if (tran !== undefined) s.itmTran = tran || null;
	s.itmList = [];
	s.itmErr = '';
	s.itmOpenRow = {};
	s.itmItemOpen = {};
	s.itmBlocks = {}; // เหตุที่ส่งไม่ได้ของรอบก่อนต้องหายไปพร้อมรายการเก่า ไม่ค้างทับใบที่แก้แล้ว
	s.itmCanId = ''; // กล่องเหตุผลที่ค้างเปิดอยู่ต้องปิดตาม — ใบเก่าอาจไม่อยู่ในลิสต์ใหม่แล้ว
	s.itmCanText = '';
	s.itmCanErr = '';
	s.costAll = []; // ยอดของคนไข้คนก่อนต้องไม่ค้างระหว่างโหลดคนใหม่
	if (!s.itmVid) return;
	const form = field.getFormRef();
	if (!form) return;
	s.itmLoading = true;
	e2Req(
		form,
		LIST_PROC,
		// full_items — ชิปชนิดหัวใบนับจากรายการ ต้องได้ครบทุกบรรทัด (ค่า default ส่งมาแค่ 8)
		{ visit_id: s.itmVid, full_items: true },
		(res) => {
			s.itmLoading = false;
			const d = (res && res.data) || {};
			// process ที่ตีกลับด้วย success:false ก็มาทาง callback นี้ ไม่ใช่ errCb — ต้องเช็คเอง
			if (!d.success) {
				s.itmErr = d.message || 'อ่านใบสั่งตรวจไม่สำเร็จ';
				return;
			}
			const all = Array.isArray(d.orders) ? d.orders : [];
			s.costAll = all; // การ์ดสรุปค่าใช้จ่ายใช้ทุกใบ — ไม่ต้องยิง process ซ้ำ
			s.itmList = all.filter((o) => String(o.service_type_code || '') !== DRUG_TYPE);
			// มีใบเดียว ⇒ กางให้เลยทุกสถานะ (พี่สั่ง 2026-10-08 — เดิมกางเฉพาะใบร่าง)
			if (s.itmList.length === 1) s.itmOpenRow[s.itmList[0].order_id] = true;
		},
		(err) => {
			s.itmLoading = false;
			s.itmErr = 'อ่านใบสั่งตรวจไม่สำเร็จ: ' + ((err && err.message) || err);
		}
	);
};

/* การ์ด "สรุปการรักษา" (treat_summary) แท็บ Lab/X-Ray โชว์ใบของวิสิทนี้ด้วย — ใบเปลี่ยนที่นี่ ต้องให้ฝั่งนั้นโหลดตาม
   (พี่ทัก 2026-10-08: แก้ใบแล้วฝั่งสรุปยังค้าง "ส่งแล้ว") · tsRefresh คงแท็บที่หมอเปิดอยู่
   🔴 ไม่มี tsRefresh (treat_summary รุ่นเก่า) = ข้ามเงียบ ไม่ใช้ tsReload แทน — ตัวนั้นดีดแท็บกลับไปยา */
const syncSummary = () => {
	const ts = field.getFieldRef('treat_summary');
	const fn = ts && ts.vueState && ts.vueState.tsRefresh;
	if (typeof fn === 'function') fn();
};

// ทุกจังหวะที่ใบอาจเปลี่ยน (ส่ง/ยกเลิก/ลบ/ดึงกลับ/ปิดจอสั่งตรวจ/กดโหลดใหม่) วิ่งผ่านตัวนี้ ⇒ sync ที่เดียวพอ
s.itmReload = () => {
	s.itmLoad(s.itmVid, undefined);
	syncSummary();
};

/* ══ ส่งใบ / ยกเลิก-ลบใบ ══════════════════════════════════════════════════
   กติกาเดียวกับการ์ดใบสั่งยา (พี่เคาะ 2026-08-09):
     ใบร่าง = **ลบทิ้ง** (ยังไม่มีใครเห็น ไม่ใช่เหตุการณ์ทางคลินิก)
     ใบที่ส่งแล้ว = **ยกเลิก** คงใบไว้ให้ห้องปลายทางเห็นว่าถูกยกเลิก + บังคับเหตุผล ≥ MIN_CAN
   🔴 ปุ่มโผล่ตาม can_edit/can_delete/can_cancel ที่ process เป็นคนตัดสิน — จอไม่คิดกติกาเอง
   🔴 ห้องปลายทางไม่ได้เลือกที่นี่ — process หาเองจาก mapping ที่ห้องนั้นตั้งไว้ */
const MIN_CAN = 10;
s.itmCanMin = MIN_CAN;

/* ส่งใบ — ใบตรวจไม่มีชั้นตรวจยา จึงไม่มีกล่อง "ยืนยันส่งทั้งที่ติดคำเตือน" แบบใบยา
   แต่ process ยังตีกลับได้ด้วยเหตุอื่น (หาห้องปลายทางไม่เจอ ฯลฯ) ⇒ แปะเหตุไว้ในการ์ดให้อ่านต่อได้
   แลปส่งซ้ำใน visit (DUP_LAB · พี่เคาะ 2026-10-02) → ถามยืนยันก่อน · ยืนยัน = ยิงใหม่พร้อม confirm_dup
   🔴 ไม่ถาม = การ์ดนี้ส่งใบที่มีแลปซ้ำไม่ออกเลย (process ตีกลับทุกครั้ง) */
// kind 'repeat' = ยังไม่พ้น repeat_days ของ master (ข้าม visit) · อื่นๆ = ซ้ำใน visit นี้
const dupText = (list) =>
	'รายการแลปต่อไปนี้เพิ่งส่งตรวจไปแล้ว — ' +
	list
		.map((d) =>
			(d.item_name || d.item_code) +
			(d.kind === 'repeat'
				? ' (ตรวจไปแล้ว ' + d.days_ago + ' วันก่อน · ไม่ควรซ้ำภายใน ' + d.repeat_days + ' วัน)'
				: ' (ใน visit นี้ · ' + (d.clinic_name || 'ไม่ทราบคลินิก') + (d.same_clinic ? ' · คลินิกนี้' : '') + ')')
		)
		.join(' · ') +
	' — ยืนยันส่งตรวจซ้ำ?';
s.itmSend = (o, extra) => {
	if (!o || !o.order_id) return;
	const id = String(o.order_id);
	if (s.itmSending[id]) return;
	if (String(o.current_status || '') !== 'draft') {
		field.alert('ใบนี้ถูกส่งไปแล้ว', 'warning');
		return;
	}
	const form = field.getFormRef();
	if (!form) return;
	s.itmSending[id] = true;
	s.itmBlocks[id] = [];
	form.userState.runProcess(
		SEND_PROC,
		Object.assign({ order_id: id }, extra || {}),
		(res) => {
			s.itmSending[id] = false;
			const d = (res && res.data) || {};
			if (!d.success && d.code === 'DUP_LAB' && Array.isArray(d.duplicates) && d.duplicates.length) {
				field.confirm(dupText(d.duplicates), () => s.itmSend(o, { confirm_dup: true }), 'warning', 'ยืนยันการส่งตรวจซ้ำ');
				return;
			}
			if (!d.success) {
				if (Array.isArray(d.blocks) && d.blocks.length) s.itmBlocks[id] = d.blocks;
				field.alert(d.message || 'ส่งใบสั่งตรวจไม่สำเร็จ', 'warning');
				s.itmReload(); // สถานะอาจเปลี่ยนไปแล้วจากอีกจอ — การ์ดต้องตรงกับ DB เสมอ
				return;
			}
			field.alert(d.message || 'ส่งใบสั่งตรวจแล้ว', 'success');
			s.itmReload();
		},
		(err) => {
			s.itmSending[id] = false;
			field.alert('ส่งใบสั่งตรวจไม่สำเร็จ: ' + ((err && err.message) || err), 'warning');
		}
	);
};

/* กล่องเหตุผลยกเลิก — เกณฑ์ความยาวต้องตรงกับ MIN_REASON ใน cpoe-order-cancel
   เช็คที่จอเพื่อบอกก่อนกด ไม่ใช่ปล่อยให้พิมพ์เสร็จแล้วโดน server ตีกลับ */
s.itmCanLen = () => String(s.itmCanText || '').trim().length;
s.itmCanInput = (v) => {
	s.itmCanText = String(v == null ? '' : v);
	if (s.itmCanErr) s.itmCanErr = '';
};
s.itmCanOpen = (o) => {
	if (!o || !o.order_id) return;
	s.itmCanId = String(o.order_id);
	s.itmCanText = '';
	s.itmCanErr = '';
};
s.itmCanClose = () => {
	s.itmCanId = '';
	s.itmCanText = '';
	s.itmCanErr = '';
};

/* ยิง process — reason ว่าง = ลบใบร่าง · มีค่า = ยกเลิกใบที่ส่งแล้ว
   process ตัดสิน mode เองจากสถานะสดใน DB จอแค่ส่งเจตนาไป (จอกับ DB อาจไม่ตรงกันได้เสมอ) */
const cancelOrder = (id, reason) => {
	const form = field.getFormRef();
	if (!form) return;
	s.itmBusy[id] = true;
	const args = { order_id: id };
	if (reason) args.reason = reason;
	form.userState.runProcess(
		CANCEL_PROC,
		args,
		(res) => {
			s.itmBusy[id] = false;
			const d = (res && res.data) || {};
			if (!d.success) {
				if (d.code === 'REASON_REQUIRED') {
					// ใบกลายเป็น sent ระหว่างที่การ์ดยังโชว์ปุ่มลบ — เปิดกล่องให้กรอกต่อ ไม่ใช่แค่เด้ง alert
					s.itmCanId = id;
					s.itmCanErr = d.message || '';
					return;
				}
				field.alert(d.message || 'ยกเลิกใบไม่สำเร็จ', 'warning');
				s.itmCanClose();
				s.itmReload();
				return;
			}
			s.itmCanClose();
			field.alert(d.message || 'ยกเลิกใบแล้ว', 'success');
			s.itmReload();
		},
		(err) => {
			s.itmBusy[id] = false;
			field.alert('ยกเลิกใบไม่สำเร็จ: ' + ((err && err.message) || err), 'warning');
		}
	);
};

// ปุ่ม "ลบใบนี้" ของใบร่าง (ผ่าน el-popconfirm — ไม่ต้องกรอกเหตุผล)
s.itmDelete = (o) => {
	if (!o || !o.order_id) return;
	const id = String(o.order_id);
	if (s.itmBusy[id]) return;
	cancelOrder(id, '');
};

// ปุ่ม "ยืนยันยกเลิก" ในกล่องเหตุผลของใบที่ส่งแล้ว
s.itmCanSubmit = (o) => {
	const id = String((o && o.order_id) || s.itmCanId || '');
	if (!id || s.itmBusy[id]) return;
	const reason = String(s.itmCanText || '').trim();
	if (reason.length < MIN_CAN) {
		s.itmCanErr = 'ระบุเหตุผลอย่างน้อย ' + MIN_CAN + ' ตัวอักษร (ตอนนี้ ' + reason.length + ')';
		return;
	}
	s.itmCanErr = '';
	cancelOrder(id, reason);
};

/* ══ patient context — ยืมของ order_card ═════════════════════════════════
   order_card เป็นเจ้าของฟังก์ชันประกอบ context (ptContext + withInscl) อยู่แล้ว
   ⇒ การ์ดนี้ยืมมาใช้ ไม่ทำชุดของตัวเอง · ถ้ายังไม่ได้แพตช์ ต้องดังพอที่คนจะรู้ว่าต้องทำอะไร */
const contextOf = (done) => {
	const oc = field.getFieldRef('order_card');
	const fn = oc && oc.vueState && oc.vueState.orderContext;
	if (typeof fn !== 'function') {
		field.alert('ยังไม่ได้แพตช์ order_card ให้เปิด orderContext() — ดู sdform/cpoe/emr-order-card-expose-context.patch.js', 'error');
		done(null);
		return;
	}
	fn(done);
};

/* เปิดจอสั่งตรวจ — extra = { order_id } เมื่อเป็นการกลับเข้าไปแก้ใบเดิม

   🔴 refresh เฉพาะตอนที่ "ใบเปลี่ยนจริง" เท่านั้น — cancelCallback เป็นทางออกทางเดียวของ popup
      ทั้ง "กดปิดเฉยๆ" และ "บันทึกแล้วปิด" วิ่งผ่านตัวเดียวกัน ⇒ ให้จอบอกผ่าน on_order_saved
   🔴 ส่งทาง `params` ไม่ใช่ `initData` — form_ui ที่มีแต่ vue-ui ตัด initData ทิ้งใน buildDataModel */
const openScreen = (ctx, extra) => {
	const form = field.getFormRef();
	s.itmDirty = false;
	form.openForm(ITEM_APP_FORM_ID, '', String(ctx.visit_id), null, {
		backdrop: false, // ติ๊กชีทยาว — กดพลาดนอกกล่องแล้วปิดทิ้ง = เสียของที่ติ๊กไว้
		// 🔴 ต้อง spread formParams ของแม่ ไม่งั้น popup ไม่เหลือ _id/xsitex/xunitx (ระบบใช้ตัดสิน site/unit)
		params: Object.assign({}, form.formParams, ctx, extra || {}, {
			// ctx มาจาก order_card ซึ่งตั้ง service_type เป็น 'med' ไว้ให้จอสั่งยา — จอนี้ต้องไม่รับค่านั้น
			// (1 ใบมีได้หลายชนิด ชนิดตัวจริงอยู่ที่รายการ ไม่ใช่ที่ใบ — spec §3.4)
			service_type: '',
			on_order_saved: () => {
				s.itmDirty = true;
			},
		}),
		// 🔴 ใส่ cancelCallback เอง = ทับ default ⇒ ต้อง subFormClose() เองด้วย
		cancelCallback: () => {
			form.subFormClose();
			if (!s.itmDirty) return; // ปิดเฉยๆ — รายการในการ์ดยังตรงกับ DB อยู่แล้ว
			s.itmDirty = false;
			s.itmReload();
		},
	});
};

// ปุ่ม "+ สั่งตรวจ" ที่หัวการ์ด — เปิดจอเปล่าเพื่อออกใบใหม่
s.itmNew = () => {
	contextOf((ctx) => {
		if (!ctx || !ctx.visit_id) {
			field.alert('ยังไม่ได้เลือกผู้ป่วย/visit', 'warning');
			return;
		}
		openScreen(ctx, null);
	});
};

// เปิดแก้ใบร่างเดิม — จอจะโหลดรายการกลับเป็นตะกร้าเองจาก order_id
s.itmEdit = (o) => {
	if (!o || !o.order_id) return;
	if (!o.can_edit) {
		field.alert('ใบนี้ไม่ใช่ใบร่างแล้ว จึงแก้จากจอสั่งตรวจไม่ได้', 'warning');
		return;
	}
	contextOf((ctx) => {
		if (!ctx || !ctx.visit_id) {
			field.alert('ยังไม่ได้เลือกผู้ป่วย/visit', 'warning');
			return;
		}
		openScreen(ctx, { order_id: String(o.order_id) });
	});
};

/* ══ แก้ใบที่ส่งแล้ว (พี่เคาะ 2026-10-08 ข้อ A) ═══════════════════════════
   ดึงใบกลับเป็นร่างก่อน (cpoe-order-cancel action:'recall') แล้วเปิดจอแก้ทันที
   แก้เสร็จหมอต้องกด "ส่งใบสั่งตรวจ" ใหม่ — ตอนส่งผ่านด่านแลปซ้ำ/ห้องปลายทางของ order-send อีกรอบ
   🔴 process ตัดสินเองว่าดึงได้ไหม (ห้องปลายทางรับไปแล้ว/รายการเริ่มดำเนินการ = ไม่ได้) จอแค่ส่งเจตนา */
s.itmRecall = (o) => {
	if (!o || !o.order_id) return;
	const id = String(o.order_id);
	if (s.itmBusy[id]) return;
	const form = field.getFormRef();
	if (!form) return;
	s.itmBusy[id] = true;
	form.userState.runProcess(
		CANCEL_PROC,
		{ order_id: id, action: 'recall' },
		(res) => {
			s.itmBusy[id] = false;
			const d = (res && res.data) || {};
			if (!d.success) {
				field.alert(d.message || 'ดึงใบกลับมาแก้ไม่สำเร็จ', 'warning');
				s.itmReload();
				return;
			}
			s.itmReload(); // การ์ดหลัง popup ต้องเห็นใบเป็น "ร่าง" แล้ว — ปิดจอโดยไม่แก้ก็ยังตรงกับ DB
			contextOf((ctx) => {
				if (!ctx || !ctx.visit_id) {
					field.alert('ยังไม่ได้เลือกผู้ป่วย/visit', 'warning');
					return;
				}
				openScreen(ctx, { order_id: id });
			});
		},
		(err) => {
			s.itmBusy[id] = false;
			field.alert('ดึงใบกลับมาแก้ไม่สำเร็จ: ' + ((err && err.message) || err), 'warning');
		}
	);
};

/* ══ การ์ดสรุปค่าใช้จ่าย (แบบ A · พี่เลือก 2026-10-08) ═══════════════════════
   แยก "ใบสั่งยา" (service_type_code = med — ชุดเดียวกับที่ order_card กรอง) กับ "ใบสั่งตรวจ" (ที่เหลือทั้งหมด)
   ใช้ยอดหัวใบ (total/claim/paid_amount) ที่ cpoe-order-list ส่งมา — ตัวเดียวกับที่โชว์ในการ์ดแต่ละใบ
   🔴 ไม่นับ cancelled/reversed: ใบที่ยกเลิก/กลับรายการไม่ใช่เงินที่คนไข้ต้องจ่าย
   🔴 ใบร่างนับด้วย — หมอใช้ประเมินค่าใช้จ่ายก่อนส่ง แต่บอกจำนวนไว้ใต้ยอด ไม่ให้เข้าใจว่าส่งครบแล้ว */
const COST_SKIP = ['cancelled', 'reversed'];
const costLive = () => (s.costAll || []).filter((o) => COST_SKIP.indexOf(String(o.current_status || '')) < 0);
const costSum = (list, key, label) => {
	const r = { key: key, label: label, count: list.length, total: 0, claim: 0, paid: 0 };
	list.forEach((o) => {
		r.total += Number(o.total_amount) || 0;
		r.claim += Number(o.claim_amount) || 0;
		r.paid += Number(o.paid_amount) || 0;
	});
	return r;
};
s.costRows = () => {
	const live = costLive();
	const med = live.filter((o) => String(o.service_type_code || '') === DRUG_TYPE);
	const other = live.filter((o) => String(o.service_type_code || '') !== DRUG_TYPE);
	return [costSum(med, 'med', 'ใบสั่งยา'), costSum(other, 'item', 'ใบสั่งตรวจ')];
};
s.costTotal = () => costSum(costLive(), 'all', 'รวมทั้งหมด');
s.costDraftCount = () => costLive().filter((o) => String(o.current_status || '') === 'draft').length;
s.costCancelCount = () => (s.costAll || []).length - costLive().length;

/* โหลดเฉพาะยอด — order_card เรียกหลังใบยาเปลี่ยน (ส่ง/ลบ/ยกเลิก/แก้/ดึงกลับ)
   🔴 ไม่เรียก itmLoad แทน: ตัวนั้นล้างแถวที่หมอกางไว้ในการ์ดใบสั่งตรวจทิ้ง ทั้งที่ใบตรวจไม่ได้เปลี่ยน
   ไม่ส่ง full_items — ใช้แค่ยอดหัวใบ */
s.costRefresh = () => {
	if (!s.itmVid) return;
	const form = field.getFormRef();
	if (!form) return;
	const vid = s.itmVid;
	s.costLoading = true;
	form.userState.runProcess(
		LIST_PROC,
		{ visit_id: vid },
		(res) => {
			s.costLoading = false;
			const d = (res && res.data) || {};
			// เปลี่ยนคนไข้ระหว่างรอ — ผลนี้เป็นของวิสิทเก่า ทิ้งไป
			if (vid !== s.itmVid || !d.success) return;
			s.costAll = Array.isArray(d.orders) ? d.orders : [];
		},
		() => {
			s.costLoading = false;
		}
	);
};

/* emr2-orders-addon — EMR v2 (gen-emr-v2-model.cjs ต่อท้ายให้ · อย่าแก้ในบิลเดอร์) */
/* ══ emr2-orders addon — EMR v2 เท่านั้น (generator ต่อท้าย onCreated ของ order_card / item_card ใน v2) ══════════
   ใช้ `s` / `field` ของไฟล์หลัก (sdform/cpoe/widget-order-card · widget-item-card .oncreated.js) — ห้ามประกาศซ้ำ
   หน้าที่: จัดใบเป็นกลุ่มตามคลินิกผู้สั่ง (board 4 · มติ M6) · คลินิกตัวเองขึ้นก่อน · คลินิกอื่น 🔒
   🔴 ใบไหนแก้ได้ ยังตัดสินด้วย can_* / own_clinic ของ cpoe-order-list เหมือนเดิม — addon แค่จัดกลุ่ม ไม่คิดกติกาเอง */

// สีของ el-tag เดิม (success/warning/…) → คลาสใน emr2-orders.css
s.e2oTone = (color) => 'is-' + String(color || 'info');

// สีป้ายสถานะเฉพาะ v2 (พี่สั่ง 2026-10-23 · ข้อ A): ส่งแล้ว → เขียว · ยกเลิก → ส้ม (เดิม info = เขียว accent อ่านไม่ออกว่ายกเลิก)
// ทับแค่ color ของ itmStatus / ordStatus — ไฟล์หลักที่ v1 ใช้ร่วมไม่แตะ · สถานะอื่นคงสีเดิม
const E2O_STATUS_TONE = { sent: 'success', cancelled: 'orange' };
['itmStatus', 'ordStatus'].forEach((key) => {
	const base = s[key];
	if (typeof base !== 'function') return;
	s[key] = (o) => {
		const st = base(o);
		const tone = E2O_STATUS_TONE[String((o && o.current_status) || '')];
		return tone ? Object.assign({}, st, { color: tone }) : st;
	};
});

/* ตัวนับปุ่ม "ผลตรวจวันนี้" (emr2_labs · ออก N · รอ M) ตามการ์ดสั่งตรวจ (พี่แจ้ง 2026-10-23 "เพิ่ม แก้ไข แล้วผลตรวจวันนี้ ไม่อัพเดทตาม")
   ทุกทางที่ใบ Lab/X-ray เปลี่ยน (สร้าง · ส่ง · ยกเลิก · ลบ · WS จากจออื่น) จบที่ s.itmLoad ⇒ ครอบตรงนี้ที่เดียว
   โหลดเฉพาะเมื่อ labs ถือ visit เดียวกันอยู่แล้ว — ตอนเปลี่ยนคนไข้ opd_card.setTran สั่ง e2lLoad เองอยู่แล้ว · มีแค่ item_card ที่มี itmLoad */
if (typeof s.itmLoad === 'function') {
	const itmLoadBase = s.itmLoad;
	s.itmLoad = (visitId, tran) => {
		itmLoadBase(visitId, tran);
		const labs = field.getFieldRef('emr2_labs');
		const ls = labs && labs.vueState;
		if (ls && ls.e2lReload && visitId && ls.e2lVid === String(visitId)) ls.e2lReload();
	};
}

const e2oSoap = () => {
	const soap = field.getFieldRef('emr2_soap');
	return (soap && soap.vueState) || {};
};

// โหมด "ซ่อน" คลินิกอื่นของช่องกลาง (emr2_soap · จำต่อเครื่อง) — ใช้ชุดเดียวกันทั้งจอ (มติ 2026-10-22)
const e2oHideOthers = () => e2oSoap().e2Mode === 'hidden';

// "16.p โรคสมอง" → "โรคสมอง" (mockup ป้ายคลินิกไม่มีรหัส — ท่าเดียวกับ bnFrom ของ emr2_soap)
s.e2oClinicName = (label) => String(label || '').replace(/^\S+\.\S*\s+/, '') || String(label || '');

/* สีป้ายคลินิก is-c0…c4 — ลำดับคลินิกใน visit (journey ของ emr2_soap) ⇒ คลินิกเดียวกันสีเดียวกันทุกการ์ดในจอ
   ไม่อยู่ใน journey (ใบเก่า/คลินิกที่ไม่มีคิว) = สีจากรหัส · cost_summary เรียกตัวนี้ผ่าน order_card */
s.e2oClinicTone = (code) => {
	const c = String(code || '');
	const journey = typeof e2oSoap().e2Journey === 'function' ? e2oSoap().e2Journey() : [];
	const i = journey.findIndex((j) => String(j.unit) === c);
	if (i >= 0) return 'is-c' + (i % 5);
	let h = 0;
	for (let k = 0; k < c.length; k += 1) h = (h + c.charCodeAt(k)) % 5;
	return 'is-c' + h;
};

// ใบที่ยังไม่มี order_clinic (ใบเก่า) process ถือว่าเป็นของคนเปิด (own_clinic true) — รวมไว้กลุ่มของฉัน
const e2oGroupAll = (list) => {
	const groups = [];
	(list || []).forEach((o) => {
		const mine = o.own_clinic !== false;
		const key = mine ? '__mine' : String(o.order_clinic_code || o.order_clinic || '-');
		let g = groups.find((x) => x.key === key);
		if (!g) {
			g = { key, mine, code: o.order_clinic_code || '', label: o.order_clinic ? s.e2oClinicName(o.order_clinic) : mine ? 'คลินิกของฉัน' : 'ไม่ระบุคลินิก', orders: [] };
			groups.push(g);
		}
		// กลุ่มของฉันมีใบที่ไม่มีคลินิกปน — ใช้ชื่อคลินิกจากใบที่มี
		if (mine && !g.code && o.order_clinic) {
			g.code = o.order_clinic_code || '';
			g.label = s.e2oClinicName(o.order_clinic);
		}
		g.orders.push(o);
	});
	// คลินิกตัวเองขึ้นก่อน · คลินิกอื่นเรียงตามที่ process ส่งมา
	return groups.filter((g) => g.mine).concat(groups.filter((g) => !g.mine));
};

s.e2oGroups = (list) => {
	const all = e2oGroupAll(list);
	return e2oHideOthers() ? all.filter((g) => g.mine) : all;
};

s.e2oHiddenCount = (list) => {
	if (!e2oHideOthers()) return 0;
	return (list || []).filter((o) => o.own_clinic === false).length;
};
/* /emr2-orders-addon */

/* emr2-once-addon — EMR v2 (gen-emr-v2-model.cjs ต่อท้ายให้ · อย่าแก้ในบิลเดอร์) */
{
/* emr2-once — กันโหลดซ้ำตอนเปิดคนไข้ครั้งแรก (B1 · วัดจอจริง 2026-10-24: เปิดครั้งแรก 30 request · เปิดซ้ำ 15)
   ต้นเหตุ: ตอน mount ครั้งแรก widget ถูกสั่งโหลด 2 ทางพร้อมกัน
     ① opd_card.onMounted → setTran($examTran) → ไล่สั่งทุกการ์ด (ทาง "feed" · opd_card ติดธง form.$e2Feed ระหว่างไล่)
     ② onMounted ของ widget เอง อ่าน $examTran แล้วโหลดเอง
   ⇒ ห่อฟังก์ชันโหลด: อีกทางเพิ่งโหลด visit เดียวกันไม่เกิน E2_ONCE_MS = ข้าม
      ทางเดียวกันเรียกซ้ำ (กดโหลดใหม่ · หลังบันทึก · WS) ไม่ข้าม · เปลี่ยนคนไข้ (visit ต่าง) ไม่ข้าม
   gen-emr-v2-model.cjs ฝังไฟล์นี้ต่อท้าย onCreated ของแต่ละ widget (ในบล็อก { } ชื่อไม่ชนโค้ดเดิม) — แก้ที่ไฟล์นี้แล้ว gen ใหม่ */
const E2_ONCE_MS = 2000;
const e2OnceWrap = (widget, name, fnName, vidOf) => {
	const st = widget.vueState;
	const orig = st[fnName];
	if (typeof orig !== 'function' || orig.e2Once) return;
	const key = `${name}.${fnName}`;
	const wrapped = (...args) => {
		const form = widget.getFormRef && widget.getFormRef();
		const raw = vidOf(...args);
		const vid = raw ? String(raw) : '';
		if (form && vid) {
			const fromFeed = form.$e2Feed === true;
			const seen = form.$e2Loaded || (form.$e2Loaded = {});
			const last = seen[key];
			const now = Date.now();
			if (last && last.vid === vid && last.fromFeed !== fromFeed && now - last.at < E2_ONCE_MS) return undefined;
			seen[key] = { vid, fromFeed, at: now };
		}
		return orig(...args);
	};
	wrapped.e2Once = true;
	st[fnName] = wrapped;
};
e2OnceWrap(this, 'item_card', 'itmLoad', (visitId) => visitId);
}
/* /emr2-once-addon */

/* emr2-req-addon — EMR v2 (gen-emr-v2-model.cjs ต่อท้ายให้ · อย่าแก้ในบิลเดอร์) */
/* emr2-req — รวม request ที่ซ้ำกันระหว่าง widget (B2 · 2026-10-24)
   วัดจอจริง: เปิดคนไข้ยิง process เดียวกัน params เดียวกันพร้อมกันหลายตัว (vx-engine · emr-lab-board-get · cpoe-order-list)
   ⇒ request ที่ยังรอคำตอบอยู่ (หรือเพิ่งตอบไม่เกิน E2_REQ_REUSE_MS) ใช้คำตอบเดียวกัน · นอกนั้นยิงใหม่ตามปกติ
   🔴 ไม่ cache ยาว — หลังบันทึกใบแล้วโหลดใหม่ต้องได้ข้อมูลสด · ค่า 300ms กันแค่ตัวที่ยิงห่างกันนิดเดียวในรอบเปิดคนไข้
   ทุกตัวได้ res.data คนละชุด (copy) — widget แก้ข้อมูลของตัวเองได้โดยไม่กระทบตัวอื่น
   สมุดเก็บที่ form.$e2Req (ฟอร์มเดียวกัน = เห็นกัน) · gen-emr-v2-model.cjs ฝังไฟล์นี้ในแต่ละ widget ที่ใช้ — แก้ที่นี่แล้ว gen ใหม่ */
const E2_REQ_REUSE_MS = 300;
const e2Req = (form, procId, params, ok, err) => {
	if (!form || !form.userState) return;
	const key = `${procId} ${JSON.stringify(params || {})}`;
	const book = form.$e2Req || (form.$e2Req = {});
	const copy = (res) => (res && typeof res === 'object' && res.data !== undefined ? { ...res, data: JSON.parse(JSON.stringify(res.data)) } : res);
	// callback ของ widget หนึ่งพัง ต้องไม่ทำให้ตัวอื่นไม่ได้ข้อมูล
	const call = (fn, value) => {
		if (typeof fn !== 'function') return;
		try {
			fn(value);
		} catch (e) {
			globalThis.console.error('[e2Req]', procId, e);
		}
	};
	const hit = book[key];
	if (hit && hit.pending) {
		hit.waiters.push([ok, err]);
		return;
	}
	if (hit && Date.now() - hit.at < E2_REQ_REUSE_MS) {
		setTimeout(() => (hit.ok ? call(ok, copy(hit.res)) : call(err, hit.res)), 0);
		return;
	}
	const entry = { pending: true, waiters: [[ok, err]], at: Date.now(), ok: false, res: null };
	book[key] = entry;
	const settle = (isOk, res) => {
		entry.pending = false;
		entry.ok = isOk;
		entry.res = res;
		entry.at = Date.now();
		entry.waiters.forEach(([o, x], i) => (isOk ? call(o, i === 0 ? res : copy(res)) : call(x, res)));
	};
	form.userState.runProcess(procId, params, (res) => settle(true, res), (e) => settle(false, e));
};
/* /emr2-req-addon */

options.onMounted:
const field = this;
const s = this.vueState;
// เคสแท็บ EMR mount หลังกดเลือกคนไข้จากคิวไปแล้ว → opd_card.setTran ยิงไปก่อนที่การ์ดนี้จะเกิด
// ⇒ ดึง tran จาก form เองรอบแรก (pattern เดียวกับ order_card)
setTimeout(() => {
	const form = field.getFormRef();
	const tran = form && form.$examTran;
	const visitId = tran && tran.vid && tran.vid.value ? String(tran.vid.value) : null;
	s.itmLoad(visitId, tran || null);
}, 0);

options.onUnmount:
// item_card · onUnmount — ปิด websocket ห้องของวิสิท (เปิดใน onCreated · wsWatch)
// ไม่ปิด = socket ค้างทุกครั้งที่สลับแท็บ/ปิดจอ EMR
if (this.vueState && this.vueState.itmCleanup) this.vueState.itmCleanup();

options.onCreated:
// ============================================================================
// vx_today_card · onCreated — การ์ด "วัคซีนวันนี้" ของหมอ (C22 · topic vaccine)
// ฟอร์ม EMR 6a4f64e7f8cdfc54cec16488 · vue-ui ชื่อ vx_today_card (คอลัมน์ 1 ต่อจาก spclinic_card)
// แบบ: design/vaccine/vaccine-mockup.html emrVaccineCard / sendOrder (:1582-1647)
//
// ข้อมูล: process vx-order (สถานะส่งฉีดของ visit นี้ · เขียน Visit History) + vx-engine (เข็มที่ให้ได้ · ตรวจก่อนส่ง)
//   จอไม่คิดกฎเอง — ติ๊กเปลี่ยนเมื่อไหร่ ส่ง keys ให้ engine จัดยี่ห้อ + ตรวจ แล้ววาดตามผล
// 3 สถานะ (ทุกสถานะมีปุ่มสมุดเต็ม · พี่สั่ง 10-19): ยังไม่ส่ง (ติ๊ก) · รอฉีด (แก้ไขได้) · ฉีดแล้ว (C24 เป็นคนเขียน)
// โหลดใหม่เองเมื่อเปลี่ยนคนไข้ — onMounted watch ช่อง vid (ไม่ผูกโค้ดใน opd_card แบบเดียวกับ spclinic_card)
//
// 🔴 ห้าม v-model กับ key ใน vueState (scope proxy ไม่มี set) · ห้าม document/window (sandbox)
// ============================================================================
const s = this.vueState
const field = this

const PROC = {
  engine: '6ad5f14921fe5a1471b50fce',   // vx-engine
  order: '6ad63a8ef2880767e1b78170',    // vx-order (get / send)
}
const ST_TEXT = { due: 'ถึงกำหนด', overdue: 'เลยกำหนด', caution: 'มีเงื่อนไข', opt: 'ทางเลือก' }
// ข้อความติ๊กยืนยันใต้แถว — เหมือน CONFIRM_TEXT ของ mockup (ตัดเลขข้อ PIDST ออกแล้ว · พี่สั่ง 10-19)
// เงื่อนไขอื่นที่ engine ขอยืนยัน (MMRV) ใช้ข้อความจาก engine ตรง ๆ
const CONFIRM_TEXT = { rota63: 'อธิบายความเสี่ยงลำไส้กลืนกันให้ผู้ปกครองแล้ว' }
const ADULT_DAYS = Math.round(18 * 365.25)   // ตาราง PIDST ครอบคลุมเด็ก-วัยรุ่น — เท่ากับแถบใน opd_card (C21)

// ---- state (ค่าเริ่มต้นต้องพร้อมก่อน render แรก)
s.vtCtx = null        // { visitId, personId }
s.vtLoading = false
s.vtError = ''
s.vtOrder = null      // ผล vx-order get .order · null = visit นี้ยังไม่ส่ง
s.vtEng = null        // ผล vx-engine (ไม่ส่ง keys) — ตาราง/เข็มที่ให้ได้
s.vtDraft = []        // เข็มที่ติ๊ก 'MMR|1'
s.vtConf = []         // เข็มที่ติ๊กยืนยันเงื่อนไขแล้ว
s.vtCheck = null      // ผล vx-engine ส่ง keys = vtDraft → lines/summary/checks/blocked/need_confirm
s.vtChecking = false
s.vtEditing = false   // กด "แก้ไข" ตอนรอฉีด → กลับมาติ๊กใหม่
s.vtSending = false
s.vtShowOther = false // ทางเลือกอื่น (พับไว้ · เหมือน <details> ของ mockup)

const form = () => field.getFormRef()
// ซ่อน/แสดงทั้ง field — ห้ามทำใน builder: hide() เขียน options.hidden ลงฟอร์ม แล้วติดไปทั้งระบบเมื่อมีคนกด Save (spclinic_card 2026-10-08)
const hideField = () => { if (!field.builderStatus) field.hide() }
const showField = () => { if (!field.builderStatus) field.show() }
s.vtHideField = hideField

// ---- โหลด
let checkSeq = 0
let checkTimer = null
s.vtLoad = (row) => {
  const vid = row && row.vid
  const ctx = vid && vid.value ? { visitId: String(vid.value), personId: vid.xtbxlv1_xfx_id ? String(vid.xtbxlv1_xfx_id) : '' } : null
  s.vtCtx = ctx
  s.vtOrder = null
  s.vtEng = null
  s.vtDraft = []
  s.vtConf = []
  s.vtCheck = null
  s.vtChecking = false
  s.vtEditing = false
  s.vtError = ''
  s.vtShowOther = false
  checkSeq++
  if (!ctx) { hideField(); return }
  const f = form()
  if (!f || !f.userState) return
  s.vtLoading = true
  const stale = () => !s.vtCtx || s.vtCtx.visitId !== ctx.visitId
  let pending = 2
  const done = () => { if (--pending === 0) { s.vtLoading = false; s.vtAfterLoad() } }
  const runEngine = (pid) => e2Req(f, PROC.engine, { pid }, (res) => {
    if (stale()) return
    const d = (res && res.data) || {}
    // engine ล้ม (เช่นไม่มีวันเกิด) = บอกในการ์ด ไม่เด้งทับจอหมอ
    if (d.success) s.vtEng = d.data
    else s.vtError = d.message || 'คำนวณตารางวัคซีนไม่ได้'
    done()
  }, () => { if (!stale()) { s.vtError = 'เรียกตารางวัคซีนไม่สำเร็จ'; done() } })
  f.userState.runProcess(PROC.order, { action: 'get', visit_id: ctx.visitId }, (res) => {
    if (stale()) return
    const d = (res && res.data) || {}
    if (d.success) s.vtOrder = d.order || null
    else s.vtError = d.message || 'อ่านรายการส่งฉีดไม่ได้'
    // tran ไม่มี person id (เปิดจาก vid อย่างเดียว) → รอผล get แล้วค่อยเรียก engine
    if (!ctx.personId && d.visit && d.visit.pid) { ctx.personId = d.visit.pid; runEngine(ctx.personId) }
    else if (!ctx.personId) done()
    done()
  }, () => { if (!stale()) { s.vtError = 'อ่านรายการส่งฉีดไม่สำเร็จ'; if (!ctx.personId) done(); done() } })
  if (ctx.personId) runEngine(ctx.personId)
}
s.vtReload = () => {
  const ctx = s.vtCtx
  if (ctx) s.vtLoad({ vid: { value: ctx.visitId, xtbxlv1_xfx_id: ctx.personId } })
}

// หลังโหลดครบ: ตัดสินว่าการ์ดขึ้นไหม + ค่าติ๊กเริ่มต้น
s.vtAfterLoad = () => {
  const e = s.vtEng
  // ผู้ใหญ่ ≥ 18 ปี ไม่ขึ้นการ์ด (engine คิดผู้ใหญ่ด้วยตารางเด็ก — วัคซีนผู้ใหญ่อยู่ checklist C13) · ยกเว้นมีรายการส่งไว้แล้ว
  if (e && e.person && e.person.age_days >= ADULT_DAYS && !s.vtOrder) { hideField(); return }
  showField()
  s.vtStartDraft()
}
// ค่าติ๊กเริ่มต้น = ถึง/เลยกำหนด (mockup) · ยังไม่มีประวัติฉีดในระบบ = ไม่ติ๊กให้
//   (engine จะนับเลยกำหนดทุกเข็ม — ติ๊กให้ทั้งหมดผิดแน่ · แบบเดียวกับแถบเทา C21 ที่พี่เลือกข้อ 1)
s.vtStartDraft = () => {
  const e = s.vtEng
  const o = s.vtOrder
  if (o && o.status === 'ordered' && s.vtEditing) {
    s.vtDraft = o.items.slice()
    s.vtConf = o.confirmed.slice()
  } else {
    s.vtDraft = e && s.vtHasHistory() ? (e.default_pick || []).slice() : []
    s.vtConf = []
  }
  s.vtRecheck(0)
}
s.vtHasHistory = () => !!(s.vtEng && (s.vtEng.shots || []).length)

// ---- ติ๊ก → ให้ engine จัดยี่ห้อ + ตรวจ (หน่วงนิดหน่อย กดติ๊กหลายช่องติดกันยิงครั้งเดียว)
s.vtRecheck = (delay) => {
  const ctx = s.vtCtx
  const keys = s.vtDraft.slice()
  const seq = ++checkSeq
  if (checkTimer) clearTimeout(checkTimer)
  if (!ctx || !ctx.personId || !keys.length) { s.vtCheck = null; s.vtChecking = false; return }
  s.vtChecking = true
  checkTimer = setTimeout(() => {
    const f = form()
    if (!f || !f.userState) return
    f.userState.runProcess(PROC.engine, { pid: ctx.personId, keys }, (res) => {
      if (seq !== checkSeq) return
      const d = (res && res.data) || {}
      s.vtChecking = false
      s.vtCheck = d.success ? d.data : null
      if (!d.success) s.vtError = d.message || 'ตรวจรายการไม่ได้'
    }, () => { if (seq === checkSeq) { s.vtChecking = false; s.vtError = 'ตรวจรายการไม่สำเร็จ' } })
  }, delay == null ? 250 : delay)
}
s.vtHas = (k) => s.vtDraft.indexOf(k) >= 0
s.vtToggle = (k, on) => {
  const d = s.vtDraft.filter((x) => x !== k)
  if (on) d.push(k)
  s.vtDraft = d
  if (!on) s.vtConf = s.vtConf.filter((x) => x !== k)
  s.vtRecheck()
}
s.vtConfirmed = (k) => s.vtConf.indexOf(k) >= 0
s.vtToggleConf = (k, on) => {
  const c = s.vtConf.filter((x) => x !== k)
  if (on) c.push(k)
  s.vtConf = c
}

// ---- อ่านผล engine สำหรับวาด
const doses = () => (s.vtEng && s.vtEng.grid ? s.vtEng.grid.reduce((a, g) => a.concat((g.doses || []).map((d) => Object.assign({ th: g.th }, d))), []) : [])
const shortLabel = (d) => String(d.label || d.ag).replace(/[()]/g, '')
s.vtDose = (k) => doses().find((d) => d.key === k) || null
s.vtName = (k) => { const d = s.vtDose(k); return d ? d.th + ' · ' + shortLabel(d) : k }
s.vtShort = shortLabel
// กลุ่มเหมือน mockup: ต้องให้ตามตาราง · หมอต้องตัดสินใจ · แนะนำ (กลุ่มเสี่ยง) · ทางเลือกอื่น (พับ)
s.vtGroups = () => {
  const giv = new Set((s.vtEng && s.vtEng.givable) || [])
  const list = doses().filter((d) => giv.has(d.key))
  return {
    all: list.length,
    must: list.filter((d) => d.st === 'due' || d.st === 'overdue'),
    cau: list.filter((d) => d.st === 'caution'),
    rec: list.filter((d) => d.st === 'opt' && d.rec),
    other: list.filter((d) => d.st === 'opt' && !d.rec),
  }
}
s.vtStText = (st) => ST_TEXT[st] || st
s.vtToggleOther = () => { s.vtShowOther = !s.vtShowOther }   // template เขียน state ตรงไม่ได้ (scope proxy ไม่มี set)
// ป้ายสถานะ — สีเดียวกับชิปในสมุด (book-drawer.css) · inline เพราะ CSS ของฟอร์ม EMR เป็น global
s.vtChipStyle = (st) => {
  const base = 'display:inline-block;padding:0 6px;border-radius:5px;font-size:11.5px;line-height:18px;margin-left:4px;border:1px solid transparent;'
  if (st === 'overdue') return base + 'background:var(--el-color-danger-light-9);color:var(--el-color-danger);border-color:var(--el-color-danger);font-weight:600'
  if (st === 'due') return base + 'background:var(--el-color-warning-light-9);color:var(--el-color-warning-dark-2);border-color:var(--el-color-warning-dark-2)'
  if (st === 'caution') return base + 'background:var(--el-color-warning-light-9);color:var(--el-color-warning-dark-2);border:1px dashed var(--el-color-warning-dark-2)'
  // ทางเลือก = ม่วง (Element Plus ไม่มีม่วง · ค่าโปร่งแสงอ่านได้ทั้งธีมมืด/สว่าง)
  return base + 'background:rgba(124,92,196,.14);color:#8467d1'
}
// เตือนระดับคนไข้บนหัวการ์ด (แดง/เหลือง 2 ข้อแรก) — เหมือน warns ของ mockup
s.vtWarns = () => ((s.vtEng && s.vtEng.alerts) || []).filter((a) => a.c === 'red' || a.c === 'amber').slice(0, 2)
s.vtWarnStyle = (c) => 'padding:4px 8px;border-radius:6px;font-size:12px;margin-bottom:4px;' + (c === 'red'
  ? 'background:var(--el-color-danger-light-9);color:var(--el-color-danger)'
  : 'background:var(--el-color-warning-light-9);color:var(--el-color-warning-dark-2)')

// ข้อที่ต้องติ๊กยืนยันของแถวนี้ (มาจาก engine เมื่อแถวถูกติ๊ก) → [{ key, text }]
s.vtNeedOf = (k) => {
  const c = s.vtCheck
  if (!c || !s.vtHas(k)) return []
  return (c.need_confirm || []).filter((n) => n.key === k).map((n) => {
    const chk = (c.checks || []).find((x) => x.confirm === n.confirm && x.key === n.key)
    const raw = chk ? String(chk.t).replace(/^[🔴🟡🔵]\s*/u, '') : 'ยืนยันแล้ว'
    return { key: n.key, confirm: n.confirm, text: CONFIRM_TEXT[n.confirm] || raw }
  })
}
// ยังไม่ติ๊กยืนยันครบ / มีข้อห้ามสีแดง = ส่งไม่ได้
s.vtUnconfirmed = () => {
  const c = s.vtCheck
  return !!c && (c.need_confirm || []).some((n) => !s.vtConfirmed(n.key))
}
s.vtReds = () => ((s.vtCheck && s.vtCheck.checks) || []).filter((x) => x.c === 'red').map((x) => String(x.t).replace(/^[🔴]\s*/u, ''))
s.vtCanSend = () => s.vtDraft.length > 0 && !!s.vtCheck && !s.vtChecking && !s.vtSending && !s.vtCheck.blocked && !s.vtUnconfirmed()
// "= HEXAXIM · MMR / ฉีด 2 เข็ม + กิน/พ่น 1" — เหมือน vxsum ของ mockup
s.vtSum = () => {
  const c = s.vtCheck
  if (!c || !c.lines) return null
  const ln = c.lines.filter((l) => l.prod)
  if (!ln.length) return null
  const inj = (c.summary && c.summary.inject) || 0
  return { names: ln.map((l) => l.name || l.prod).join(' · '), inject: inj, other: ln.length - inj }
}

// ---- สถานะการส่ง
s.vtMode = () => {
  const o = s.vtOrder
  if (o && o.status === 'given') return 'given'
  if (o && o.status === 'ordered' && !s.vtEditing) return 'ordered'
  return 'draft'
}
const hhmm = (v) => (v ? String(v).slice(11, 16) : '')
s.vtHhmm = hhmm
// '2026-10-19' → '19/10/2569' (แบบเดียวกับ vbDateFull ของสมุด)
s.vtDateFull = (v) => {
  const m = /^(\d{4})-(\d{2})-(\d{2})/.exec(String(v || ''))
  return m ? Number(m[3]) + '/' + Number(m[2]) + '/' + (Number(m[1]) + 543) : ''
}
s.vtNext = () => (s.vtEng && s.vtEng.next) || null

s.vtEdit = () => {
  s.vtEditing = true
  s.vtStartDraft()
}
s.vtCancelEdit = () => {
  s.vtEditing = false
  s.vtCheck = null
  checkSeq++
}

s.vtSend = () => {
  const ctx = s.vtCtx
  const f = form()
  if (!ctx || !f || !s.vtCanSend()) return
  s.vtSending = true
  const keys = s.vtDraft.slice()
  f.userState.runProcess(PROC.order, { action: 'send', visit_id: ctx.visitId, keys, confirmed: s.vtConf.slice() }, (res) => {
    s.vtSending = false
    if (!s.vtCtx || s.vtCtx.visitId !== ctx.visitId) return
    const d = (res && res.data) || {}
    if (!d.success) {
      field.alert(d.message || 'ส่งไม่สำเร็จ', 'warning')
      // สถานะเข็ม/ใบเปลี่ยนระหว่างที่จอเปิดค้าง → โหลดการ์ดใหม่ให้เห็นของจริง
      if (d.changed) s.vtReload()
      return
    }
    s.vtOrder = d.order || null
    s.vtEditing = false
    s.vtCheck = null
    field.alert(d.message || 'ส่งพยาบาลห้องฉีดแล้ว', 'success')
  }, () => { s.vtSending = false; field.alert('ส่งไม่สำเร็จ', 'error') })
}

// สมุดเต็ม — ใช้ปุ่มเปิดสมุดของ opd_card (C21) ตัวเดียวกัน: drawer ขวา + ค่าตั้ง backdrop ของฟอร์ม Vaccine Book
s.vtOpenBook = () => {
  const oc = field.getFieldRef('opd_card')
  if (oc && oc.vueState && oc.vueState.openVxBook) { oc.vueState.openVxBook(); return }
  field.alert('เปิดสมุดวัคซีนไม่ได้ (ไม่พบ opd_card)', 'warning')
}

/* emr2-orders-addon — EMR v2 (gen-emr-v2-model.cjs ต่อท้ายให้ · อย่าแก้ในบิลเดอร์) */
/* ══ emr2-orders · vx addon — EMR v2 เท่านั้น (generator ต่อท้าย onCreated ของ vx_today_card ใน v2) ══════════
   ใช้ `s` ของไฟล์หลัก (sdform/vaccine/today-card.oncreated.js) — ห้ามประกาศซ้ำ
   ข้อความเตือนจาก vx-engine ขึ้นต้นด้วย emoji (🟡/🔴/🔵) — จอจริงห้ามใช้ emoji เป็น icon (พี่สั่ง 2026-10-22)
   ⇒ ตัดออกตอนแสดง สีของกล่องบอกระดับแทน (ท่าเดียวกับ vtReds/vtNeedOf ของไฟล์หลัก) */
s.e2vText = (t) => String(t || '').replace(/^[\u{1F300}-\u{1FAFF}\u{2600}-\u{27BF}]\u{FE0F}?\s*/u, '');
/* /emr2-orders-addon */

/* emr2-req-addon — EMR v2 (gen-emr-v2-model.cjs ต่อท้ายให้ · อย่าแก้ในบิลเดอร์) */
/* emr2-req — รวม request ที่ซ้ำกันระหว่าง widget (B2 · 2026-10-24)
   วัดจอจริง: เปิดคนไข้ยิง process เดียวกัน params เดียวกันพร้อมกันหลายตัว (vx-engine · emr-lab-board-get · cpoe-order-list)
   ⇒ request ที่ยังรอคำตอบอยู่ (หรือเพิ่งตอบไม่เกิน E2_REQ_REUSE_MS) ใช้คำตอบเดียวกัน · นอกนั้นยิงใหม่ตามปกติ
   🔴 ไม่ cache ยาว — หลังบันทึกใบแล้วโหลดใหม่ต้องได้ข้อมูลสด · ค่า 300ms กันแค่ตัวที่ยิงห่างกันนิดเดียวในรอบเปิดคนไข้
   ทุกตัวได้ res.data คนละชุด (copy) — widget แก้ข้อมูลของตัวเองได้โดยไม่กระทบตัวอื่น
   สมุดเก็บที่ form.$e2Req (ฟอร์มเดียวกัน = เห็นกัน) · gen-emr-v2-model.cjs ฝังไฟล์นี้ในแต่ละ widget ที่ใช้ — แก้ที่นี่แล้ว gen ใหม่ */
const E2_REQ_REUSE_MS = 300;
const e2Req = (form, procId, params, ok, err) => {
	if (!form || !form.userState) return;
	const key = `${procId} ${JSON.stringify(params || {})}`;
	const book = form.$e2Req || (form.$e2Req = {});
	const copy = (res) => (res && typeof res === 'object' && res.data !== undefined ? { ...res, data: JSON.parse(JSON.stringify(res.data)) } : res);
	// callback ของ widget หนึ่งพัง ต้องไม่ทำให้ตัวอื่นไม่ได้ข้อมูล
	const call = (fn, value) => {
		if (typeof fn !== 'function') return;
		try {
			fn(value);
		} catch (e) {
			globalThis.console.error('[e2Req]', procId, e);
		}
	};
	const hit = book[key];
	if (hit && hit.pending) {
		hit.waiters.push([ok, err]);
		return;
	}
	if (hit && Date.now() - hit.at < E2_REQ_REUSE_MS) {
		setTimeout(() => (hit.ok ? call(ok, copy(hit.res)) : call(err, hit.res)), 0);
		return;
	}
	const entry = { pending: true, waiters: [[ok, err]], at: Date.now(), ok: false, res: null };
	book[key] = entry;
	const settle = (isOk, res) => {
		entry.pending = false;
		entry.ok = isOk;
		entry.res = res;
		entry.at = Date.now();
		entry.waiters.forEach(([o, x], i) => (isOk ? call(o, i === 0 ? res : copy(res)) : call(x, res)));
	};
	form.userState.runProcess(procId, params, (res) => settle(true, res), (e) => settle(false, e));
};
/* /emr2-req-addon */

options.onMounted:
// vx_today_card · onMounted — โหลดตามคนไข้ที่เปิดอยู่ และโหลดใหม่ทุกครั้งที่เปลี่ยนคนไข้
//
// ไม่ผูกโค้ดใน opd_card (แบบ spclinic_card): opd_card.setTran เก็บ tran ไว้ที่ vueState.tran แล้วเขียนเลข visit ลงช่อง vid เสมอ
// ⇒ การ์ด watch ช่อง vid (form data = reactive) แล้วหยิบ tran จาก opd_card เอง
const field = this
const s = this.vueState

// tran ปัจจุบัน: opd_card ก่อน (ตัวที่ setTran ตั้งล่าสุด) · สำรอง form.$examTran (scan / ปุ่ม EMR จากคิว)
const currentTran = () => {
  const oc = field.getFieldRef('opd_card')
  const f = field.getFormRef()
  return (oc && oc.vueState && oc.vueState.tran) || (f && f.$examTran) || null
}

// แท็บ EMR mount หลังเลือกคนไข้แล้ว → โหลดเลย · ยังไม่มีคนไข้ → ซ่อนไว้ก่อน (ไม่ทำใน builder)
setTimeout(() => {
  const tran = currentTran()
  if (tran && !s.vtCtx) s.vtLoad(tran)
  else if (!tran) s.vtHideField()
}, 0)

// เปลี่ยนคนไข้ / ล้างคนไข้
field.$watch(() => field.formModel && field.formModel.vid, (v) => {
  const vid = v ? String(v) : ''
  if (s.vtCtx && s.vtCtx.visitId === vid) return
  if (!vid) { s.vtLoad(null); return }
  const tran = currentTran()
  // tran ไม่ตรง visit ที่เพิ่งเปลี่ยน → ส่งแค่เลข visit ให้ process หาคนไข้เอง ดีกว่าโชว์คนไข้ผิดคน
  const sameVisit = tran && tran.vid && String(tran.vid.value) === vid
  s.vtLoad(sameVisit ? tran : { vid: { value: vid } })
})

options.onCreated:
const s = this.vueState
const field = this
const BOOKING_FORM = '6a8c472df851000f28e50229'    // APPT Booking (form_db) — เปิด readonly เท่านั้น
/* ＋ นัดหมาย เปิดตัวนี้ — ฟอร์มนัดของหมอ ไม่มีแท็บอื่น ไม่มีขั้นค้นผู้ป่วย
   🔴 เปลี่ยนจากจอ N ทั้งจอเมื่อ 02/09 (รุ่นพี่ตีกลับ: เปิดมาแล้วมีแท็บของพยาบาลติดมาด้วย) */
const DOCTOR_BOOKING = '6a97b33a422c1ca959829fe1'

/* 🔴 ทุกคีย์ขึ้นต้น apt — หน้า EMR มีการ์ดหลายใบ ชื่อชนกันแล้วเขียนทับกันเงียบ ๆ
   (การ์ด item_card ของทีมเขาใช้ itm* ด้วยเหตุผลเดียวกัน) */
s.aptList = []
s.aptLoading = false
s.aptErr = ''
s.aptVid = ''
/* ตัวคนไข้ที่ส่งต่อให้ฟอร์มนัด — มาจาก tran ของ opd_card ทั้งชุด
   🔴 `aptPid` คือ person _id (`row.vid.xtbxlv1_xfx_id`) ไม่ใช่ `pid.value`
      ตัวเดียวกับที่ registry_card ใช้ · appt-staff-book หา zdata_person ด้วย _id ตัวนี้ตรง ๆ
   🔴 ส่ง pid ไปแทนการให้ฟอร์มค้นจาก hn — `hn` ไม่ unique ใน zdata_person (เจอจริง 3 แถวต่อ HN)
      ค้นด้วย hn แล้วเจอหลายแถว = มีโอกาสลงนัดให้เด็กผิดคน */
s.aptPid = ''
s.aptHn = ''
s.aptName = ''
s.aptPhone = ''
s.aptAll = false
s.aptToggle = () => { s.aptAll = !s.aptAll }

s.aptDead = (b) => b.status === 'cancelled' || b.status === 'no_show'
/* สรุปบนหัวแถว — นับเฉพาะใบที่ยังรอพยาบาลยืนยัน (ท่าเดียวกับ waitCount() ของ consult) */
s.aptWait = () => (s.aptList || []).filter((b) => !b.status || b.status === 'pending').length
s.aptStatus = (b) => b.status === 'confirmed' ? { color: 'success', label: 'ยืนยันแล้ว' }
  : b.status === 'checked_in' ? { color: 'success', label: 'มาตามนัด' }
  : b.status === 'cancelled' ? { color: 'danger', label: 'ยกเลิก' }
  : b.status === 'no_show' ? { color: 'danger', label: 'ไม่มา' }
  : b.status === 'moved' ? { color: 'info', label: 'เลื่อนแล้ว' }
  : { color: 'warning', label: 'รอยืนยัน' }

s.aptClinic = (b) => { const c = b.clinic || {}; return c.label || c.value || '' }
// วันไทยแบบสั้น — หมอต้องรู้ว่านัดวันไหนจากการกวาดตาแถวเดียว
s.aptWhen = (b) => {
  const p = String(b.slot_date || '').split('-')
  if (p.length !== 3) return String(b.slot_date || '')
  const M = ['','ม.ค.','ก.พ.','มี.ค.','เม.ย.','พ.ค.','มิ.ย.','ก.ค.','ส.ค.','ก.ย.','ต.ค.','พ.ย.','ธ.ค.']
  return Number(p[2]) + ' ' + (M[Number(p[1])] || '') + ' ' + ((Number(p[0]) + 543) % 100)
}

s.aptRows = () => {
  const st = { pending: 0, confirmed: 1, checked_in: 2, moved: 3, no_show: 4, cancelled: 5 }
  const sorted = [...(s.aptList || [])].sort((a, b) =>
    ((st[a.status] ?? 9) - (st[b.status] ?? 9)) ||
    String(a.slot_date || '').localeCompare(String(b.slot_date || '')))
  return s.aptAll ? sorted : sorted.slice(0, 3)
}

/* 🔴 กรองด้วย `from_visit` = visit ที่หมอเปิดอยู่ **ไม่ใช่** `visit_id`
   from_visit = visit วันที่สั่งนัด (วันนี้) · visit_id = visit วันที่ผู้ป่วยมาตามนัด (อนาคต)
   ใช้ผิดตัว = ใบหลุดจากการ์ดทันทีที่ promote สำเร็จ
   เก็บเป็น objectid ⇒ ต้อง CONVERT ก่อนเทียบ เหมือนที่ consult ทำกับ vid.value */
/* arg2 = `tran` ทั้งก้อนจาก opd_card (ท่าเดียวกับ ordLoad/itmLoad ของทีมเขา)
   🔴 รับ string ได้ด้วยเพื่อความเข้ากันได้ย้อนหลัง — ถ้าหน้า EMR ยังเป็นรุ่นที่ส่งแต่ hn มา
      การ์ดจะยังแสดงรายการได้ปกติ แต่ปุ่ม ＋ จะไม่มี pid ⇒ ฟอร์มนัดจะบอกให้เปิดใหม่
      (ยอมให้ตันดีกว่ายอมให้ค้นเอง — ค้นเองคือทางที่ลงนัดผิดคนได้) */
s.aptLoad = (visitId, tran) => {
  s.aptVid = visitId ? String(visitId) : ''
  if (typeof tran === 'string') { if (tran) s.aptHn = tran }
  else if (tran && tran.vid) {
    const v = tran.vid; const pd = v.pid || {}
    s.aptPid = v.xtbxlv1_xfx_id ? String(v.xtbxlv1_xfx_id) : ''
    s.aptHn = String(pd.hn || '')
    /* 🔴 `pid` ไม่มีคีย์ชื่อเต็มสักตัว — ไม่มีทั้ง label / patient_name / name
       ของจริงมีแค่ prename{value,label} · p_fname · p_lname (ตรวจ zdata_visit_tran 02/09)
       รอบแรกผมเดาว่ามี .label แล้วชื่อออกมาว่างบนจอ โดยที่ HN มาปกติ ⇒ ดูเหมือนทำงานอยู่
       ประกอบเองแบบเดียวกับที่ vid.label ของเขาแสดง: คำนำหน้าติดชื่อ ไม่เว้นวรรค */
    const nm = String(pd.p_fname || '') + (pd.p_lname ? ' ' + pd.p_lname : '')
    s.aptName = nm ? ((pd.prename && pd.prename.label) || '') + nm : ''
    /* เบอร์ไม่มีใน pid เลย — ปล่อยว่างถูกแล้ว appt-staff-book หยิบจากเวชระเบียนเอง */
  }
  s.aptErr = ''
  globalThis.__apptCardReload = () => s.aptReload()   // ฟอร์มนัดเรียกกลับหลังจองสำเร็จ
  if (!s.aptVid) { s.aptList = []; return }
  s.aptLoading = true
  try {
    field.getFormRef().userState.crudGetAll({
      sdProvider: {
        providerId: BOOKING_FORM,
        providerType: 'FORM',
        params: { vid: s.aptVid },
        options: {
          where: '`from_visit` = CONVERT(:vid, \'objectId\')',
          orderBy: [{ column: 'slot_date', sort: 'ASC' }],
          limit: 100,
          page: 1
        }
      },
      totalEnable: false
    }, (res) => { s.aptLoading = false; s.aptList = (res && res.data) || [] })
  } catch (e) {
    /* 🔴 พังตรงนี้ต้องพูด — การ์ดว่างเงียบ ๆ แยกไม่ออกจาก 'ไม่มีนัด' */
    s.aptLoading = false
    s.aptErr = 'อ่านรายการนัดไม่สำเร็จ: ' + ((e && e.message) || e)
  }
}
/* 🔴 โหลดซ้ำห้ามส่ง arg2 — ค่าคนไข้ตั้งไว้แล้วตอน setTran ส่ง tran มา
   ส่ง s.aptHn กลับเข้าไปจะไปเข้าสาขา string แล้ว pid/ชื่อ/เบอร์ ที่มีอยู่หายทันที */
s.aptReload = () => s.aptLoad(s.aptVid)

/* ดูใบนัด — เปิดจอ D โหมด view ซึ่งวาดเป็น **ใบนัด** ไม่ใช่ตารางช่องกรอก
   🔴 ของเดิมเปิด APPT Booking แบบ readonly ⇒ หมอเห็น field ดิบ 23 ช่องเรียงกัน
      รุ่นพี่สั่งให้ใช้หน้าตาเดียวกับตอนจองเสร็จ (02/09) และให้ปริ้นท์ได้
   🔴 ยังห้ามเปิด APPT Booking แบบแก้ได้เหมือนเดิม — CRUD ของฟอร์มนั้นยิงแค่ appt-recount
      ซึ่งไม่ใช่ด่าน · เซฟผ่านทางนั้น = ใบไม่มี booking_no · ไม่กันคิวซ้ำ · ไม่ push LINE
   🔴 ไม่มี DOCTOR_BOOKING ⇒ ตกกลับไปเปิดแบบ readonly ของเดิม ยังดูใบได้ ไม่ตัน */
s.aptOpen = (b) => {
  const form = field.getFormRef()
  globalThis.__apptCardClose = () => {
    try { form.subFormClose() } catch (e) { globalThis.console.log('[appt_box] ปิดกล่องไม่สำเร็จ', e) }
    s.aptReload()
  }
  if (!DOCTOR_BOOKING) {
    form.openForm(BOOKING_FORM, String(b._id), s.aptVid, null, {
      readonly: true,
      afterSaveCallback: () => { form.subFormClose(); s.aptReload() }
    })
    return
  }
  form.openForm(DOCTOR_BOOKING, null, s.aptVid, {
    mode: 'view', booking_no: b.booking_no,
    pid: s.aptPid, hn: s.aptHn, patient_name: s.aptName, from_visit: s.aptVid
  }, {
    afterSaveCallback: () => { form.subFormClose(); s.aptReload() }
  })
}

/* ＋ นัดหมาย — เปิดฟอร์มนัดของหมอ ซึ่งจองผ่าน appt-staff-book (ด่านครบ: กันคิวซ้ำ · โควตา · push LINE)
   arg3 = parentId · arg4 = formData — พิสูจน์ 01/09 ด้วย gen-openform-params.js
   🔴 ส่ง pid ไปด้วยเสมอ — ฟอร์มนัดจะได้ไม่ต้องค้นคนไข้เอง (ดูเหตุผลที่ s.aptPid)
   🔴 ไม่ผ่าน CRUD ⇒ afterSaveCallback ไม่ยิง · ฟอร์มนัดเรียก __apptCardReload() กลับมาเอง
      ที่ยังใส่ไว้เพราะไม่มีผลเสีย และเป็นตาข่ายถ้าวันหนึ่งฟอร์มเซฟผ่านแพลตฟอร์มจริง */
s.aptNew = () => {
  if (!s.aptVid) { field.alert('ยังไม่ได้เลือกคนไข้', 'warning'); return }
  if (!DOCTOR_BOOKING) {
    /* 🔴 ยังไม่ได้ import ฟอร์มนัด — บอกตรง ๆ ดีกว่าเปิดกล่องเปล่าให้งง
       และห้ามตกกลับไปเปิดจอ N แทน (นั่นคือของที่ถูกตีกลับ) */
    field.alert('ยังไม่ได้ติดตั้งฟอร์มนัดหมาย (APPT Doctor Booking) — แจ้งผู้พัฒนา', 'warning')
    return
  }
  const form = field.getFormRef()
  /* 🔴 แขวนตัวปิดไว้ให้จอลูกเรียกกลับ — `subFormClose()` เป็นเมธอดของ **ฝั่งที่เปิด**
     ไม่ใช่ของฟอร์มที่ถูกเปิด · จอลูกเรียก getFormRef().subFormClose() เองแล้วไม่มีอะไรเกิดขึ้น
     (พิสูจน์บนเครื่องจริง 02/09: จองผ่าน แต่ปุ่ม ปิด/ยกเลิก กดไม่ติด)
     ท่าเดียวกับ __apptCardReload ที่ใช้ได้อยู่แล้ว */
  globalThis.__apptCardClose = () => {
    try { form.subFormClose() } catch (e) { globalThis.console.log('[appt_box] ปิดกล่องไม่สำเร็จ', e) }
    s.aptReload()
  }
  form.openForm(DOCTOR_BOOKING, null, s.aptVid, {
    pid: s.aptPid, hn: s.aptHn, patient_name: s.aptName, phone: s.aptPhone,
    from_visit: s.aptVid, mode: 'followup'
  }, {
    afterSaveCallback: () => { form.subFormClose(); s.aptReload() }
  })
}

/* emr2-once-addon — EMR v2 (gen-emr-v2-model.cjs ต่อท้ายให้ · อย่าแก้ในบิลเดอร์) */
{
/* emr2-once — กันโหลดซ้ำตอนเปิดคนไข้ครั้งแรก (B1 · วัดจอจริง 2026-10-24: เปิดครั้งแรก 30 request · เปิดซ้ำ 15)
   ต้นเหตุ: ตอน mount ครั้งแรก widget ถูกสั่งโหลด 2 ทางพร้อมกัน
     ① opd_card.onMounted → setTran($examTran) → ไล่สั่งทุกการ์ด (ทาง "feed" · opd_card ติดธง form.$e2Feed ระหว่างไล่)
     ② onMounted ของ widget เอง อ่าน $examTran แล้วโหลดเอง
   ⇒ ห่อฟังก์ชันโหลด: อีกทางเพิ่งโหลด visit เดียวกันไม่เกิน E2_ONCE_MS = ข้าม
      ทางเดียวกันเรียกซ้ำ (กดโหลดใหม่ · หลังบันทึก · WS) ไม่ข้าม · เปลี่ยนคนไข้ (visit ต่าง) ไม่ข้าม
   gen-emr-v2-model.cjs ฝังไฟล์นี้ต่อท้าย onCreated ของแต่ละ widget (ในบล็อก { } ชื่อไม่ชนโค้ดเดิม) — แก้ที่ไฟล์นี้แล้ว gen ใหม่ */
const E2_ONCE_MS = 2000;
const e2OnceWrap = (widget, name, fnName, vidOf) => {
	const st = widget.vueState;
	const orig = st[fnName];
	if (typeof orig !== 'function' || orig.e2Once) return;
	const key = `${name}.${fnName}`;
	const wrapped = (...args) => {
		const form = widget.getFormRef && widget.getFormRef();
		const raw = vidOf(...args);
		const vid = raw ? String(raw) : '';
		if (form && vid) {
			const fromFeed = form.$e2Feed === true;
			const seen = form.$e2Loaded || (form.$e2Loaded = {});
			const last = seen[key];
			const now = Date.now();
			if (last && last.vid === vid && last.fromFeed !== fromFeed && now - last.at < E2_ONCE_MS) return undefined;
			seen[key] = { vid, fromFeed, at: now };
		}
		return orig(...args);
	};
	wrapped.e2Once = true;
	st[fnName] = wrapped;
};
e2OnceWrap(this, 'appt_box', 'aptLoad', (visitId) => visitId);
}
/* /emr2-once-addon */

