   ต้นเหตุ: ตอน mount ครั้งแรก widget ถูกสั่งโหลด 2 ทางพร้อมกัน
     ① opd_card.onMounted → setTran($examTran) → ไล่สั่งทุกการ์ด (ทาง "feed" · opd_card ติดธง form.$e2Feed ระหว่างไล่)
     ② onMounted ของ widget เอง อ่าน $examTran แล้วโหลดเอง
   ⇒ ห่อฟังก์ชันโหลด: อีกทางเพิ่งโหลด visit เดียวกันไม่เกิน E2_ONCE_MS = ข้าม
      ทางเดียวกันเรียกซ้ำ (กดโหลดใหม่ · หลังบันทึก · WS) ไม่ข้าม · เปลี่ยนคนไข้ (visit ต่าง) ไม่ข้าม
   gen-emr-v2-model.cjs ฝังไฟล์นี้ต่อท้าย onCreated ของแต่ละ widget (ในบล็อก { } ชื่อไม่ชนโค้ดเดิม) — แก้ที่ไฟล์นี้แล้ว gen ใหม่ */
const E2_ONCE_MS = 2000;
const e2OnceWrap = (widget, name, fnName, vidOf) => {
	const st = widget.vueState;
	const orig = st[fnName];
	if (typeof orig !== 'function' || orig.e2Once) return;
	const key = `${name}.${fnName}`;
	const wrapped = (...args) => {
		const form = widget.getFormRef && widget.getFormRef();
		const raw = vidOf(...args);
		const vid = raw ? String(raw) : '';
		if (form && vid) {
			const fromFeed = form.$e2Feed === true;
			const seen = form.$e2Loaded || (form.$e2Loaded = {});
			const last = seen[key];
			const now = Date.now();
			if (last && last.vid === vid && last.fromFeed !== fromFeed && now - last.at < E2_ONCE_MS) return undefined;
			seen[key] = { vid, fromFeed, at: now };
		}
		return orig(...args);
	};
	wrapped.e2Once = true;
	st[fnName] = wrapped;
};
e2OnceWrap(this, 'emr2_labs', 'e2lLoad', (visitId) => visitId);
}
if (vid0) s.e2lLoad(vid0);

