const CERT_APP = '6ac5b9c4481c196fbb32d445'; // แอป "ใบรับรองแพทย์" (การ์ด certificate_card — modules/medical-certificate)

// 🔴 ห้ามชื่อ btn/index — button-ui compile onClick ด้วยพารามิเตอร์ (btn, index) ประกาศซ้ำ = SyntaxError ทั้งปุ่ม
