const tran = form.$examTran;
// vid ของคิว: { value: ObjectId | string | { $oid } }
const idOf = (v) => {
	const x = v && typeof v === 'object' && 'value' in v ? v.value : v;
	if (x && typeof x === 'object') return String(x.$oid || x);
	return x ? String(x) : '';
};
