 */

// 🔴 ห้ามชื่อ btn/index — button-ui compile onClick ด้วยพารามิเตอร์ (btn, index) ประกาศซ้ำ = SyntaxError ทั้งปุ่ม
this.alert('Admit ยังไม่เปิดใช้งาน', 'info');

/**
 * ปุ่ม "ตรวจเสร็จ" — แถบปุ่มล่าง EMR v2 (button-ui `action_bar_btns` · gen-emr-v2-model.cjs ใส่ให้ · v1 ไม่แตะ)
 * ส่งใบร่างทุกใบที่ส่งได้ · ไม่ส่งคิว (ส่งต่อใช้ปุ่มอื่น) — logic เดิมของปุ่มนี้ + กติกาใหม่ (พี่สั่ง 2026-10-23):
 *   ① ยังไม่ลง ICD10 วินิจฉัยหลัก + Principal Diagnosis (+ วินิจฉัยของคลินิกนี้) = ไม่ให้ตรวจเสร็จ
 *   ② ใบยาติดคำเตือนห้ามสั่ง = บอกเหตุที่ติดให้ไปแก้เอง ไม่เปิดกล่องกรอกเหตุผลให้อัตโนมัติ
 * logic อยู่ frame/done.lib.js (generator ฝังแทน token)
 *
 * 🔴 ห้ามใช้ await — onClick เป็น sync handler
 */

// 🔴 ห้ามชื่อ btn/index — button-ui compile onClick ด้วยพารามิเตอร์ (btn, index) ประกาศซ้ำ = SyntaxError ทั้งปุ่ม
const self = this;
const form = this.getFormRef();
const api = form.userState;
const tran = form.$examTran;
if (!tran || !tran._id || !tran.vid || !tran.vid.value) {
	this.alert('ยังไม่ได้เลือกผู้ป่วย', 'warning');
	return;
}

/* ── emr2 done (frame/done.lib.js · gen-emr-v2-model.cjs ฝังลงปุ่ม "ตรวจเสร็จ" + "ตรวจเสร็จ + ส่งต่อ") ──
   ตรวจเสร็จ = ① ต้องลงวินิจฉัยครบก่อน ② ส่งใบร่างทุกใบที่ส่งได้ (พี่สั่ง 2026-10-23 · เลือก ⭐ A + B)
   ① วินิจฉัย — อ่าน emr2-soap-get (ตัวเดียวกับช่องกลาง · ฝั่ง server · สดตอนกด):
      ต้องมี ICD10 วินิจฉัยหลัก (primary_dx) + Principal Diagnosis (principal_dx) ของ visit
      และ **คลินิกนี้ต้องลงวินิจฉัยอย่างน้อย 1 แถว** (กลุ่ม mine) — ตอนนี้ 1 visit มีใบวินิจฉัยใบเดียว
      ICD10 หลักเป็นของคลินิกเจ้าของ คลินิกที่ 2 ลงเป็นแถวโรครองของตัวเอง (ใบละคลินิกจริง = C41)
   ② ส่งใบร่าง — ลอกจากปุ่ม "ตรวจเสร็จ" เดิม · ต่างตรงนี้ (พี่สั่ง ⭐ B):
      ใบยาติดคำเตือนห้ามสั่ง = **ไม่เปิดกล่องกรอกเหตุผลให้อัตโนมัติ** บอกเหตุที่ติดให้ไปแก้เอง
      (การ์ดใบสั่งยายังยืนยันส่งพร้อมเหตุผลได้เหมือนเดิม — ทางออกเวลาจำเป็น)
   ต้องมีตัวแปร self · form · api · tran ก่อนส่วนนี้ · 🔴 ห้ามใช้ await */
const DN_SOAP_PROC = '6ada1ba0abcbb06488ffb615'; // emr2-soap-get (อ่านอย่างเดียว)
const DN_LIST_PROC = '6a71fe5f29c75d41e9c7e9cb'; // cpoe-order-list
const DN_SEND_PROC = '6a757d1bf7bf7668d7673c63'; // cpoe-order-send (draft → sent)
const DN_DRUG_TYPE = 'med';

const dnVisitId = () => (tran && tran.vid && tran.vid.value ? String(tran.vid.value) : '');
const dnErr = (e) => String((e && e.message) || e);

/* ① วินิจฉัยครบไหม → next() เมื่อครบ · ไม่ครบ = เตือนแดงแล้วหยุด */
const emr2CheckDx = (next) => {
	api.runProcess(
		DN_SOAP_PROC,
		{ visit_id: dnVisitId() },
		(res) => {
			const d = (res && res.data) || {};
			if (!d.success) {
				self.alert('ตรวจการวินิจฉัยไม่สำเร็จ: ' + (d.message || 'ไม่ทราบสาเหตุ') + ' — ยังตรวจเสร็จไม่ได้', 'error');
				return;
			}
			const dx = d.dx || null;
			const groups = (dx && dx.groups) || [];
			const hasPrimary = groups.some((g) => (g.rows || []).some((r) => r.primary));
			const mine = groups.find((g) => g.mine);
			const missing = [];
			if (mine && mine.sheet) {
				// ใบวินิจฉัยละคลินิก (C41): ดูใบของคลินิกนี้อย่างเดียว · เจ้าของไข้ = โรคหลัก + Principal · รับปรึกษา = โรคอย่างน้อย 1 โรค
				const myPrimary = (mine.rows || []).some((r) => r.primary);
				if (mine.origin === 'รับปรึกษา') {
					if (!(mine.rows || []).length) missing.push('วินิจฉัยของคลินิกนี้ (ลงอย่างน้อย 1 โรค)');
				} else {
					if (!myPrimary) missing.push('ICD10 วินิจฉัยหลักของคลินิกนี้');
					if (!String(mine.principal || '').trim()) missing.push('Principal Diagnosis');
				}
			} else if (dx && dx.canAdd) {
				missing.push('ใบวินิจฉัยของคลินิกนี้');
			} else {
				// ใบเดิม 1 ใบ/visit
				if (!hasPrimary) missing.push('ICD10 วินิจฉัยหลัก');
				if (!dx || !String(dx.principal || '').trim()) missing.push('Principal Diagnosis');
				if (hasPrimary && (!mine || !(mine.rows || []).length)) missing.push('วินิจฉัยของคลินิกนี้ (ลงอย่างน้อย 1 โรค)');
			}
			if (missing.length) {
				self.alert('⛔ ยังตรวจเสร็จไม่ได้ — ยังไม่ได้ลง ' + missing.join(' · ') + ' — บันทึกที่ "วินิจฉัยโรค" ในช่องกลางก่อน', 'error');
				return;
			}
			next();
		},
		(err) => self.alert('ตรวจการวินิจฉัยไม่สำเร็จ: ' + dnErr(err) + ' — ยังตรวจเสร็จไม่ได้', 'error')
	);
};

/* อ่านใบของ visit → { mine: ใบร่างที่ฉันส่งได้, other: จำนวนใบร่างคลินิกอื่น, drafts: ใบร่างทั้งหมด } */
const emr2ListDrafts = (done) => {
	api.runProcess(
		DN_LIST_PROC,
		{ visit_id: dnVisitId() },
		(res) => {
			const d = (res && res.data) || {};
			if (!d.success) {
				self.alert(d.message || 'อ่านใบสั่งของวิสิทนี้ไม่สำเร็จ', 'warning');
				return;
			}
			const drafts = (Array.isArray(d.orders) ? d.orders : []).filter((o) => String(o.current_status || '') === 'draft');
			const mine = drafts.filter((o) => o.can_edit === true);
			done({ drafts, mine, other: drafts.length - mine.length });
		},
		(err) => self.alert('อ่านใบสั่งของวิสิทนี้ไม่สำเร็จ: ' + dnErr(err), 'warning')
	);
};

const dnKindOf = (o) => (String(o.service_type_code || '') === DN_DRUG_TYPE ? 'ใบสั่งยา' : 'ใบสั่งตรวจ');
const dnNoOf = (o) => o.order_number || dnKindOf(o);
// โหลดการ์ดใหม่ครั้งเดียวตอนจบ (ไม่เปิดกล่องเหตุผลให้แล้ว — ⭐ B)
const dnReloadCards = () => {
	const oc = form.getFieldRef('order_card');
	if (oc && oc.vueState && oc.vueState.ordReload) oc.vueState.ordReload();
	const ic = form.getFieldRef('item_card');
	if (ic && ic.vueState && ic.vueState.itmReload) ic.vueState.itmReload();
};

/* ② ส่งใบร่างทีละใบ → done(r) · r.ok = ทุกใบส่งผ่าน · r.text = สรุปพร้อมเหตุที่ติดทีละข้อ */
const emr2SendDrafts = (list, other, done) => {
	const r = { sent: [], blocked: [], dup: [], failed: [], other: other || 0 };
	const step = (i) => {
		if (i >= list.length) {
			dnReloadCards();
			const lines = [];
			if (r.sent.length) lines.push('ส่งใบแล้ว ' + r.sent.length + ' ใบ (' + r.sent.join(', ') + ')');
			r.blocked.forEach((b) => lines.push('⛔ ' + b.no + ' ติดคำเตือนห้ามสั่ง: ' + b.why.join(' · ') + ' — แก้ให้ครบแล้วส่งใหม่'));
			if (r.dup.length) lines.push('แลปซ้ำ ' + r.dup.length + ' ใบ (' + r.dup.join(', ') + ') — กด "ส่งใบสั่งตรวจ" ที่การ์ดเพื่อยืนยันส่งซ้ำ');
			if (r.failed.length) lines.push('ส่งไม่สำเร็จ ' + r.failed.length + ' ใบ: ' + r.failed.join(' · '));
			if (r.other) lines.push('ใบร่างของคลินิกอื่น ' + r.other + ' ใบไม่ได้ส่ง');
			r.ok = !r.blocked.length && !r.dup.length && !r.failed.length;
			r.text = lines.join(' · ');
			done(r);
			return;
		}
		const o = list[i];
		const no = dnNoOf(o);
		api.runProcess(
			DN_SEND_PROC,
			{ order_id: String(o.order_id) },
			(res) => {
				const d = (res && res.data) || {};
				if (d.success) r.sent.push(no);
				else if (d.code === 'HAS_BLOCK' || d.code === 'OVERRIDE_REASON_TOO_SHORT') {
					// เหตุที่ติดไม่ซ้ำ (หลายรายการยาติดกฎเดียวกัน = ข้อความเดียวกัน)
					const why = [];
					(d.blocks || []).forEach((b) => {
						const m = String((b && b.message) || '').trim();
						if (m && why.indexOf(m) < 0) why.push(m);
					});
					r.blocked.push({ no, why: why.length ? why : [d.message || 'ติดคำเตือนห้ามสั่ง'] });
				} else if (d.code === 'DUP_LAB') r.dup.push(no);
				else r.failed.push(no + ' — ' + (d.message || 'ส่งไม่สำเร็จ'));
				step(i + 1);
			},
			(err) => {
				r.failed.push(no + ' — ' + dnErr(err));
				step(i + 1);
			}
		);
	};
	step(0);
};
const dnConfirmText = (head, mine, other, tail) => {
	const med = mine.filter((o) => String(o.service_type_code || '') === DN_DRUG_TYPE).length;
	return head + ' จะส่งใบร่าง ' + mine.length + ' ใบ (ใบสั่งยา ' + med + ' · ใบสั่งตรวจ ' + (mine.length - med) + ')' +
		(other ? ' — ใบของคลินิกอื่น ' + other + ' ใบจะไม่ถูกส่ง' : '') + (tail || '');
};
/* ── /emr2 done ── */

emr2CheckDx(() =>
	emr2ListDrafts((ls) => {
		if (!ls.mine.length) {
			self.alert(ls.other ? 'ไม่มีใบร่างที่คุณส่งได้ — ใบร่าง ' + ls.other + ' ใบเป็นของคลินิกอื่น' : 'วินิจฉัยครบ · ไม่มีใบร่างที่ต้องส่ง', 'info');
			return;
		}
		self.confirm(
			dnConfirmText('ยืนยันตรวจเสร็จ?', ls.mine, ls.other),
			() => emr2SendDrafts(ls.mine, ls.other, (r) => self.alert(r.text || 'ไม่มีใบที่ต้องส่ง', r.ok ? 'success' : 'warning')),
			'success',
			'ตรวจเสร็จ'
		);
	})
);

/**
 * ปุ่ม "ย้ายห้อง" — action bar หน้า EMR (ฟอร์ม EMR 6a4f64e7f8cdfc54cec16488 · button-ui `action_bar_btns` ปุ่มที่ 2)
 *
 * เหมือนปุ่ม "ย้ายห้อง" ในเมนูคิว (sdform/queue-move-room/btn-row-move-room.onclick.js) ทุกอย่าง
 * ต่างแค่แหล่งคิว: เมนูคิวใช้ dataRow · ที่นี่ใช้คนไข้ที่เปิดอยู่ (form.$examTran — ปุ่ม EMR ของคิวเป็นคนเซ็ต)
 *
 * หลังปิด popup: อ่านคิวจาก DB ใหม่ — ย้ายสำเร็จ (ห้องเปลี่ยน) = คนไข้ออกจากห้องนี้แล้ว ⇒ ล้างหน้า EMR กลับแท็บ My Room
 *   กดปิด popup เฉย ๆ = ห้องไม่เปลี่ยน ⇒ อยู่หน้า EMR ต่อ (callback ของ popup ทั้งสองกรณีวิ่งทางเดียวกัน แยกไม่ได้จากตรงนั้น)
 *
 * 🔴 ห้ามใช้ await — onClick เป็น sync handler
 */

const MOVE_ROOM_FORM = '6a9524df422c1ca959829d9e'; // ฟอร์ม "ย้ายห้อง"
const TRAN_FORM = '6a461235e521219e514d1c4b'; // Visit Tran
const MY_ROOM_TAB = 'tab_pane_10728'; // แท็บ My Room ใน main_app

// 🔴 ห้ามชื่อ btn/index — button-ui compile onClick ด้วยพารามิเตอร์ (btn, index) ประกาศซ้ำ = SyntaxError ทั้งปุ่ม
const self = this;
const form = this.getFormRef();
const tran = form.$examTran;
if (!tran || !tran._id) {
	this.alert('ยังไม่ได้เลือกผู้ป่วย', 'warning');
	return;
}
if (!['waiting', 'called', 'in_progress', 'skipped'].includes(tran.vtran_status)) {
	this.alert('ย้ายห้องได้เฉพาะคิวที่ยังอยู่ในแผนก', 'warning');
	return;
}

const codeOf = (v) => String((v && v.value) || '');
const refreshQueues = () => {
	['visit_unit', 'visit_room'].forEach((n) => {
		const f = form.getFieldRef(n);
		if (f && f.getFieldEditor && f.getFieldEditor()) f.getFieldEditor().handleRefresh();
	});
};
// คนไข้ออกจากห้องแล้ว — ล้างการ์ดทั้งหน้า (setTran(null) ซ่อนโซน SOAP + ปลุกการ์ดลูกให้ล้างตาม) แล้วกลับคิวห้องตัวเอง
const leaveEmr = (msg) => {
	form.$examTran = null;
	const card = form.getFieldRef('opd_card');
	if (card && card.vueState && card.vueState.setTran) card.vueState.setTran(null);
	const tab = form.getFieldRef('main_app');
	if (tab) tab.activeTabName = MY_ROOM_TAB;
	if (msg) self.alert(msg, 'success');
};
// อ่านคิวสดจาก DB — snapshot ใน $examTran ไม่รู้ว่าเพิ่งถูกย้าย
const readTran = (done) => {
	form.userState.crudGetAll(
		{
			sdProvider: {
				providerId: TRAN_FORM,
				providerType: 'FORM',
				params: { id: String(tran._id) },
				options: { where: "`_id` = CONVERT(:id, 'objectId')", limit: 1, page: 1 },
			},
			totalEnable: false,
		},
		(res) => done((res && res.data && res.data[0]) || null)
	);
};

const unitCode = codeOf(tran.unit_to);
const curRoomCode = codeOf(tran.room_to);
const ctx = {
	tran_id: String(tran._id),
	// ห้องเก็บแผนกเป็น label "A103 คลินิกทันตกรรม" ที่ขึ้นต้นด้วย unit_code → prefix นี้คัดเหลือห้องในแผนกเดียวกัน
	unit_prefix: unitCode ? unitCode + '%' : '%',
	cur_room: curRoomCode || '~', // ไม่มีห้อง = '~' ไม่ตรงกับ code ไหน (ไม่ตัดอะไร)
	cur_room_label: (tran.room_to && tran.room_to.label) || '',
	queue_label: tran.queue_label || '',
};

form.openForm(MOVE_ROOM_FORM, '', '', ctx, {
	params: ctx,
	cancelCallback: () => {
		form.subFormClose();
		refreshQueues();
		readTran((row) => {
			if (!row) return; // อ่านไม่ได้ = ไม่เดา อยู่หน้าเดิม (คิวในแท็บคิว refresh แล้ว)
			if (codeOf(row.room_to) !== curRoomCode || row.vtran_status === 'done') {
				leaveEmr('ย้ายคิว ' + (row.queue_label || '') + ' ไป ' + ((row.room_to && row.room_to.label) || 'ห้องใหม่') + ' แล้ว');
			}
		});
	},
});

/**
 * ปุ่ม "ส่งต่อ (กำหนดเอง)" — แถบปุ่มล่าง EMR v2 (button-ui `action_bar_btns` · gen-emr-v2-model.cjs ใส่ให้)
 *   ต้นฉบับ = โค้ดสดบน DB ของ v2 (ยกมาจาก EMR v1 6a4f64e7…) ดึงลงไฟล์ 2026-10-23 · v1 ยังเป็นโค้ดเดิม
 *
 * เหมือนปุ่ม "ส่งต่อ" ในเมนูคิว (list-ui visit_unit/visit_room) ทุกอย่าง — popup Move Unit + เติมปลายทางให้ตามลำดับเดิม:
 *   consult (ต้นทาง → คลินิก consult / ปลายทางขอส่งกลับ → คลินิกต้นทาง) > visit_route (การเงิน/ห้องยา + เปิดคิวห้องยาคู่) > ไม่เติม
 * ต่างแค่แหล่งคิว: เมนูคิวใช้ dataRow · ที่นี่ใช้คนไข้ที่เปิดอยู่ (form.$examTran)
 *
 * หลังปิด popup: อ่านคิวจาก DB ใหม่ — ส่งต่อสำเร็จ (move-unit ปิดคิวเดิมเป็น done) ⇒ ล้างหน้า EMR กลับแท็บ My Room
 *   กดปิด popup เฉย ๆ = คิวยังเปิดอยู่ ⇒ อยู่หน้า EMR ต่อ
 *
 * 🔴 ห้ามใช้ await — onClick เป็น sync handler
 * 🔴 หา dest ไม่ได้/ล้ม = เปิดฟอร์มตามปกติ ห้ามบล็อก (ตัวช่วยกรอก ไม่ใช่ด่าน — หลักเดียวกับเมนูคิว)
 */

const MOVE_UNIT_FORM = '6a4f828d22f95f21b606d9a2'; // ฟอร์ม Move Unit
const ROUTE_PROC = '6a8c4732f851000f28e5022a'; // his-finance-bill-v2 · action visit_route (อ่านอย่างเดียว)
const TRAN_FORM = '6a461235e521219e514d1c4b'; // Visit Tran
const MY_ROOM_TAB = 'tab_pane_10728'; // แท็บ My Room ใน main_app

// 🔴 ห้ามชื่อ btn/index — button-ui compile onClick ด้วยพารามิเตอร์ (btn, index) ประกาศซ้ำ = SyntaxError ทั้งปุ่ม
const self = this;
const form = this.getFormRef();
const tran = form.$examTran;
if (!tran || !tran._id) {
	this.alert('ยังไม่ได้เลือกผู้ป่วย', 'warning');
	return;
}

const refreshQueues = () => {
	['visit_unit', 'visit_room'].forEach((n) => {
		const f = form.getFieldRef(n);
		if (f && f.getFieldEditor && f.getFieldEditor()) f.getFieldEditor().handleRefresh();
	});
};
const leaveEmr = (msg) => {
	form.$examTran = null;
	const card = form.getFieldRef('opd_card');
	if (card && card.vueState && card.vueState.setTran) card.vueState.setTran(null);
	const tab = form.getFieldRef('main_app');
	if (tab) tab.activeTabName = MY_ROOM_TAB;
	if (msg) self.alert(msg, 'success');
};
const readTran = (done) => {
	form.userState.crudGetAll(
		{
			sdProvider: {
				providerId: TRAN_FORM,
				providerType: 'FORM',
				params: { id: String(tran._id) },
				options: { where: "`_id` = CONVERT(:id, 'objectId')", limit: 1, page: 1 },
			},
			totalEnable: false,
		},
		(res) => done((res && res.data && res.data[0]) || null),
		() => done(null)
	);
};

// ตัดสินปลายทางจากคิวสดจาก DB — form.$examTran ตั้งครั้งเดียวตอนเปิดคนไข้ consult ที่สร้างทีหลังจึงไม่มี consult_info
//   ⇒ เคยตกไปทาง visit_route → การเงิน ทั้งที่ consult ต้องมาก่อน (พี่เจอ 2026-10-23 · VD001 consult ศัลยกรรม)
//   อ่านไม่ได้ = ใช้ค่าในจอต่อ (พฤติกรรมเดิม) · ทับลง tran ตัวเดียวกับ form.$examTran ให้จออัปเดตด้วย
const decide = () => {
	const ci = tran.consult_info || null;
	const curUnit = (tran.unit_to && tran.unit_to.value) || '';
	const ctx = {
		tran_id: String(tran._id),
		cur_unit: curUnit,
		visit_priority: tran.visit_priority || '10',
		tran_note: '',
		consult_id: '',
		open_drug_leg: false,
	};

	const openMove = () => {
		form.openForm(MOVE_UNIT_FORM, '', '', ctx, {
			params: ctx,
			cancelCallback: () => {
				form.subFormClose();
				refreshQueues();
				readTran((row) => {
					// move-unit ปิดคิวเดิมเป็น done เสมอเมื่อสำเร็จ — ตัวตัดสินว่า "ส่งไปแล้วจริง"
					if (row && row.vtran_status === 'done') leaveEmr('ส่งต่อคิว ' + (row.queue_label || '') + ' แล้ว');
				});
			},
		});
	};

	if (ci && ci.clinic && String(ci.clinic) !== String(curUnit)) {
		// ต้นทาง → ส่งไปคลินิก consult + stamp accept
		ctx.unit_to = { value: ci.clinic, label: ci.to_label || ci.clinic };
		ctx.tran_note = ci.reason || '';
		ctx.visit_priority = ci.priority || ctx.visit_priority;
		ctx.consult_id = ci.consult_id || '';
		openMove();
	} else if (ci && ci.reply && String(ci.clinic) === String(curUnit) && tran.unit_from && tran.unit_from.value) {
		// ปลายทาง + ขอส่งกลับ → prefill คลินิกต้นทาง (tran.unit_from — ไม่ใช่ consult_info)
		ctx.unit_to = { value: tran.unit_from.value, label: tran.unit_from.label || tran.unit_from.value };
		openMove();
	} else {
		// ไม่มี consult → ถามเส้นทางจากงานที่ค้าง (การเงิน / ห้องยา / เปิดคิวห้องยาคู่)
		form.userState.runProcess(
			ROUTE_PROC,
			{ action: 'visit_route', tran_id: ctx.tran_id },
			(res) => {
				const d = (res && res.data) || {};
				if (d.ok) {
					const u = d.patient_leg === 'finance' ? d.finance_unit : d.patient_leg === 'pharmacy' ? d.pharmacy_unit : null;
					if (u && u.value) ctx.unit_to = { value: u.value, label: u.label || u.value };
					const notes = [];
					if (d.reason) notes.push(d.reason);
					(d.warnings || []).forEach((w) => {
						if (w && w.message) notes.push('⚠️ ' + w.message);
					});
					ctx.route_note = notes.join(' · ');
					if (d.drug_leg && d.pharmacy_unit && d.pharmacy_unit.value) {
						ctx.open_drug_leg = true;
						ctx.visit_id = d.visit_id || '';
						ctx.drug_leg_unit = d.pharmacy_unit.value;
						ctx.drug_leg_label = d.pharmacy_unit.label || d.pharmacy_unit.value;
					}
				}
				openMove();
			},
			() => openMove()
		);
	}
};

readTran((row) => {
	if (row) Object.assign(tran, row);
	decide();
});

/**
 * ปุ่ม "ส่งต่ออัตโนมัติ" — แถบปุ่มล่าง EMR v2 (button-ui `action_bar_btns` · gen-emr-v2-model.cjs ใส่ให้)
 * เดิมคือ "ส่งต่อ ห้องยา" (ส่งห้องยาตาม serve_units เสมอ) → เปลี่ยนเป็นหาปลายทางเอง (พี่สั่ง 2026-10-23)
 *   consult → คลินิก consult · ใบยา → ห้องยา · ค้างชำระ → การเงิน · ไม่มีอะไร → หน้าห้องตรวจ
 * logic อยู่ frame/auto-forward.lib.js (generator ฝังแทน token ข้างล่าง · ใช้ร่วมกับปุ่ม "ตรวจเสร็จ + ส่งต่อ")
 * ยังมีใบร่างค้าง (ทุกคลินิก) = กล่องเตือนแดงแยกก่อน บอกเลขใบที่ยังไม่ได้ส่ง ต้องยืนยันถึงไปต่อ (พี่สั่ง 2026-10-23)
 *   ใบร่างไม่ถึงห้องยา/การเงิน และ visit_route ไม่นับ ⇒ ปลายทางอาจผิด
 *
 * 🔴 ห้ามใช้ await — onClick เป็น sync handler
 */

// 🔴 ห้ามชื่อ btn/index — button-ui compile onClick ด้วยพารามิเตอร์ (btn, index) ประกาศซ้ำ = SyntaxError ทั้งปุ่ม
const self = this;
const form = this.getFormRef();
const api = form.userState;
const tran = form.$examTran;
if (!tran || !tran._id) {
	this.alert('ยังไม่ได้เลือกผู้ป่วย', 'warning');
	return;
}

/* ── emr2 done (frame/done.lib.js · gen-emr-v2-model.cjs ฝังลงปุ่ม "ตรวจเสร็จ" + "ตรวจเสร็จ + ส่งต่อ") ──
   ตรวจเสร็จ = ① ต้องลงวินิจฉัยครบก่อน ② ส่งใบร่างทุกใบที่ส่งได้ (พี่สั่ง 2026-10-23 · เลือก ⭐ A + B)
   ① วินิจฉัย — อ่าน emr2-soap-get (ตัวเดียวกับช่องกลาง · ฝั่ง server · สดตอนกด):
      ต้องมี ICD10 วินิจฉัยหลัก (primary_dx) + Principal Diagnosis (principal_dx) ของ visit
      และ **คลินิกนี้ต้องลงวินิจฉัยอย่างน้อย 1 แถว** (กลุ่ม mine) — ตอนนี้ 1 visit มีใบวินิจฉัยใบเดียว
      ICD10 หลักเป็นของคลินิกเจ้าของ คลินิกที่ 2 ลงเป็นแถวโรครองของตัวเอง (ใบละคลินิกจริง = C41)
   ② ส่งใบร่าง — ลอกจากปุ่ม "ตรวจเสร็จ" เดิม · ต่างตรงนี้ (พี่สั่ง ⭐ B):
      ใบยาติดคำเตือนห้ามสั่ง = **ไม่เปิดกล่องกรอกเหตุผลให้อัตโนมัติ** บอกเหตุที่ติดให้ไปแก้เอง
      (การ์ดใบสั่งยายังยืนยันส่งพร้อมเหตุผลได้เหมือนเดิม — ทางออกเวลาจำเป็น)
   ต้องมีตัวแปร self · form · api · tran ก่อนส่วนนี้ · 🔴 ห้ามใช้ await */
const DN_SOAP_PROC = '6ada1ba0abcbb06488ffb615'; // emr2-soap-get (อ่านอย่างเดียว)
const DN_LIST_PROC = '6a71fe5f29c75d41e9c7e9cb'; // cpoe-order-list
const DN_SEND_PROC = '6a757d1bf7bf7668d7673c63'; // cpoe-order-send (draft → sent)
const DN_DRUG_TYPE = 'med';

const dnVisitId = () => (tran && tran.vid && tran.vid.value ? String(tran.vid.value) : '');
const dnErr = (e) => String((e && e.message) || e);

/* ① วินิจฉัยครบไหม → next() เมื่อครบ · ไม่ครบ = เตือนแดงแล้วหยุด */
const emr2CheckDx = (next) => {
	api.runProcess(
		DN_SOAP_PROC,
		{ visit_id: dnVisitId() },
		(res) => {
			const d = (res && res.data) || {};
			if (!d.success) {
				self.alert('ตรวจการวินิจฉัยไม่สำเร็จ: ' + (d.message || 'ไม่ทราบสาเหตุ') + ' — ยังตรวจเสร็จไม่ได้', 'error');
				return;
			}
			const dx = d.dx || null;
			const groups = (dx && dx.groups) || [];
			const hasPrimary = groups.some((g) => (g.rows || []).some((r) => r.primary));
			const mine = groups.find((g) => g.mine);
			const missing = [];
			if (mine && mine.sheet) {
				// ใบวินิจฉัยละคลินิก (C41): ดูใบของคลินิกนี้อย่างเดียว · เจ้าของไข้ = โรคหลัก + Principal · รับปรึกษา = โรคอย่างน้อย 1 โรค
				const myPrimary = (mine.rows || []).some((r) => r.primary);
				if (mine.origin === 'รับปรึกษา') {
					if (!(mine.rows || []).length) missing.push('วินิจฉัยของคลินิกนี้ (ลงอย่างน้อย 1 โรค)');
				} else {
					if (!myPrimary) missing.push('ICD10 วินิจฉัยหลักของคลินิกนี้');
					if (!String(mine.principal || '').trim()) missing.push('Principal Diagnosis');
				}
			} else if (dx && dx.canAdd) {
				missing.push('ใบวินิจฉัยของคลินิกนี้');
			} else {
				// ใบเดิม 1 ใบ/visit
				if (!hasPrimary) missing.push('ICD10 วินิจฉัยหลัก');
				if (!dx || !String(dx.principal || '').trim()) missing.push('Principal Diagnosis');
				if (hasPrimary && (!mine || !(mine.rows || []).length)) missing.push('วินิจฉัยของคลินิกนี้ (ลงอย่างน้อย 1 โรค)');
			}
			if (missing.length) {
				self.alert('⛔ ยังตรวจเสร็จไม่ได้ — ยังไม่ได้ลง ' + missing.join(' · ') + ' — บันทึกที่ "วินิจฉัยโรค" ในช่องกลางก่อน', 'error');
				return;
			}
			next();
		},
		(err) => self.alert('ตรวจการวินิจฉัยไม่สำเร็จ: ' + dnErr(err) + ' — ยังตรวจเสร็จไม่ได้', 'error')
	);
};

/* อ่านใบของ visit → { mine: ใบร่างที่ฉันส่งได้, other: จำนวนใบร่างคลินิกอื่น, drafts: ใบร่างทั้งหมด } */
const emr2ListDrafts = (done) => {
	api.runProcess(
		DN_LIST_PROC,
		{ visit_id: dnVisitId() },
		(res) => {
			const d = (res && res.data) || {};
			if (!d.success) {
				self.alert(d.message || 'อ่านใบสั่งของวิสิทนี้ไม่สำเร็จ', 'warning');
				return;
			}
			const drafts = (Array.isArray(d.orders) ? d.orders : []).filter((o) => String(o.current_status || '') === 'draft');
			const mine = drafts.filter((o) => o.can_edit === true);
			done({ drafts, mine, other: drafts.length - mine.length });
		},
		(err) => self.alert('อ่านใบสั่งของวิสิทนี้ไม่สำเร็จ: ' + dnErr(err), 'warning')
	);
};

const dnKindOf = (o) => (String(o.service_type_code || '') === DN_DRUG_TYPE ? 'ใบสั่งยา' : 'ใบสั่งตรวจ');
const dnNoOf = (o) => o.order_number || dnKindOf(o);
// โหลดการ์ดใหม่ครั้งเดียวตอนจบ (ไม่เปิดกล่องเหตุผลให้แล้ว — ⭐ B)
const dnReloadCards = () => {
	const oc = form.getFieldRef('order_card');
	if (oc && oc.vueState && oc.vueState.ordReload) oc.vueState.ordReload();
	const ic = form.getFieldRef('item_card');
	if (ic && ic.vueState && ic.vueState.itmReload) ic.vueState.itmReload();
};

/* ② ส่งใบร่างทีละใบ → done(r) · r.ok = ทุกใบส่งผ่าน · r.text = สรุปพร้อมเหตุที่ติดทีละข้อ */
const emr2SendDrafts = (list, other, done) => {
	const r = { sent: [], blocked: [], dup: [], failed: [], other: other || 0 };
	const step = (i) => {
		if (i >= list.length) {
			dnReloadCards();
			const lines = [];
			if (r.sent.length) lines.push('ส่งใบแล้ว ' + r.sent.length + ' ใบ (' + r.sent.join(', ') + ')');
			r.blocked.forEach((b) => lines.push('⛔ ' + b.no + ' ติดคำเตือนห้ามสั่ง: ' + b.why.join(' · ') + ' — แก้ให้ครบแล้วส่งใหม่'));
			if (r.dup.length) lines.push('แลปซ้ำ ' + r.dup.length + ' ใบ (' + r.dup.join(', ') + ') — กด "ส่งใบสั่งตรวจ" ที่การ์ดเพื่อยืนยันส่งซ้ำ');
			if (r.failed.length) lines.push('ส่งไม่สำเร็จ ' + r.failed.length + ' ใบ: ' + r.failed.join(' · '));
			if (r.other) lines.push('ใบร่างของคลินิกอื่น ' + r.other + ' ใบไม่ได้ส่ง');
			r.ok = !r.blocked.length && !r.dup.length && !r.failed.length;
			r.text = lines.join(' · ');
			done(r);
			return;
		}
		const o = list[i];
		const no = dnNoOf(o);
		api.runProcess(
			DN_SEND_PROC,
			{ order_id: String(o.order_id) },
			(res) => {
				const d = (res && res.data) || {};
				if (d.success) r.sent.push(no);
				else if (d.code === 'HAS_BLOCK' || d.code === 'OVERRIDE_REASON_TOO_SHORT') {
					// เหตุที่ติดไม่ซ้ำ (หลายรายการยาติดกฎเดียวกัน = ข้อความเดียวกัน)
					const why = [];
					(d.blocks || []).forEach((b) => {
						const m = String((b && b.message) || '').trim();
						if (m && why.indexOf(m) < 0) why.push(m);
					});
					r.blocked.push({ no, why: why.length ? why : [d.message || 'ติดคำเตือนห้ามสั่ง'] });
				} else if (d.code === 'DUP_LAB') r.dup.push(no);
				else r.failed.push(no + ' — ' + (d.message || 'ส่งไม่สำเร็จ'));
				step(i + 1);
			},
			(err) => {
				r.failed.push(no + ' — ' + dnErr(err));
				step(i + 1);
			}
		);
	};
	step(0);
};
const dnConfirmText = (head, mine, other, tail) => {
	const med = mine.filter((o) => String(o.service_type_code || '') === DN_DRUG_TYPE).length;
	return head + ' จะส่งใบร่าง ' + mine.length + ' ใบ (ใบสั่งยา ' + med + ' · ใบสั่งตรวจ ' + (mine.length - med) + ')' +
		(other ? ' — ใบของคลินิกอื่น ' + other + ' ใบจะไม่ถูกส่ง' : '') + (tail || '');
};
/* ── /emr2 done ── */

/* ── emr2 auto-forward (frame/auto-forward.lib.js · gen-emr-v2-model.cjs ฝังลงปุ่ม "ส่งต่ออัตโนมัติ" + "ตรวจเสร็จ + ส่งต่อ") ──
   ส่งคิวคนไข้ไปที่ถัดไปเอง (พี่เคาะ 2026-10-23 · เลือกตาม ⭐ ทั้ง 5 ข้อ):
     1. มี consult (ต้นทาง) → คลินิก consult · ปลายทางขอส่งกลับ → คลินิกต้นทาง (ลำดับเดียวกับ "ส่งต่อ (กำหนดเอง)")
     2. ไม่มี consult → visit_route (his-finance-bill-v2 · E132 กติกาเส้นทางที่เดียวของระบบ):
          pharmacy → ห้องยา · finance → การเงิน (+ เปิดคิวห้องยาคู่เมื่อ drug_leg) · none → หน้าห้องตรวจ
     3. หน้าห้องตรวจ = skip-recall to_center (ล้างห้อง/หมอ · เลขคิวเดิม) แทน move-unit (ไม่เปิดคิวใหม่)
   ทุกทางยืนยันก่อน ("ส่งไป X เพราะ Y") · เขียนหมายเหตุลงคิว (tran_note) ให้ห้องที่รับงานต่ออ่านได้ (พี่สั่ง 2026-10-23)
   หาปลายทางไม่ได้ = บอกเหตุ + ให้ใช้ "ส่งต่อ (กำหนดเอง)" · ห้ามเดาห้อง (ส่งผิดห้องอันตรายกว่า)
   ต้องมีตัวแปร self · form · api · tran ก่อนส่วนนี้ (ประกาศในไฟล์ปุ่ม) · 🔴 ห้ามใช้ await (onClick เป็น sync handler) */
const AF_ROUTE_PROC = '6a8c4732f851000f28e5022a'; // his-finance-bill-v2 · action visit_route (อ่านอย่างเดียว)
const AF_MOVE_UNIT = '6a4b9464ac48023662b1b42c'; // move-unit — ปิดคิวนี้ เปิดคิวใหม่ที่ปลายทาง
const AF_CHECKIN = '6a4b6f8fac48023662b1b41e'; // checkin — เปิดคิวห้องยาคู่ (กันคิวซ้ำเอง)
const AF_SKIP_RECALL = '6a4b9451ac48023662b1b42b'; // skip-recall — action to_center
const AF_TRAN_UPDATE = '6a50cc20e97c6d6bbf111ce0'; // tran-update — เขียน tran_note (whitelist)
const AF_MY_ROOM_TAB = 'tab_pane_10728'; // แท็บ My Room ใน main_app
const AF_TRAN_FORM = '6a461235e521219e514d1c4b'; // Visit Tran — อ่านคิวสดก่อนตัดสินปลายทาง

const afRefreshQueues = () => {
	['visit_unit', 'visit_room'].forEach((n) => {
		const f = form.getFieldRef(n);
		if (f && f.getFieldEditor && f.getFieldEditor()) f.getFieldEditor().handleRefresh();
	});
};
// คนไข้ออกจากห้องแล้ว — ล้างการ์ดทั้งหน้า กลับคิวห้องตัวเอง (ท่าเดียวกับปุ่มส่งต่อเดิม)
const afLeaveEmr = (msg, type) => {
	form.$examTran = null;
	const card = form.getFieldRef('opd_card');
	if (card && card.vueState && card.vueState.setTran) card.vueState.setTran(null);
	const tab = form.getFieldRef('main_app');
	if (tab) tab.activeTabName = AF_MY_ROOM_TAB;
	if (msg) self.alert(msg, type || 'success');
};
const afErr = (e) => String((e && e.message) || e);
const afNow = () => {
	const d = new Date();
	const p = (n) => String(n).padStart(2, '0');
	return p(d.getHours()) + ':' + p(d.getMinutes());
};
const afUnitLabel = (u) => (u && (u.label || u.value)) || '';

// หมายเหตุส่งต่อ — ห้องที่รับงานต่ออ่านบนคิว: มาจากไหน · เพราะอะไร · คำเตือนที่ระบบเจอ
const afNote = (why, warns) => {
	const from = afUnitLabel(tran.unit_to) || 'ห้องตรวจ';
	const parts = ['ส่งต่ออัตโนมัติจาก ' + from + ' ' + afNow(), why].concat(warns || []).filter(Boolean);
	return parts.join(' · ');
};

/* ── หาปลายทาง → plan { kind: 'move'|'center', unit, why, warns, consultId, priority, drugLeg } ── */
const afPlan = (done) => {
	const ci = tran.consult_info || null;
	const curUnit = String((tran.unit_to && tran.unit_to.value) || '');
	if (ci && ci.clinic && String(ci.clinic) !== curUnit) {
		done({
			kind: 'move',
			unit: { value: ci.clinic, label: ci.to_label || ci.clinic },
			why: 'Consult' + (ci.reason ? ': ' + ci.reason : ''),
			warns: [],
			consultId: ci.consult_id || '',
			priority: ci.priority || '',
		});
		return;
	}
	if (ci && ci.reply && String(ci.clinic) === curUnit && tran.unit_from && tran.unit_from.value) {
		done({
			kind: 'move',
			unit: { value: tran.unit_from.value, label: tran.unit_from.label || tran.unit_from.value },
			why: 'ตอบ consult แล้ว ส่งกลับคลินิกต้นทาง',
			warns: [],
			consultId: '',
		});
		return;
	}
	api.runProcess(
		AF_ROUTE_PROC,
		{ action: 'visit_route', tran_id: String(tran._id) },
		(res) => {
			const d = (res && res.data) || {};
			if (!d.ok) {
				done(null, (d.message || 'หาเส้นทางไม่ได้') + ' — ใช้ปุ่ม "ส่งต่อ (กำหนดเอง)" แทน');
				return;
			}
			const warns = (d.warnings || []).map((w) => w && w.message).filter(Boolean);
			if (d.patient_leg === 'none') {
				done({ kind: 'center', why: 'ตรวจเสร็จ ไม่มีใบยาและไม่มีรายการค้างชำระ — คืนหน้าห้องตรวจ', warns });
				return;
			}
			const unit = d.patient_leg === 'finance' ? d.finance_unit : d.patient_leg === 'pharmacy' ? d.pharmacy_unit : null;
			if (!unit || !unit.value) {
				done(null, 'หา' + (d.patient_leg === 'finance' ? 'ห้องการเงิน' : 'ห้องยา') + 'ไม่ได้' + (warns.length ? ' (' + warns.join(' · ') + ')' : '') + ' — ใช้ปุ่ม "ส่งต่อ (กำหนดเอง)" แทน');
				return;
			}
			const drugLeg = d.drug_leg && d.pharmacy_unit && d.pharmacy_unit.value && d.pharmacy_unit.value !== unit.value
				? { unit: d.pharmacy_unit, visitId: d.visit_id || '' }
				: null;
			done({ kind: 'move', unit: { value: unit.value, label: unit.label || unit.value }, why: d.reason || '', warns, consultId: '', drugLeg });
		},
		(err) => done(null, 'หาเส้นทางไม่สำเร็จ: ' + afErr(err) + ' — ใช้ปุ่ม "ส่งต่อ (กำหนดเอง)" แทน')
	);
};

/* ── ทำตาม plan ── */
const afMove = (plan, note, prefix) => {
	const tranId = String(tran._id);
	api.runProcess(
		AF_MOVE_UNIT,
		{
			tran_id: tranId,
			unit_to: plan.unit,
			unit_room: null, // ไม่ล็อกช่อง — ปลายทางเรียกคิวเอง
			doctor_to: null,
			tran_note: note,
			visit_priority: plan.priority || tran.visit_priority || '10',
			consult_id: plan.consultId || '',
		},
		(res) => {
			const m = (res && res.data) || {};
			afRefreshQueues();
			if (!m.success) {
				self.alert(prefix + (m.message || 'ส่งต่อไม่สำเร็จ'), 'warning');
				return;
			}
			const sent = prefix + 'ส่งคิว ' + (m.queue_label || tran.queue_label || '') + ' ไป ' + afUnitLabel(plan.unit) + ' แล้ว';
			if (!plan.drugLeg || !plan.drugLeg.visitId) {
				afLeaveEmr(sent);
				return;
			}
			// ขายา: ห้องยาจัดยาระหว่างคนไข้ไปชำระ (ท่าเดียวกับปุ่ม "ส่งตัว" ของ Move Unit · E132 A6)
			const drugLabel = afUnitLabel(plan.drugLeg.unit);
			api.runProcess(
				AF_CHECKIN,
				{
					visit_id: plan.drugLeg.visitId,
					unit_to: plan.drugLeg.unit.value,
					unit_from: tran.unit_to && tran.unit_to.value ? { value: tran.unit_to.value, label: afUnitLabel(tran.unit_to) } : null,
					visit_priority: tran.visit_priority || null,
					tran_note: 'ขายา (คู่กับคิว ' + (m.queue_label || '') + ') · ' + note,
				},
				(r2) => {
					const d2 = (r2 && r2.data) || {};
					if (!d2.success) {
						afLeaveEmr(sent + ' · ⚠️ เปิดคิวห้องยา (' + drugLabel + ') ไม่สำเร็จ: ' + (d2.message || 'ไม่ทราบสาเหตุ') + ' — ส่งคิวห้องยาเองจากเมนูคิว', 'warning');
						return;
					}
					afLeaveEmr(sent + ' · ห้องยา ' + drugLabel + ' ' + (d2.duplicated ? 'มีคิวอยู่แล้ว ' : 'คิว ') + (d2.queue_label || ''));
				},
				(e2) => afLeaveEmr(sent + ' · ⚠️ เปิดคิวห้องยา (' + drugLabel + ') ไม่สำเร็จ: ' + afErr(e2) + ' — ส่งคิวห้องยาเองจากเมนูคิว', 'warning')
			);
		},
		(err) => self.alert(prefix + 'ส่งต่อไม่สำเร็จ: ' + afErr(err), 'warning')
	);
};

// หน้าห้องตรวจ: คิวเดิม (ไม่เปิดใหม่) ⇒ หมายเหตุใหม่ต่อหน้าหมายเหตุเดิมของคิว ไม่ทับทิ้ง
const afCenter = (note, prefix) => {
	const tranId = String(tran._id);
	const old = String(tran.tran_note || '').trim();
	api.runProcess(
		AF_SKIP_RECALL,
		{ tran_id: tranId, action: 'to_center' },
		(res) => {
			const d = (res && res.data) || {};
			if (!d.success) {
				afRefreshQueues();
				self.alert(prefix + (d.message || 'คืนหน้าห้องตรวจไม่สำเร็จ'), 'warning');
				return;
			}
			const q = d.queue_label || tran.queue_label || '';
			const done = (extra) => {
				afRefreshQueues();
				afLeaveEmr(prefix + 'คืนคิว ' + q + ' กลับหน้าห้องตรวจแล้ว' + (extra || ''), extra ? 'warning' : 'success');
			};
			api.runProcess(
				AF_TRAN_UPDATE,
				{ tran_id: tranId, set: { tran_note: old && old !== note ? note + ' | ' + old : note } },
				(r2) => done(r2 && r2.data && r2.data.success ? '' : ' · ⚠️ เขียนหมายเหตุลงคิวไม่สำเร็จ'),
				() => done(' · ⚠️ เขียนหมายเหตุลงคิวไม่สำเร็จ')
			);
		},
		(err) => self.alert(prefix + 'คืนหน้าห้องตรวจไม่สำเร็จ: ' + afErr(err), 'warning')
	);
};

/* ── ทางเข้า: หาปลายทาง → ยืนยัน → ส่ง · prefix = ข้อความนำของผลขั้นก่อนหน้า (เช่น "ส่งใบร่างแล้ว 2 ใบ · ")
   noteWarn = คำเตือนที่ต้องไปถึงห้องปลายทางด้วย (เช่น ใบร่างค้าง) — ต่อท้ายหมายเหตุบนคิว ── */
/* คิวสดจาก DB ทับลง tran (= form.$examTran ตัวเดียวกัน) ก่อนตัดสิน
   🔴 form.$examTran ตั้งครั้งเดียวตอนเปิดคนไข้ — consult ที่สร้างทีหลัง (จอนี้หรือจออื่น) ไม่มี consult_info
      ⇒ ตกไปทาง visit_route → การเงิน ทั้งที่ consult ต้องมาก่อน (พี่เจอ 2026-10-23 · VD001 consult ศัลยกรรม)
   อ่านไม่ได้ = ใช้ค่าในจอต่อ (พฤติกรรมเดิม) ไม่บล็อกการส่งต่อ */
const afFresh = (done) => {
	api.crudGetAll(
		{
			sdProvider: {
				providerId: AF_TRAN_FORM,
				providerType: 'FORM',
				params: { id: String(tran._id) },
				options: { where: "`_id` = CONVERT(:id, 'objectId')", limit: 1, page: 1 },
			},
			totalEnable: false,
		},
		(res) => {
			const row = (res && res.data && res.data[0]) || null;
			if (row) Object.assign(tran, row);
			done();
		},
		() => done()
	);
};

const emr2AutoForward = (prefix, noteWarn) => {
	const pre = prefix || '';
	afFresh(() => afPlan((plan, errMsg) => {
		if (!plan) {
			self.alert(pre + errMsg, 'warning');
			return;
		}
		const curUnit = String((tran.unit_to && tran.unit_to.value) || '');
		if (plan.kind === 'move' && String(plan.unit.value) === curUnit) {
			self.alert(pre + 'คิวนี้อยู่ที่ ' + afUnitLabel(plan.unit) + ' อยู่แล้ว', 'info');
			return;
		}
		const note = afNote(plan.why, plan.warns.concat(noteWarn ? [noteWarn] : []));
		const where = plan.kind === 'center' ? 'หน้าห้องตรวจ (คิวเดิม ' + (tran.queue_label || '') + ')' : afUnitLabel(plan.unit);
		const msg =
			pre + 'ส่งคิว ' + (tran.queue_label || '') + ' ไป ' + where + '?' +
			(plan.why ? ' — ' + plan.why : '') +
			(plan.drugLeg ? ' · เปิดคิวห้องยาคู่ ' + afUnitLabel(plan.drugLeg.unit) : '') +
			(plan.warns.length ? ' · ⚠️ ' + plan.warns.join(' · ') : '');
		self.confirm(msg, () => (plan.kind === 'center' ? afCenter(note, pre) : afMove(plan, note, pre)), 'info', 'ส่งต่ออัตโนมัติ');
	}));
};
/* ── /emr2 auto-forward ── */

emr2ListDrafts((ls) => {
	if (!ls.drafts.length) {
		emr2AutoForward('');
		return;
	}
	const nos = ls.drafts.map(dnNoOf).join(', ');
	self.confirm(
		'⛔ ยังมีใบร่างที่ยังไม่ได้ส่ง ' + ls.drafts.length + ' ใบ: ' + nos +
			' — ใบเหล่านี้จะไม่ถึงห้องยา/การเงิน และปลายทางที่ระบบหาให้อาจผิด · ถ้าตรวจเสร็จแล้วให้ใช้ "ตรวจเสร็จ + ส่งต่อ" · ยืนยันส่งต่อทั้งที่ใบยังไม่ส่ง?',
		() => emr2AutoForward('ใบร่างค้าง ' + ls.drafts.length + ' ใบ (' + nos + ') · ', '⚠️ ใบร่างยังไม่ส่ง ' + nos),
		'error',
		'ยังมีใบร่างไม่ได้ส่ง'
	);
});

/**
 * ปุ่ม "ตรวจเสร็จ + ส่งต่อ" — แถบปุ่มล่าง EMR v2 (button-ui `action_bar_btns` ปุ่มขวาสุด · gen-emr-v2-model.cjs ใส่ให้)
 * = "ตรวจเสร็จ" แล้วต่อด้วย "ส่งต่ออัตโนมัติ" (พี่สั่ง 2026-10-23)
 *   ① วินิจฉัยไม่ครบ = ⛔ หยุด (ตรวจเสร็จไม่ได้ ก็ไม่ส่งต่อ)
 *   ② ส่งใบร่าง — ใบไหนส่งไม่ผ่าน (ห้ามสั่ง/แลปซ้ำ/ล้ม) = ⛔ หยุดทันที ไม่ส่งต่อ (คนไข้ห้ามไปห้องยาก่อนใบถึง)
 *   ③ ผ่านหมด → ส่งต่ออัตโนมัติ (visit_route นับใบที่ "ส่งแล้ว" — ใบร่างไม่นับ จึงต้องส่งใบก่อน)
 * logic อยู่ frame/done.lib.js + frame/auto-forward.lib.js (generator ฝังแทน token)
 *
 * 🔴 ห้ามใช้ await — onClick เป็น sync handler
 */

// 🔴 ห้ามชื่อ btn/index — button-ui compile onClick ด้วยพารามิเตอร์ (btn, index) ประกาศซ้ำ = SyntaxError ทั้งปุ่ม
const self = this;
const form = this.getFormRef();
const api = form.userState;
const tran = form.$examTran;
if (!tran || !tran._id || !tran.vid || !tran.vid.value) {
	this.alert('ยังไม่ได้เลือกผู้ป่วย', 'warning');
	return;
}

/* ── emr2 done (frame/done.lib.js · gen-emr-v2-model.cjs ฝังลงปุ่ม "ตรวจเสร็จ" + "ตรวจเสร็จ + ส่งต่อ") ──
   ตรวจเสร็จ = ① ต้องลงวินิจฉัยครบก่อน ② ส่งใบร่างทุกใบที่ส่งได้ (พี่สั่ง 2026-10-23 · เลือก ⭐ A + B)
   ① วินิจฉัย — อ่าน emr2-soap-get (ตัวเดียวกับช่องกลาง · ฝั่ง server · สดตอนกด):
      ต้องมี ICD10 วินิจฉัยหลัก (primary_dx) + Principal Diagnosis (principal_dx) ของ visit
      และ **คลินิกนี้ต้องลงวินิจฉัยอย่างน้อย 1 แถว** (กลุ่ม mine) — ตอนนี้ 1 visit มีใบวินิจฉัยใบเดียว
      ICD10 หลักเป็นของคลินิกเจ้าของ คลินิกที่ 2 ลงเป็นแถวโรครองของตัวเอง (ใบละคลินิกจริง = C41)
   ② ส่งใบร่าง — ลอกจากปุ่ม "ตรวจเสร็จ" เดิม · ต่างตรงนี้ (พี่สั่ง ⭐ B):
      ใบยาติดคำเตือนห้ามสั่ง = **ไม่เปิดกล่องกรอกเหตุผลให้อัตโนมัติ** บอกเหตุที่ติดให้ไปแก้เอง
      (การ์ดใบสั่งยายังยืนยันส่งพร้อมเหตุผลได้เหมือนเดิม — ทางออกเวลาจำเป็น)
   ต้องมีตัวแปร self · form · api · tran ก่อนส่วนนี้ · 🔴 ห้ามใช้ await */
const DN_SOAP_PROC = '6ada1ba0abcbb06488ffb615'; // emr2-soap-get (อ่านอย่างเดียว)
const DN_LIST_PROC = '6a71fe5f29c75d41e9c7e9cb'; // cpoe-order-list
const DN_SEND_PROC = '6a757d1bf7bf7668d7673c63'; // cpoe-order-send (draft → sent)
const DN_DRUG_TYPE = 'med';

const dnVisitId = () => (tran && tran.vid && tran.vid.value ? String(tran.vid.value) : '');
const dnErr = (e) => String((e && e.message) || e);

/* ① วินิจฉัยครบไหม → next() เมื่อครบ · ไม่ครบ = เตือนแดงแล้วหยุด */
const emr2CheckDx = (next) => {
	api.runProcess(
		DN_SOAP_PROC,
		{ visit_id: dnVisitId() },
		(res) => {
			const d = (res && res.data) || {};
			if (!d.success) {
				self.alert('ตรวจการวินิจฉัยไม่สำเร็จ: ' + (d.message || 'ไม่ทราบสาเหตุ') + ' — ยังตรวจเสร็จไม่ได้', 'error');
				return;
			}
			const dx = d.dx || null;
			const groups = (dx && dx.groups) || [];
			const hasPrimary = groups.some((g) => (g.rows || []).some((r) => r.primary));
			const mine = groups.find((g) => g.mine);
			const missing = [];
			if (mine && mine.sheet) {
				// ใบวินิจฉัยละคลินิก (C41): ดูใบของคลินิกนี้อย่างเดียว · เจ้าของไข้ = โรคหลัก + Principal · รับปรึกษา = โรคอย่างน้อย 1 โรค
				const myPrimary = (mine.rows || []).some((r) => r.primary);
				if (mine.origin === 'รับปรึกษา') {
					if (!(mine.rows || []).length) missing.push('วินิจฉัยของคลินิกนี้ (ลงอย่างน้อย 1 โรค)');
				} else {
					if (!myPrimary) missing.push('ICD10 วินิจฉัยหลักของคลินิกนี้');
					if (!String(mine.principal || '').trim()) missing.push('Principal Diagnosis');
				}
			} else if (dx && dx.canAdd) {
				missing.push('ใบวินิจฉัยของคลินิกนี้');
			} else {
				// ใบเดิม 1 ใบ/visit
				if (!hasPrimary) missing.push('ICD10 วินิจฉัยหลัก');
				if (!dx || !String(dx.principal || '').trim()) missing.push('Principal Diagnosis');
				if (hasPrimary && (!mine || !(mine.rows || []).length)) missing.push('วินิจฉัยของคลินิกนี้ (ลงอย่างน้อย 1 โรค)');
			}
			if (missing.length) {
				self.alert('⛔ ยังตรวจเสร็จไม่ได้ — ยังไม่ได้ลง ' + missing.join(' · ') + ' — บันทึกที่ "วินิจฉัยโรค" ในช่องกลางก่อน', 'error');
				return;
			}
			next();
		},
		(err) => self.alert('ตรวจการวินิจฉัยไม่สำเร็จ: ' + dnErr(err) + ' — ยังตรวจเสร็จไม่ได้', 'error')
	);
};

/* อ่านใบของ visit → { mine: ใบร่างที่ฉันส่งได้, other: จำนวนใบร่างคลินิกอื่น, drafts: ใบร่างทั้งหมด } */
const emr2ListDrafts = (done) => {
	api.runProcess(
		DN_LIST_PROC,
		{ visit_id: dnVisitId() },
		(res) => {
			const d = (res && res.data) || {};
			if (!d.success) {
				self.alert(d.message || 'อ่านใบสั่งของวิสิทนี้ไม่สำเร็จ', 'warning');
				return;
			}
			const drafts = (Array.isArray(d.orders) ? d.orders : []).filter((o) => String(o.current_status || '') === 'draft');
			const mine = drafts.filter((o) => o.can_edit === true);
			done({ drafts, mine, other: drafts.length - mine.length });
		},
		(err) => self.alert('อ่านใบสั่งของวิสิทนี้ไม่สำเร็จ: ' + dnErr(err), 'warning')
	);
};

const dnKindOf = (o) => (String(o.service_type_code || '') === DN_DRUG_TYPE ? 'ใบสั่งยา' : 'ใบสั่งตรวจ');
const dnNoOf = (o) => o.order_number || dnKindOf(o);
// โหลดการ์ดใหม่ครั้งเดียวตอนจบ (ไม่เปิดกล่องเหตุผลให้แล้ว — ⭐ B)
const dnReloadCards = () => {
	const oc = form.getFieldRef('order_card');
	if (oc && oc.vueState && oc.vueState.ordReload) oc.vueState.ordReload();
	const ic = form.getFieldRef('item_card');
	if (ic && ic.vueState && ic.vueState.itmReload) ic.vueState.itmReload();
};

/* ② ส่งใบร่างทีละใบ → done(r) · r.ok = ทุกใบส่งผ่าน · r.text = สรุปพร้อมเหตุที่ติดทีละข้อ */
const emr2SendDrafts = (list, other, done) => {
	const r = { sent: [], blocked: [], dup: [], failed: [], other: other || 0 };
	const step = (i) => {
		if (i >= list.length) {
			dnReloadCards();
			const lines = [];
			if (r.sent.length) lines.push('ส่งใบแล้ว ' + r.sent.length + ' ใบ (' + r.sent.join(', ') + ')');
			r.blocked.forEach((b) => lines.push('⛔ ' + b.no + ' ติดคำเตือนห้ามสั่ง: ' + b.why.join(' · ') + ' — แก้ให้ครบแล้วส่งใหม่'));
			if (r.dup.length) lines.push('แลปซ้ำ ' + r.dup.length + ' ใบ (' + r.dup.join(', ') + ') — กด "ส่งใบสั่งตรวจ" ที่การ์ดเพื่อยืนยันส่งซ้ำ');
			if (r.failed.length) lines.push('ส่งไม่สำเร็จ ' + r.failed.length + ' ใบ: ' + r.failed.join(' · '));
			if (r.other) lines.push('ใบร่างของคลินิกอื่น ' + r.other + ' ใบไม่ได้ส่ง');
			r.ok = !r.blocked.length && !r.dup.length && !r.failed.length;
			r.text = lines.join(' · ');
			done(r);
			return;
		}
		const o = list[i];
		const no = dnNoOf(o);
		api.runProcess(
			DN_SEND_PROC,
			{ order_id: String(o.order_id) },
			(res) => {
				const d = (res && res.data) || {};
				if (d.success) r.sent.push(no);
				else if (d.code === 'HAS_BLOCK' || d.code === 'OVERRIDE_REASON_TOO_SHORT') {
					// เหตุที่ติดไม่ซ้ำ (หลายรายการยาติดกฎเดียวกัน = ข้อความเดียวกัน)
					const why = [];
					(d.blocks || []).forEach((b) => {
						const m = String((b && b.message) || '').trim();
						if (m && why.indexOf(m) < 0) why.push(m);
					});
					r.blocked.push({ no, why: why.length ? why : [d.message || 'ติดคำเตือนห้ามสั่ง'] });
				} else if (d.code === 'DUP_LAB') r.dup.push(no);
				else r.failed.push(no + ' — ' + (d.message || 'ส่งไม่สำเร็จ'));
				step(i + 1);
			},
			(err) => {
				r.failed.push(no + ' — ' + dnErr(err));
				step(i + 1);
			}
		);
	};
	step(0);
};
const dnConfirmText = (head, mine, other, tail) => {
	const med = mine.filter((o) => String(o.service_type_code || '') === DN_DRUG_TYPE).length;
	return head + ' จะส่งใบร่าง ' + mine.length + ' ใบ (ใบสั่งยา ' + med + ' · ใบสั่งตรวจ ' + (mine.length - med) + ')' +
		(other ? ' — ใบของคลินิกอื่น ' + other + ' ใบจะไม่ถูกส่ง' : '') + (tail || '');
};
/* ── /emr2 done ── */

/* ── emr2 auto-forward (frame/auto-forward.lib.js · gen-emr-v2-model.cjs ฝังลงปุ่ม "ส่งต่ออัตโนมัติ" + "ตรวจเสร็จ + ส่งต่อ") ──
   ส่งคิวคนไข้ไปที่ถัดไปเอง (พี่เคาะ 2026-10-23 · เลือกตาม ⭐ ทั้ง 5 ข้อ):
     1. มี consult (ต้นทาง) → คลินิก consult · ปลายทางขอส่งกลับ → คลินิกต้นทาง (ลำดับเดียวกับ "ส่งต่อ (กำหนดเอง)")
     2. ไม่มี consult → visit_route (his-finance-bill-v2 · E132 กติกาเส้นทางที่เดียวของระบบ):
          pharmacy → ห้องยา · finance → การเงิน (+ เปิดคิวห้องยาคู่เมื่อ drug_leg) · none → หน้าห้องตรวจ
     3. หน้าห้องตรวจ = skip-recall to_center (ล้างห้อง/หมอ · เลขคิวเดิม) แทน move-unit (ไม่เปิดคิวใหม่)
   ทุกทางยืนยันก่อน ("ส่งไป X เพราะ Y") · เขียนหมายเหตุลงคิว (tran_note) ให้ห้องที่รับงานต่ออ่านได้ (พี่สั่ง 2026-10-23)
   หาปลายทางไม่ได้ = บอกเหตุ + ให้ใช้ "ส่งต่อ (กำหนดเอง)" · ห้ามเดาห้อง (ส่งผิดห้องอันตรายกว่า)
   ต้องมีตัวแปร self · form · api · tran ก่อนส่วนนี้ (ประกาศในไฟล์ปุ่ม) · 🔴 ห้ามใช้ await (onClick เป็น sync handler) */
const AF_ROUTE_PROC = '6a8c4732f851000f28e5022a'; // his-finance-bill-v2 · action visit_route (อ่านอย่างเดียว)
const AF_MOVE_UNIT = '6a4b9464ac48023662b1b42c'; // move-unit — ปิดคิวนี้ เปิดคิวใหม่ที่ปลายทาง
const AF_CHECKIN = '6a4b6f8fac48023662b1b41e'; // checkin — เปิดคิวห้องยาคู่ (กันคิวซ้ำเอง)
const AF_SKIP_RECALL = '6a4b9451ac48023662b1b42b'; // skip-recall — action to_center
const AF_TRAN_UPDATE = '6a50cc20e97c6d6bbf111ce0'; // tran-update — เขียน tran_note (whitelist)
const AF_MY_ROOM_TAB = 'tab_pane_10728'; // แท็บ My Room ใน main_app
const AF_TRAN_FORM = '6a461235e521219e514d1c4b'; // Visit Tran — อ่านคิวสดก่อนตัดสินปลายทาง

const afRefreshQueues = () => {
	['visit_unit', 'visit_room'].forEach((n) => {
		const f = form.getFieldRef(n);
		if (f && f.getFieldEditor && f.getFieldEditor()) f.getFieldEditor().handleRefresh();
	});
};
// คนไข้ออกจากห้องแล้ว — ล้างการ์ดทั้งหน้า กลับคิวห้องตัวเอง (ท่าเดียวกับปุ่มส่งต่อเดิม)
const afLeaveEmr = (msg, type) => {
	form.$examTran = null;
	const card = form.getFieldRef('opd_card');
	if (card && card.vueState && card.vueState.setTran) card.vueState.setTran(null);
	const tab = form.getFieldRef('main_app');
	if (tab) tab.activeTabName = AF_MY_ROOM_TAB;
	if (msg) self.alert(msg, type || 'success');
};
const afErr = (e) => String((e && e.message) || e);
const afNow = () => {
	const d = new Date();
	const p = (n) => String(n).padStart(2, '0');
	return p(d.getHours()) + ':' + p(d.getMinutes());
};
const afUnitLabel = (u) => (u && (u.label || u.value)) || '';

// หมายเหตุส่งต่อ — ห้องที่รับงานต่ออ่านบนคิว: มาจากไหน · เพราะอะไร · คำเตือนที่ระบบเจอ
const afNote = (why, warns) => {
	const from = afUnitLabel(tran.unit_to) || 'ห้องตรวจ';
	const parts = ['ส่งต่ออัตโนมัติจาก ' + from + ' ' + afNow(), why].concat(warns || []).filter(Boolean);
	return parts.join(' · ');
};

/* ── หาปลายทาง → plan { kind: 'move'|'center', unit, why, warns, consultId, priority, drugLeg } ── */
const afPlan = (done) => {
	const ci = tran.consult_info || null;
	const curUnit = String((tran.unit_to && tran.unit_to.value) || '');
	if (ci && ci.clinic && String(ci.clinic) !== curUnit) {
		done({
			kind: 'move',
			unit: { value: ci.clinic, label: ci.to_label || ci.clinic },
			why: 'Consult' + (ci.reason ? ': ' + ci.reason : ''),
			warns: [],
			consultId: ci.consult_id || '',
			priority: ci.priority || '',
		});
		return;
	}
	if (ci && ci.reply && String(ci.clinic) === curUnit && tran.unit_from && tran.unit_from.value) {
		done({
			kind: 'move',
			unit: { value: tran.unit_from.value, label: tran.unit_from.label || tran.unit_from.value },
			why: 'ตอบ consult แล้ว ส่งกลับคลินิกต้นทาง',
			warns: [],
			consultId: '',
		});
		return;
	}
	api.runProcess(
		AF_ROUTE_PROC,
		{ action: 'visit_route', tran_id: String(tran._id) },
		(res) => {
			const d = (res && res.data) || {};
			if (!d.ok) {
				done(null, (d.message || 'หาเส้นทางไม่ได้') + ' — ใช้ปุ่ม "ส่งต่อ (กำหนดเอง)" แทน');
				return;
			}
			const warns = (d.warnings || []).map((w) => w && w.message).filter(Boolean);
			if (d.patient_leg === 'none') {
				done({ kind: 'center', why: 'ตรวจเสร็จ ไม่มีใบยาและไม่มีรายการค้างชำระ — คืนหน้าห้องตรวจ', warns });
				return;
			}
			const unit = d.patient_leg === 'finance' ? d.finance_unit : d.patient_leg === 'pharmacy' ? d.pharmacy_unit : null;
			if (!unit || !unit.value) {
				done(null, 'หา' + (d.patient_leg === 'finance' ? 'ห้องการเงิน' : 'ห้องยา') + 'ไม่ได้' + (warns.length ? ' (' + warns.join(' · ') + ')' : '') + ' — ใช้ปุ่ม "ส่งต่อ (กำหนดเอง)" แทน');
				return;
			}
			const drugLeg = d.drug_leg && d.pharmacy_unit && d.pharmacy_unit.value && d.pharmacy_unit.value !== unit.value
				? { unit: d.pharmacy_unit, visitId: d.visit_id || '' }
				: null;
			done({ kind: 'move', unit: { value: unit.value, label: unit.label || unit.value }, why: d.reason || '', warns, consultId: '', drugLeg });
		},
		(err) => done(null, 'หาเส้นทางไม่สำเร็จ: ' + afErr(err) + ' — ใช้ปุ่ม "ส่งต่อ (กำหนดเอง)" แทน')
	);
};

/* ── ทำตาม plan ── */
const afMove = (plan, note, prefix) => {
	const tranId = String(tran._id);
	api.runProcess(
		AF_MOVE_UNIT,
		{
			tran_id: tranId,
			unit_to: plan.unit,
			unit_room: null, // ไม่ล็อกช่อง — ปลายทางเรียกคิวเอง
			doctor_to: null,
			tran_note: note,
			visit_priority: plan.priority || tran.visit_priority || '10',
			consult_id: plan.consultId || '',
		},
		(res) => {
			const m = (res && res.data) || {};
			afRefreshQueues();
			if (!m.success) {
				self.alert(prefix + (m.message || 'ส่งต่อไม่สำเร็จ'), 'warning');
				return;
			}
			const sent = prefix + 'ส่งคิว ' + (m.queue_label || tran.queue_label || '') + ' ไป ' + afUnitLabel(plan.unit) + ' แล้ว';
			if (!plan.drugLeg || !plan.drugLeg.visitId) {
				afLeaveEmr(sent);
				return;
			}
			// ขายา: ห้องยาจัดยาระหว่างคนไข้ไปชำระ (ท่าเดียวกับปุ่ม "ส่งตัว" ของ Move Unit · E132 A6)
			const drugLabel = afUnitLabel(plan.drugLeg.unit);
			api.runProcess(
				AF_CHECKIN,
				{
					visit_id: plan.drugLeg.visitId,
					unit_to: plan.drugLeg.unit.value,
					unit_from: tran.unit_to && tran.unit_to.value ? { value: tran.unit_to.value, label: afUnitLabel(tran.unit_to) } : null,
					visit_priority: tran.visit_priority || null,
					tran_note: 'ขายา (คู่กับคิว ' + (m.queue_label || '') + ') · ' + note,
				},
				(r2) => {
					const d2 = (r2 && r2.data) || {};
					if (!d2.success) {
						afLeaveEmr(sent + ' · ⚠️ เปิดคิวห้องยา (' + drugLabel + ') ไม่สำเร็จ: ' + (d2.message || 'ไม่ทราบสาเหตุ') + ' — ส่งคิวห้องยาเองจากเมนูคิว', 'warning');
						return;
					}
					afLeaveEmr(sent + ' · ห้องยา ' + drugLabel + ' ' + (d2.duplicated ? 'มีคิวอยู่แล้ว ' : 'คิว ') + (d2.queue_label || ''));
				},
				(e2) => afLeaveEmr(sent + ' · ⚠️ เปิดคิวห้องยา (' + drugLabel + ') ไม่สำเร็จ: ' + afErr(e2) + ' — ส่งคิวห้องยาเองจากเมนูคิว', 'warning')
			);
		},
		(err) => self.alert(prefix + 'ส่งต่อไม่สำเร็จ: ' + afErr(err), 'warning')
	);
};

// หน้าห้องตรวจ: คิวเดิม (ไม่เปิดใหม่) ⇒ หมายเหตุใหม่ต่อหน้าหมายเหตุเดิมของคิว ไม่ทับทิ้ง
const afCenter = (note, prefix) => {
	const tranId = String(tran._id);
	const old = String(tran.tran_note || '').trim();
	api.runProcess(
		AF_SKIP_RECALL,
		{ tran_id: tranId, action: 'to_center' },
		(res) => {
			const d = (res && res.data) || {};
			if (!d.success) {
				afRefreshQueues();
				self.alert(prefix + (d.message || 'คืนหน้าห้องตรวจไม่สำเร็จ'), 'warning');
				return;
			}
			const q = d.queue_label || tran.queue_label || '';
			const done = (extra) => {
				afRefreshQueues();
				afLeaveEmr(prefix + 'คืนคิว ' + q + ' กลับหน้าห้องตรวจแล้ว' + (extra || ''), extra ? 'warning' : 'success');
			};
			api.runProcess(
				AF_TRAN_UPDATE,
				{ tran_id: tranId, set: { tran_note: old && old !== note ? note + ' | ' + old : note } },
				(r2) => done(r2 && r2.data && r2.data.success ? '' : ' · ⚠️ เขียนหมายเหตุลงคิวไม่สำเร็จ'),
				() => done(' · ⚠️ เขียนหมายเหตุลงคิวไม่สำเร็จ')
			);
		},
		(err) => self.alert(prefix + 'คืนหน้าห้องตรวจไม่สำเร็จ: ' + afErr(err), 'warning')
	);
};

/* ── ทางเข้า: หาปลายทาง → ยืนยัน → ส่ง · prefix = ข้อความนำของผลขั้นก่อนหน้า (เช่น "ส่งใบร่างแล้ว 2 ใบ · ")
   noteWarn = คำเตือนที่ต้องไปถึงห้องปลายทางด้วย (เช่น ใบร่างค้าง) — ต่อท้ายหมายเหตุบนคิว ── */
/* คิวสดจาก DB ทับลง tran (= form.$examTran ตัวเดียวกัน) ก่อนตัดสิน
   🔴 form.$examTran ตั้งครั้งเดียวตอนเปิดคนไข้ — consult ที่สร้างทีหลัง (จอนี้หรือจออื่น) ไม่มี consult_info
      ⇒ ตกไปทาง visit_route → การเงิน ทั้งที่ consult ต้องมาก่อน (พี่เจอ 2026-10-23 · VD001 consult ศัลยกรรม)
   อ่านไม่ได้ = ใช้ค่าในจอต่อ (พฤติกรรมเดิม) ไม่บล็อกการส่งต่อ */
const afFresh = (done) => {
	api.crudGetAll(
		{
			sdProvider: {
				providerId: AF_TRAN_FORM,
				providerType: 'FORM',
				params: { id: String(tran._id) },
				options: { where: "`_id` = CONVERT(:id, 'objectId')", limit: 1, page: 1 },
			},
			totalEnable: false,
		},
		(res) => {
			const row = (res && res.data && res.data[0]) || null;
			if (row) Object.assign(tran, row);
			done();
		},
		() => done()
	);
};

const emr2AutoForward = (prefix, noteWarn) => {
	const pre = prefix || '';
	afFresh(() => afPlan((plan, errMsg) => {
		if (!plan) {
			self.alert(pre + errMsg, 'warning');
			return;
		}
		const curUnit = String((tran.unit_to && tran.unit_to.value) || '');
		if (plan.kind === 'move' && String(plan.unit.value) === curUnit) {
			self.alert(pre + 'คิวนี้อยู่ที่ ' + afUnitLabel(plan.unit) + ' อยู่แล้ว', 'info');
			return;
		}
		const note = afNote(plan.why, plan.warns.concat(noteWarn ? [noteWarn] : []));
		const where = plan.kind === 'center' ? 'หน้าห้องตรวจ (คิวเดิม ' + (tran.queue_label || '') + ')' : afUnitLabel(plan.unit);
		const msg =
			pre + 'ส่งคิว ' + (tran.queue_label || '') + ' ไป ' + where + '?' +
			(plan.why ? ' — ' + plan.why : '') +
			(plan.drugLeg ? ' · เปิดคิวห้องยาคู่ ' + afUnitLabel(plan.drugLeg.unit) : '') +
			(plan.warns.length ? ' · ⚠️ ' + plan.warns.join(' · ') : '');
		self.confirm(msg, () => (plan.kind === 'center' ? afCenter(note, pre) : afMove(plan, note, pre)), 'info', 'ส่งต่ออัตโนมัติ');
	}));
};
