function shortDate(ts) {
  var m = /^(\d{4})-(\d{2})-(\d{2})/.exec(s(ts));
  if (!m) return '';
  return Number(m[3]) + ' ' + MON[Number(m[2]) - 1] + ' ' + String(Number(m[1]) + 543).slice(2);
}

function parseTran(tran) {
  if (!tran || !tran.vid) return null;
  var v = tran.vid;
  var pd = v.pid || {};
  var nm = s(pd.p_fname) + (pd.p_lname ? ' ' + s(pd.p_lname) : '');
  return {
    pid: v.xtbxlv1_xfx_id ? String(v.xtbxlv1_xfx_id) : '',
    hn: s(pd.hn),
    name: nm ? ((pd.prename && pd.prename.label) || '') + nm : '',

    vid: s(v.value || v._id || ''),
    vn: s(v.vn),
  };
}

