  globalThis.document.addEventListener('change', input, true);
  globalThis.document.addEventListener('keydown', key, true);
  globalThis[KEY] = { click: click, input: input, key: key };
}

function injectCss() {
  if (typeof REFER_CSS !== 'string' || !REFER_CSS) return;
  try {
    var id = 'refer-css-' + WRAP_CLASS;
    var doc = globalThis.document;
    var el = doc.getElementById(id);
    if (el && el.getAttribute('data-build') === BUILD_AT) return;
    if (!el) { el = doc.createElement('style'); el.id = id; doc.head.appendChild(el); }
    el.setAttribute('data-build', BUILD_AT);
    el.textContent = REFER_CSS;
  } catch (e) { LOG('ใส่ CSS ไม่สำเร็จ ' + (e && e.message)); }
}

var T0 = Date.now();
var bootDone = false;
var bootT = null;
function bootTick() {
  if (bootDone) return;
  if (!S) {
    var vs = null;
    try { vs = SELF && SELF.vueState; } catch (e) { vs = null; }
    if (!vs) {
      if (Date.now() - T0 > 12000) { bootDone = true; globalThis.clearInterval(bootT); LOG('🔴 ไม่มี vueState — ท่า template ใช้ไม่ได้บนหน้านี้'); }
      return;
    }
    S = vs;
    INIT_STATE(S);
    injectCss();
    bindEvents();
    LOG('เจอ vueState แล้ว · ' + (Date.now() - T0) + 'ms');
  }
  var needUs = (typeof NEED_US === 'undefined') ? true : !!NEED_US;
  if (needUs && !getUS()) {
    if (Date.now() - T0 > 18000) {
      bootDone = true; globalThis.clearInterval(bootT);
      LOG('🔴 หมดเวลารอ userState');
      if (typeof onBootFail === 'function') onBootFail('เชื่อมต่อกับระบบไม่ได้ — ไม่พบตัวเรียก process (แจ้งผู้ดูแลระบบ)');
    }
    return;
  }
  bootDone = true;
  globalThis.clearInterval(bootT);
  if (typeof onBoot === 'function') onBoot();
}
bootT = globalThis.setInterval(bootTick, 300);
bootTick();

/* emr2-refer — ปุ่ม "ส่งตัว (Refer)" แถบล่าง EMR v2 (gen-emr-v2-model.cjs ต่อท้าย onMounted ของ refer_emr_card ให้ · อย่าแก้ในบิลเดอร์)
   การ์ดนี้ยกจาก v1 มาซ่อนไว้ในแถบปุ่มล่าง (ไม่โชว์การ์ด) — ใช้แค่ dialog + logic เดิมทั้งก้อน
   1 visit = 1 เคส (พี่สั่ง 2026-10-23): visit นี้มีเคสแล้ว → เปิดเคสเดิม (ยังเตรียมอยู่ = แก้ได้ · ศูนย์รับแล้ว = ดูอย่างเดียว ตามกติกาเดิม)
   ไม่มี → เปิดเคสใหม่ · รายการ cases มาจาก outCase action 'mine' (pid + vid ของ visit ที่เปิดอยู่) */
function emr2ReferOpen() {
  if (!S || !S.rfoPid) return 'notready';
  if (S.rfoLoading) return 'loading';
  var active = cases.filter(function (c) { return OPEN_ST.indexOf(s(c.status)) >= 0; });
  var pick = active[0] || cases[0];
  if (pick) openCase(s(pick.case_no));
  else openNew();
  return 'ok';
}
globalThis.__emr2ReferOpen = emr2ReferOpen;
