/* ── EMR v2 · ตัวงาน 3 ช่อง (gen-emr-v2-model.cjs · อย่าแก้ในบิลเดอร์ จะโดนทับ) ── */
/* ตัวงานอยู่ในแท็บ main_app — Element Plus ตั้ง .el-tabs__content{overflow:hidden} ซึ่งทำให้ sticky ไม่ทำงาน
   ปลดเฉพาะแท็บที่มีตัวงาน v2 (:has) ไม่กระทบแท็บอื่นของฟอร์ม */
.el-tabs__content:has(.emr2-row){overflow:visible}
/* ไม่ zoom (พี่เลือกข้อ A 2026-10-22 21:3x) — เคยใช้ zoom 112% แล้วจริงบนจอใหญ่เกิน + หัวแท็บช่องขวาว่าง
   ⚠️ ถ้ากลับมาใช้ zoom: ความยาวในตัวที่ zoom ถูกคูณด้วย (รวม 100vh) ต้องหารความสูง/ระยะตรึงกลับ · และเช็คหัว el-tabs ด้วย */
/* 3 ช่อง = สูงเต็มที่เหลือของจอเสมอ (board 4 · พี่วงโซน 2026-10-22: "ขยาย auto ตามหน้าจอ ถ้า content ยาวก็กลายเป็นสกอ")
   --emr2-h = emr2_soap วัดจากจอจริง (ทั้งหน้าพอดีจอ: หัวคนไข้บน · ตัวงาน · แถบปุ่มล่างสุด)
   เลื่อนเฉพาะโซนที่วง: ซ้าย = ทั้งช่อง · กลาง = เนื้อหาใต้แถบหัวของ emr2_soap · ขวา = เนื้อหาในแท็บ (แท็บ + ค่าใช้จ่ายอยู่กับที่) */
@media (min-width:1200px){
  .emr2-row{align-items:stretch}
  .el-row.emr2-row>.emr2-col{height:var(--emr2-h,calc(100vh - 380px));min-height:500px;overflow:hidden;display:flex;flex-direction:column}
  .emr2-col-left{overflow-y:auto!important;overscroll-behavior:contain;scrollbar-width:thin}
  .emr2-col-left>*{flex:0 0 auto}
  /* กลาง: กล่อง emr2_soap สูงเท่าช่อง — ตั้งความสูงตรงจาก --emr2-h (ตัวแปรสืบทอดลงมา)
     ไม่ใช้ flex ยืดผ่านตัวห่อ: vue-ui ถูกห่อด้วย div ของแพลตฟอร์มหลายชั้น ความสูงส่งไม่ถึง (เทส mock: ช่องกลางเลื่อนไม่ได้) */
  .emr2-col-center .e2s{height:var(--emr2-h);margin-bottom:0;box-sizing:border-box}
  /* ขวา: แท็บกินที่ทั้งหมด เนื้อในแท็บเลื่อน · การ์ดค่าใช้จ่าย (ตัวสุดท้าย) อยู่ล่างไม่ยืด */
  .emr2-col-right>*{flex:0 0 auto}
  .emr2-col-right>.container-wrapper:has(.emr2-order-tabs){flex:1 1 auto;min-height:0;display:flex;flex-direction:column;margin-bottom:10px!important}
  .emr2-col-right .tab-container{flex:1 1 auto;min-height:0;display:flex;flex-direction:column}
  .emr2-order-tabs{flex:1 1 auto;min-height:0;display:flex;flex-direction:column}
  .emr2-order-tabs>.el-tabs__content{flex:1 1 auto;min-height:0;overflow-y:auto!important;overscroll-behavior:contain;scrollbar-width:thin}
}
/* แถบปุ่มอยู่ใน flow ใต้ตัวงาน (พี่ลบ affix) — เว้นระยะเท่า board 4 · ตัววัดหักระยะนี้ให้เอง */
.container-wrapper.emr2-bar{margin-top:12px}
/* จอแคบ: เรียงลงมาเลื่อนทั้งหน้า (board 4 · < 1180px) */
@media (max-width:1199px){
  .emr2-row>.emr2-col{flex:0 0 100%;max-width:100%}
