.pcard-timer .emr2-fullbtn{margin-left:8px;padding:0 0 0 8px;border:none;border-left:1px solid var(--el-border-color);background:transparent;color:inherit;cursor:pointer;display:inline-flex;align-items:center;line-height:1}
