.emr2-offscreen{position:absolute!important;left:-10000px;top:0;width:800px;height:400px;overflow:hidden;pointer-events:none}
/* emr2_soap · ช่องกลาง EMR v2 (board 4) — generator ต่อท้ายใน formConfig.cssCode ช่วง marker EMR v2
   ใช้ตัวแปรสีของ Element Plus ⇒ ตามธีมสว่าง/มืดของแอปเอง
   ตัวอักษรฐาน 14px เท่าการ์ดเดิม (ไม่ zoom แล้ว · พี่เลือกข้อ A 2026-10-22 หลังเห็น 112% บนจอจริงใหญ่เกิน) */
/* accent = เขียว รพ. (--e2-brand ตั้งที่ .emr2-row) — ปุ่มแก้ไข · ลิงก์ "+ เพิ่ม" ทุก SOAP (พี่สั่ง 2026-10-23) · นอกตัวงาน EMR v2 ตกเป็นเขียว EP */
.e2s{--e2-accent:var(--e2-brand-text,var(--el-color-success));--e2-accent-bg:var(--e2-brand-bg,var(--el-color-success-light-9));--e2-line:var(--el-border-color-lighter);--e2-muted:var(--el-text-color-secondary);--e2-lock:var(--el-fill-color-lighter);
  font-size:14px;line-height:1.55;color:var(--el-text-color-primary);background:var(--el-bg-color);border:1px solid var(--e2-line);border-radius:12px;margin-bottom:15px}
.e2s a{color:var(--e2-accent);cursor:pointer}
/* กล่องเต็มช่อง (CSS ตัวงานใน generator ยืดให้) · แถบหัวอยู่กับที่ · เลื่อนเฉพาะ .e2s-body — เส้นขอบกล่องจึงไม่หายตอนเลื่อน */
.e2s{display:flex;flex-direction:column;overflow:hidden}
.e2s-bar{flex:0 0 auto;display:flex;flex-wrap:wrap;align-items:center;justify-content:space-between;gap:8px;padding:10px 14px;background:var(--el-bg-color);border-bottom:1px solid var(--e2-line)}
.e2s-body{flex:1 1 auto;min-height:0;overflow-y:auto;overscroll-behavior:contain;scrollbar-width:thin}
.e2s-bar-l,.e2s-bar-r{display:flex;align-items:center;gap:10px;flex-wrap:wrap}
/* ปุ่มหลัก = เขียวตัวงาน (--e2-brand ตั้งที่ .emr2-row ใน orders/emr2-orders.css · พี่สั่ง 2026-10-23 "สีปุ่มใช้แบบด้านขวา") */
.e2s-btn-main{display:inline-flex;align-items:center;gap:6px;border:none;background:var(--e2-brand,var(--e2-accent));color:#fff;border-radius:8px;padding:7px 14px;font:inherit;font-weight:600;cursor:pointer;min-height:36px}
.e2s-btn{display:inline-flex;align-items:center;gap:8px;font:inherit;font-size:14px;border:1px solid var(--e2-line);background:var(--el-fill-color-light);color:inherit;border-radius:8px;padding:6px 12px;cursor:pointer;min-height:36px}
.e2s-btn-sm{font:inherit;font-size:13px;border:1px solid var(--e2-line);background:transparent;color:inherit;border-radius:6px;padding:2px 10px;cursor:pointer;min-height:28px}
/* แก้ไข = ชุดสีเดียวกับปุ่ม "ส่งต่ออัตโนมัติ" แถบล่าง (พี่สั่ง 2026-10-23 "ทำแบบนี้") — พื้นเขียวจาง · ขอบเขียวเข้ม · ตัวเขียว */
.e2s-btn-sm.is-main{border-color:var(--e2-brand,var(--e2-accent));background:var(--e2-accent-bg);color:var(--e2-accent)}
/* ปุ่มรอง ตัวเขียว ขอบเทา พื้นโปร่ง = "+ Consult" ของ mockup board 4 (พี่สั่ง 2026-10-23) */
.e2s-btn-sm.is-text{color:var(--e2-accent)}
.e2s-seg{display:flex;background:var(--el-fill-color-light);border:1px solid var(--e2-line);border-radius:7px;padding:2px;gap:2px}
.e2s-seg button{font:inherit;font-size:13px;border:none;background:transparent;color:var(--e2-muted);border-radius:5px;padding:3px 10px;cursor:pointer}
/* ตัวที่เลือก = เขียวแบบแท็บช่องขวา ไม่มีเงา (พี่สั่ง 2026-10-23) */
.e2s-seg button.on{background:var(--e2-brand-bg,var(--el-bg-color));color:var(--e2-brand-text,var(--el-text-color-primary));font-weight:600}
.e2s-dots{display:inline-flex;gap:3px}
.e2s-dot{width:8px;height:8px;border-radius:999px;background:var(--e2-muted)}
/* สีจุด = ตัวอักษรของป้ายคลินิก (--cN-fg) ⇒ จุดกับป้ายคลินิกเดียวกันสีตรงกัน · ของเรา = วงล้อมสีเดียวกัน */
.e2s-dot.is-c0{background:var(--c0-fg)}.e2s-dot.is-c1{background:var(--c1-fg)}.e2s-dot.is-c2{background:var(--c2-fg)}.e2s-dot.is-c3{background:var(--c3-fg)}.e2s-dot.is-c4{background:var(--c4-fg)}
.e2s-dot.is-me{box-shadow:0 0 0 2px var(--el-fill-color-light),0 0 0 3.5px currentColor;color:var(--e2-muted)}
.e2s-dot.is-me.is-c0{color:var(--c0-fg)}.e2s-dot.is-me.is-c1{color:var(--c1-fg)}.e2s-dot.is-me.is-c2{color:var(--c2-fg)}.e2s-dot.is-me.is-c3{color:var(--c3-fg)}.e2s-dot.is-me.is-c4{color:var(--c4-fg)}
.e2s-dots{padding:0 3px}
.e2s-pop{position:relative}
.e2s-pop-panel{position:absolute;top:calc(100% + 6px);left:0;z-index:20;width:340px;max-width:80vw;background:var(--el-bg-color-overlay);border:1px solid var(--e2-line);border-radius:10px;box-shadow:var(--el-box-shadow-light);padding:6px}
.e2s-pop-row{display:flex;align-items:center;gap:10px;padding:7px 8px;border-radius:8px}
.e2s-pop-row.is-me{background:var(--e2-accent-bg)}
.e2s-pop-no{flex:none;width:22px;height:22px;border-radius:999px;display:inline-flex;align-items:center;justify-content:center;font-size:12px;font-weight:700;background:var(--el-fill-color);color:var(--e2-muted)}
.e2s-pop-foot{border-top:1px solid var(--e2-line);margin-top:6px;padding:8px 8px 4px;font-size:12px;color:var(--e2-muted)}
.e2s-sec{padding:12px 14px;border-bottom:1px solid var(--e2-line);display:flex;flex-direction:column;gap:8px}
.e2s-sec:last-child{border-bottom:none}
.e2s-head{display:flex;align-items:center;gap:8px;flex-wrap:wrap}
.e2s-head-r{margin-left:auto;display:inline-flex;align-items:center;gap:8px}
.e2s-sub{font-size:11px;letter-spacing:.06em;color:var(--e2-muted)}
.e2s-badge{flex:none;width:26px;height:26px;border-radius:7px;display:inline-flex;align-items:center;justify-content:center;font-weight:700;font-size:14px}
.e2s-badge.is-s{background:var(--el-color-primary-light-9);color:var(--el-color-primary)}
.e2s-badge.is-o{background:var(--el-color-success-light-9);color:var(--el-color-success)}
.e2s-badge.is-a{background:var(--el-color-warning-light-9);color:var(--el-color-warning)}
.e2s-badge.is-c{background:var(--el-fill-color);color:var(--e2-muted)}
.e2s-badge-ico{width:16px;height:16px}
/* P = ม่วง (พี่สั่ง 2026-10-23 "แผนการรักษาเอาสีม่วง") — ม่วงชุดเดียวกับป้าย "ทางเลือก" ของแท็บวัคซีน (EP ไม่มีม่วง) */
.e2s-badge.is-p{background:rgba(132,103,209,.16);color:#6a4fc0}
html.dark .e2s-badge.is-p{color:#b3a0f0}
.e2s-lines{display:flex;flex-direction:column;gap:4px}
.e2s-line{display:flex;gap:10px}
.e2s-l{flex:0 0 72px;font-size:13px;color:var(--e2-muted);padding-top:1px}
/* S · O · P — ป้ายซ้าย·ค่าขวา บรรทัดเดียวเสมอ (พี่สั่ง 2026-10-23 "แสดงแบบประวัติอาการ")
   คอลัมน์ป้ายกว้างเท่าป้ายที่ยาวสุดของใบนั้น (ไม่เกิน 180px แล้วตัดบรรทัดในช่องป้าย) ⇒ ค่าทุกแถวเริ่มตรงกัน */
.e2s-lines.is-grid{display:grid;grid-template-columns:fit-content(180px) minmax(0,1fr);column-gap:10px;row-gap:4px}
.e2s-lines.is-grid>.e2s-line{display:contents}
.e2s-lines.is-grid>.e2s-muted{grid-column:1/-1}
.e2s-l.is-narrow{flex-basis:18px;font-weight:700}
.e2s-t{min-width:0;white-space:pre-wrap;word-break:break-word}
.e2s-t.is-flag{color:var(--el-color-danger)}
.e2s-others{display:flex;flex-direction:column;gap:6px}
.e2s-lock{display:flex;flex-direction:column;gap:4px;padding:8px 10px;border-radius:8px;background:var(--e2-lock);border:1px dashed var(--e2-line)}
.e2s-lock.is-compact{flex-direction:row;align-items:center;gap:8px;padding:5px 10px;min-width:0}
.e2s-lock-head{display:flex;align-items:center;gap:8px}
.e2s-chip{display:inline-block;font-size:12px;padding:0 8px;border-radius:999px;border:1px solid var(--e2-line);color:var(--e2-muted);white-space:nowrap;line-height:1.7}
.e2s-chip.is-me{border-color:transparent;background:var(--e2-accent-bg);color:var(--e2-accent);font-weight:600}
.e2s-chip.is-main{border-color:var(--el-color-danger-light-7);color:var(--el-color-danger);font-weight:600}
.e2s-chip.is-ok{border-color:transparent;background:var(--el-color-success-light-9);color:var(--el-color-success)}
.e2s-chip.is-warn,.e2s-chip.cs-accept{border-color:transparent;background:var(--el-color-warning-light-9);color:var(--el-color-warning)}
.e2s-chip.is-danger{border-color:transparent;background:var(--el-color-danger-light-9);color:var(--el-color-danger);font-weight:600}
.e2s-chip.cs-complete{border-color:transparent;background:var(--el-color-success-light-9);color:var(--el-color-success)}
.e2s-chip.cs-send{border-color:transparent;background:var(--el-color-info-light-9);color:var(--el-color-info)}
.e2s-dx{display:flex;flex-direction:column;gap:6px;padding:8px 10px;border-radius:8px;border:1px solid var(--e2-line)}
.e2s-dx-head,.e2s-dx-row{display:flex;align-items:center;gap:8px;flex-wrap:wrap}
.e2s-cs{border:1px solid var(--e2-line);border-radius:8px;overflow:hidden}
.e2s-cs-row{display:flex;flex-wrap:wrap;align-items:center;gap:8px;padding:7px 10px;cursor:pointer}
.e2s-cs-row:hover{background:var(--el-fill-color-light)}
.e2s-cs-body{padding:8px 10px;border-top:1px dashed var(--e2-line);display:flex;flex-direction:column;gap:4px;background:var(--el-fill-color-lighter)}
.e2s-cs-foot{text-align:right;font-size:13px}
/* แบนเนอร์ consult — ค่าสียกตรงจาก mockup (design/emr-multiclinic/mockup/EMRv2.dc.html · --warn/--ok ของ .emr) · พี่สั่ง 2026-10-23 */
.e2s-banner{--bn-warn:#8a5300;--bn-warn-bg:#fff4d6;--bn-ok:#1c6b3a;--bn-ok-bg:#e5f3ea;display:flex;align-items:center;gap:12px;padding:10px 12px;border-radius:10px}
html.dark .e2s-banner{--bn-warn:#f5c451;--bn-warn-bg:rgba(240,180,41,.13);--bn-ok:#62d39b;--bn-ok-bg:rgba(76,195,138,.14)}
.e2s-banner.is-wait{background:var(--bn-warn-bg);border:1px solid rgba(240,180,41,.32)}
.e2s-banner.is-done{background:var(--bn-ok-bg);border:1px solid rgba(76,195,138,.32)}
.e2s-banner-ic{flex:none;width:36px;height:36px;border-radius:999px;display:inline-flex;align-items:center;justify-content:center}
.e2s-banner-ic svg{width:18px;height:18px}
.e2s-banner.is-wait .e2s-banner-ic{background:rgba(240,180,41,.18);color:var(--bn-warn)}
.e2s-banner.is-done .e2s-banner-ic{background:rgba(76,195,138,.18);color:var(--bn-ok)}
/* "แก้ไขคำตอบ" = เขียว รพ. ทึบ ตัวขาว — ขอบเขียวบนพื้นเขียวมองไม่เห็นบนจอจริง (พี่ติ 2026-10-23 · 2 รอบ) */
.e2s-banner.is-done .e2s-btn{border-color:transparent;background:var(--e2-brand,var(--e2-accent));color:#fff;font-weight:600}
.e2s-note{margin:10px 14px;padding:8px 12px;border-radius:8px;background:var(--el-fill-color-light);color:var(--e2-muted);font-size:14px}
.e2s-note.is-danger{background:var(--el-color-danger-light-9);color:var(--el-color-danger)}
.e2s-muted{color:var(--e2-muted)}
.e2s-warn{color:var(--el-color-warning)}
.e2s-sm{font-size:12px}
.e2s-grow{flex:1 1 auto}
.e2s-min0{min-width:0}
.e2s-push{margin-left:auto}
.e2s-ellip{overflow:hidden;text-overflow:ellipsis;white-space:nowrap;min-width:0}
/* icon = Element Plus Icons ที่แอป register ไว้ (พี่สั่ง 2026-10-22: ไม่ใช้ emoji เป็น icon) */
.e2s .el-icon{vertical-align:-2px}
.e2s-lock-head>.el-icon,.e2s-dx-head>.el-icon,.e2s-lock-ic{flex:none;color:var(--e2-muted)}
/* ── คลินิกเฉพาะทางใน O (sp-addon.js · ลอกการ์ด spclinic_card ของ v1) — ค่าระยะ/ขนาดยกจาก mockup board 4 ส่วน O ตรง ๆ ──
   หลักไม่ให้ตาลาย: บรรทัดเดียวต่อฟอร์ม · กางทีละอัน · สถานะเป็นสีตัวอักษร ไม่มีป้ายทึบ ไม่มีกล่องตอนยุบ */
.e2s-offscreen{position:absolute;left:-9999px;top:0;width:0;height:0;overflow:hidden}
.e2s-sp{display:flex;flex-direction:column;gap:1px}
.e2s-sp-head{display:flex;align-items:center;gap:8px;padding:10px 0 4px;margin-top:4px;border-top:1px dashed var(--e2-line)}
/* หัวแบบฟอร์มคลินิก — ป้ายไอคอนสีคลินิก + ชื่อตัวหนาเท่าเนื้อหา (เดิมตัวเล็กสีจาง มองไม่เห็น · พี่ติ 2026-10-23) */
.e2s-sp-ic{flex:none;width:22px;height:22px;border-radius:6px;display:inline-flex;align-items:center;justify-content:center;font-size:12px;font-weight:700;background:var(--el-color-success-light-9);color:var(--el-color-success)}
.e2s-sp-ic svg{width:14px;height:14px}
.e2s-sp-title{font-size:14px}
/* ฟอร์มคลินิกเฉพาะทางของคลินิกอื่น (ใบ 🔒) — กดเปิดดูแบบอ่านอย่างเดียว */
.e2s-sp-olink{color:var(--e2-accent);cursor:pointer;text-decoration:underline dotted;text-underline-offset:3px}
.e2s-sp-olink:hover{text-decoration-style:solid}
.e2s-sp-age{font-size:12px;color:var(--e2-muted);padding:0 8px;border-radius:999px;background:var(--el-fill-color-light)}
.e2s-sp-head.is-assess{border-top:none;padding:8px 0 2px}
.e2s-sp-link{font:inherit;font-size:13px;border:none;background:transparent;color:var(--e2-accent);cursor:pointer;padding:2px 0;min-height:28px}
.e2s-sp-item{border-radius:8px}
.e2s-sp-item.is-open{background:var(--el-fill-color-light)}
.e2s-sp-row{box-sizing:border-box;display:flex;align-items:center;gap:8px;width:100%;border:none;background:transparent;color:inherit;padding:5px 8px;cursor:pointer;text-align:left;font:inherit;font-size:14px;min-height:32px;min-width:0}
.e2s-sp-row.is-due{cursor:default;padding-left:28px}
.e2s-sp-chev{flex:none;width:12px;height:12px;color:var(--e2-muted);transition:transform .15s}
.e2s-sp-item.is-open>.e2s-sp-row>.e2s-sp-chev{transform:rotate(90deg)}
.e2s-sp-dot{flex:none;width:8px;height:8px;border-radius:999px;background:var(--dot)}
.e2s-sp-dot.is-hollow{background:transparent;border:1.5px solid var(--dot)}
.e2s-sp-name{font-weight:500;white-space:nowrap}
.e2s-sp-status{font-size:12px;font-weight:600;white-space:nowrap}
.e2s-sp-due{color:var(--el-color-warning);font-weight:600}
.e2s-sp-detail{font-size:13px}
.e2s-sp-act{margin-left:auto;font-size:12px;color:var(--e2-accent);white-space:nowrap}
.e2s-sp-score{font-variant-numeric:tabular-nums}
.e2s-sp-bar{flex:0 0 90px;height:5px;border-radius:999px;background:var(--e2-line);overflow:hidden}
.e2s-sp-bar>span{display:block;height:100%;border-radius:999px}
.e2s-sp-nowrap{white-space:nowrap}
.e2s-sp-body{padding:2px 10px 10px 40px;display:flex;flex-direction:column;gap:6px}
.e2s-sp-entry{display:flex;flex-direction:column;gap:6px}
.e2s-sp-entry+.e2s-sp-entry{border-top:1px dashed var(--e2-line);padding-top:6px}
.e2s-sp-chips{display:flex;flex-wrap:wrap;gap:6px}
/* ชิปส่วนตรวจ — ขอบ/ตัวอักษรเข้มขึ้นให้อ่านได้ในธีมมืด (พี่ติ "เส้น tag ไม่ชัด" 2026-10-23) */
.e2s-sp-chip{font-size:12px;padding:1px 9px;border-radius:999px;border:1px solid var(--el-border-color);background:var(--el-fill-color-light);color:var(--el-text-color-regular)}
.e2s-sp-find{font-size:13px}
.e2s-sp-gap{margin-left:10px}
.e2s-sp-draw{display:flex;flex-wrap:wrap;gap:8px}
.e2s-sp-foot{display:flex;align-items:center;gap:10px;flex-wrap:wrap;font-size:12px;color:var(--e2-muted)}
.e2s-sp-body.e2s-sp-foot{flex-direction:row;font-size:13px}
.e2s-sp-pad{padding:2px 8px}
.e2s-sp-menu{align-self:flex-end;width:340px;max-width:100%;border:1px solid var(--e2-line);border-radius:10px;background:var(--el-bg-color-overlay);box-shadow:var(--el-box-shadow-light);padding:6px;display:flex;flex-direction:column;gap:2px}
.e2s-sp-menu-title{font-size:11px;font-weight:600;letter-spacing:.04em;padding:4px 8px 0}
.e2s-sp-menu-row{display:flex;align-items:center;gap:8px;padding:5px 8px;border-radius:6px;cursor:pointer}
.e2s-sp-menu-row:hover{background:var(--el-fill-color-light)}

.e2s-sp-print{font-size:18px;padding:0 2px;height:28px}
/* emr2-orders · ช่องขวา EMR v2 — ลอกจาก mockup board 4 (design/emr-multiclinic/mockup/EMRv2.dc.html · ธีมเขียว รพ.)
   แท็บ ยา · สั่งตรวจ · วัคซีน · นัด + การ์ดค่าใช้จ่าย · generator ต่อท้ายใน formConfig.cssCode ช่วง marker EMR v2
   🔴 ค่าสี/ขนาดทุกตัวยกมาจาก mockup ตรง ๆ (พี่ตีกลับ 2026-10-22: "ออกแบบไว้แล้ว แต่ตอนทำ ทำอีกแบบ")
      ห้ามแต่งเองจากความรู้สึก — จะเปลี่ยน ให้แก้ mockup ก่อนแล้วค่อยยกมา
   token = ชุด .emr.light.green / .emr.green ของ mockup · ธีมมืดของแอป = html.dark */

/* ── เขียวหลักของตัวงาน EMR v2 — ที่เดียวทั้ง 3 ช่อง (พี่สั่ง 2026-10-23 "สีปุ่มใช้แบบด้านขวา")
   ค่า = accent ของ mockup ธีมเขียว รพ. · ปุ่มหลักช่องกลาง (emr2-soap.css) กับแท็บ/ปุ่มช่องขวาอ่านตัวแปรชุดนี้
   ตั้งที่ .emr2-row (แถว 3 ช่อง) ⇒ ทุก widget ในตัวงานเห็น รวมโหมดเต็มจอ */
.emr2-row{--e2-brand:#17834f;--e2-brand-text:#126c41;--e2-brand-bg:#e2f3e9}
html.dark .emr2-row{--e2-brand:#1b7f52;--e2-brand-text:#7fd8a9;--e2-brand-bg:rgba(34,147,95,.16)}

/* ── token ──
   พื้น · เส้น · ตัวอักษร = ตัวแปร Element Plus ชุดเดียวกับการ์ดกลาง emr2_soap (พี่สั่ง 2026-10-22 "ทำการ์ดธีมสีเส้น แบบการ์ดกลาง")
     ⇒ ธีมสว่าง/มืดตามแอปเอง เส้นสองช่องเป็นสีเดียวกัน
   สีสถานะ / accent / ป้าย = ของ mockup (.emr.light.green / .emr.green) */
.emr2-order-tabs,.emr2-cost{--e2-panel:var(--el-bg-color);--e2-panel2:var(--el-fill-color-light);--e2-line:var(--el-border-color-lighter);--e2-text:var(--el-text-color-primary);--e2-muted:var(--el-text-color-secondary);--e2-lock:var(--el-fill-color-lighter);
  --e2-accent:var(--e2-brand);--e2-accent-text:var(--e2-brand-text);--e2-accent-bg:var(--e2-brand-bg);
  --e2-danger:#b4261e;--e2-danger-bg:#fdecea;--e2-warn:#8a5300;--e2-warn-bg:#fff4d6;--e2-ok:#1c6b3a;--e2-ok-bg:#e5f3ea;
  --e2-purple:#6a4fc0;--e2-purple-bg:rgba(132,103,209,.16)}
html.dark .emr2-order-tabs,html.dark .emr2-cost{
  --e2-danger:#ff8a80;--e2-danger-bg:rgba(255,107,107,.13);--e2-warn:#f5c451;--e2-warn-bg:rgba(240,180,41,.13);--e2-ok:#62d39b;--e2-ok-bg:rgba(76,195,138,.14);
  --e2-purple:#b3a0f0}
/* สีป้ายคลินิก — ชุด C ของ mockup (กุมาร · ทันตะ · โสต) + 2 สีสำรอง · ลำดับตามคลินิกใน visit (e2oClinicTone)
   .emr2-row = ช่องกลางใช้ป้ายสีเดียวกัน (e2Tone ใน emr2_soap · พี่เลือกแบบ ก 2026-10-23) */
.emr2-row,.emr2-order-tabs,.emr2-cost{--c0-fg:#0d6b62;--c0-bg:#e2f3f0;--c1-fg:#3b34b8;--c1-bg:#ebe9fc;--c2-fg:#8a4600;--c2-bg:#fdeedd;--c3-fg:#1d5fbf;--c3-bg:#e7effc;--c4-fg:#9b2c6f;--c4-bg:#fbe7f2}
html.dark .emr2-row,html.dark .emr2-order-tabs,html.dark .emr2-cost{--c0-fg:#7fdccf;--c0-bg:rgba(45,180,160,.18);--c1-fg:#b9b4ff;--c1-bg:rgba(130,120,255,.2);--c2-fg:#ffc285;--c2-bg:rgba(255,160,70,.18);--c3-fg:#8fb6ff;--c3-bg:rgba(76,141,255,.14);--c4-fg:#f0a6d2;--c4-bg:rgba(230,90,170,.16)}
.e2-tag{display:inline-flex;align-items:center;font-size:12px;font-weight:600;padding:1px 9px;border-radius:999px;white-space:nowrap;background:var(--c0-bg);color:var(--c0-fg)}
.e2-tag.is-c1{background:var(--c1-bg);color:var(--c1-fg)}
.e2-tag.is-c2{background:var(--c2-bg);color:var(--c2-fg)}
.e2-tag.is-c3{background:var(--c3-bg);color:var(--c3-fg)}
.e2-tag.is-c4{background:var(--c4-bg);color:var(--c4-fg)}

/* ── ความสูง: เนื้อในแท็บเลื่อน · ปุ่มล่างอยู่กับที่ ──
   DOM จริง (initcraft tab-render + StaticContentWrapper): .el-tabs__content > .el-tab-pane > .field-wrapper > .static-content-item.emr2-orders > .e2o
   ⇒ ส่ง flex ลงไปทีละชั้นด้วยชื่อคลาสที่รู้แน่ (§🧠 ข้อ 10) · แท็บที่ซ่อน el-tabs ใส่ display:none แบบ inline ชนะเอง
   .static-content-item มี display inline จากแพลตฟอร์ม ⇒ !important · คลาส mb15 เดิมของการ์ด ⇒ ล้าง margin */
@media (min-width:1200px){
  .emr2-order-tabs>.el-tabs__content>.el-tab-pane:has(>.field-wrapper>.emr2-orders){height:100%;display:flex;flex-direction:column}
  .emr2-order-tabs .el-tab-pane>.field-wrapper:has(>.emr2-orders){flex:1 1 auto;min-height:0;display:flex;flex-direction:column}
  .emr2-order-tabs .static-content-item.emr2-orders{flex:1 1 auto;min-height:0;display:flex!important;flex-direction:column}
  .emr2-orders>.e2o{flex:1 1 auto;min-height:0}
  .e2o-list{flex:1 1 auto;min-height:0;overflow-y:auto;overscroll-behavior:contain;scrollbar-width:thin}
}
.emr2-order-tabs .static-content-item.emr2-orders{margin:0!important}
/* tab-render.vue (scoped) ใส่ .el-tabs__content{padding-bottom:5px} ให้ทุกแท็บของแพลตฟอร์ม
   ⇒ ใต้แถบปุ่มล่างกว้างกว่าด้านบน 5px (พี่วัดจอจริง 8 / 13 · console.table 2026-10-23) — แท็บนี้ไม่ต้องมี */
.emr2-order-tabs>.el-tabs__content{padding-bottom:0!important}

/* ── กล่องแท็บ = การ์ดเดียว (mockup: background panel · border line · radius 12) ── */
/* 🔴 tab-render ใส่ customClass ทั้งกล่องนอก (.container-wrapper) และ el-tabs ข้างใน (§🧠 ข้อ 12)
   ใส่กรอบแบบไม่ระบุชั้น = กรอบซ้อน 2 เส้น + ช่องว่างระหว่างกรอบ (พี่เห็นบนจอจริง 2026-10-23: เส้นหนา · ระยะล่างไม่เท่าบน)
   ⇒ กรอบ/พื้นอยู่ที่ .el-tabs ตัวเดียว */
.el-tabs.emr2-order-tabs{background:var(--e2-panel);border:1px solid var(--e2-line);border-radius:12px;overflow:hidden;color:var(--e2-text)}
/* ไฮไลต์ตอนกดป้ายวัคซีนบนหัวคนไข้ (emr2OpenVxTab ใน frame/head-addon.js · พี่สั่ง 2026-10-23 "มี effect ไฮไลบอกเวลากด")
   กระพริบที่หัวแท็บ "วัคซีน" (พี่ชี้ภาพ) — พื้นเขียวจาง + กรอบเขียวด้านใน ค่อยๆ ขึ้น-ลง 3 รอบ รอบละ 0.9 วิ
   (รุ่นแรก 2 ครั้งใน 1.3 วิ พี่บอก "ไวมาก มองไม่ทัน" 2026-10-23) · ความยาวรวมต้องตรงกับ setTimeout ใน head-addon.js */
@keyframes emr2-flash{0%,100%{background:transparent;box-shadow:inset 0 0 0 2px transparent}50%{background:var(--e2-brand-bg);box-shadow:inset 0 0 0 2px var(--e2-brand)}}
.emr2-order-tabs .el-tabs__item.emr2-flash{animation:emr2-flash .9s ease-in-out 3;border-radius:6px}
/* หัวแท็บ = แท็บเส้นใต้แบบแท็บย่อย ยา · Lab · X-Ray ของช่องซ้าย (.e2h-sub ใน history/emr2-hist.css · พี่สั่ง 2026-10-23 ส่งภาพ)
   ⇒ ไม่ตาม mockup board 4 แล้ว (เดิมเป็นปุ่มเม็ด) · ความกว้างตามข้อความ ชิดซ้าย · สูง 44 เท่าหัวแท็บช่องซ้าย (หัวสองช่องเสมอกัน) */
.emr2-order-tabs>.el-tabs__header{margin:0!important;padding:0 8px;border-bottom:1px solid var(--e2-line)}
.emr2-order-tabs .el-tabs__nav-wrap::after,.emr2-order-tabs .el-tabs__active-bar{display:none}
.emr2-order-tabs .el-tabs__nav{gap:2px}
/* ปุ่มแท็บ: font 14 · padding 10/8 · สูงขั้นต่ำ 44 · ปกติ muted · เลือกอยู่ = accentText + 600 + เส้นล่าง 2px accent
   เส้นใต้วาดที่ปุ่มเอง (ไม่ใช้ active-bar ของ EP — ท่าเดียวกับแท็บช่องซ้าย) */
.emr2-order-tabs .el-tabs__item{height:auto;min-height:44px;line-height:1.4;padding:10px 8px!important;font-size:14px;font-weight:400;color:var(--e2-muted);border-bottom:2px solid transparent}
.emr2-order-tabs .el-tabs__item:hover{color:var(--e2-text)}
.emr2-order-tabs .el-tabs__item.is-active{color:var(--e2-accent-text);font-weight:600;border-bottom-color:var(--e2-accent)}
/* ป้ายจำนวน = ป้ายเม็ดแบบแท็บ "ทะเบียนโรค" ช่องซ้าย (พี่สั่ง 2026-10-23): margin 6 · font 11 · 600 · padding 0/7 · pill
   เลือกอยู่ accentBg/accentText · ไม่เลือก panel2/muted
   ตัวเลขมาจาก data-e2o-n ที่ order_card เขียนลงปุ่มแท็บ (orders/tab-count.js) · ไม่มีค่า = ไม่มีป้าย */
.emr2-order-tabs .el-tabs__item[data-e2o-n]::after{content:attr(data-e2o-n);margin-left:6px;font-size:11px;font-weight:600;padding:0 7px;border-radius:999px;line-height:18px;background:var(--e2-panel2);color:var(--e2-muted)}
.emr2-order-tabs .el-tabs__item.is-active[data-e2o-n]::after{background:var(--e2-accent-bg);color:var(--e2-accent-text)}

/* ── เนื้อในแท็บ ── */
.e2o{display:flex;flex-direction:column;font-size:14px;line-height:1.5;color:var(--e2-text);background:var(--e2-panel)}
.e2o .el-icon{vertical-align:-2px}
.e2o-muted{color:var(--e2-muted);font-size:12px}
.e2o-ico{display:inline-flex;align-items:center;gap:4px}
.e2o-empty{padding:16px 14px;font-size:13px;color:var(--e2-muted)}
.e2o-err{margin:10px 14px 0;padding:8px 10px;border-radius:8px;background:var(--e2-danger-bg);color:var(--e2-danger);font-size:13px}

/* หัวกลุ่มคลินิก: padding 10/14/0 · ป้ายคลินิก + "ใบของคลินิกอื่น" */
.e2o-clinic{padding:10px 14px 0;display:flex;align-items:center;gap:8px}
.e2o-lockt{display:inline-flex;align-items:center;gap:4px;font-size:12px;color:var(--e2-muted)}
.e2o-group{padding:8px 14px 4px;display:flex;flex-direction:column;gap:8px}

/* ใบสั่ง: radius 10 · border line (กางอยู่ = accent) · ใบคลินิกอื่นพื้น lock · ยกเลิก = จาง */
.e2o-ord{border-radius:10px;overflow:hidden;border:1px solid var(--e2-line);background:var(--e2-panel)}
.e2o-ord.is-open{border-color:var(--e2-accent)}
.e2o-ord.is-other{background:var(--e2-lock)}
.e2o-ord.is-cancel{opacity:.55}
.e2o-ord.is-cancel .e2o-no{text-decoration:line-through}
.e2o-ord-head{padding:9px 12px;display:flex;flex-direction:column;gap:3px;font-size:14px;cursor:pointer}
.e2o-row1{display:flex;align-items:center;gap:6px;flex-wrap:wrap}
.e2o-no{font-weight:600}
.e2o-no.is-nono{font-weight:500;color:var(--e2-muted)}
.e2o-type{font-size:11px;padding:0 6px;border-radius:5px;border:1px solid var(--e2-line);white-space:nowrap}
.e2o-status{margin-left:auto}
.e2o-chev{flex:none;color:var(--e2-muted);font-size:14px;transition:transform .15s}
.e2o-chev.is-open{transform:rotate(180deg)}
.e2o-row2{display:flex;align-items:center;gap:6px;font-size:12px;color:var(--e2-muted)}
.e2o-ell{flex:1 1 auto;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.e2o-total{flex:none;margin-left:auto;font-size:14px;font-weight:600;color:var(--e2-text);font-variant-numeric:tabular-nums}
.e2o-row3{display:flex;justify-content:flex-end;gap:10px;font-size:12px;color:var(--e2-muted);font-variant-numeric:tabular-nums}
.e2o-pay{color:var(--e2-danger)}
.e2o-pay.is-due{font-weight:700}

/* ป้ายสถานะ (pill ของ mockup: font 11 · 600 · padding 1/8) — คลาส is-<สี el-tag เดิม> จาก e2oTone()
   info/primary = accent · warning = warn · success = ok · danger = danger (ตาม toneBg/toneText ของ mockup) */
.e2o-pill{flex:none;font-size:11px;font-weight:600;padding:1px 8px;border-radius:999px;white-space:nowrap;background:var(--e2-accent-bg);color:var(--e2-accent-text)}
.e2o-pill.is-warning{background:var(--e2-warn-bg);color:var(--e2-warn)}
.e2o-pill.is-success{background:var(--e2-ok-bg);color:var(--e2-ok)}
.e2o-pill.is-danger{background:var(--e2-danger-bg);color:var(--e2-danger)}
.e2o-pill.is-solid{background:var(--e2-danger);color:#fff}
/* ยกเลิก = ส้ม (orders-addon E2O_STATUS_TONE · พี่สั่ง 2026-10-23) — ค่าสีชุดส้มของป้ายคลินิก c2 ใน mockup */
.e2o-pill.is-orange{background:var(--c2-bg);color:var(--c2-fg)}
.e2o-pill .el-icon{margin-right:3px;vertical-align:-1px}
.e2o-type.is-success{color:var(--e2-ok)}
.e2o-type.is-warning{color:var(--e2-warn)}
.e2o-type.is-danger{color:var(--e2-danger)}
.e2o-type.is-primary,.e2o-type.is-info{color:var(--e2-accent-text)}

/* รายการในใบ (กาง): border-top dashed · padding 8/12/10 · gap 7 · font 13 */
.e2o-body{border-top:1px dashed var(--e2-line);padding:8px 12px 10px;display:flex;flex-direction:column;gap:7px}
.e2o-item-row{display:flex;align-items:center;gap:8px;font-size:13px;cursor:pointer}
.e2o-item-name{flex:1 1 auto;min-width:0}
.e2o-num{flex:none;font-variant-numeric:tabular-nums;white-space:nowrap}
.e2o-item-price{display:flex;flex-wrap:wrap;justify-content:flex-end;gap:4px 12px;font-size:12px;color:var(--e2-muted)}
.e2o-item-price .is-warn{color:var(--e2-warn)}
.e2o-note{font-size:12px;color:var(--e2-muted)}
.e2o-note.is-warn{color:var(--e2-warn)}

/* แถวปุ่ม (mockup): ลบใบนี้ = ตัวอักษรแดงชิดซ้าย · แก้ใบนี้ = ขอบ line · ส่ง = พื้น accent ตัวขาว · ยกเลิกใบ = ขอบแดง
   ปุ่มทั้งหมด font 13 · radius 7 · padding 4/12 · สูงขั้นต่ำ 32 */
.e2o-acts{display:flex;align-items:center;gap:8px;flex-wrap:wrap;padding-top:4px}
.e2o-acts-note{font-size:12px;color:var(--e2-muted)}
.e2o-acts-gap{flex:1 1 0}
/* ขนาด xs ทุกแท็บ (พี่สั่ง 2026-10-22 "ปุ่มใหญ่ไป ใช้แบบ xs ทุกแท็บ จะได้ประหยัดพื้นที่") — สูง 24 · font 12 · padding 0/10 */
.e2o-btn{font:inherit;font-size:12px;line-height:1;border:1px solid var(--e2-line);background:transparent;color:var(--e2-text);border-radius:6px;padding:0 10px;cursor:pointer;height:24px;white-space:nowrap}
.e2o-btn.is-main{font-weight:600;border-color:transparent;background:var(--e2-accent);color:#fff}
.e2o-btn.is-danger{border-color:var(--e2-danger);color:var(--e2-danger)}
.e2o-btn.is-link{border:none;padding:0;color:var(--e2-danger)}
.e2o-btn.is-accent{color:var(--e2-accent-text)}
.e2o-btn:disabled{opacity:.5;cursor:not-allowed}

/* กล่องยืนยัน / คำเตือน / ใบที่ถูกยกเลิก */
.e2o-box{padding:8px 10px;border-radius:8px;background:var(--e2-panel2);font-size:12px;line-height:1.5}
.e2o-box.is-danger{background:var(--e2-danger-bg)}
.e2o-box.is-warn{background:var(--e2-warn-bg)}
.e2o-box-t{margin-bottom:6px}
.e2o-danger{color:var(--e2-danger)}
.e2o-text{width:100%;box-sizing:border-box;font:inherit;font-size:13px;line-height:1.5;padding:6px 8px;border-radius:7px;resize:vertical;color:var(--e2-text);background:var(--e2-panel);border:1px solid var(--e2-line)}
.e2o-box-foot{display:flex;align-items:center;gap:8px;margin-top:6px;flex-wrap:wrap}
.e2o-len{flex:1 1 auto;font-size:11px;color:var(--e2-muted)}
.e2o-len.is-short{color:var(--e2-danger)}

/* ท้ายแท็บ (อยู่กับที่): padding 8/14 · border-top line · ปุ่มเพิ่ม = dashed ok · okBg · ok · font 13 600 · สูง 34 */
.e2o-foot{flex:0 0 auto;display:flex;align-items:center;gap:10px;padding:8px 14px;border-top:1px solid var(--e2-line);background:var(--e2-panel)}
.e2o-add{flex:1 1 auto;font:inherit;font-size:12px;line-height:1;font-weight:600;border:1px dashed var(--e2-ok);background:var(--e2-ok-bg);color:var(--e2-ok);border-radius:6px;padding:0 10px;cursor:pointer;height:24px}
.e2o-reload{flex:0 0 auto;font:inherit;font-size:12px;border:none;background:transparent;color:var(--e2-muted);cursor:pointer;height:24px;padding:0}
.e2o-add:disabled,.e2o-reload:disabled{opacity:.5;cursor:not-allowed}

/* ── วัคซีน (mockup: padding 10/14 · gap 10 · หัวกลุ่ม 12/600/muted · แถว dashed) ── */
.e2v{padding:10px 14px;display:flex;flex-direction:column;gap:10px}
.e2v-alert{padding:6px 10px;border-radius:8px;font-size:12px;background:var(--e2-warn-bg);color:var(--e2-warn)}
.e2v-alert.is-red{background:var(--e2-danger-bg);color:var(--e2-danger)}
.e2v-alert.is-gray{background:var(--e2-panel2);color:var(--e2-muted)}
.e2v-grp{display:flex;flex-direction:column}
.e2v-grp-t{font-size:12px;font-weight:600;color:var(--e2-muted);padding-bottom:2px}
.e2v-row{display:flex;flex-direction:column;gap:2px;padding:7px 0;border-bottom:1px dashed var(--e2-line)}
.e2v-pick{display:flex;align-items:center;gap:8px;cursor:pointer;min-height:28px;margin:0}
.e2v-pick input{width:16px;height:16px;accent-color:var(--e2-accent);flex:0 0 auto;margin:0}
.e2v-th{font-weight:600}
.e2v-short{font-size:12px;color:var(--e2-muted);min-width:0}
.e2v-chip{margin-left:auto;font-size:11px;font-weight:600;padding:1px 8px;border-radius:999px;white-space:nowrap;background:var(--e2-warn-bg);color:var(--e2-warn)}
.e2v-chip.is-overdue{background:var(--e2-danger-bg);color:var(--e2-danger)}
.e2v-chip.is-caution{border:1px dashed var(--e2-warn)}
.e2v-chip.is-opt{background:var(--e2-purple-bg);color:var(--e2-purple)}
.e2v-why{font-size:12px;color:var(--e2-warn);padding-left:24px}
.e2v-rec{font-size:12px;color:var(--e2-purple);padding-left:24px}
.e2v-conf{display:flex;align-items:center;gap:8px;padding-left:24px;font-size:12px;cursor:pointer;margin:0}
.e2v-conf input{width:14px;height:14px;accent-color:var(--e2-accent);margin:0}
.e2v-more{display:inline-flex;align-items:center;gap:4px;font-size:12px;color:var(--e2-muted);cursor:pointer;user-select:none}
.e2v-sum{padding:8px 10px;border-radius:8px;background:var(--e2-panel2);font-size:13px}
.e2v-sum b{color:var(--e2-text)}
.e2v-done{padding:8px 10px;border-radius:8px;background:var(--e2-accent-bg);color:var(--e2-accent-text);font-size:13px;font-weight:600}
.e2v-done.is-given{background:var(--e2-ok-bg);color:var(--e2-ok)}

/* ── นัด (mockup: การ์ดแถว radius 10 · border line · padding 9/12) ── */
.e2a{padding:10px 14px;display:flex;flex-direction:column;gap:8px}
.e2a-row{display:flex;flex-direction:column;gap:4px;width:100%;text-align:left;cursor:pointer;border:1px solid var(--e2-line);border-radius:10px;background:var(--e2-panel);color:var(--e2-text);padding:9px 12px;font:inherit;font-size:14px}
.e2a-row.is-dead{opacity:.55}
.e2a-row.is-dead .e2a-no{text-decoration:line-through}
.e2a-l1,.e2a-l2{display:flex;align-items:center;gap:6px;width:100%}
.e2a-l2{gap:8px;font-size:13px}
.e2a-no{font-weight:600;white-space:nowrap}
/* ชื่อคลินิกนัดยาว ("พรีเมี่ยมคลินิก (โรคทางเดินอาหาร)") ดันเลขใบตกบรรทัด ⇒ ตัดชื่อด้วย … แทน */
.e2a-l1>.e2o-muted{flex:1 1 auto;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.e2a-go{margin-left:auto;color:var(--e2-muted)}

/* ── การ์ดค่าใช้จ่าย (mockup: panel · border line · radius 12 · padding 10/14 · gap 6 · grid 1fr 72 72 64 gap 8) ── */
.e2c{background:var(--e2-panel);border:1px solid var(--e2-line);border-radius:12px;padding:10px 14px;display:flex;flex-direction:column;gap:6px;font-size:14px;color:var(--e2-text)}
.e2c-head{display:flex;justify-content:space-between;align-items:center}
.e2c-head b{font-weight:600}
.e2c-sub{font-size:12px;color:var(--e2-muted)}
.e2c-row{display:grid;grid-template-columns:minmax(0,1fr) 72px 72px 64px;gap:8px;align-items:center;font-size:13px;font-variant-numeric:tabular-nums;text-align:right}
.e2c-row>:first-child{text-align:left}
.e2c-row.is-head{font-size:11px;color:var(--e2-muted)}
.e2c-row.is-total{border-top:1px solid var(--e2-line);padding-top:6px;font-weight:600}
/* รวมเฉพาะยา (พี่สั่งเพิ่ม 2026-10-22 "อย่าลืม รวมเฉพาะยาด้วย") — ใต้รวมทั้งหมด สีรอง */
.e2c-row.is-drug{color:var(--e2-muted)}
.e2c-wait{grid-column:2 / span 3;text-align:left;color:var(--e2-muted)}
.e2c-pay{color:var(--e2-danger)}
.e2c-pay.is-due{font-weight:700}
.e2c-note{font-size:11px;color:var(--e2-muted)}
/* emr2-hist · ช่องซ้าย EMR v2 — ลอกจาก mockup board 4 (design/emr-multiclinic/mockup/EMRv2.dc.html · ธีมเขียว รพ.)
   การ์ด PMH (box_mhistory) · แท็บ ประวัติครั้งก่อน | ทะเบียนโรค (emr2_hist_tabs) · ปุ่มพับช่อง → แถบตั้ง "ประวัติการรักษา"
   generator ต่อท้ายใน formConfig.cssCode ช่วง marker EMR v2 · ค่าสี/ขนาดยกจาก mockup ตรง ๆ — จะเปลี่ยน แก้ mockup ก่อน
   token ชุดเดียวกับช่องขวา (orders/emr2-orders.css): พื้น/เส้น/ตัวอักษร = ตัวแปร EP · เขียวหลัก = --e2-brand ของ .emr2-row
   สีสถานะ = ของ mockup (.emr.light.green / .emr.green) · ธีมมืดของแอป = html.dark */

/* ── token ── */
.emr2-col-left{--e2-panel:var(--el-bg-color);--e2-panel2:var(--el-fill-color-light);--e2-line:var(--el-border-color-lighter);--e2-text:var(--el-text-color-primary);--e2-muted:var(--el-text-color-secondary);
  --e2-accent:var(--e2-brand);--e2-accent-text:var(--e2-brand-text);--e2-accent-bg:var(--e2-brand-bg);
  --e2-danger:#b4261e;--e2-danger-bg:#fdecea;--e2-warn:#8a5300;--e2-warn-bg:#fff4d6;--e2-ok:#1c6b3a;--e2-ok-bg:#e5f3ea}
html.dark .emr2-col-left{--e2-danger:#ff8a80;--e2-danger-bg:rgba(255,107,107,.13);--e2-warn:#f5c451;--e2-warn-bg:rgba(240,180,41,.13);--e2-ok:#62d39b;--e2-ok-bg:rgba(76,195,138,.14)}

/* ระยะระหว่างการ์ดในช่อง = gap 12 ของ mockup · ContainerRenderWrapper ใส่ margin-bottom:15px แบบ inline ⇒ !important */
.emr2-col-left>.container-wrapper{margin-bottom:12px!important}

/* ── การ์ด PMH (box_mhistory · คลาส e2h-card) — panel · เส้น line · radius 12 · ไม่มีเงา
   🔴 card-render ใส่ customClass ทั้ง .container-wrapper และ .el-card ⇒ ระบุ .el-card เสมอ (บทเรียนเดียวกับแท็บช่องขวา) */
.el-card.e2h-card{background:var(--e2-panel)!important;border:1px solid var(--e2-line)!important;border-radius:12px!important;box-shadow:none!important;overflow:hidden;color:var(--e2-text)}
.el-card.e2h-card>.el-card__header{padding:10px 12px!important;border-bottom:none!important}
.el-card.e2h-card .card-header{font-weight:400}
.el-card.e2h-card .wcard-head{gap:10px}
.el-card.e2h-card .wcard-icon{width:34px;height:34px;border-radius:9px;background:var(--e2-accent-bg);color:var(--e2-accent-text)}
.el-card.e2h-card .wcard-icon svg{width:17px;height:17px}
.el-card.e2h-card .wcard-titles{gap:0;line-height:1.25}
.el-card.e2h-card .wcard-title{font-size:14px;font-weight:600;line-height:1.25;color:var(--e2-text)}
.el-card.e2h-card .wcard-sub{font-size:11px;font-weight:400;letter-spacing:.08em;color:var(--e2-muted)}
.el-card.e2h-card .card-header>.el-icon--right{font-size:16px;color:var(--e2-muted)}
/* เนื้อการ์ด PMH (m_history · history/pmh.content.html) — "ข้อ A กล่องย่อย + เส้นคั่น" (พี่เลือก 2026-10-23 รอบสอง)
   หัวข้อ 13 muted + ตัวนับเม็ด · กล่องพื้น panel2 radius 8 · แถว 14 คั่นเส้น line · ระยะเวลา 12 muted · ปุ่มดินสอ 28 ขอบบาง · เวลาอัปเดต 12 ท้ายการ์ด */
.e2h-pmh{font-size:14px;line-height:1.5;color:var(--e2-text)}
.e2h-pmh-head{display:flex;align-items:center;gap:6px;min-height:28px;margin-bottom:6px;font-size:13px;color:var(--e2-muted)}
.e2h-pmh-n{font-size:11px;font-weight:600;padding:0 7px;border-radius:999px;line-height:18px;background:var(--e2-panel2);color:var(--e2-muted)}
/* ตัวนับหัวการ์ด PMH (history/pmh-addon.js เขียน data-e2h-n · พี่เลือกข้อ A 2026-10-24) — เม็ดเดียวกับ .e2h-pmh-n */
.el-card.e2h-pmh-card .wcard-title[data-e2h-n]::after{content:attr(data-e2h-n);display:inline-block;margin-left:6px;vertical-align:1px;font-size:11px;font-weight:600;padding:0 7px;border-radius:999px;line-height:18px;background:var(--e2-panel2);color:var(--e2-muted)}
.e2h-pmh-edit{margin-left:auto;flex:none;width:28px;height:28px;padding:0;border:1px solid var(--e2-line);border-radius:6px;background:transparent;color:var(--e2-muted);cursor:pointer;display:inline-flex;align-items:center;justify-content:center}
.e2h-pmh-edit:hover{color:var(--e2-accent-text);border-color:var(--e2-accent)}
.e2h-pmh-edit .svg-icon,.e2h-pmh-edit svg{width:15px;height:15px}
.e2h-pmh-box{background:var(--e2-panel2);border-radius:8px;padding:2px 12px;margin-bottom:12px}
.e2h-pmh-row{display:flex;align-items:baseline;gap:8px;padding:6px 0}
.e2h-pmh-row+.e2h-pmh-row{border-top:1px solid var(--e2-line)}
.e2h-pmh-item{flex:1;min-width:0;overflow-wrap:anywhere}
.e2h-pmh-year{flex:none;font-size:12px;color:var(--e2-muted)}
.e2h-pmh-none{padding:6px 0;font-size:13px;color:var(--e2-muted)}
.e2h-pmh-stamp{font-size:12px;line-height:1.4;color:var(--e2-muted)}
.e2h-pmh-by{display:inline-block}
/* body-style ของ card-render เป็น inline (15/15/5/15) ⇒ !important · พับอยู่ card-render ซ่อน body เอง */
.el-card.e2h-card:not(.folded)>.el-card__body{padding:10px 12px 12px!important;border-top:1px solid var(--e2-line)}

/* ── กล่องแท็บ = การ์ดเดียว (mockup: panel · border line · radius 12) ──
   🔴 tab-render ใส่ customClass ทั้ง .container-wrapper และ .el-tabs ⇒ กรอบอยู่ที่ .el-tabs ตัวเดียว */
.el-tabs.emr2-hist-tabs{background:var(--e2-panel);border:1px solid var(--e2-line);border-radius:12px;overflow:hidden;color:var(--e2-text)}
/* หัวแท็บ: padding 0/4/0/8 · เส้นล่าง line · ปุ่ม ‹ ท้ายแถว (hist-addon.js แปะ .e2h-fold)
   🔴 แท็บช่องขวา (.emr2-order-tabs ใน orders/emr2-orders.css) ใช้แบบเดียวกับตรงนี้ (พี่สั่ง 2026-10-23) — แก้ที่หนึ่งต้องแก้อีกที่ */
.emr2-hist-tabs>.el-tabs__header{margin:0!important;padding:0 4px 0 8px;border-bottom:1px solid var(--e2-line);display:flex;align-items:center}
.emr2-hist-tabs>.el-tabs__header>.el-tabs__nav-wrap{flex:1 1 auto;min-width:0}
.emr2-hist-tabs>.el-tabs__header .el-tabs__nav-wrap::after,.emr2-hist-tabs>.el-tabs__header .el-tabs__active-bar{display:none}
.emr2-hist-tabs>.el-tabs__header .el-tabs__nav{width:100%;float:none;display:flex}
/* แท็บเส้นใต้ แบ่งครึ่งเท่ากัน: font 14 · padding 10/8 · สูงขั้นต่ำ 44 · ปกติ muted · เลือกอยู่ = accentText + 600 + เส้นล่าง 2px accent
   เส้นใต้วาดที่ปุ่มเอง (ไม่ใช้ active-bar ของ EP ซึ่งวัดความกว้างตอน render — ตอนช่องพับอยู่วัดได้ 0) */
.emr2-hist-tabs>.el-tabs__header .el-tabs__item{flex:1 1 0;justify-content:center;gap:6px;height:auto;min-height:44px;line-height:1.4;padding:10px 8px!important;font-size:14px;font-weight:400;color:var(--e2-muted);border-bottom:2px solid transparent}
.emr2-hist-tabs>.el-tabs__header .el-tabs__item:hover{color:var(--e2-text)}
.emr2-hist-tabs>.el-tabs__header .el-tabs__item.is-active{color:var(--e2-accent-text);font-weight:600;border-bottom-color:var(--e2-accent)}
/* ป้ายจำนวนทะเบียนโรค: font 11 · 600 · padding 0/7 · pill · เลือกอยู่ accentBg/accentText · ไม่เลือก panel2/muted
   ตัวเลขมาจาก data-e2h-n ที่ registry_card เขียนลงปุ่มแท็บ (history/reg-badge.js) */
.emr2-hist-tabs>.el-tabs__header .el-tabs__item[data-e2h-n]::after{content:attr(data-e2h-n);font-size:11px;font-weight:600;padding:0 7px;border-radius:999px;line-height:18px;background:var(--e2-panel2);color:var(--e2-muted)}
.emr2-hist-tabs>.el-tabs__header .el-tabs__item.is-active[data-e2h-n]::after{background:var(--e2-accent-bg);color:var(--e2-accent-text)}
.e2h-fold{flex:none;width:32px;height:32px;padding:0;border:none;background:transparent;color:var(--e2-muted);cursor:pointer;display:inline-flex;align-items:center;justify-content:center}
.e2h-fold:hover{color:var(--e2-text)}
/* เนื้อในแท็บ: padding 10/12/12 · tab-render (scoped) ใส่ padding-bottom 5px ทุกแท็บ ⇒ !important */
.emr2-hist-tabs>.el-tabs__content{padding:10px 12px 12px!important}
/* การ์ดสรุปการรักษาเดิม (card62530 · คลาส e2h-plain) อยู่ในแท็บแล้ว — ถอดกรอบ/หัว/เงา เหลือแค่เนื้อ */
.container-wrapper.e2h-plain{margin-bottom:0!important}
.el-card.e2h-plain{border:none!important;border-radius:0!important;box-shadow:none!important;background:transparent!important}
.el-card.e2h-plain>.el-card__header{display:none}
.el-card.e2h-plain>.el-card__body{padding:0!important;background:transparent}
.emr2-hist-tabs .static-content-item{margin:0!important}

/* ── เนื้อร่วม ── */
.e2h-ts,.e2h-reg{font-size:14px;line-height:1.5;color:var(--e2-text)}
.e2h-muted{font-size:12px;color:var(--e2-muted)}
.e2h-empty{padding:4px 0;font-size:12px;color:var(--e2-muted)}
.e2h-err{margin-bottom:8px;padding:8px 10px;border-radius:8px;background:var(--e2-danger-bg);color:var(--e2-danger);font-size:13px}
/* ปุ่มขอบบาง (ดูทั้งใบ · + Add): font 12 · border line · radius 6 · padding 2/10 · สูงขั้นต่ำ 28 */
.e2h-btn{flex:0 0 auto;font-family:inherit;font-size:12px;border:1px solid var(--e2-line);background:transparent;color:var(--e2-text);border-radius:6px;padding:2px 10px;cursor:pointer;min-height:28px}
.e2h-btn:hover{border-color:var(--e2-accent)}

/* ── ประวัติครั้งก่อน (treat_summary · คลาส e2h-ts) ── */
.e2h-last-head{display:flex;justify-content:space-between;align-items:center;gap:8px;margin-bottom:10px}
.e2h-last-txt{display:flex;flex-direction:column;min-width:0}
.e2h-ell{font-size:13px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
/* ปุ่มสลับคลินิกของครั้งก่อน (C12 · ข้อ ค) — ตัวที่เลือกใช้สี tone คลินิก --cN-* (ประกาศบน .emr2-row ใน orders/emr2-orders.css) */
.e2h-sheets{display:flex;flex-wrap:wrap;gap:6px;margin:-2px 0 10px}
.e2h-sheet{font-family:inherit;font-size:12px;border:1px solid var(--e2-line);background:transparent;color:var(--e2-muted);border-radius:999px;padding:1px 10px;cursor:pointer;min-height:26px}
.e2h-sheet:hover{border-color:var(--e2-accent)}
.e2h-sheet.is-on{font-weight:600;border-color:transparent;background:var(--c0-bg);color:var(--c0-fg)}
.e2h-sheet.is-on.is-c1{background:var(--c1-bg);color:var(--c1-fg)}
.e2h-sheet.is-on.is-c2{background:var(--c2-bg);color:var(--c2-fg)}
.e2h-sheet.is-on.is-c3{background:var(--c3-bg);color:var(--c3-fg)}
.e2h-sheet.is-on.is-c4{background:var(--c4-bg);color:var(--c4-fg)}
/* หัวข้อ: ไอคอน 14 + ชื่อ 12/600 + วันที่ 11 muted ชิดขวา · เนื้อเยื้อง 20
   สี = สี badge SOAP ของช่องกลาง (.e2s-badge.is-s/o/a ใน soap/emr2-soap.css · พี่สั่ง 2026-10-23) — เปลี่ยนที่นั่นต้องเปลี่ยนที่นี่ด้วย */
.e2h-sec{display:flex;flex-direction:column;gap:2px;margin-bottom:10px}
.e2h-sec-h{display:flex;align-items:center;gap:6px;font-size:12px;font-weight:600}
.e2h-sec-h .svg-icon,.e2h-sec-h .el-icon{font-size:14px;width:14px;height:14px}
.e2h-sec-h .svg-icon svg{width:14px;height:14px}
.e2h-sec-h.is-s{color:var(--el-color-primary)}
.e2h-sec-h.is-o{color:var(--el-color-success)}
.e2h-sec-h.is-a{color:var(--el-color-warning)}
.e2h-date{margin-left:auto;font-size:11px;font-weight:400;color:var(--e2-muted)}
.e2h-sec-b{padding-left:20px;overflow-wrap:anywhere}
.e2h-pre{white-space:pre-line}
.e2h-click,.e2h-dx,.e2h-med{cursor:pointer}
.e2h-pe{display:flex;align-items:baseline;gap:8px}
.e2h-pe-n{flex:none;min-width:84px;color:var(--e2-muted)}
.e2h-pe-v{flex:1;min-width:0;overflow-wrap:anywhere}
.e2h-pe-v.is-bad{color:var(--e2-danger)}
.e2h-pe-note{margin-top:4px;font-size:13px;overflow-wrap:anywhere}
.e2h-dx{display:flex;align-items:baseline;gap:6px}
/* ป้าย "หลัก": font 11 · padding 0/6 · radius 5 · ขอบ danger · ตัว danger 600 */
.e2h-main{flex:none;font-size:11px;padding:0 6px;border-radius:5px;border:1px solid var(--e2-danger);color:var(--e2-danger);font-weight:600}

/* แท็บย่อย ยา / Lab / X-Ray / หัตถการ: เส้นใต้ · font 13 · padding 6/8 · สูงขั้นต่ำ 32 · เส้นคั่นล่าง line · margin-top 4 */
.el-tabs.e2h-sub>.el-tabs__header{margin:4px 0 8px;border-bottom:1px solid var(--e2-line)}
.el-tabs.e2h-sub>.el-tabs__header .el-tabs__nav-wrap::after,.el-tabs.e2h-sub>.el-tabs__header .el-tabs__active-bar{display:none}
.el-tabs.e2h-sub>.el-tabs__header .el-tabs__nav{gap:2px}
.el-tabs.e2h-sub>.el-tabs__header .el-tabs__item{height:auto;min-height:32px;line-height:1.4;padding:6px 8px!important;font-size:13px;font-weight:400;color:var(--e2-muted);border-bottom:2px solid transparent}
.el-tabs.e2h-sub>.el-tabs__header .el-tabs__item:hover{color:var(--e2-text)}
.el-tabs.e2h-sub>.el-tabs__header .el-tabs__item.is-active{color:var(--e2-accent-text);font-weight:600;border-bottom-color:var(--e2-accent)}
/* ตัวนับแท็บย่อย (ยา) — ป้ายเม็ดชุดเดียวกับตัวเลข "ทะเบียนโรค" ข้างบน (พี่สั่ง 2026-10-23) */
.el-tabs.e2h-sub .e2h-n{margin-left:6px;font-size:11px;font-weight:600;padding:0 7px;border-radius:999px;line-height:18px;background:var(--e2-panel2);color:var(--e2-muted)}
.el-tabs.e2h-sub .el-tabs__item.is-active .e2h-n{background:var(--e2-accent-bg);color:var(--e2-accent-text)}
/* รายการยา: gap 6 · ชื่อ 14 · sig 12 muted */
.e2h-meds{display:flex;flex-direction:column;gap:6px}
.e2h-med-r{display:flex;align-items:baseline;gap:8px}
.e2h-med-n{flex:1;min-width:0;overflow-wrap:anywhere}

/* ── ทะเบียนโรค (registry_card · .e2h-reg) ── */
/* ทุกแถว (หัว + รายการ) ห่างกัน gap 10 ตาม mockup */
.e2h-reg{display:flex;flex-direction:column;gap:10px}
.e2h-reg-h{display:flex;align-items:center;gap:8px;font-size:11px;letter-spacing:.06em;color:var(--e2-muted)}
/* แถว: padding 3/0 · gap 6 · ลงทะเบียนแล้ว = ชื่อ 600 + ×N + ป้ายสถานะ + › · ยังไม่ลง = ชื่อ muted + ปุ่ม + Add */
.e2h-reg-row{display:flex;align-items:center;gap:6px;width:100%;padding:3px 0;border:none;background:transparent;color:var(--e2-text);font-family:inherit;font-size:14px;text-align:left;cursor:pointer}
.e2h-reg-n{min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
button.e2h-reg-row .e2h-reg-n{font-weight:600}
.e2h-reg-row.is-off .e2h-reg-n{color:var(--e2-muted)}
.e2h-chev{margin-left:auto;color:var(--e2-muted)}
/* แถวหลายบรรทัด (ข้อ B · 2026-10-23): บรรทัดบน = ชื่อ ×N ป้าย › · ล่าง = ล่าสุดเมื่อไหร่/ใคร · เส้นสถานะ */
.e2h-reg-row.is-col{flex-direction:column;align-items:stretch;gap:3px}
.e2h-reg-top{display:flex;align-items:center;gap:6px;width:100%;min-width:0}
.e2h-reg-sub{font-size:12px;line-height:1.45;color:var(--e2-muted)}
/* ล่าสุด/คนบันทึก ชิดขวาบรรทัดบน — ชื่อโรคไม่หด ข้อความนี้หดแล้วตัด … · › ต่อท้ายติดกัน */
.e2h-reg-top .e2h-reg-n{flex:none;max-width:60%}
.e2h-reg-meta{margin-left:auto;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-size:12px;color:var(--e2-muted)}
.e2h-reg-meta+.e2h-chev{margin-left:4px}
.e2h-reg-tl{display:flex;align-items:center;gap:4px;flex-wrap:wrap;font-size:11px}
.e2h-reg-tl .e2h-muted{font-size:11px}
/* สถานะ primary (เช่น "กำลังรักษา") = ฟ้า — accent ของตัวงานเป็นเขียวเหมือน "หาย" อ่านแยกไม่ออกในเส้นสถานะ (ตาม mockup ข้อ B) */
.e2h-reg .e2h-pill.is-primary{background:var(--el-color-primary-light-9);color:var(--el-color-primary)}
.e2h-btn.is-add{margin-left:auto;padding:1px 8px;min-height:26px;color:var(--e2-accent-text)}
/* ป้ายสถานะ: font 11 · padding 0/7 · pill — สีตาม op_color ของทะเบียน (success = ok · info = panel2/muted ตาม mockup) */
.e2h-pill{flex:none;font-size:11px;padding:0 7px;border-radius:999px;white-space:nowrap;background:var(--e2-panel2);color:var(--e2-muted)}
.e2h-pill.is-success{background:var(--e2-ok-bg);color:var(--e2-ok)}
.e2h-pill.is-primary{background:var(--e2-accent-bg);color:var(--e2-accent-text)}
.e2h-pill.is-warning{background:var(--e2-warn-bg);color:var(--e2-warn)}
.e2h-pill.is-danger{background:var(--e2-danger-bg);color:var(--e2-danger)}

/* ── พับช่อง → แถบตั้ง "ประวัติการรักษา" (mockup: ช่องซ้าย 52px · ช่องกลางกินที่เพิ่ม) ──
   ป้ายแถบ (พี่สั่ง 2026-10-23 ส่งภาพ): ชื่อ "ประวัติการรักษา" · อ่านจากล่างขึ้นบน · ตัวหนา สีตัวอักษรหลัก + ป้าย H · พื้นแถบคงเดิม
     ล่างขึ้นบน = vertical-rl แล้วหมุน 180° (sideways-lr ยังไม่ครบทุกเบราว์เซอร์)
   แถวได้คลาส e2h-closed จาก hist-addon.js · แถบตั้ง .e2h-rail แปะท้ายช่องซ้าย (โชว์เฉพาะตอนพับ)
   จอแคบ (< 1200) เรียงลงมาอยู่แล้ว ไม่มีพับ */
.e2h-rail{display:none;flex-direction:column;align-items:center;gap:4px;padding:6px 0;background:var(--e2-panel);border:1px solid var(--e2-line);border-radius:12px;cursor:pointer}
.e2h-rail>button{width:40px;height:40px;padding:0;border:none;background:transparent;color:var(--e2-accent-text);cursor:pointer;display:inline-flex;align-items:center;justify-content:center}
/* ป้าย H = ทรงเดียวกับ badge SOAP ช่องกลาง (.e2s-badge ใน soap/emr2-soap.css) · สีเขียว รพ. (--e2-brand-* บน .emr2-row · พี่สั่ง 2026-10-23) */
.e2h-rail>.e2h-rail-ico{flex:none;width:26px;height:26px;border-radius:7px;display:inline-flex;align-items:center;justify-content:center;font-style:normal;font-weight:700;font-size:14px;background:var(--e2-brand-bg);color:var(--e2-brand-text)}
.e2h-rail>span{writing-mode:vertical-rl;transform:rotate(180deg);font-size:14px;font-weight:700;color:var(--e2-text);padding:6px 0}
@media (min-width:1200px){
  .el-row.emr2-row.e2h-closed>.emr2-col-left{flex:0 0 52px;max-width:52px}
  .el-row.emr2-row.e2h-closed>.emr2-col-center{flex:1 1 0;max-width:none}
  .emr2-row.e2h-closed>.emr2-col-left>:not(.e2h-rail){display:none!important}
  .emr2-row.e2h-closed>.emr2-col-left>.e2h-rail{display:flex}
}
@media (max-width:1199px){
  .e2h-fold{display:none}
}
/* emr2-frame · หัวคนไข้ (opd_card → คลาส emr2-head) + แถบปุ่มล่าง (action_bar_card → emr2-bar) ของ EMR v2
   ค่าสีทุกตัวยกจาก mockup board 4 (design/emr-multiclinic/mockup/EMRv2.dc.html · .emr / .emr.light + ธีมเขียว รพ.)
   ทั้งสองอยู่นอก .emr2-row ⇒ ตั้ง token ชุดของตัวเองที่นี่ (ค่าเดียวกับ --e2-brand ใน orders/emr2-orders.css)
   drawer ผลตรวจ (el-drawer append-to-body) หลุดไปอยู่ใต้ body ⇒ ตั้ง token ที่ .emr2-lab-drawer ด้วย */
.emr2-head,.emr2-bar,.emr2-lab-drawer{--e2f-brand:#17834f;--e2f-brand-text:#126c41;--e2f-brand-bg:#e2f3e9;--e2f-ok-solid:#23874f;--e2f-ok:#1c6b3a;
  --e2f-danger:#b4261e;--e2f-danger-bg:#fdecea;--e2f-warn:#8a5300;--e2f-warn-bg:#fff4d6;--e2f-blue:#1d5fbf;--e2f-purple:#6a4fc0}
html.dark .emr2-head,html.dark .emr2-bar,html.dark .emr2-lab-drawer{--e2f-brand:#1b7f52;--e2f-brand-text:#7fd8a9;--e2f-brand-bg:rgba(34,147,95,.16);--e2f-ok-solid:#2f9e66;--e2f-ok:#62d39b;
  --e2f-danger:#ff8a80;--e2f-danger-bg:rgba(255,107,107,.13);--e2f-warn:#f5c451;--e2f-warn-bg:rgba(240,180,41,.13);--e2f-blue:#8fb6ff;--e2f-purple:#b3a0f0}

/* ── ป้ายระดับแพ้ยา — เดิมตัวขาวบนพื้นทึบ (สีกลางของแพลตฟอร์ม) "เล็กน้อย" เทา/ขาว อ่านยาก (พี่ 2026-10-23)
   ⇒ พื้นอ่อน + ตัวสีเข้มแบบป้ายใน mockup · แก้เฉพาะ v2 (initcraft/QSNICH index.scss ไม่แตะ — v1 ยังเป็นแบบเดิม) */
.emr2-head .pcard-sev{color:var(--e2f-danger);background:var(--e2f-danger-bg);box-shadow:inset 0 0 0 1px currentColor}
.emr2-head .pcard-sev.moderate{color:var(--e2f-warn);background:var(--e2f-warn-bg)}
.emr2-head .pcard-sev.mild{color:var(--el-text-color-regular);background:var(--el-fill-color);box-shadow:inset 0 0 0 1px var(--el-border-color)}

/* ── แถวแจ้งเตือน: วัคซีนต่อท้ายแถวแพ้ยา (frame/head-alert.html) ──
   มีแพ้ยา: วัคซีนชิดขวา (ไม่มีข้อความ "ตรวจสอบทุกครั้งก่อนสั่งยา" แล้ว · พี่สั่ง 2026-10-23)
   ไม่มีแพ้ยา: แถวพื้นเทาเรียบ วัคซีนชิดซ้าย */
.emr2-head .pcard-alert--danger .emr2-vx{margin-left:auto}
.emr2-head .pcard-alert.emr2-alert-plain{background:var(--el-fill-color-light);border-top-color:var(--el-border-color-lighter)}
.emr2-head .emr2-vx{display:inline-flex;align-items:center;flex-wrap:wrap;gap:6px;padding:2px 10px;border-radius:999px;font-size:13px;font-weight:600;
  color:var(--e2f-warn);background:var(--e2f-warn-bg);cursor:pointer}
.emr2-head .emr2-vx.is-none{color:var(--el-text-color-secondary);background:transparent;font-weight:400;padding-left:0}
.emr2-head .emr2-vx.is-none .emr2-vx-label{font-weight:600}
.emr2-head .emr2-vx svg{width:15px;height:15px}
.emr2-head .emr2-vx:hover{filter:brightness(1.08)}

/* ── แถบปุ่มล่าง (button-ui action_bar_btns → คลาส emr2-btns) — จัดตาม board 4 + ภาพพี่ 2026-10-23
   ซ้าย: ใบรับรองแพทย์ · ส่งตัว (Refer) · Admit | ขวา: ตรวจเสร็จ · ย้ายห้อง · ส่งต่อ (กำหนดเอง) · ส่งต่ออัตโนมัติ · ตรวจเสร็จ + ส่งต่อ
   ลำดับปุ่มใน buttons[] generator เรียงให้แล้ว (ขั้น frame 1 · BAR_ORDER) ⇒ ตัวที่ 3 (Admit) ดันกลุ่มขวาไปชิดขอบ
   🔴 เพิ่ม/ย้ายปุ่ม = แก้ BAR_ORDER กับเลข nth-child ข้างล่างคู่กัน
   DOM: .static-content-item.emr2-btns > div > .el-button ×8 */
.static-content-item.emr2-btns>div{display:flex;flex-wrap:wrap;align-items:center;gap:8px}
.static-content-item.emr2-btns .el-button{margin:0;min-height:40px;padding:8px 14px;font-size:14px;border-radius:8px;
  --el-button-bg-color:transparent;--el-button-border-color:var(--el-border-color);--el-button-text-color:var(--el-text-color-primary);
  --el-button-hover-bg-color:var(--el-fill-color-light);--el-button-hover-border-color:var(--el-border-color);--el-button-hover-text-color:var(--el-text-color-primary)}
.static-content-item.emr2-btns .el-button:nth-child(3){margin-right:auto}
/* ตรวจเสร็จ (logic เดิม · ไม่ส่งต่อ): ขอบเขียว ตัวเขียว — รองจากปุ่มเขียวทึบขวาสุด */
.static-content-item.emr2-btns .el-button:nth-child(4){--el-button-border-color:var(--e2f-brand);--el-button-text-color:var(--e2f-brand-text);
  --el-button-hover-border-color:var(--e2f-brand);--el-button-hover-text-color:var(--e2f-brand-text)}
.static-content-item.emr2-btns .el-button:nth-child(5){--el-button-text-color:var(--e2f-warn);--el-button-hover-text-color:var(--e2f-warn)}
.static-content-item.emr2-btns .el-button:nth-child(6){--el-button-text-color:var(--e2f-brand-text);--el-button-hover-text-color:var(--e2f-brand-text)}
.static-content-item.emr2-btns .el-button:nth-child(7){--el-button-bg-color:var(--e2f-brand-bg);--el-button-border-color:var(--e2f-brand);--el-button-text-color:var(--e2f-brand-text);
  --el-button-hover-bg-color:var(--e2f-brand-bg);--el-button-hover-border-color:var(--e2f-brand);--el-button-hover-text-color:var(--e2f-brand-text)}
.static-content-item.emr2-btns .el-button:nth-child(8){padding:8px 18px;font-weight:600;border:none;
  --el-button-bg-color:var(--e2f-ok-solid);--el-button-text-color:#fff;--el-button-hover-bg-color:var(--e2f-ok-solid);--el-button-hover-text-color:#fff}
.static-content-item.emr2-btns .el-button:nth-child(8):hover{filter:brightness(1.08)}
.static-content-item.emr2-btns .el-button svg{width:16px;height:16px}
/* สีไอคอนตามความหมาย (พี่ขอ 2026-10-23) — ข้อความคงสีเดิม · ปุ่มที่ข้อความมีสีอยู่แล้ว ไอคอนสีเดียวกับข้อความ
   ใบรับรองแพทย์ = ฟ้า (เอกสาร) · ส่งตัว = แดง (ออกนอก รพ.) · Admit = ม่วง (นอน รพ. · ม่วงชุดเดียวกับตัว P) */
.static-content-item.emr2-btns .el-button:nth-child(1) svg{color:var(--e2f-blue)}
.static-content-item.emr2-btns .el-button:nth-child(2) svg{color:var(--e2f-danger)}
.static-content-item.emr2-btns .el-button:nth-child(3) svg{color:var(--e2f-purple)}

/* การ์ดส่งตัว (refer_emr_card · ยกจาก v1) ซ่อนในแถบนี้ — ใช้แค่ dialog ที่ปุ่ม "ส่งตัว" เปิด
   ไม่ใช้ display:none (dialog เป็น position:fixed ข้างในการ์ด — ถ้าซ่อนแบบนั้น dialog ไม่ขึ้นด้วย)
   ออกนอกจอแทน: fixed อ้างอิงจอ ไม่ใช่กล่องแม่ ⇒ dialog ยังขึ้นกลางจอ · ไม่กินความสูงแถบ */
.emr2-refer-host{position:absolute!important;left:-10000px;top:0;width:560px}
/* ตัวห่อ field-wrapper ของการ์ดที่ซ่อน ไม่ให้กินระยะใต้แถบปุ่ม */
.field-wrapper:has(>.emr2-refer-host){height:0;margin:0;padding:0}

/* ── ผลตรวจวันนี้ (vue-ui emr2_labs · frame/labs.*) — ปุ่มซ้ายสุดของแถบ + drawer ขวา ตาม board 4 ④⑤ ──
   การ์ดแถบปุ่มเรียงลูกแนวนอน: [emr2_labs][action_bar_btns ยืดเต็มที่เหลือ] · การ์ดส่งตัวที่ซ่อนอยู่นอก flow อยู่แล้ว */
.el-card.emr2-bar>.el-card__body{display:flex;align-items:center;flex-wrap:wrap}
.el-card.emr2-bar>.el-card__body>.field-wrapper:has(.emr2-btns){flex:1 1 auto;min-width:0}
.e2l-btn{display:inline-flex;align-items:center;gap:8px;margin-right:8px;font-size:14px;font-weight:600;min-height:40px;padding:8px 14px;border-radius:8px;cursor:pointer;
  border:1px solid var(--e2f-brand);background:var(--e2f-brand-bg);color:var(--e2f-brand-text);font-family:inherit}
.e2l-btn:hover{filter:brightness(1.06)}
.e2l-st{font-size:12px;font-weight:500}
.e2l-st.is-wait{color:var(--e2f-warn)}
.e2l-st.is-ok{color:var(--e2f-ok)}
/* drawer: ทับสไตล์ el-drawer ให้เป็นแผงแบบ mockup (กว้าง 580 · เส้นซ้าย · เงา) */
.el-drawer.emr2-lab-drawer{max-width:100%;background:var(--el-bg-color);border-left:1px solid var(--el-border-color-lighter);box-shadow:-12px 0 30px rgba(0,0,0,.3);color:var(--el-text-color-primary)}
.emr2-lab-drawer .el-drawer__body{padding:0;display:flex;flex-direction:column;min-height:0}
.e2l-head{flex:0 0 auto;display:flex;align-items:center;gap:10px;padding:14px 16px;border-bottom:1px solid var(--el-border-color-lighter)}
.e2l-titles{display:flex;flex-direction:column}
.e2l-title{font-size:16px;font-weight:600}
.e2l-sub{font-size:12px;color:var(--el-text-color-secondary)}
.e2l-close{margin-left:auto;border:1px solid var(--el-border-color-lighter);background:transparent;color:var(--el-text-color-secondary);border-radius:8px;width:36px;height:36px;display:inline-flex;align-items:center;justify-content:center;cursor:pointer}
.e2l-tabs{flex:0 0 auto;display:flex;gap:4px;padding:0 12px;border-bottom:1px solid var(--el-border-color-lighter)}
.e2l-tabs button{font-size:13px;border:none;background:transparent;cursor:pointer;padding:8px 12px;margin-bottom:-1px;min-height:38px;font-family:inherit;color:var(--el-text-color-secondary);border-bottom:2px solid transparent}
.e2l-tabs button.on{color:var(--e2f-brand-text);font-weight:600;border-bottom-color:var(--e2f-brand)}
.e2l-body{flex:1 1 auto;min-height:0;overflow-y:auto;padding:14px 16px;display:flex;flex-direction:column;gap:12px;overscroll-behavior:contain}
.e2l-group{font-size:12px;font-weight:600;color:var(--el-text-color-secondary)}
.e2l-card{border:1px solid var(--el-border-color-lighter);border-radius:10px;overflow:hidden;flex:0 0 auto}
.e2l-card-head{display:flex;align-items:center;gap:8px;padding:10px 12px;background:var(--el-fill-color-light);flex-wrap:wrap}
.e2l-name{font-weight:600}
.e2l-meta{font-size:12px;color:var(--el-text-color-secondary)}
.e2l-steps{display:flex;gap:12px;padding:8px 12px 0;font-size:12px;flex-wrap:wrap}
.e2l-steps.is-flat{padding:0}
.e2l-steps>span{display:inline-flex;align-items:center;gap:4px;white-space:nowrap}
.e2l-steps .is-done{color:var(--e2f-ok)}
.e2l-steps .is-wait{color:var(--e2f-warn)}
.e2l-steps .is-dead{color:var(--e2f-danger)}
.e2l-time{color:var(--el-text-color-secondary)}
.e2l-table{padding:8px 12px 12px}
.e2l-row{display:grid;grid-template-columns:minmax(0,1fr) 64px 72px 84px 84px;gap:6px;font-size:13px;padding:5px 0;font-variant-numeric:tabular-nums}
.e2l-row>span{overflow-wrap:anywhere}
.e2l-row.is-dash{border-bottom:1px dashed var(--el-border-color-lighter)}
.e2l-row-long{display:flex;flex-direction:column;gap:2px;font-size:13px;padding:5px 0}
.e2l-row-long.is-dash{border-bottom:1px dashed var(--el-border-color-lighter)}
.e2l-row-long>span:last-child{white-space:pre-line;font-weight:400;overflow-wrap:anywhere}
.e2l-row-head{font-size:11px;color:var(--el-text-color-secondary);padding:0 0 4px;border-bottom:1px solid var(--el-border-color-lighter)}
.e2l-row .m{color:var(--el-text-color-secondary)}
.e2l-row .is-val{font-weight:600}
.e2l-row .is-abn{font-weight:600;color:var(--e2f-danger)}
.e2l-row .is-hidden{color:var(--el-text-color-secondary);font-style:italic}
.e2l-xbody{padding:10px 12px;display:flex;flex-direction:column;gap:6px;font-size:13px}
.e2l-report{white-space:pre-line}
.e2l-empty{font-size:13px;color:var(--el-text-color-secondary);padding:8px 0}
.e2l-empty.is-err{color:var(--e2f-danger)}
.e2l-foot{font-size:12px;color:var(--el-text-color-secondary)}
/* ── /EMR v2 ── */
